def load_ultralytics_model(path: str, task: str = 'segment'):
    try:
        from ultralytics import YOLO  # type: ignore
    except Exception as e:
        raise RuntimeError(
            "Ultralytics is required. Install with: pip install ultralytics\n"
            f"Import error: {e}"
        ) from e
    return YOLO(path, task=task)


def background_model_load_enabled() -> bool:
    """Return True when YOLO model loading should overlap CPU volume setup.

    Model construction is not expected to be the multi-minute startup bottleneck, so
    the overlap thread is opt-in.  The important fast-start path is streaming CPU
    resize/render work into the GPU consumer once the processing volume is available.
    """
    return _env_flag('YOLO_TTA_BACKGROUND_MODEL_LOAD', False)


def canonical_single_device(device: str) -> str:
    raw = str(device or '').strip()
    if not raw:
        return 'cpu'

    token = raw.split(',')[0].strip()
    low = token.lower()
    if low in ('cpu', 'mps'):
        return low
    if low.startswith('cuda'):
        return low
    if token.isdigit():
        return f'cuda:{token}'
    return token


def _canonical_single_device_token(token: str) -> str:
    low = str(token).strip().lower()
    if low in ('cpu', 'mps'):
        return low
    if low.startswith('cuda'):
        return low
    if low.isdigit():
        return f'cuda:{low}'
    return str(token).strip()


def parse_device_list(device: 'Sequence[str] | str | None') -> List[str]:
    """v13.0.0 multi-GPU device parsing (v13.1.0 accepts space-separated values).

    --device accepts a single GPU index (``0``), multiple comma/whitespace separated GPU
    indices (``0,1,2,3`` or ``0 1 2 3``) for multi-GPU scheduling, or ``cpu``.  GPU indices
    and ``cpu`` cannot be mixed.  Returns a de-duplicated, order-preserving list of canonical
    device strings such as ``['cuda:0', 'cuda:1']`` or ``['cpu']``.

    v13.1.0: the argparser now uses ``nargs='+'`` for --device, so ``device`` may arrive as a
    list of tokens (e.g. ``['0', '1', '2', '3']`` from ``--device 0 1 2 3``) as well as a single
    string (e.g. ``'0,1,2,3'``). Both forms, and mixtures (``--device "0,1" 2 3``), are flattened
    here on the same comma/whitespace split, matching the other multi-value flags.
    """
    if device is None:
        return ['cpu']
    if isinstance(device, str):
        raw = device.strip()
    else:
        # nargs='+' list (or any sequence): join on spaces, then split on comma/whitespace below.
        raw = ' '.join(str(t) for t in device).strip()
    if not raw:
        return ['cpu']
    tokens = [t for t in re.split(r'[\s,]+', raw) if t]
    if not tokens:
        return ['cpu']

    canon: List[str] = []
    seen: set[str] = set()
    saw_cpu = False
    saw_gpu = False
    for tok in tokens:
        dev = _canonical_single_device_token(tok)
        if dev == 'cpu':
            saw_cpu = True
        elif dev == 'mps' or str(dev).startswith('cuda'):
            saw_gpu = True
        if dev not in seen:
            seen.add(dev)
            canon.append(dev)

    if saw_cpu and saw_gpu:
        raise ValueError('--device cannot mix cpu and GPU indices; use either cpu or one/more GPU indices')
    if saw_cpu:
        # cpu is a single logical device regardless of how many times it was listed.
        return ['cpu']
    return canon


def is_cpu_device_list(devices: Sequence[str]) -> bool:
    return all(str(d).strip().lower() == 'cpu' for d in devices)


def resolve_retina_mask_processor(explicit: Optional[str], devices: Sequence[str]) -> Tuple[str, str]:
    """v13.0.0 resolve --retina_mask_processor against --device rules.

    Returns (processor, reason) where processor is 'cpu' or 'gpu'.

      1. --device cpu forces 'cpu' and overrides any explicit value.
      2. Otherwise an explicit --retina_mask_processor is honored.
      3. Otherwise more than one GPU implicitly switches to 'gpu'.
      4. Otherwise the default is 'cpu' (single GPU).
    """
    explicit_norm = None if explicit is None else str(explicit).strip().lower()
    if is_cpu_device_list(devices):
        return 'cpu', '--device cpu forces CPU retina reconstruction'
    if explicit_norm in ('cpu', 'gpu'):
        return explicit_norm, f'explicit --retina_mask_processor {explicit_norm}'
    if len([d for d in devices if str(d).startswith('cuda')]) > 1:
        return 'gpu', 'more than one GPU enabled; retina masks resolved on GPU by default'
    return 'cpu', 'single-GPU default CPU retina reconstruction'


# v13.0.0: the active retina-mask processor resolved in main() from --retina_mask_processor and
# --device. None means "fall back to the YOLO_TTA_CPU_RETINA_MASKS env default" (back-compat).
_RETINA_MASK_PROCESSOR_IS_CPU: Optional[bool] = None


def set_retina_mask_processor(processor: str) -> None:
    """Set the resolved retina-mask processor ('cpu' or 'gpu') for the run."""
    global _RETINA_MASK_PROCESSOR_IS_CPU
    _RETINA_MASK_PROCESSOR_IS_CPU = bool(str(processor).strip().lower() == 'cpu')


# v13.1.0 (#2.3): when set, the single-angle + gpu-retina fast path is active. The stored
# (min_conf, min_radius) drive the on-GPU cleanup: instances below min_conf are dropped before the
# union/flatten, and min_radius + 2D hole fill run on the GPU (cupy) after the on-GPU warp to
# view-native space. None disables the fast path. min_conf may be 0.0 (fast path active, no instance
# drop) so the GPU still does the warp + hole fill (+ min_radius if > 0).
_SINGLE_ANGLE_GPU_FASTPATH: Optional[Tuple[float, float]] = None


def gpu_retina_flatten_enabled() -> bool:
    """v13.1.0 (#2.2): flatten GPU retina masks (n,H,W) -> union + max-conf planes before PCIe copy.

    Active only when retina masks are resolved on the GPU (not cpu_retina_masks_enabled()). The env
    flag YOLO_TTA_GPU_RETINA_FLATTEN (default on) allows forcing the legacy whole-stack copy for
    regression comparison.
    """
    return _env_flag('YOLO_TTA_GPU_RETINA_FLATTEN', True)


def gpu_retina_warp_enabled() -> bool:
    """v13.1.0 (#2.2): perform the flattened-plane affine warp to view-native space on the GPU.

    When enabled, the union and max-confidence planes are warped to view-native space on the GPU
    (torch grid_sample) before the host copy, so neither affine warp runs on the CPU and only the
    view-native planes cross PCIe. YOLO_TTA_GPU_RETINA_WARP=0 keeps the warps on the CPU (the
    flattened out-size planes are copied down and cv2.warpAffine'd) for regression comparison.
    """
    return _env_flag('YOLO_TTA_GPU_RETINA_WARP', True)


def gpu_retina_eager_flatten_enabled() -> bool:
    """v13.1.0 (#2.2): run the cheap GPU union/max-conf reduction on the model-stream thread.

    When on the GPU-flatten path, reducing each (n,Hr,Wr) stack to 2 small planes as results stream
    (rather than deferring the reduction to a postprocess worker) lets the full native-resolution
    retina-mask stack be released immediately, so at most ~the bounded pending count of small planes
    (not full stacks) stay resident on the GPU. YOLO_TTA_GPU_RETINA_EAGER_FLATTEN=0 defers it.
    """
    return _env_flag('YOLO_TTA_GPU_RETINA_EAGER_FLATTEN', True)


def gpu_retina_flatten_pending_limit(worker_count: int) -> int:
    """v13.1.0 (#2.2): bound on queued GPU-resident flattened frames, to cap GPU memory.

    The CPU-RAM-oriented cpu_mask_postprocess_pending_limit defaults to ~num_frames, which is unsafe
    for GPU-resident intermediates: queuing a whole view's worth of flattened planes (or, worse,
    un-reduced stacks) can OOM the device. This caps the in-flight count so GPU residency stays
    bounded while leaving enough work to keep the postprocess workers busy.
    YOLO_TTA_GPU_RETINA_PENDING_FRAMES overrides it.
    """
    wc = max(1, int(worker_count))
    return max(8, _env_int('YOLO_TTA_GPU_RETINA_PENDING_FRAMES', min(4 * wc, 256)))


def gpu_retina_cleanup_enabled() -> bool:
    """v13.1.0 (#2.3): run --min_radius on the GPU for the single-angle fast path.

    Requires cupy/cupyx. YOLO_TTA_GPU_RETINA_CLEANUP=0 forces the connected-component cleanup back
    onto the CPU (the per-slice streaming cleanup) even when the fast path is otherwise active.
    v13.3.0 (R8): the per-frame GPU 2D hole fill is removed (the final per-view volume pass
    performs the hole fill once, in spec order), so this gate now only covers the --min_radius
    connected-component filter and is a no-op when --min_radius is 0.
    """
    return _env_flag('YOLO_TTA_GPU_RETINA_CLEANUP', True)


def gpu_retina_proto_union_enabled() -> bool:
    """v13.3.0 (R9): compute the GPU retina union at PROTO resolution inside construct_result.

    Active only in GPU retina mask mode. Instead of Ultralytics materializing an
    (n, imgsz, imgsz) float retina stack per image (a batch-scaled VRAM transient of
    batch x n x 16 MB that this pipeline immediately reduces to one plane), the patched
    construct_result box-crops the per-instance mask logits at proto scale, reduces them to a
    single max-logit plane, and bilinearly upsamples ONE plane to the network raster. Box-edge
    differences are sub-voxel scale. YOLO_TTA_GPU_PROTO_UNION=0 restores the native retina
    stack + flatten path.
    """
    return _env_flag('YOLO_TTA_GPU_PROTO_UNION', True)


def gpu_postprocess_side_stream_enabled() -> bool:
    """v13.3.0 (R18): run the GPU postprocess tail on a per-thread side CUDA stream."""
    return _env_flag('YOLO_TTA_GPU_POSTPROCESS_STREAM', True)


def gpu_postprocess_pinned_d2h_enabled() -> bool:
    """v13.3.0 (R18): stage device->host postprocess copies through per-thread pinned buffers."""
    return _env_flag('YOLO_TTA_GPU_POSTPROCESS_PINNED', True)


def set_single_angle_gpu_fastpath(min_conf: Optional[float], min_radius: float = 0.0) -> None:
    """Enable/disable the v13.1.0 (#2.3) single-angle + gpu-retina fast path.

    min_conf None disables the fast path. A float (incl. 0.0) enables it; min_radius is the radius
    used for the on-GPU connected-component filter.
    """
    global _SINGLE_ANGLE_GPU_FASTPATH
    if min_conf is None:
        _SINGLE_ANGLE_GPU_FASTPATH = None
    else:
        _SINGLE_ANGLE_GPU_FASTPATH = (float(min_conf), float(min_radius))


def single_angle_gpu_fastpath() -> Optional[Tuple[float, float]]:
    """Return the active (min_conf, min_radius) fast-path config, or None when the fast path is off."""
    return _SINGLE_ANGLE_GPU_FASTPATH


def ensure_yolo_ready_for_predict(model: object, cfg: 'PredictConfig') -> None:
    """Keep the active YOLO backend resident on the requested device.

    The scheduling contract wants the GPU to stay hot until work is exhausted. Offloading the model
    between videos can leave Ultralytics with CUDA inputs but CPU weights on the next predict() call.
    This helper lazily restores the requested device/dtype when needed and is a cheap no-op while the
    model already matches the active predict configuration.
    """
    try:
        import torch  # type: ignore
    except Exception:
        return

    target = canonical_single_device(str(cfg.device))
    wants_half = bool(cfg.half) and str(target).startswith('cuda')
    state = (str(target), bool(wants_half))
    if getattr(model, '_tta_predict_state', None) == state:
        return

    candidates: List[object] = [model]
    direct_model = getattr(model, 'model', None)
    if direct_model is not None:
        candidates.append(direct_model)
    predictor = getattr(model, 'predictor', None)
    predictor_model = getattr(predictor, 'model', None) if predictor is not None else None
    if predictor_model is not None and predictor_model is not direct_model:
        candidates.append(predictor_model)

    seen_ids: set[int] = set()
    for candidate in candidates:
        if candidate is None:
            continue
        cid = id(candidate)
        if cid in seen_ids:
            continue
        seen_ids.add(cid)

        to_fn = getattr(candidate, 'to', None)
        if callable(to_fn):
            try:
                to_fn(target)
            except Exception:
                pass

        precision_fn = getattr(candidate, 'half', None) if wants_half else getattr(candidate, 'float', None)
        if callable(precision_fn):
            try:
                precision_fn()
            except Exception:
                pass

    if predictor is not None:
        try:
            setattr(predictor, 'device', torch.device(target))
        except Exception:
            pass
        args_obj = getattr(predictor, 'args', None)
        if args_obj is not None:
            try:
                setattr(args_obj, 'device', target)
            except Exception:
                pass

    try:
        setattr(model, '_tta_predict_state', state)
    except Exception:
        pass


def offload_between_jobs_enabled() -> bool:
    return _env_flag('YOLO_TTA_OFFLOAD_BETWEEN_JOBS', False)


def trim_cuda_memory() -> None:
    try:
        import torch  # type: ignore
    except Exception:
        return

    try:
        if not bool(torch.cuda.is_available()):
            return
        torch.cuda.empty_cache()
        ipc_collect = getattr(torch.cuda, 'ipc_collect', None)
        if callable(ipc_collect):
            ipc_collect()
    except Exception:
        pass


def offload_yolo_from_gpu(model: object) -> None:
    modules: List[object] = []
    direct_model = getattr(model, 'model', None)
    if direct_model is not None:
        modules.append(direct_model)

    predictor = getattr(model, 'predictor', None)
    predictor_model = getattr(predictor, 'model', None) if predictor is not None else None
    if predictor_model is not None and predictor_model is not direct_model:
        modules.append(predictor_model)

    for module in modules:
        try:
            to_fn = getattr(module, 'to', None)
            if callable(to_fn):
                to_fn('cpu')
        except Exception:
            pass

    try:
        setattr(model, '_tta_predict_state', None)
    except Exception:
        pass

    trim_cuda_memory()


def unload_yolo_model(model: object) -> None:
    offload_yolo_from_gpu(model)
    predictor = getattr(model, 'predictor', None)
    if predictor is not None:
        try:
            setattr(model, 'predictor', None)
        except Exception:
            pass
    trim_cuda_memory()


@dataclass
class PredictConfig:
    imgsz: int
    conf: float
    device: str
    half: bool
    int8: bool
    batch: int = 1


def async_predict_postprocess_enabled() -> bool:
    """Return True when single-angle prediction CPU tails may run behind the GPU."""
    return _env_flag('YOLO_TTA_ASYNC_PREDICT_POSTPROCESS', True)


def async_predict_join_workers(default_value: int) -> int:
    return max(1, _env_int('YOLO_TTA_ASYNC_PREDICT_JOIN_WORKERS', max(1, int(default_value))))


def async_predict_pending_frame_limit(num_frames: int) -> int:
    """Optional cap for queued async result-worker futures per source.

    The default 0 means source-sized buffering: the GPU-facing iterator will not
    intentionally wait for CPU result workers while a prediction volume streams.
    Set YOLO_TTA_ASYNC_PREDICT_PENDING_FRAMES to a positive value to reduce
    transient CPU/GPU result memory at the cost of some continuity.
    """
    requested = _env_int('YOLO_TTA_ASYNC_PREDICT_PENDING_FRAMES', 0)
    if int(requested) <= 0:
        return 0
    return max(1, min(max(1, int(num_frames)), int(requested)))


@dataclass
class PredictionAccumulationHandle:
    """Background CPU accumulation tail for one streamed prediction source."""
    source_label: str
    futures: List[Future]
    view_union_mm: np.ndarray
    view_confmap_mm: Optional[np.ndarray]
    submitted_frames: int = 0
    synthetic_discarded: int = 0
    precompleted_prediction_count: int = 0
    precompleted_frames_with_predictions: int = 0
    pending_limit: int = 0

    def wait(self) -> Dict[str, int]:
        prediction_count = int(self.precompleted_prediction_count)
        frames_with_predictions = int(self.precompleted_frames_with_predictions)
        try:
            for fut in as_completed(list(self.futures)):
                pred_inc, frame_inc = fut.result()
                prediction_count += int(pred_inc)
                frames_with_predictions += int(frame_inc)
        finally:
            if prediction_hot_path_flush_enabled():
                if self.view_confmap_mm is not None:
                    flush_array(self.view_confmap_mm)
                flush_array(self.view_union_mm)
        return {
            'prediction_count': int(prediction_count),
            'frames_with_predictions': int(frames_with_predictions),
            'submitted_frames': int(self.submitted_frames),
            'synthetic_discarded': int(self.synthetic_discarded),
            'async_accumulation': 1,
        }


DEFAULT_GAUSSIAN_SMOOTHING_SIGMA = 3.0
DEFAULT_GAUSSIAN_SMOOTHING_PASSES = 1


def resolve_gaussian_smoothing_settings(
    gaussian_smoothing_arg: Optional[float],
    gaussian_smoothing_passes_arg: Optional[int],
) -> Tuple[bool, float, int]:
    """Resolve Gaussian smoothing enablement from the v12.2.0 CLI contract.

    Gaussian smoothing is active iff at least one Gaussian flag is explicitly set
    and neither explicitly supplied value is 0. Unset values use the defaults
    from the specification: sigma=3.0 and passes=1.
    """
    sigma_explicit = gaussian_smoothing_arg is not None
    passes_explicit = gaussian_smoothing_passes_arg is not None
    sigma_f = (
        float(gaussian_smoothing_arg)
        if sigma_explicit
        else float(DEFAULT_GAUSSIAN_SMOOTHING_SIGMA)
    )
    passes_i = (
        int(gaussian_smoothing_passes_arg)
        if passes_explicit
        else int(DEFAULT_GAUSSIAN_SMOOTHING_PASSES)
    )
    enabled = bool((sigma_explicit or passes_explicit) and sigma_f > 0.0 and passes_i > 0)
    if not enabled:
        return False, 0.0, max(0, int(passes_i))
    return True, float(sigma_f), int(passes_i)


CONF_U8_MAX = 255


def quantize_conf_to_u8(conf: float) -> np.uint8:
    conf_clamped = min(1.0, max(0.0, float(conf)))
    return np.uint8(int(round(conf_clamped * float(CONF_U8_MAX))))


def min_conf_to_u8_threshold(min_conf: float) -> int:
    conf_clamped = min(1.0, max(0.0, float(min_conf)))
    return int(math.ceil(conf_clamped * float(CONF_U8_MAX) - 1e-9))


@dataclass(frozen=True)
class CpuRetinaMaskPayload:
    """CPU-owned YOLO segmentation tensors needed to reconstruct retina/native masks off-GPU."""

    proto: np.ndarray             # (C, mask_h, mask_w), float32 CPU
    coeffs: np.ndarray            # (N, C), float32 CPU
    boxes_xyxy: np.ndarray        # (N, 4), scaled to prediction-video pixel coordinates
    confs: np.ndarray             # (N,), float32 CPU
    orig_shape: Tuple[int, int]   # (height, width) of the prediction-video frame
    img_shape: Tuple[int, int]    # (height, width) of the network input tensor
    frame_path: str = ''


@dataclass
class GpuFlattenedRetinaPayload:
    """v13.1.0 (#2.2/#2.3): one retina-mask frame flattened on the GPU, kept on the GPU.

    Ultralytics produces a native-resolution (n, Hr, Wr) retina-mask stack on the GPU. Instead of
    copying the whole stack down and OR/resizing it in a single-threaded per-instance CPU loop, the
    stack is reduced on the GPU to a per-pixel union plane and a per-pixel max-confidence plane. The
    GPU tensors are retained (not copied to the CPU here) so the affine warp to view-native space --
    and, for the single-angle fast path, --min_radius + 2D hole fill -- can also run on the GPU; only
    the finished view-native plane(s) then cross PCIe (#2.2: O(2*H*W); #2.3: one cleaned plane).

    union_gpu is a torch tensor (Hr, Wr) of 0/1 (float or bool). conf_gpu is a torch tensor (Hr, Wr)
    of per-pixel max confidence in [0,1] (pre-quantization), or None when no boxes.conf was present.
    instance_count is the number of (kept) instances (prediction-count stats only). min_conf_applied
    records whether the on-GPU instance-level --min_conf drop ran. run_gpu_cleanup requests the on-GPU
    --min_radius + hole fill (#2.3); gpu_min_radius is the radius for it. cleanup_done_on_gpu is set by
    the frame processor once the GPU connected-component cleanup actually completed, so the per-slice
    CPU streaming cleanup can be skipped for that slice.
    """

    union_gpu: object
    conf_gpu: Optional[object]
    instance_count: int = 0
    # v13.3.12 (C3): generic direct-backend compaction retains its scalar count on device.
    # The device-union path records it into a per-frame task tensor and reads totals once at
    # task end; host-output fallbacks stage it alongside their unavoidable mask D2H.
    instance_count_device: Optional[object] = None
    min_conf_applied: bool = False
    run_gpu_cleanup: bool = False
    gpu_min_radius: float = 0.0
    cleanup_done_on_gpu: bool = False
    # v13.3.0 (R18): CUDA event recorded on the producing stream after union/conf were computed,
    # so the postprocess side stream can order against the producer without a host sync.
    ready_event: Optional[object] = None
    # v13.3.2 (R21): set by the frame processor when this frame's native plane was written into
    # the per-task device union accumulator (no host write happened; the task-end flush merges).
    accumulated_on_device: bool = False
    # Keep raw head/proto and compaction workspaces alive until ready_event has ordered every
    # consumer. CuPy launches are invisible to torch's allocator stream tracking by themselves.
    device_refs: Optional[Tuple[object, ...]] = field(default=None, repr=False)


@dataclass(frozen=True)
class DeferredCpuRetinaMaskPayload:
    """Compact GPU tensors captured from Ultralytics and copied in result-worker threads."""

    pred: object
    proto: object
    orig_shape: Tuple[int, int]
    img_shape: Tuple[int, int]
    frame_path: str = ''


_ULTRALYTICS_CPU_RETINA_PATCHED = False
_ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT: Optional[object] = None


_DEFERRED_CLONE_FALLBACK_WARNED = False


def _detach_clone_tensor_if_torch(value: object) -> object:
    """Detach+clone a torch tensor so a deferred payload owns its storage.

    Buffer-reusing inference backends (e.g. TensorRT engines through AutoBackend) hand
    construct_result views of output bindings that the NEXT batch's execute overwrites in
    place. A payload whose realization is deferred to a worker thread must never alias
    those bindings, or it reads a later frame's protos (v13.2.2 bug #11). The clone is a
    device-side copy queued on the current stream — it does not synchronize the host, so
    the deferral still keeps the GPU->CPU copy off the model-stream thread.

    Non-tensor values pass through unchanged. Clone failures (e.g. a transient CUDA OOM)
    PROPAGATE: silently returning the aliased binding would reinstate exactly the
    corruption this exists to prevent — the caller falls back to synchronous
    realization instead.
    """
    detach = getattr(value, 'detach', None)
    if not callable(detach):
        return value
    detached = detach()
    clone = getattr(detached, 'clone', None)
    if not callable(clone):
        return detached
    return clone()


def cpu_retina_masks_enabled() -> bool:
    """Return True when retina masks are reconstructed on the CPU.

    v13.0.0: when main() has resolved --retina_mask_processor (against the --device rules),
    that decision wins: 'cpu' -> deferred CPU retina reconstruction (retina_masks=False to
    YOLO); 'gpu' -> Ultralytics native retina_masks=True on the GPU. When unset (e.g. helper
    used standalone), fall back to the YOLO_TTA_CPU_RETINA_MASKS env default.

    CPU reconstruction captures compact mask coefficients/protos and rebuilds bbox-local
    masks in prediction-result workers, keeping large full-resolution GPU mask tensors off
    the scheduler/model-stream thread. Resolving them on GPU frees the CPUs for view
    creation/postprocessing, which is what multi-GPU runs need.
    """
    if _RETINA_MASK_PROCESSOR_IS_CPU is not None:
        return bool(_RETINA_MASK_PROCESSOR_IS_CPU)
    return _env_flag('YOLO_TTA_CPU_RETINA_MASKS', True)


def cpu_retina_roi_only_enabled() -> bool:
    """Use bbox-ROI-only CPU upsampling instead of reconstructing every full-size instance mask."""
    return _env_flag('YOLO_TTA_CPU_RETINA_ROI_ONLY', True)


def cpu_retina_block_detections() -> int:
    """Number of mask logits to reconstruct per CPU matrix-multiply block."""
    return max(1, _env_int('YOLO_TTA_CPU_RETINA_BLOCK_DETECTIONS', 8))


def cpu_retina_deferred_payload_enabled() -> bool:
    """Defer compact pred/proto CPU copies from Ultralytics construct_result to result workers."""
    if os.environ.get('YOLO_TTA_CPU_RETINA_DEFER_GPU_COPY') is not None:
        return _env_flag('YOLO_TTA_CPU_RETINA_DEFER_GPU_COPY', True)
    return _env_flag('YOLO_TTA_CPU_RETINA_DEFERRED_PAYLOAD', True)


def cpu_mask_postprocess_pending_limit(worker_count: int, num_frames: int) -> int:
    """Bound queued CPU mask-reconstruction frames while allowing RAM-backed buffering.

    Setting YOLO_TTA_CPU_MASK_PENDING_FRAMES=0 removes the frame-count cap for sites that
    intentionally want to absorb the entire CPU backlog in RAM. The default is deliberately much
    larger than the worker count so GPU inference is not throttled by CPU retina reconstruction under
    normal SLURM allocations.
    """
    workers = max(1, int(worker_count))
    frames = max(1, int(num_frames))
    requested = _env_int('YOLO_TTA_CPU_MASK_PENDING_FRAMES', 0)
    if int(requested) <= 0:
        return max(workers, frames)
    return max(workers, min(frames, max(int(requested), workers * 2)))


_ULTRALYTICS_SINGLE_CHANNEL_PREPROCESS_PATCHED = False
_ULTRALYTICS_ORIGINAL_BASE_PREPROCESS: Optional[object] = None


def ensure_single_channel_yolo_preprocess_patch() -> bool:
    """Patch Ultralytics preprocessing so H×W×1 in-memory slices stay one-channel tensors.

    The v12 in-memory source deliberately yields single-channel image arrays. Recent
    Ultralytics preprocessors assume OpenCV-style H×W×3 BGR arrays for numpy-image
    batches and transpose them as BHWC. This patch handles batches that are already
    single-channel by constructing a BCHW tensor directly, bypassing any gray-to-BGR
    duplication while leaving normal RGB/BGR and video sources on the original path.
    """
    global _ULTRALYTICS_SINGLE_CHANNEL_PREPROCESS_PATCHED, _ULTRALYTICS_ORIGINAL_BASE_PREPROCESS

    if _ULTRALYTICS_SINGLE_CHANNEL_PREPROCESS_PATCHED:
        return True

    try:
        import torch  # type: ignore
        from ultralytics.engine.predictor import BasePredictor  # type: ignore
    except Exception as exc:  # pragma: no cover - ultralytics is imported lazily on SLURM
        print(f'Warning: single-channel YOLO preprocess patch could not be installed ({exc})')
        return False

    original_preprocess = BasePredictor.preprocess
    _ULTRALYTICS_ORIGINAL_BASE_PREPROCESS = original_preprocess

    def _tta_single_channel_preprocess(self, im):  # type: ignore[no-untyped-def]
        gpu_tensor = getattr(im, '_tta_gpu_tensor', None)
        if gpu_tensor is not None:
            try:
                wait_fn = getattr(im, 'wait_ready', None)
                if callable(wait_fn):
                    tensor = wait_fn()
                else:
                    tensor = gpu_tensor
                model_obj = getattr(self, 'model', None)
                use_half = bool(getattr(model_obj, 'fp16', False))
                if use_half and getattr(tensor, 'dtype', None) != torch.float16:
                    tensor = tensor.half()
                elif (not use_half) and getattr(tensor, 'dtype', None) != torch.float32:
                    tensor = tensor.float()
                # GPU-staged batches are already normalized to [0,1].
                return tensor
            except Exception as exc:
                raise RuntimeError(f'Failed to consume GPU-staged YOLO input batch: {exc}') from exc

        not_tensor = not isinstance(im, torch.Tensor)
        if not_tensor:
            if isinstance(im, np.ndarray):
                seq = [im]
            elif isinstance(im, (list, tuple)):
                seq = list(im)
            else:
                seq = []

            if seq:
                gray_frames: List[np.ndarray] = []
                single_channel_batch = True
                for item in seq:
                    arr = np.asarray(item)
                    if arr.ndim == 2:
                        gray = arr
                    elif arr.ndim == 3 and int(arr.shape[2]) == 1:
                        gray = arr[:, :, 0]
                    else:
                        single_channel_batch = False
                        break
                    gray_frames.append(np.ascontiguousarray(gray, dtype=np.uint8))

                if single_channel_batch:
                    try:
                        shapes = {tuple(int(v) for v in frame.shape) for frame in gray_frames}
                        if len(shapes) != 1:
                            raise ValueError(f'single-channel batch contains mixed shapes: {sorted(shapes)}')
                        batch = np.stack(gray_frames, axis=0)[:, None, :, :]  # BCHW, C=1
                        tensor = torch.from_numpy(np.ascontiguousarray(batch))
                        device = getattr(self, 'device', None)
                        if device is not None:
                            tensor = tensor.to(device)
                        model_obj = getattr(self, 'model', None)
                        use_half = bool(getattr(model_obj, 'fp16', False))
                        tensor = tensor.half() if use_half else tensor.float()
                        tensor /= 255.0
                        return tensor
                    except Exception as exc:
                        raise RuntimeError(f'Failed to preprocess single-channel in-memory YOLO batch: {exc}') from exc

        return original_preprocess(self, im)

    BasePredictor.preprocess = _tta_single_channel_preprocess
    _ULTRALYTICS_SINGLE_CHANNEL_PREPROCESS_PATCHED = True
    print('Single-channel YOLO preprocess enabled: in-memory H×W×1 slices are passed as BCHW tensors with C=1.')
    return True


def _as_numpy_float32_cpu(x: object) -> np.ndarray:
    """Detach torch/array-like tensors into owned, contiguous CPU float32 NumPy arrays."""
    try:
        detach = getattr(x, 'detach', None)
        if callable(detach):
            x = detach()
        to_fn = getattr(x, 'to', None)
        if callable(to_fn):
            try:
                import torch  # type: ignore
                x = to_fn(device='cpu', dtype=torch.float32)
            except Exception:
                cpu_fn = getattr(x, 'cpu', None)
                if callable(cpu_fn):
                    x = cpu_fn()
        cpu_fn = getattr(x, 'cpu', None)
        if callable(cpu_fn):
            x = cpu_fn()
        numpy_fn = getattr(x, 'numpy', None)
        if callable(numpy_fn):
            arr = numpy_fn()
        else:
            arr = np.asarray(x)
    except Exception:
        arr = np.asarray(x)
    return np.ascontiguousarray(arr, dtype=np.float32)


def _clip_boxes_np(boxes: np.ndarray, shape: Sequence[int]) -> np.ndarray:
    h = int(shape[0])
    w = int(shape[1])
    boxes[:, 0] = np.clip(boxes[:, 0], 0.0, float(w))
    boxes[:, 1] = np.clip(boxes[:, 1], 0.0, float(h))
    boxes[:, 2] = np.clip(boxes[:, 2], 0.0, float(w))
    boxes[:, 3] = np.clip(boxes[:, 3], 0.0, float(h))
    return boxes


def _scale_boxes_np(
    img1_shape: Sequence[int],
    boxes: np.ndarray,
    img0_shape: Sequence[int],
    *,
    padding: bool = True,
) -> np.ndarray:
    """NumPy equivalent of Ultralytics ops.scale_boxes for xyxy boxes."""
    if boxes.size <= 0:
        return boxes.astype(np.float32, copy=False)

    img1_h, img1_w = int(img1_shape[0]), int(img1_shape[1])
    img0_h, img0_w = int(img0_shape[0]), int(img0_shape[1])
    gain = min(float(img1_h) / max(1.0, float(img0_h)), float(img1_w) / max(1.0, float(img0_w)))
    if gain <= 0.0:
        return _clip_boxes_np(boxes.astype(np.float32, copy=False), img0_shape)

    pad_x = round((float(img1_w) - round(float(img0_w) * gain)) / 2.0 - 0.1)
    pad_y = round((float(img1_h) - round(float(img0_h) * gain)) / 2.0 - 0.1)
    out = boxes.astype(np.float32, copy=True)
    if bool(padding):
        out[:, [0, 2]] -= float(pad_x)
        out[:, [1, 3]] -= float(pad_y)
    out[:, :4] /= float(gain)
    return _clip_boxes_np(out, img0_shape)


def _scale_masks_crop_slices_np(mask_shape: Tuple[int, int], target_shape: Tuple[int, int]) -> Tuple[slice, slice]:
    """Return the low-resolution crop used by Ultralytics scale_masks before interpolation."""
    im1_h, im1_w = int(mask_shape[0]), int(mask_shape[1])
    im0_h, im0_w = int(target_shape[0]), int(target_shape[1])
    if im1_h == im0_h and im1_w == im0_w:
        return slice(0, im1_h), slice(0, im1_w)

    gain = min(float(im1_h) / max(1.0, float(im0_h)), float(im1_w) / max(1.0, float(im0_w)))
    pad_w = (float(im1_w) - round(float(im0_w) * gain)) / 2.0
    pad_h = (float(im1_h) - round(float(im0_h) * gain)) / 2.0
    top = int(round(pad_h - 0.1))
    left = int(round(pad_w - 0.1))
    bottom = int(im1_h - round(pad_h + 0.1))
    right = int(im1_w - round(pad_w + 0.1))
    top = int(np.clip(top, 0, im1_h))
    left = int(np.clip(left, 0, im1_w))
    bottom = int(np.clip(bottom, top + 1, im1_h)) if im1_h > 0 else 0
    right = int(np.clip(right, left + 1, im1_w)) if im1_w > 0 else 0
    return slice(top, bottom), slice(left, right)


def _bbox_to_integer_roi(box_xyxy: np.ndarray, target_shape: Tuple[int, int]) -> Optional[Tuple[int, int, int, int]]:
    h, w = int(target_shape[0]), int(target_shape[1])
    if h <= 0 or w <= 0:
        return None
    x1 = int(math.ceil(max(0.0, float(box_xyxy[0]))))
    y1 = int(math.ceil(max(0.0, float(box_xyxy[1]))))
    x2 = int(math.ceil(min(float(w), float(box_xyxy[2]))))
    y2 = int(math.ceil(min(float(h), float(box_xyxy[3]))))
    if x2 <= x1 or y2 <= y1:
        return None
    return y1, y2, x1, x2


def _resize_lowres_logits_roi(
    low_logits: np.ndarray,
    target_shape: Tuple[int, int],
    roi: Tuple[int, int, int, int],
) -> np.ndarray:
    """Upsample only the requested high-resolution ROI using align-corners=False geometry.

    This avoids allocating an N x H x W tensor for hundreds of detections. It is equivalent in
    coordinate mapping to resizing the low-resolution retina logits to the prediction-video frame and
    then cropping the bbox ROI, while doing the expensive interpolation only inside the bbox.
    """
    y1, y2, x1, x2 = (int(v) for v in roi)
    target_h, target_w = int(target_shape[0]), int(target_shape[1])
    low = np.asarray(low_logits, dtype=np.float32)
    low_h, low_w = int(low.shape[0]), int(low.shape[1])
    roi_h = int(y2 - y1)
    roi_w = int(x2 - x1)

    if roi_h <= 0 or roi_w <= 0 or low_h <= 0 or low_w <= 0:
        return np.zeros((max(0, roi_h), max(0, roi_w)), dtype=np.float32)

    if low_h == target_h and low_w == target_w:
        return np.ascontiguousarray(low[y1:y2, x1:x2], dtype=np.float32)

    if not cpu_retina_roi_only_enabled():
        full = cv2.resize(low, (target_w, target_h), interpolation=cv2.INTER_LINEAR)
        return np.ascontiguousarray(full[y1:y2, x1:x2], dtype=np.float32)

    # Destination pixel-center to source-coordinate mapping for bilinear resize with
    # align_corners=False. Coordinates outside the low-resolution raster are edge-clamped,
    # matching torch.nn.functional.interpolate and cv2.resize behavior.
    xs = ((np.arange(x1, x2, dtype=np.float32) + 0.5) * (float(low_w) / float(target_w))) - 0.5
    ys = ((np.arange(y1, y2, dtype=np.float32) + 0.5) * (float(low_h) / float(target_h))) - 0.5
    xs = np.clip(xs, 0.0, float(low_w - 1))
    ys = np.clip(ys, 0.0, float(low_h - 1))

    x0 = np.floor(xs).astype(np.int32, copy=False)
    y0 = np.floor(ys).astype(np.int32, copy=False)
    x1_idx = np.minimum(x0 + 1, low_w - 1).astype(np.int32, copy=False)
    y1_idx = np.minimum(y0 + 1, low_h - 1).astype(np.int32, copy=False)
    wx = (xs - x0.astype(np.float32, copy=False)).astype(np.float32, copy=False)
    wy = (ys - y0.astype(np.float32, copy=False)).astype(np.float32, copy=False)

    top = (low[y0[:, None], x0[None, :]] * (1.0 - wx[None, :])) + (low[y0[:, None], x1_idx[None, :]] * wx[None, :])
    bottom = (low[y1_idx[:, None], x0[None, :]] * (1.0 - wx[None, :])) + (low[y1_idx[:, None], x1_idx[None, :]] * wx[None, :])
    return np.ascontiguousarray((top * (1.0 - wy[:, None])) + (bottom * wy[:, None]), dtype=np.float32)


def _iter_cpu_retina_payload_rois(
    payload: CpuRetinaMaskPayload,
    target_shape: Tuple[int, int],
) -> Iterator[Tuple[int, float, int, int, int, int, np.ndarray]]:
    """Yield per-instance high-resolution ROI masks reconstructed from CPU protos/coefficients."""
    proto = np.asarray(payload.proto, dtype=np.float32)
    if proto.ndim == 4 and int(proto.shape[0]) == 1:
        proto = proto[0]
    if proto.ndim != 3:
        return

    coeffs = np.asarray(payload.coeffs, dtype=np.float32)
    boxes = np.asarray(payload.boxes_xyxy, dtype=np.float32)
    confs = np.asarray(payload.confs, dtype=np.float32)
    if coeffs.ndim != 2 or coeffs.shape[0] <= 0 or coeffs.shape[1] != int(proto.shape[0]):
        return

    target_h, target_w = int(target_shape[0]), int(target_shape[1])
    if target_h <= 0 or target_w <= 0:
        return

    mask_crop_y, mask_crop_x = _scale_masks_crop_slices_np(
        (int(proto.shape[1]), int(proto.shape[2])),
        (target_h, target_w),
    )
    c, mh, mw = int(proto.shape[0]), int(proto.shape[1]), int(proto.shape[2])
    proto_flat = np.ascontiguousarray(proto.reshape(c, mh * mw), dtype=np.float32)
    block = cpu_retina_block_detections()
    n = int(coeffs.shape[0])

    for start in range(0, n, block):
        stop = min(n, start + block)
        logits_block = np.matmul(
            np.ascontiguousarray(coeffs[start:stop], dtype=np.float32),
            proto_flat,
        ).reshape((stop - start, mh, mw))

        for local_idx in range(stop - start):
            inst_idx = int(start + local_idx)
            if inst_idx >= int(boxes.shape[0]):
                continue
            roi = _bbox_to_integer_roi(boxes[inst_idx], (target_h, target_w))
            if roi is None:
                continue
            y1, y2, x1, x2 = roi
            low_logits = np.ascontiguousarray(logits_block[local_idx, mask_crop_y, mask_crop_x], dtype=np.float32)
            roi_logits = _resize_lowres_logits_roi(low_logits, (target_h, target_w), roi)
            roi_mask = np.asarray(roi_logits > 0.0, dtype=bool)
            if not np.any(roi_mask):
                continue
            conf_val = float(confs[inst_idx]) if inst_idx < int(confs.shape[0]) else 0.0
            yield inst_idx, conf_val, y1, y2, x1, x2, roi_mask


def _accumulate_cpu_retina_payload_to_prediction_frame(
    payload: CpuRetinaMaskPayload,
    out_size: int,
) -> Tuple[np.ndarray, np.ndarray, int]:
    """Build a prediction-space union/confidence frame from CPU-side retina payload tensors."""
    target_shape = (int(out_size), int(out_size))
    frame_union = np.zeros(target_shape, dtype=np.uint8)
    frame_confmap = np.zeros(target_shape, dtype=np.uint8)
    kept_instances = 0

    # The generated inference videos are square --imgsz frames. If a future source ever reports a
    # different original shape, keep the current --imgsz target because the affine matrices in this
    # pipeline are defined in that prediction-video coordinate system.
    for _inst_idx, conf_val, y1, y2, x1, x2, roi_mask in _iter_cpu_retina_payload_rois(payload, target_shape):
        roi_u8 = roi_mask.astype(np.uint8, copy=False)
        frame_union[y1:y2, x1:x2] |= roi_u8
        conf_u8 = quantize_conf_to_u8(float(conf_val))
        conf_patch = frame_confmap[y1:y2, x1:x2]
        conf_patch[roi_mask] = np.maximum(conf_patch[roi_mask], conf_u8)
        kept_instances += 1

    return frame_union, frame_confmap, int(kept_instances)


def _realize_deferred_cpu_retina_payload(payload: DeferredCpuRetinaMaskPayload) -> CpuRetinaMaskPayload:
    """Copy compact segmentation tensors to CPU and build a CPU-retina payload."""
    pred_cpu = _as_numpy_float32_cpu(payload.pred)
    if pred_cpu.ndim != 2 or int(pred_cpu.shape[0]) <= 0:
        return CpuRetinaMaskPayload(
            proto=np.zeros((0, 0, 0), dtype=np.float32),
            coeffs=np.zeros((0, 0), dtype=np.float32),
            boxes_xyxy=np.zeros((0, 4), dtype=np.float32),
            confs=np.zeros((0,), dtype=np.float32),
            orig_shape=(int(payload.orig_shape[0]), int(payload.orig_shape[1])),
            img_shape=(int(payload.img_shape[0]), int(payload.img_shape[1])),
            frame_path=str(payload.frame_path),
        )

    boxes_scaled = _scale_boxes_np(payload.img_shape, pred_cpu[:, :4], payload.orig_shape)
    pred_cpu[:, :4] = boxes_scaled
    proto_cpu = _as_numpy_float32_cpu(payload.proto)
    if proto_cpu.ndim == 4 and int(proto_cpu.shape[0]) == 1:
        proto_cpu = proto_cpu[0]
    if proto_cpu.ndim != 3:
        proto_cpu = np.zeros((0, 0, 0), dtype=np.float32)
    coeffs = pred_cpu[:, 6:] if int(pred_cpu.shape[1]) > 6 else np.zeros((int(pred_cpu.shape[0]), 0), dtype=np.float32)
    confs = pred_cpu[:, 4] if int(pred_cpu.shape[1]) > 4 else np.zeros((int(pred_cpu.shape[0]),), dtype=np.float32)
    return CpuRetinaMaskPayload(
        proto=np.ascontiguousarray(proto_cpu, dtype=np.float32),
        coeffs=np.ascontiguousarray(coeffs, dtype=np.float32),
        boxes_xyxy=np.ascontiguousarray(pred_cpu[:, :4], dtype=np.float32),
        confs=np.ascontiguousarray(confs, dtype=np.float32),
        orig_shape=(int(payload.orig_shape[0]), int(payload.orig_shape[1])),
        img_shape=(int(payload.img_shape[0]), int(payload.img_shape[1])),
        frame_path=str(payload.frame_path),
    )


def ensure_cpu_retina_mask_predictor_patch() -> bool:
    """Patch Ultralytics segmentation postprocess to return CPU-retina payloads, not GPU masks."""
    global _ULTRALYTICS_CPU_RETINA_PATCHED, _ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT

    if not cpu_retina_masks_enabled():
        return False
    if _ULTRALYTICS_CPU_RETINA_PATCHED:
        return True

    try:
        from ultralytics.engine.results import Results  # type: ignore
        from ultralytics.models.yolo.segment.predict import SegmentationPredictor  # type: ignore
    except Exception as exc:
        print(f'Warning: CPU retina-mask predictor patch could not be installed; falling back to Ultralytics masks ({exc})')
        return False

    original_construct_result = SegmentationPredictor.construct_result
    _ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT = original_construct_result

    def _tta_cpu_retina_construct_result(self, pred, img, orig_img, img_path, proto):  # type: ignore[no-untyped-def]
        if not cpu_retina_masks_enabled():
            return original_construct_result(self, pred, img, orig_img, img_path, proto)

        try:
            img_shape = tuple(int(x) for x in img.shape[2:])
        except Exception:
            img_shape = (int(getattr(orig_img, 'shape', (0, 0))[0]), int(getattr(orig_img, 'shape', (0, 0))[1]))
        try:
            orig_shape = (int(orig_img.shape[0]), int(orig_img.shape[1]))
        except Exception:
            orig_shape = (int(img_shape[0]), int(img_shape[1]))

        if bool(cpu_retina_deferred_payload_enabled()):
            # Keep the Results object lightweight; compact pred/proto tensors are realized in
            # the prediction-result worker, not inside Ultralytics construct_result.
            try:
                deferred_payload: Optional[DeferredCpuRetinaMaskPayload] = DeferredCpuRetinaMaskPayload(
                    pred=_detach_clone_tensor_if_torch(pred),
                    proto=_detach_clone_tensor_if_torch(proto),
                    orig_shape=(int(orig_shape[0]), int(orig_shape[1])),
                    img_shape=(int(img_shape[0]), int(img_shape[1])),
                    frame_path=str(img_path),
                )
            except Exception as clone_exc:
                # v13.2.2 bug #11: a failed clone (e.g. transient CUDA OOM) must NOT fall
                # back to aliasing the backend's reusable output bindings — that silently
                # reinstates the corruption. Realize this frame synchronously below (the
                # CPU copy completes before the next batch executes).
                global _DEFERRED_CLONE_FALLBACK_WARNED
                if not _DEFERRED_CLONE_FALLBACK_WARNED:
                    _DEFERRED_CLONE_FALLBACK_WARNED = True
                    print(
                        f'Warning: deferred CPU retina payload clone failed ({clone_exc}); '
                        'falling back to synchronous realization for affected frames.'
                    )
                deferred_payload = None
            if deferred_payload is not None:
                result = Results(orig_img, path=img_path, names=self.model.names, boxes=None, masks=None)
                setattr(result, '_tta_deferred_cpu_retina_payload', deferred_payload)
                return result

        payload = _realize_deferred_cpu_retina_payload(DeferredCpuRetinaMaskPayload(
            pred=pred,
            proto=proto,
            orig_shape=(int(orig_shape[0]), int(orig_shape[1])),
            img_shape=(int(img_shape[0]), int(img_shape[1])),
            frame_path=str(img_path),
        ))
        boxes_for_result = np.zeros((0, 6), dtype=np.float32)
        if payload.confs.size > 0 and payload.boxes_xyxy.shape[0] == payload.confs.shape[0]:
            boxes_for_result = np.concatenate(
                [payload.boxes_xyxy, payload.confs[:, None], np.zeros((payload.confs.shape[0], 1), dtype=np.float32)],
                axis=1,
            ).astype(np.float32, copy=False)
        result = Results(orig_img, path=img_path, names=self.model.names, boxes=boxes_for_result, masks=None)
        setattr(result, '_tta_cpu_retina_payload', payload)
        return result

    SegmentationPredictor.construct_result = _tta_cpu_retina_construct_result
    _ULTRALYTICS_CPU_RETINA_PATCHED = True
    print(
        'Deferred CPU retina masks enabled: Ultralytics GPU mask upsampling is bypassed; '
        'compact mask protos/coefficients are copied and reconstructed in prediction-result workers.'
    )
    return True


_ULTRALYTICS_GPU_PROTO_UNION_PATCHED = False
_ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT_FOR_GPU: Optional[object] = None


def _build_gpu_flattened_payload_from_proto(pred: object, img: object, proto: object) -> Optional['GpuFlattenedRetinaPayload']:
    """v13.3.0 (R9): build the flattened union payload at PROTO resolution.

    Instead of letting Ultralytics materialize the (n, imgsz, imgsz) float retina stack that the
    pipeline immediately reduces to one plane, the per-instance mask logits are combined from
    the protos, box-cropped at proto scale, reduced with a single max-logit plane, and ONE plane
    is bilinearly upsampled to the network raster and thresholded at 0 (union(bilinear(l_i)>0)
    becomes bilinear(max_i l_i)>0 — identical away from instance box edges, sub-voxel there).
    Instance-level --min_conf (single-angle fast path) and the optional per-pixel max-confidence
    plane are applied at proto resolution. Returns None on any unexpected condition so the
    caller falls back to the unpatched Ultralytics path.
    """
    try:
        import torch  # type: ignore
        import torch.nn.functional as F  # type: ignore
    except Exception:
        return None
    if not isinstance(pred, torch.Tensor) or not isinstance(proto, torch.Tensor):
        return None
    try:
        proto_t = proto
        if proto_t.ndim == 4 and int(proto_t.shape[0]) == 1:
            proto_t = proto_t[0]
        if proto_t.ndim != 3 or pred.ndim != 2:
            return None
        img_h = int(img.shape[2])
        img_w = int(img.shape[3])
        if img_h <= 0 or img_w <= 0:
            return None
        c, mh, mw = (int(proto_t.shape[0]), int(proto_t.shape[1]), int(proto_t.shape[2]))
        if c <= 0 or mh <= 0 or mw <= 0 or int(pred.shape[1]) < 6 + c:
            return None

        fastpath = single_angle_gpu_fastpath()
        fastpath_min_conf = None if fastpath is None else float(fastpath[0])
        fastpath_min_radius = 0.0 if fastpath is None else float(fastpath[1])
        run_gpu_cleanup = bool(
            fastpath is not None and gpu_retina_cleanup_enabled() and float(fastpath_min_radius) > 0.0
        )

        pred_t = pred
        n = int(pred_t.shape[0])
        confs_t = pred_t[:, 4].to(torch.float32).reshape(-1) if n > 0 else None

        # Single-angle fast path: drop low-confidence instances before the union (exact
        # instance-level --min_conf, mirroring _try_flatten_gpu_retina_result).
        min_conf_applied = False
        if (
            fastpath_min_conf is not None
            and float(fastpath_min_conf) > 0.0
            and confs_t is not None
            and n > 0
        ):
            keep = confs_t >= float(fastpath_min_conf)
            pred_t = pred_t[keep]
            confs_t = confs_t[keep]
            n = int(pred_t.shape[0])
            min_conf_applied = True

        if n <= 0:
            return GpuFlattenedRetinaPayload(
                union_gpu=None, conf_gpu=None, instance_count=0,
                min_conf_applied=min_conf_applied, run_gpu_cleanup=run_gpu_cleanup,
                gpu_min_radius=float(fastpath_min_radius),
            )

        coeffs = pred_t[:, 6:6 + c].to(torch.float32)
        logits = (coeffs @ proto_t.to(torch.float32).view(c, -1)).view(n, mh, mw)

        # Box crop at proto scale (Ultralytics crop_mask semantics: r >= x1 and r < x2).
        boxes = pred_t[:, :4].to(torch.float32)
        sx = float(mw) / float(img_w)
        sy = float(mh) / float(img_h)
        x1 = (boxes[:, 0] * sx).view(-1, 1, 1)
        y1 = (boxes[:, 1] * sy).view(-1, 1, 1)
        x2 = (boxes[:, 2] * sx).view(-1, 1, 1)
        y2 = (boxes[:, 3] * sy).view(-1, 1, 1)
        cols = torch.arange(mw, device=logits.device, dtype=torch.float32).view(1, 1, -1)
        rows = torch.arange(mh, device=logits.device, dtype=torch.float32).view(1, -1, 1)
        inside = (cols >= x1) & (cols < x2) & (rows >= y1) & (rows < y2)

        # Crop fill: a bounded "confident background" logit rather than -inf. An extreme fill
        # bleeds through the bilinear upsample and erodes up to a full proto cell of box
        # interior; -6 (sigmoid ~0.0025) keeps real logit zero-crossings exact while limiting
        # crop-edge bleed to ~1 px at the network raster. Ultralytics' own non-retina path
        # (ops.process_mask) also crops at proto resolution, with a multiplicative zero fill.
        neg_fill = logits.new_full((), -6.0)
        max_logit = torch.where(inside, logits, neg_fill).amax(dim=0)  # (mh, mw)
        union_gpu = (
            F.interpolate(
                max_logit.reshape(1, 1, mh, mw), size=(img_h, img_w),
                mode='bilinear', align_corners=False,
            ).reshape(img_h, img_w) > 0.0
        ).to(torch.float32)

        conf_gpu = None
        if confs_t is not None and gpu_flatten_conf_tracking_enabled():
            inst_proto = (logits > 0.0) & inside
            conf_plane = (confs_t.clamp(0.0, 1.0).view(-1, 1, 1) * inst_proto).amax(dim=0)
            conf_gpu = F.interpolate(
                conf_plane.reshape(1, 1, mh, mw), size=(img_h, img_w), mode='nearest',
            ).reshape(img_h, img_w)

        ready_event = None
        try:
            if union_gpu.is_cuda:
                ready_event = torch.cuda.Event()
                ready_event.record(torch.cuda.current_stream(union_gpu.device))
        except Exception:
            ready_event = None
        return GpuFlattenedRetinaPayload(
            union_gpu=union_gpu, conf_gpu=conf_gpu, instance_count=int(n),
            min_conf_applied=min_conf_applied, run_gpu_cleanup=run_gpu_cleanup,
            gpu_min_radius=float(fastpath_min_radius),
            ready_event=ready_event,
        )
    except Exception:
        return None


def ensure_gpu_retina_proto_union_predictor_patch() -> bool:
    """v13.3.0 (R9): patch Ultralytics segmentation postprocess for GPU retina mode.

    Mirrors ensure_cpu_retina_mask_predictor_patch: construct_result returns a lightweight
    Results carrying a prebuilt GpuFlattenedRetinaPayload (union computed at proto resolution)
    instead of an (n, imgsz, imgsz) retina-mask stack. Any failure falls back per-frame to the
    original Ultralytics construct_result.
    """
    global _ULTRALYTICS_GPU_PROTO_UNION_PATCHED, _ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT_FOR_GPU

    if cpu_retina_masks_enabled() or not gpu_retina_proto_union_enabled():
        return False
    if _ULTRALYTICS_GPU_PROTO_UNION_PATCHED:
        return True

    try:
        from ultralytics.engine.results import Results  # type: ignore
        from ultralytics.models.yolo.segment.predict import SegmentationPredictor  # type: ignore
    except Exception as exc:
        print(f'Warning: GPU proto-union predictor patch could not be installed; keeping Ultralytics retina masks ({exc})')
        return False

    original_construct_result = SegmentationPredictor.construct_result
    _ULTRALYTICS_ORIGINAL_SEG_CONSTRUCT_RESULT_FOR_GPU = original_construct_result

    def _tta_gpu_proto_union_construct_result(self, pred, img, orig_img, img_path, proto):  # type: ignore[no-untyped-def]
        if cpu_retina_masks_enabled() or not gpu_retina_proto_union_enabled():
            return original_construct_result(self, pred, img, orig_img, img_path, proto)
        payload = _build_gpu_flattened_payload_from_proto(pred, img, proto)
        if payload is None:
            return original_construct_result(self, pred, img, orig_img, img_path, proto)
        result = Results(orig_img, path=img_path, names=self.model.names, boxes=None, masks=None)
        setattr(result, '_tta_gpu_flattened_payload', payload)
        return result

    SegmentationPredictor.construct_result = _tta_gpu_proto_union_construct_result
    _ULTRALYTICS_GPU_PROTO_UNION_PATCHED = True
    print(
        'GPU proto-resolution retina union enabled (v13.3.0 R9): per-frame unions are reduced at '
        'proto scale and one plane is upsampled, bypassing the (n, imgsz, imgsz) retina stack.'
    )
    return True


def _affine_theta_for_grid_sample(
    M_out_to_native: np.ndarray, out_size: int, native_h: int, native_w: int,
) -> np.ndarray:
    """Convert a cv2 pixel-space affine into a torch affine_grid theta (align_corners=False).

    cv2.warpAffine(src(out_size,out_size), M_out_to_native, dsize=(native_w, native_h)) maps each
    native output pixel back to a source (out-size) pixel using the inverse of M_out_to_native, then
    samples (nearest). torch.nn.functional.affine_grid expects theta to map normalized OUTPUT coords
    to normalized INPUT coords. theta = N_in @ Minv_pix @ P_out, where:
      P_out : normalized native output -> native output pixel
      Minv_pix : native output pixel -> source (out-size) pixel (inverse of M_out_to_native)
      N_in : source pixel -> normalized source coords
    """
    M = np.asarray(M_out_to_native, dtype=np.float64).reshape(2, 3)
    M3 = np.vstack([M, [0.0, 0.0, 1.0]])
    Minv = np.linalg.inv(M3)  # native pixel -> out-size source pixel (3x3)
    nh = float(native_h)
    nw = float(native_w)
    os_ = float(out_size)
    # normalized native output (onx,ony in [-1,1], align_corners=False) -> native output pixel (cx,ry)
    P_out = np.array([
        [nw / 2.0, 0.0, nw / 2.0 - 0.5],
        [0.0, nh / 2.0, nh / 2.0 - 0.5],
        [0.0, 0.0, 1.0],
    ], dtype=np.float64)
    # source pixel (sx,sy) -> normalized source coords (align_corners=False)
    N_in = np.array([
        [2.0 / os_, 0.0, 1.0 / os_ - 1.0],
        [0.0, 2.0 / os_, 1.0 / os_ - 1.0],
        [0.0, 0.0, 1.0],
    ], dtype=np.float64)
    theta3 = N_in @ Minv @ P_out
    return theta3[:2].astype(np.float32, copy=False)


def _affine_theta_from_dst_to_src(
    M_dst_to_src: np.ndarray, src_h: int, src_w: int, dst_h: int, dst_w: int,
) -> np.ndarray:
    """v13.3.0: theta for grid_sample given the dst-pixel -> src-pixel affine directly.

    Generalizes _affine_theta_for_grid_sample to non-square sources (used by the GPU render
    engine, whose AffineSpec already stores M_out_to_src — no inversion needed). Matches
    cv2.warpAffine(src, inv(M_dst_to_src), dsize=(dst_w, dst_h)) pixel-center conventions with
    align_corners=False.
    """
    M3 = np.vstack([np.asarray(M_dst_to_src, dtype=np.float64).reshape(2, 3), [0.0, 0.0, 1.0]])
    dh = float(dst_h)
    dw = float(dst_w)
    sh = float(src_h)
    sw = float(src_w)
    P_dst = np.array([
        [dw / 2.0, 0.0, dw / 2.0 - 0.5],
        [0.0, dh / 2.0, dh / 2.0 - 0.5],
        [0.0, 0.0, 1.0],
    ], dtype=np.float64)
    N_src = np.array([
        [2.0 / sw, 0.0, 1.0 / sw - 1.0],
        [0.0, 2.0 / sh, 1.0 / sh - 1.0],
        [0.0, 0.0, 1.0],
    ], dtype=np.float64)
    theta3 = N_src @ M3 @ P_dst
    return theta3[:2].astype(np.float32, copy=False)


def _warp_matrix_is_identity(M: np.ndarray, atol: float = 1e-5) -> bool:
    """v13.3.0 (R8): True when a cv2-style 2x3 affine is the identity within tolerance."""
    try:
        m = np.asarray(M, dtype=np.float64).reshape(2, 3)
    except Exception:
        return False
    return bool(
        abs(m[0, 0] - 1.0) <= atol and abs(m[1, 1] - 1.0) <= atol
        and abs(m[0, 1]) <= atol and abs(m[1, 0]) <= atol
        and abs(m[0, 2]) <= atol and abs(m[1, 2]) <= atol
    )


# v13.3.0 (R8): affine grids are constant per (matrix, geometry, device) — one small LRU
# replaces a fresh full-resolution affine_grid allocation per frame.
_AFFINE_GRID_CACHE: 'OrderedDict[Tuple[object, ...], object]' = OrderedDict()
_AFFINE_GRID_CACHE_LOCK = threading.Lock()


def _affine_grid_cache_entries() -> int:
    return max(1, _env_int('YOLO_TTA_GPU_WARP_GRID_CACHE_ENTRIES', 12))


def _get_cached_affine_grid(theta_np: np.ndarray, dst_h: int, dst_w: int, device: object) -> object:
    import torch  # type: ignore
    import torch.nn.functional as F  # type: ignore
    key = (
        str(device), int(dst_h), int(dst_w),
        tuple(np.round(np.asarray(theta_np, dtype=np.float64).reshape(-1), 9).tolist()),
    )
    with _AFFINE_GRID_CACHE_LOCK:
        cached = _AFFINE_GRID_CACHE.get(key)
        if cached is not None:
            _AFFINE_GRID_CACHE.move_to_end(key)
            return cached
    theta = torch.from_numpy(np.asarray(theta_np, dtype=np.float32)).to(device=device).reshape(1, 2, 3)
    grid = F.affine_grid(theta, [1, 1, int(dst_h), int(dst_w)], align_corners=False)
    # The grid is built once on the creating thread's stream but read from arbitrary streams
    # afterwards; synchronize the producing stream once so later cross-stream reads are ordered.
    try:
        torch.cuda.current_stream(grid.device).synchronize()
    except Exception:
        pass
    with _AFFINE_GRID_CACHE_LOCK:
        _AFFINE_GRID_CACHE[key] = grid
        _AFFINE_GRID_CACHE.move_to_end(key)
        while len(_AFFINE_GRID_CACHE) > _affine_grid_cache_entries():
            _AFFINE_GRID_CACHE.popitem(last=False)
    return grid


# v13.3.0 (R18): per-thread side stream + pinned staging buffers for the GPU postprocess tail.
_GPU_POSTPROCESS_TLS = threading.local()


def _gpu_postprocess_side_stream(torch_mod: object, device: object) -> Optional[object]:
    """Return this thread's postprocess CUDA stream for ``device`` (None when disabled)."""
    if not gpu_postprocess_side_stream_enabled():
        return None
    try:
        if device is None or getattr(device, 'type', '') != 'cuda':
            return None
        streams = getattr(_GPU_POSTPROCESS_TLS, 'streams', None)
        if streams is None:
            streams = {}
            _GPU_POSTPROCESS_TLS.streams = streams
        dev_key = int(getattr(device, 'index', 0) or 0)
        stream = streams.get(dev_key)
        if stream is None:
            stream = torch_mod.cuda.Stream(device=device)
            streams[dev_key] = stream
        return stream
    except Exception:
        return None


def _tensor_to_host_numpy(torch_mod: object, tensor: object, stream: Optional[object]) -> np.ndarray:
    """Copy a small device tensor to host, via this thread's pinned staging buffer when enabled.

    The returned array aliases a per-thread reusable pinned buffer (one per dtype); callers must
    consume it before requesting another transfer of the same dtype on the same thread.
    """
    t = tensor.contiguous()
    if not gpu_postprocess_pinned_d2h_enabled():
        return t.cpu().numpy()
    try:
        pools = getattr(_GPU_POSTPROCESS_TLS, 'pinned', None)
        if pools is None:
            pools = {}
            _GPU_POSTPROCESS_TLS.pinned = pools
        dtype_key = str(t.dtype)
        numel = int(t.numel())
        buf = pools.get(dtype_key)
        if buf is None or int(buf.numel()) < numel:
            buf = torch_mod.empty((numel,), dtype=t.dtype, pin_memory=True)
            pools[dtype_key] = buf
        view = buf[:numel].view(t.shape)
        view.copy_(t, non_blocking=True)
        if stream is not None:
            stream.synchronize()
        else:
            torch_mod.cuda.current_stream(t.device).synchronize()
        return view.numpy()
    except Exception:
        return t.cpu().numpy()


def _torch_warp_planes_to_native(
    planes: 'Sequence[object]', M_out_to_native: np.ndarray, out_size: int, native_h: int, native_w: int,
) -> 'List[object]':
    """v13.1.0 (#2.2): nearest affine warp of one or more co-located planes to view-native space.

    Each plane is a torch tensor (Hr, Wr) on the same device/shape; planes are resized to
    (out_size, out_size) with nearest sampling if needed, stacked on the channel axis, and warped to
    (native_h, native_w) with a SINGLE grid_sample (nearest, zero-padded). Matches
    cv2.warpAffine(..., INTER_NEAREST, BORDER_CONSTANT, 0) up to half-pixel rounding ties.
    v13.3.0 (R8): identity warps (native == out and M == I, e.g. every imgsz-folded radial frame
    at --angle 0) skip the sample entirely, and non-identity warps reuse one cached grid per
    (matrix, geometry) instead of rebuilding a full-resolution affine_grid per frame. Returns a
    list of float32 (native_h, native_w) tensors on the device.
    """
    import torch  # type: ignore
    import torch.nn.functional as F  # type: ignore
    prepared = []
    for p in planes:
        t = p if p.dtype == torch.float32 else p.to(torch.float32)
        if int(t.shape[0]) != int(out_size) or int(t.shape[1]) != int(out_size):
            t = F.interpolate(
                t.reshape(1, 1, int(t.shape[0]), int(t.shape[1])),
                size=(int(out_size), int(out_size)), mode='nearest',
            ).reshape(int(out_size), int(out_size))
        prepared.append(t)
    if (
        int(native_h) == int(out_size) and int(native_w) == int(out_size)
        and _warp_matrix_is_identity(M_out_to_native)
    ):
        return prepared
    inp = torch.stack(prepared, dim=0).unsqueeze(0)  # (1, K, out_size, out_size)
    theta_np = _affine_theta_for_grid_sample(M_out_to_native, int(out_size), int(native_h), int(native_w))
    grid = _get_cached_affine_grid(theta_np, int(native_h), int(native_w), inp.device)
    out = F.grid_sample(inp, grid, mode='nearest', padding_mode='zeros', align_corners=False)
    return [out[0, k] for k in range(int(out.shape[1]))]


def _min_radius_filter_ndimage(xp, ndi, mask_bool, min_radius: float):
    """Backend-agnostic --min_radius filter mirroring _filter_connected_components_by_min_radius_scipy.

    Works with (numpy, scipy.ndimage) on the CPU or (cupy, cupyx.scipy.ndimage) on the GPU. Keeps
    connected components whose maximum distance-transform value (radius) is >= min_radius.
    """
    if float(min_radius) <= 0.0:
        return mask_bool
    structure = xp.ones((3, 3), dtype=bool)
    labels2d, num = ndi.label(mask_bool, structure=structure)
    num_i = int(num)
    if num_i <= 0:
        return xp.zeros(mask_bool.shape, dtype=bool)
    label_ids = xp.arange(1, num_i + 1)
    dist = ndi.distance_transform_edt(mask_bool)
    radii = xp.asarray(ndi.maximum(dist, labels=labels2d, index=label_ids))
    keep_lookup = xp.zeros((num_i + 1,), dtype=bool)
    keep_lookup[1:] = radii >= float(min_radius)
    return keep_lookup[labels2d]


def _fill_holes_ndimage(xp, ndi, mask_bool):
    """Backend-agnostic 2D hole fill mirroring _fill_holes_2d_scipy (binary_fill_holes)."""
    return ndi.binary_fill_holes(mask_bool)


def _try_import_cupy_ndimage():
    """Return (cupy, cupyx.scipy.ndimage) when both import and a CUDA device is available, else None."""
    try:
        import cupy as cp  # type: ignore
        import cupyx.scipy.ndimage as cpx_ndi  # type: ignore
    except Exception:
        return None
    try:
        if int(cp.cuda.runtime.getDeviceCount()) <= 0:
            return None
    except Exception:
        return None
    return cp, cpx_ndi


def _try_flatten_gpu_retina_result(r, masks_data: object) -> Optional[GpuFlattenedRetinaPayload]:
    """v13.1.0 (#2.2/#2.3): reduce a GPU retina-mask stack to GPU-resident union + max-conf planes.

    masks_data is r.masks.data, expected to be a torch tensor of shape (n, Hr, Wr). The union (OR)
    and per-pixel max confidence are computed on the GPU and KEPT on the GPU so the affine warp to
    view-native space (and, for the single-angle fast path, --min_radius + hole fill) can also run on
    the GPU. When the single-angle fast path is active (#2.3), instances below --min_conf are dropped
    on the GPU before the reduction so the union is already confidence-filtered. Returns None on any
    unexpected condition so the caller falls back to the legacy whole-stack copy.
    """
    try:
        import torch  # type: ignore
    except Exception:
        return None
    if not isinstance(masks_data, torch.Tensor):
        return None
    try:
        masks = masks_data
        if masks.ndim != 3:
            return None
        h = int(masks.shape[1])
        w = int(masks.shape[2])
        n = int(masks.shape[0])

        fastpath = single_angle_gpu_fastpath()
        fastpath_min_conf = None if fastpath is None else float(fastpath[0])
        fastpath_min_radius = 0.0 if fastpath is None else float(fastpath[1])
        # v13.3.0 (R8): the per-frame GPU hole fill is gone (the volume-level pass fills once,
        # in spec order), so GPU cleanup only has work when a positive --min_radius is set.
        run_gpu_cleanup = bool(
            fastpath is not None and gpu_retina_cleanup_enabled() and float(fastpath_min_radius) > 0.0
        )

        # Pull confidences onto the mask's device as a (n,) float tensor.
        confs_t = None
        boxes = getattr(r, 'boxes', None)
        if boxes is not None and getattr(boxes, 'conf', None) is not None:
            confs_t = boxes.conf
            try:
                confs_t = confs_t.detach()
            except Exception:
                pass
            confs_t = confs_t.to(device=masks.device, dtype=torch.float32).reshape(-1)
            if int(confs_t.shape[0]) != n:
                # Length mismatch: fall back rather than guessing an alignment.
                return None

        masks_bool = masks > 0

        # #2.3 single-angle fast path: drop low-confidence instances on the GPU (exact --min_conf at
        # instance granularity) before the union/flatten.
        min_conf_applied = False
        if (
            fastpath_min_conf is not None
            and float(fastpath_min_conf) > 0.0
            and confs_t is not None
            and n > 0
        ):
            keep = confs_t >= float(fastpath_min_conf)
            masks_bool = masks_bool[keep]
            confs_t = confs_t[keep]
            n = int(masks_bool.shape[0])
            min_conf_applied = True

        if n <= 0:
            # v13.2.5 (speed #7): an empty frame needs no zero planes, no warp, no GPU cleanup,
            # and no D2H — union_gpu=None short-circuits the frame processor immediately.
            return GpuFlattenedRetinaPayload(
                union_gpu=None, conf_gpu=None, instance_count=0,
                min_conf_applied=min_conf_applied, run_gpu_cleanup=run_gpu_cleanup,
                gpu_min_radius=float(fastpath_min_radius),
            )

        union_gpu = masks_bool.any(dim=0).to(torch.float32)  # (h, w) 0/1
        # v13.2.5 (speed #7): with --min_conf 0 no confidence volume exists anywhere downstream,
        # so skip the per-frame (n,H,W) float transient + amax reduction entirely.
        if confs_t is not None and gpu_flatten_conf_tracking_enabled():
            # Out-of-place clamp: confs_t may be a view onto r.boxes.conf (detach()/to()/reshape()
            # can share storage), so never mutate it in place.
            cf = confs_t.clamp(0.0, 1.0)
            # Per-pixel max confidence among covering instances (pre-quantization, in [0,1]). quantize
            # is monotonic so a later quantize matches the CPU per-instance accumulation. The
            # float<-bool promotion in the multiply keeps a single (n,H,W) transient (no separate cast).
            conf_gpu = (cf.view(-1, 1, 1) * masks_bool).amax(dim=0)
        else:
            conf_gpu = None
        # v13.3.0 (R18): record readiness on the producing stream so the postprocess side
        # stream can wait on the event instead of the whole default stream.
        ready_event = None
        try:
            if union_gpu.is_cuda:
                ready_event = torch.cuda.Event()
                ready_event.record(torch.cuda.current_stream(union_gpu.device))
        except Exception:
            ready_event = None
        return GpuFlattenedRetinaPayload(
            union_gpu=union_gpu, conf_gpu=conf_gpu, instance_count=int(n),
            min_conf_applied=min_conf_applied, run_gpu_cleanup=run_gpu_cleanup,
            gpu_min_radius=float(fastpath_min_radius),
            ready_event=ready_event,
        )
    except Exception:
        return None


def _extract_result_masks_and_confs(r) -> Tuple[Optional[object], Optional[np.ndarray]]:
    """Detach one streamed YOLO result into CPU-owned data for asynchronous postprocess."""
    # v13.3.0 (R9): the GPU proto-union construct_result patch attaches a prebuilt flattened
    # payload (union already reduced at proto resolution); nothing remains to extract.
    prebuilt_payload = getattr(r, '_tta_gpu_flattened_payload', None)
    if isinstance(prebuilt_payload, GpuFlattenedRetinaPayload):
        return prebuilt_payload, None

    deferred_payload = getattr(r, '_tta_deferred_cpu_retina_payload', None)
    if isinstance(deferred_payload, DeferredCpuRetinaMaskPayload):
        payload = _realize_deferred_cpu_retina_payload(deferred_payload)
        return payload, np.ascontiguousarray(payload.confs, dtype=np.float32)

    cpu_payload = getattr(r, '_tta_cpu_retina_payload', None)
    if isinstance(cpu_payload, CpuRetinaMaskPayload):
        return cpu_payload, np.ascontiguousarray(cpu_payload.confs, dtype=np.float32)

    if getattr(r, 'masks', None) is None or r.masks is None or r.masks.data is None:
        return None, None

    masks_data = r.masks.data  # (n,h,w)

    # v13.1.0 (#2.2/#2.3): in GPU retina mode, flatten (n,H,W) -> union + max-conf on the GPU and copy
    # only those 2 planes. The flattened payload carries its own confidence plane, so the second
    # return value is None. Falls back to the legacy whole-stack copy below on any failure.
    if gpu_retina_flatten_enabled() and not cpu_retina_masks_enabled():
        flattened = _try_flatten_gpu_retina_result(r, masks_data)
        if flattened is not None:
            return flattened, None

    try:
        masks_np = np.asarray(masks_data.detach().cpu().numpy(), dtype=np.uint8)
    except Exception:
        try:
            masks_np = np.asarray(masks_data.cpu().numpy(), dtype=np.uint8)
        except Exception:
            masks_np = np.asarray(masks_data, dtype=np.uint8)

    if masks_np.ndim != 3 or int(masks_np.shape[0]) <= 0:
        return None, None

    num_inst = int(masks_np.shape[0])
    if getattr(r, 'boxes', None) is not None and r.boxes is not None and getattr(r.boxes, 'conf', None) is not None:
        try:
            confs_np = np.asarray(r.boxes.conf.detach().cpu().numpy(), dtype=np.float32)
        except Exception:
            try:
                confs_np = np.asarray(r.boxes.conf.cpu().numpy(), dtype=np.float32)
            except Exception:
                confs_np = np.asarray(r.boxes.conf, dtype=np.float32)
    else:
        confs_np = np.zeros((num_inst,), dtype=np.float32)

    if confs_np.ndim == 0:
        confs_np = np.full((num_inst,), float(confs_np), dtype=np.float32)
    elif int(confs_np.shape[0]) != num_inst:
        confs_np = np.resize(confs_np, (num_inst,)).astype(np.float32, copy=False)

    return np.ascontiguousarray(masks_np), np.ascontiguousarray(confs_np)


def _process_cpu_retina_prediction_frame(
    idx: int,
    payload: CpuRetinaMaskPayload,
    out_size: int,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    slice_lock: Optional[threading.Lock] = None,
) -> Tuple[int, int]:
    """CPU equivalent of retina_masks=True accumulation without allocating GPU HxW masks."""
    frame_union, frame_confmap, kept_instances = _accumulate_cpu_retina_payload_to_prediction_frame(
        payload,
        int(out_size),
    )
    if int(kept_instances) <= 0 or not np.any(frame_union):
        return int(kept_instances), 0

    native_union = cv2.warpAffine(
        frame_union,
        M_out_to_native,
        dsize=(native_w, native_h),
        flags=cv2.INTER_NEAREST,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    ) > 0

    native_conf: Optional[np.ndarray] = None
    if frame_confmap is not None and np.any(frame_confmap):
        native_conf = cv2.warpAffine(
            frame_confmap,
            M_out_to_native,
            dsize=(native_w, native_h),
            flags=cv2.INTER_NEAREST,
            borderMode=cv2.BORDER_CONSTANT,
            borderValue=0,
        ).astype(np.uint8, copy=False)

    def _write_native_outputs() -> None:
        if np.any(native_union):
            view_union_mm[int(idx), :, :] |= native_union.astype(np.uint8, copy=False)

        if view_confmap_mm is not None and native_conf is not None and np.any(native_conf):
            conf_slice = view_confmap_mm[int(idx)]
            np.maximum(conf_slice, native_conf, out=conf_slice)

    if slice_lock is None:
        _write_native_outputs()
    else:
        with slice_lock:
            _write_native_outputs()

    return int(kept_instances), 1


def gpu_device_union_enabled() -> bool:
    """v13.3.2 (R21): accumulate per-task native unions on device; one chunked D2H per task."""
    return _env_flag('YOLO_TTA_GPU_DEVICE_UNION', True)


def gpu_device_hole_fill_enabled() -> bool:
    """v13.3.3 (S2): 2D-hole-fill the per-task device union on the GPU before the flush.

    Valid only when --min_conf and --min_radius have no work (spec order is conf -> radius ->
    hole fill) and every frame of the task accumulated on device; the scheduler additionally
    skips the CPU per-view hole-fill pass only when EVERY slice of the view was device-filled.
    """
    return _env_flag('YOLO_TTA_GPU_HOLE_FILL', True)


def gpu_union_flush_overlap_enabled() -> bool:
    """Retire a worker task's device union on a background D2H/host-copy lane.

    The multi-GPU worker keeps at most one retiring accumulator while the main worker
    thread starts inference for the next queued task with a fresh accumulator.  Result
    publication remains ordered after the retiring flush completes.  Single-process
    callers retain the synchronous path.
    """
    return _env_flag('YOLO_TTA_GPU_UNION_FLUSH_OVERLAP', True)


_GPU_UNION_FLUSH_EXECUTOR: Optional[ThreadPoolExecutor] = None
_GPU_UNION_FLUSH_EXECUTOR_LOCK = threading.Lock()


def _gpu_union_flush_executor() -> ThreadPoolExecutor:
    """One copy/host-merge retirement lane per process (therefore per GPU worker)."""
    global _GPU_UNION_FLUSH_EXECUTOR
    with _GPU_UNION_FLUSH_EXECUTOR_LOCK:
        if _GPU_UNION_FLUSH_EXECUTOR is None:
            _GPU_UNION_FLUSH_EXECUTOR = ThreadPoolExecutor(
                max_workers=1, thread_name_prefix='gpu-union-flush',
            )
        return _GPU_UNION_FLUSH_EXECUTOR


def _shutdown_gpu_union_flush_executor() -> None:
    global _GPU_UNION_FLUSH_EXECUTOR
    with _GPU_UNION_FLUSH_EXECUTOR_LOCK:
        executor = _GPU_UNION_FLUSH_EXECUTOR
        _GPU_UNION_FLUSH_EXECUTOR = None
    if executor is not None:
        try:
            executor.shutdown(wait=True, cancel_futures=False)
        except TypeError:
            executor.shutdown(wait=True)


# v13.3.3 (S2): reusable pinned staging buffers for device-union flushes. The old path did one
# ~chunk-sized cudaHostAlloc + free per task (~70 tasks x ~0.6 GB); this keeps a small pool per
# process (workers flush one task at a time, so the pool normally holds a single buffer).
_PINNED_U8_BUFFER_POOL: List[object] = []
_PINNED_U8_BUFFER_POOL_LOCK = threading.Lock()
_PINNED_U8_BUFFER_POOL_MAX = 4


def _acquire_pinned_u8_buffer(torch_mod: object, numel: int) -> object:
    need = max(1, int(numel))
    with _PINNED_U8_BUFFER_POOL_LOCK:
        for i, buf in enumerate(_PINNED_U8_BUFFER_POOL):
            if int(buf.numel()) >= need:
                return _PINNED_U8_BUFFER_POOL.pop(i)
    return torch_mod.empty((need,), dtype=torch_mod.uint8, pin_memory=True)


def _release_pinned_u8_buffer(buf: object) -> None:
    if buf is None:
        return
    with _PINNED_U8_BUFFER_POOL_LOCK:
        _PINNED_U8_BUFFER_POOL.append(buf)
        # Keep the largest buffers; drop the smallest beyond the cap.
        if len(_PINNED_U8_BUFFER_POOL) > _PINNED_U8_BUFFER_POOL_MAX:
            _PINNED_U8_BUFFER_POOL.sort(key=lambda b: int(b.numel()))
            del _PINNED_U8_BUFFER_POOL[0]


class _DeviceUnionAccumulator:
    """v13.3.2 (R21): per-task on-device native-space union (+confmap) accumulation.

    Postprocess side-stream threads write each frame's warped native plane into a
    device-resident uint8 volume slice instead of a per-frame pinned D2H + host ``|=``; the task
    then performs ONE chunked pinned D2H into the host result windows. Each slice index is
    written at most once per task (single-angle contract; padded synthetic frames repeat a real
    slice with identical content), so plain assignment is race-free across threads.

    v13.3.3 (S2): per-slice ``written`` tracking makes the flush precise — device-written slices
    are plain-copied (their destination rows started zeroed and nothing else wrote them),
    slices that fell back to host processing are skipped (their device rows are zero, and the
    host write already happened) — and the flush ping-pongs two halves of a pooled pinned
    buffer so the D2H of chunk i+1 overlaps the host merge of chunk i. ``fill_holes_2d`` can
    hole-fill the accumulated union on device before the flush (see gpu_device_hole_fill_enabled).
    """

    def __init__(self, torch_mod: object, device: object, num_frames: int, native_h: int, native_w: int, want_conf: bool) -> None:
        self.torch = torch_mod
        self.device = device
        self.union_dev = torch_mod.zeros(
            (int(num_frames), int(native_h), int(native_w)), dtype=torch_mod.uint8, device=device,
        )
        self.conf_dev = (
            torch_mod.zeros((int(num_frames), int(native_h), int(native_w)), dtype=torch_mod.uint8, device=device)
            if bool(want_conf) else None
        )
        # C3 device-compacted generic payloads write one scalar per slice. Static/legacy
        # payloads leave zero here and continue returning their host-known stats normally.
        self.prediction_counts_dev = torch_mod.zeros(
            (int(num_frames),), dtype=torch_mod.int32, device=device,
        )
        # Per-slice device-write tracking (GIL-atomic independent cells; indices are disjoint
        # across postprocess threads). host_written records any frame that bypassed the device
        # union (CPU fallback / cupy-cleanup frames) and wrote the host window directly.
        self.written = np.zeros((int(num_frames),), dtype=bool)
        self.host_written = False

    def mark_host_write(self) -> None:
        self.host_written = True

    def write_frame(
        self,
        idx: int,
        union_bool_t: object,
        conf_u8_t: Optional[object] = None,
        prediction_count_dev: Optional[object] = None,
    ) -> None:
        # Runs on the calling thread's side stream (inside the frame processor's stream ctx);
        # slice indices are disjoint across threads, so no lock is needed.
        self.union_dev[int(idx)] = union_bool_t.to(self.torch.uint8)
        if self.conf_dev is not None and conf_u8_t is not None:
            self.conf_dev[int(idx)] = conf_u8_t
        if prediction_count_dev is not None:
            self.prediction_counts_dev[int(idx)].copy_(
                prediction_count_dev.reshape(-1)[0], non_blocking=True,
            )
        self.written[int(idx)] = True

    def take_device_prediction_stats(self) -> Tuple[int, int]:
        """Read C3 prediction/frame totals once after every side-stream frame has settled."""
        if self.prediction_counts_dev is None:
            return 0, 0
        try:
            self.torch.cuda.synchronize(self.device)
            counts = self.prediction_counts_dev
            stats = self.torch.stack([
                counts.to(self.torch.int64).sum(),
                (counts > 0).to(self.torch.int64).sum(),
            ]).cpu().numpy()
            return int(stats[0]), int(stats[1])
        except Exception:
            return 0, 0

    def fill_holes_2d(self) -> int:
        """v13.3.3 (S2): fill enclosed 2D background per accumulated slice, ON DEVICE, in place.

        One cupy ``label`` call per sub-block with a z-disconnected structure (3x3x3 with only
        the in-plane 4-neighbourhood set) labels every slice's background independently in a
        single kernel pass; labels touching a slice border are background, the rest are holes.
        Matches the CPU path's scipy/cv2 4-connected background semantics. Returns the number
        of frames now hole-filled (== num_frames), or 0 when skipped or failed (any host-side
        frame, cupy unavailable, VRAM pressure, or any error -> the CPU per-view pass runs).
        """
        torch = self.torch
        if self.union_dev is None:
            return 0
        if bool(self.host_written):
            # Some frame bypassed the device union and wrote the host window directly; its
            # device slice is zero, so a device fill would miss it. Report 0 so the CPU
            # per-view pass covers the whole view. Frames that are merely EMPTY (no payload,
            # no write anywhere) are fine: filling an empty slice is a no-op on both paths.
            return 0
        cp_mod = _try_import_cupy_ndimage()
        if cp_mod is None:
            return 0
        cp, cpx_ndi = cp_mod
        n, h, w = (int(x) for x in self.union_dev.shape)
        if n <= 0 or h < 3 or w < 3:
            return 0
        try:
            # Order every postprocess side-stream's writes before the cupy reads.
            torch.cuda.synchronize(self.device)
            dev_idx = int(getattr(self.device, 'index', 0) or 0)
            block = max(1, _env_int('YOLO_TTA_GPU_HOLE_FILL_BLOCK', 64))
            with cp.cuda.Device(dev_idx):
                while block > 1:
                    need = int(block) * h * w * 6 + 512 * 1024 * 1024  # int32 labels + 2x bool
                    free_bytes, _total = torch.cuda.mem_get_info(self.device)
                    if int(free_bytes) >= int(need):
                        break
                    block //= 2
                structure = cp.zeros((3, 3, 3), dtype=cp.bool_)
                structure[1, 1, 1] = True
                structure[1, 0, 1] = True
                structure[1, 2, 1] = True
                structure[1, 1, 0] = True
                structure[1, 1, 2] = True
                for z0 in range(0, n, int(block)):
                    z1 = min(n, z0 + int(block))
                    blk = cp.asarray(self.union_dev[z0:z1])  # zero-copy CUDA-array-interface view
                    bg = blk == 0
                    labels, num = cpx_ndi.label(bg, structure=structure)
                    if int(num) <= 0:
                        continue
                    touches = cp.zeros((int(num) + 1,), dtype=cp.bool_)
                    touches[cp.unique(labels[:, 0, :])] = True
                    touches[cp.unique(labels[:, -1, :])] = True
                    touches[cp.unique(labels[:, :, 0])] = True
                    touches[cp.unique(labels[:, :, -1])] = True
                    enclosed = bg & ~touches[labels]
                    if bool(enclosed.any()):
                        blk[enclosed] = cp.uint8(1)  # writes through to union_dev
                cp.cuda.get_current_stream().synchronize()
            return int(n)
        except Exception:
            return 0
        finally:
            try:
                cp.get_default_memory_pool().free_all_blocks()
            except Exception:
                pass

    def compute_slice_metadata(self) -> Optional[Dict[str, np.ndarray]]:
        """v13.3.6 (D1): per-slice foreground metadata from the device union, pre-flush.

        Two device reductions over the resident union yield per-slice any flags, bboxes
        (y0,y1,x0,x1; exclusive stops) and per-(slice,row) occupancy bits — a few hundred
        KB D2H that lets downstream CPU stages (labeling, foreground gates, the radial
        backprojection occupancy scan) skip whole read passes over the union memmaps.
        Frames that fell back to host writes make the device rows unrepresentative, so any
        host_written task returns None (consumers fall back to scanning). Call AFTER
        fill_holes_2d (holes are enclosed, so the metadata is identical either way, but
        the ordering keeps the contract obvious).
        """
        torch = self.torch
        if self.union_dev is None or bool(self.host_written):
            return None
        try:
            torch.cuda.synchronize(self.device)
            u = self.union_dev
            n, h, w = (int(x) for x in u.shape)
            rows = u.amax(dim=2) > 0   # (n, h)
            cols = u.amax(dim=1) > 0   # (n, w)
            any_t = rows.any(dim=1)    # (n,)
            rows_u8 = rows.to(torch.uint8)
            cols_u8 = cols.to(torch.uint8)
            y0 = rows_u8.argmax(dim=1)
            y1 = int(h) - rows_u8.flip(1).argmax(dim=1)
            x0 = cols_u8.argmax(dim=1)
            x1 = int(w) - cols_u8.flip(1).argmax(dim=1)
            bbox_t = torch.stack([y0, y1, x0, x1], dim=1).to(torch.int64)
            any_np = any_t.cpu().numpy()
            bbox_np = bbox_t.cpu().numpy()
            rows_np = rows.cpu().numpy()
            bbox_np[~any_np] = 0  # argmax on all-zero rows would report a full-extent bbox
            return {
                'slice_any': np.ascontiguousarray(any_np),
                'slice_bboxes': np.ascontiguousarray(bbox_np),
                # Bit-packed (n, ceil(h/8)) row-occupancy — small enough for the mp result queue.
                'slice_row_any': np.packbits(np.ascontiguousarray(rows_np), axis=1),
                'slice_row_count': np.asarray([int(h)], dtype=np.int64),
            }
        except Exception:
            return None

    def synchronize_for_retirement(self) -> None:
        """Seal every producer write before a background flush can overlap new inference."""
        self.torch.cuda.synchronize(self.device)

    def flush_into(
        self,
        view_union_mm: np.ndarray,
        view_confmap_mm: Optional[np.ndarray],
        chunk_slices: int = 64,
        *,
        synchronize_device: bool = True,
    ) -> None:
        torch = self.torch
        # The synchronous path orders every side stream here. G8 seals on the worker thread
        # before submitting this method, so the retirement thread must not device-sync and
        # accidentally wait on kernels from the NEXT task.
        if bool(synchronize_device):
            torch.cuda.synchronize(self.device)
        n, h, w = (int(x) for x in self.union_dev.shape)
        chunk = max(1, min(int(chunk_slices), n))
        plane = int(h) * int(w)
        written = self.written
        pin_buf = _acquire_pinned_u8_buffer(torch, 2 * chunk * plane)
        pin_views = (
            pin_buf[: chunk * plane].view(chunk, h, w),
            pin_buf[chunk * plane: 2 * chunk * plane].view(chunk, h, w),
        )
        pin_np = (pin_views[0].numpy(), pin_views[1].numpy())
        copy_stream = torch.cuda.Stream(device=self.device)
        events = (torch.cuda.Event(), torch.cuda.Event())
        try:
            def _drain(src_dev: object, dst_mm: np.ndarray) -> None:
                # Chunks with no device-written slice carry only zeros: skip them outright
                # (host-side fallback writes for those slices already happened).
                chunks = [
                    (z0, min(n, z0 + chunk))
                    for z0 in range(0, n, chunk)
                    if bool(written[z0:min(n, z0 + chunk)].any())
                ]
                if not chunks:
                    return

                def _issue(ci: int) -> None:
                    z0_i, z1_i = chunks[ci]
                    buf = ci % 2
                    with torch.cuda.stream(copy_stream):
                        pin_views[buf][: z1_i - z0_i].copy_(src_dev[z0_i:z1_i], non_blocking=True)
                        events[buf].record(copy_stream)

                _issue(0)
                for ci, (z0, z1) in enumerate(chunks):
                    if ci + 1 < len(chunks):
                        _issue(ci + 1)  # overlaps the host merge below
                    events[ci % 2].synchronize()
                    host = pin_np[ci % 2][: z1 - z0]
                    wr = written[z0:z1]
                    if bool(wr.all()):
                        np.copyto(np.asarray(dst_mm[z0:z1]), host)
                    else:
                        for zi in range(z1 - z0):
                            if wr[zi]:
                                np.copyto(np.asarray(dst_mm[z0 + zi]), host[zi])

            _drain(self.union_dev, view_union_mm)
            if self.conf_dev is not None and view_confmap_mm is not None:
                _drain(self.conf_dev, view_confmap_mm)
        finally:
            _release_pinned_u8_buffer(pin_buf)
        self.union_dev = None
        self.conf_dev = None
        self.prediction_counts_dev = None


def _try_create_device_union_accumulator(
    device_str: str, num_frames: int, native_h: int, native_w: int, *, want_conf: bool,
) -> Optional[_DeviceUnionAccumulator]:
    """v13.3.2 (R21): build the per-task device union when VRAM allows; None -> per-frame D2H."""
    if not gpu_device_union_enabled():
        return None
    try:
        import torch  # type: ignore
        if not str(device_str).startswith('cuda') or not bool(torch.cuda.is_available()):
            return None
        device = torch.device(str(device_str))
        need = int(num_frames) * int(native_h) * int(native_w) * (2 if bool(want_conf) else 1)
        free_bytes, _total = torch.cuda.mem_get_info(device)
        if int(free_bytes) < int(need) + 2 * GIB:
            return None
        return _DeviceUnionAccumulator(torch, device, int(num_frames), int(native_h), int(native_w), bool(want_conf))
    except Exception:
        return None


def _process_gpu_flattened_prediction_frame(
    idx: int,
    payload: GpuFlattenedRetinaPayload,
    out_size: int,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    slice_lock: Optional[threading.Lock] = None,
    device_union: Optional[_DeviceUnionAccumulator] = None,
) -> Tuple[int, int]:
    """v13.1.0 (#2.2/#2.3): accumulate a GPU-flattened retina frame, warping (and optionally cleaning) on the GPU.

    The (n,Hr,Wr) stack was already reduced on the GPU to a union plane and a max-confidence plane.
    Here both planes are warped to view-native space ON THE GPU (#2.2: no CPU warp, no per-instance
    loop; v13.3.0 R8: identity warps skipped, grids cached) and, for the single-angle fast path
    (#2.3), a positive --min_radius runs on the GPU (cupy) on the native union before the host
    copy; in that case cleanup_done_on_gpu is set so the per-slice CPU streaming cleanup is
    skipped. v13.3.0 (R8): the per-frame GPU 2D hole fill is removed — the final per-view volume
    pass performs the hole fill once, in spec order. v13.3.0 (R18): all of this runs on a
    per-thread side CUDA stream with pinned D2H staging. Falls back to a CPU warp (and CPU
    cleanup) if the GPU warp path raises, so results are always produced.
    """
    instance_count = max(0, int(payload.instance_count))
    union_gpu = payload.union_gpu
    if union_gpu is None:
        return int(instance_count), 0

    track_conf = view_confmap_mm is not None
    native_union_np: Optional[np.ndarray] = None
    native_conf_np: Optional[np.ndarray] = None
    cleaned_on_gpu = False

    try:
        import torch  # type: ignore
        if not gpu_retina_warp_enabled():
            raise RuntimeError('gpu retina warp disabled')

        # v13.3.0 (R18): the whole postprocess tail runs on this thread's side CUDA stream,
        # ordered against the producer via the payload's recorded event, so warp/quantize/D2H
        # no longer serialize with TensorRT kernel issue on the default stream.
        device = getattr(union_gpu, 'device', None)
        side_stream = _gpu_postprocess_side_stream(torch, device)
        stream_ctx = torch.cuda.stream(side_stream) if side_stream is not None else contextlib.nullcontext()
        with stream_ctx:
            if side_stream is not None:
                ready_evt = getattr(payload, 'ready_event', None)
                if ready_evt is not None:
                    side_stream.wait_event(ready_evt)
                else:
                    side_stream.wait_stream(torch.cuda.default_stream(device))
                # Payload tensors are produced on the inference/default stream but can be
                # released as soon as this worker returns, while the side-stream write is still
                # in flight. Tell the caching allocator about every cross-stream use.
                _record_candidates: List[object] = [
                    union_gpu, payload.conf_gpu, payload.instance_count_device,
                ]
                if payload.device_refs is not None:
                    _record_candidates.extend(payload.device_refs)
                for _candidate in _record_candidates:
                    if isinstance(_candidate, torch.Tensor):
                        try:
                            _candidate.record_stream(side_stream)
                        except Exception:
                            pass

            # Warp union (and conf) to view-native space on the GPU (nearest, zero-padded). Both
            # planes share one grid_sample; identity warps skip it entirely and non-identity
            # warps reuse a cached grid (v13.3.0 R8).
            warp_conf = bool(track_conf and payload.conf_gpu is not None)
            warped = _torch_warp_planes_to_native(
                [union_gpu, payload.conf_gpu] if warp_conf else [union_gpu],
                M_out_to_native, int(out_size), int(native_h), int(native_w),
            )
            native_union_t = warped[0]
            native_union_bool_t = native_union_t > 0.5

            native_conf_t = None
            if warp_conf:
                native_conf_f = warped[1]
                # Quantize to u8 (round-half-even) only where the union is foreground.
                native_conf_t = torch.where(
                    native_union_bool_t,
                    (native_conf_f.clamp(0.0, 1.0) * float(CONF_U8_MAX)).round(),
                    torch.zeros((), dtype=native_conf_f.dtype, device=native_conf_f.device),
                ).clamp(0.0, 255.0).to(torch.uint8)

            # v13.3.2 (R21): with a per-task device union, the warped plane stays ON DEVICE —
            # no per-frame D2H, no host |=; the task-end flush does one chunked transfer.
            # Frames that still need the cupy --min_radius cleanup (which lands on host) fall
            # through to the legacy path; the flush's OR/max merge keeps both consistent.
            if device_union is not None and not (
                bool(payload.run_gpu_cleanup) and float(payload.gpu_min_radius) > 0.0
            ):
                device_union.write_frame(
                    int(idx), native_union_bool_t, native_conf_t,
                    prediction_count_dev=payload.instance_count_device,
                )
                payload.accumulated_on_device = True
                payload.cleanup_done_on_gpu = False
                # frames_with_predictions: reported from the pre-warp instance count (checking
                # post-warp emptiness would force a device sync per frame; the stat is
                # informational only).
                if payload.instance_count_device is not None:
                    return 0, 0  # task-end device reduction supplies both stats
                return int(instance_count), (1 if int(instance_count) > 0 else 0)

            # #2.3 / v13.3.0 (R8): connected-component --min_radius on the GPU (cupy), in native
            # space, only when a positive radius is set. The old per-frame 2D hole fill
            # (cupyx binary_fill_holes, an iterative-dilation kernel/sync storm) is removed:
            # spec order is --min_conf -> --min_radius -> hole fill and the final per-view
            # volume pass performs the hole fill once, so the per-frame fill was pure recompute.
            if bool(payload.run_gpu_cleanup) and float(payload.gpu_min_radius) > 0.0:
                cp_mod = _try_import_cupy_ndimage()
                if cp_mod is not None:
                    cp, cpx_ndi = cp_mod
                    try:
                        # Pin the cupy device to the torch tensor's CUDA index so cp.asarray does
                        # not default to device 0 when inference runs on a non-default GPU.
                        _dev_idx = getattr(native_union_bool_t.device, 'index', None)
                        _cp_dev = cp.cuda.Device(int(_dev_idx)) if _dev_idx is not None else cp.cuda.Device()
                        _cp_stream = (
                            _cupy_external_stream(cp, side_stream)
                            if side_stream is not None else contextlib.nullcontext()
                        )
                        with _cp_dev, _cp_stream:
                            # Move to cupy via uint8 (torch bool tensors do not reliably expose
                            # __cuda_array_interface__), then back to a boolean mask for the CC ops.
                            union_cp = cp.asarray(native_union_bool_t.to(torch.uint8).contiguous()) > 0
                            union_cp = _min_radius_filter_ndimage(cp, cpx_ndi, union_cp, float(payload.gpu_min_radius))
                            native_union_np = np.ascontiguousarray(cp.asnumpy(union_cp).astype(np.uint8, copy=False) > 0)
                        cleaned_on_gpu = True
                    except Exception:
                        native_union_np = None  # fall back to torch->cpu union, CPU cleanup downstream

            if native_union_np is None:
                # v13.3.0 (R18): D2H through this thread's pinned staging buffer (non-blocking
                # copy + stream sync); copy out immediately since the buffer is reused per frame.
                native_union_np = np.ascontiguousarray(
                    _tensor_to_host_numpy(torch, native_union_bool_t, side_stream)
                )
                native_union_np = native_union_np > 0
            if native_conf_t is not None:
                native_conf_np = np.ascontiguousarray(
                    _tensor_to_host_numpy(torch, native_conf_t, side_stream).astype(np.uint8, copy=True)
                )
                if bool(cleaned_on_gpu):
                    # Keep confidence only where the cleaned union remains foreground.
                    native_conf_np = np.where(native_union_np, native_conf_np, np.uint8(0)).astype(np.uint8, copy=False)
    except Exception:
        # Robust CPU fallback: copy the flattened GPU planes down and warp on the CPU (cv2).
        native_union_np = None
        native_conf_np = None
        cleaned_on_gpu = False
        try:
            import torch  # type: ignore
            frame_union = np.ascontiguousarray((union_gpu.detach().cpu().numpy() > 0).astype(np.uint8))
        except Exception:
            return int(instance_count), 0
        if int(frame_union.shape[0]) != int(out_size) or int(frame_union.shape[1]) != int(out_size):
            frame_union = cv2.resize(frame_union, (int(out_size), int(out_size)), interpolation=cv2.INTER_NEAREST)
        native_union_np = cv2.warpAffine(
            frame_union, M_out_to_native, dsize=(native_w, native_h),
            flags=cv2.INTER_NEAREST, borderMode=cv2.BORDER_CONSTANT, borderValue=0,
        ) > 0
        if track_conf and payload.conf_gpu is not None:
            conf_plane = payload.conf_gpu.detach().cpu().numpy()
            conf_u8 = np.clip(np.rint(np.clip(conf_plane, 0.0, 1.0) * float(CONF_U8_MAX)), 0, 255).astype(np.uint8)
            if int(conf_u8.shape[0]) != int(out_size) or int(conf_u8.shape[1]) != int(out_size):
                conf_u8 = cv2.resize(conf_u8, (int(out_size), int(out_size)), interpolation=cv2.INTER_NEAREST)
            native_conf_np = cv2.warpAffine(
                conf_u8, M_out_to_native, dsize=(native_w, native_h),
                flags=cv2.INTER_NEAREST, borderMode=cv2.BORDER_CONSTANT, borderValue=0,
            ).astype(np.uint8, copy=False)
            native_conf_np = np.where(native_union_np, native_conf_np, np.uint8(0)).astype(np.uint8, copy=False)

    if payload.instance_count_device is not None and not bool(payload.accumulated_on_device):
        # This host/cupy fallback already performs a mask D2H; only the normal device-union
        # path is synchronization-free per frame. Preserve exact informational counts here.
        try:
            instance_count = int(payload.instance_count_device.detach().cpu().reshape(-1)[0])
        except Exception:
            instance_count = 0

    if native_union_np is None or not np.any(native_union_np):
        # Empty after warp/cleanup: nothing written, so report no contributing frame (matches the
        # CPU retina path). Still record whether the GPU cleanup ran so the CPU cleanup stays skipped.
        payload.cleanup_done_on_gpu = bool(cleaned_on_gpu)
        return int(instance_count), 0

    def _write_native_outputs() -> None:
        view_union_mm[int(idx), :, :] |= native_union_np.astype(np.uint8, copy=False)
        if view_confmap_mm is not None and native_conf_np is not None and np.any(native_conf_np):
            conf_slice = view_confmap_mm[int(idx)]
            np.maximum(conf_slice, native_conf_np, out=conf_slice)

    # v13.3.3 (S2): this frame bypassed the device union (cupy cleanup or CPU fallback) and
    # writes the host window directly — the device-side hole fill must stand down for this task.
    if device_union is not None:
        device_union.mark_host_write()
    if slice_lock is None:
        _write_native_outputs()
    else:
        with slice_lock:
            _write_native_outputs()

    payload.cleanup_done_on_gpu = bool(cleaned_on_gpu)
    return int(instance_count), 1


def _process_prediction_frame(
    idx: int,
    masks_np: Optional[object],
    confs_np: Optional[np.ndarray],
    out_size: int,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    slice_lock: Optional[threading.Lock] = None,
    device_union: Optional[_DeviceUnionAccumulator] = None,
) -> Tuple[int, int]:
    """Collapse one streamed result directly into unpacked native-view union + confidence volumes."""
    if isinstance(masks_np, GpuFlattenedRetinaPayload):
        return _process_gpu_flattened_prediction_frame(
            idx=idx,
            payload=masks_np,
            out_size=out_size,
            view_union_mm=view_union_mm,
            view_confmap_mm=view_confmap_mm,
            M_out_to_native=M_out_to_native,
            native_h=native_h,
            native_w=native_w,
            slice_lock=slice_lock,
            device_union=device_union,
        )

    if isinstance(masks_np, CpuRetinaMaskPayload):
        # v13.3.3 (S2): host-side accumulation path — device hole fill stands down for the task.
        if device_union is not None:
            device_union.mark_host_write()
        return _process_cpu_retina_prediction_frame(
            idx=idx,
            payload=masks_np,
            out_size=out_size,
            view_union_mm=view_union_mm,
            view_confmap_mm=view_confmap_mm,
            M_out_to_native=M_out_to_native,
            native_h=native_h,
            native_w=native_w,
            slice_lock=slice_lock,
        )

    if masks_np is None:
        return 0, 0
    masks_arr = np.asarray(masks_np)
    if masks_arr.ndim != 3 or int(masks_arr.shape[0]) <= 0:
        return 0, 0
    # v13.3.3 (S2): raw retina-stack frames accumulate host-side below.
    if device_union is not None:
        device_union.mark_host_write()

    track_conf = view_confmap_mm is not None
    frame_union = np.zeros((out_size, out_size), dtype=np.uint8)
    frame_confmap = np.zeros((out_size, out_size), dtype=np.uint8) if track_conf else None
    num_inst = int(masks_arr.shape[0])

    for inst_idx in range(num_inst):
        inst = np.asarray(masks_arr[inst_idx], dtype=np.uint8)
        if inst.shape[0] != out_size or inst.shape[1] != out_size:
            inst = cv2.resize(inst, (out_size, out_size), interpolation=cv2.INTER_NEAREST)
        inst = (inst > 0).astype(np.uint8, copy=False)
        if not np.any(inst):
            continue

        frame_union |= inst
        if track_conf and frame_confmap is not None:
            conf_val = float(confs_np[inst_idx]) if (confs_np is not None and inst_idx < int(confs_np.shape[0])) else 0.0
            conf_u8 = quantize_conf_to_u8(conf_val)
            inst_bool = inst > 0
            frame_confmap[inst_bool] = np.maximum(frame_confmap[inst_bool], conf_u8)

    if not np.any(frame_union):
        return int(num_inst), 1

    native_union = cv2.warpAffine(
        frame_union,
        M_out_to_native,
        dsize=(native_w, native_h),
        flags=cv2.INTER_NEAREST,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=0,
    ) > 0

    native_conf: Optional[np.ndarray] = None
    if frame_confmap is not None and np.any(frame_confmap):
        native_conf = cv2.warpAffine(
            frame_confmap,
            M_out_to_native,
            dsize=(native_w, native_h),
            flags=cv2.INTER_NEAREST,
            borderMode=cv2.BORDER_CONSTANT,
            borderValue=0,
        ).astype(np.uint8, copy=False)

    def _write_native_outputs() -> None:
        if np.any(native_union):
            view_union_mm[int(idx), :, :] |= native_union.astype(np.uint8, copy=False)

        if view_confmap_mm is not None and native_conf is not None and np.any(native_conf):
            conf_slice = view_confmap_mm[int(idx)]
            np.maximum(conf_slice, native_conf, out=conf_slice)

    if slice_lock is None:
        _write_native_outputs()
    else:
        with slice_lock:
            _write_native_outputs()

    return int(num_inst), 1


# --------------------------
# v13.3.6 (C2): direct backend execution loop (no Ultralytics stream_inference)
# --------------------------
# On the GPU proto-union fast path, model.predict(stream=True) contributes only per-batch
# generator plumbing (source bookkeeping, callbacks, and Profile stage timers that call
# torch.cuda.synchronize on CUDA), ops.non_max_suppression at iou=1.0 (which can never
# suppress anything — IoU > 1.0 is impossible; iou=1.0 is set precisely to maximize recall —
# while forcing data-dependent boolean-index syncs per image), and one Results object per
# frame. The direct loop keeps the two pieces that matter — the patched preprocess (the
# _tta_gpu_tensor contract) and the AutoBackend forward — and replaces NMS with a pure
# confidence gate + on-device decode feeding the existing proto-union payload builder.
# Recall is preserved or improved: the union/amax reductions are idempotent under duplicate
# boxes, and two recall hazards of the stock path disappear (max_det=300 truncation of
# crowded frames, and the NMS per-batch time-limit early break). YOLO_TTA_DIRECT_PREDICT=0
# restores model.predict; setup/shape surprises fall back automatically before the first
# batch is consumed, and mid-stream layout errors raise (they indicate a wrong model type).

_DIRECT_PREDICT_ANNOUNCED = False
_RESIDENT_TRT_RING_ANNOUNCED = False
_RESIDENT_TRT_RING_FALLBACK_WARNED = False


def direct_predict_enabled() -> bool:
    return _env_flag('YOLO_TTA_DIRECT_PREDICT', True)


def resident_trt_ring_enabled() -> bool:
    """Enable the fixed batch-1 resident-render TensorRT pipeline."""
    return _env_flag('YOLO_TTA_RESIDENT_TRT_RING', True)


def resident_trt_cuda_graphs_enabled() -> bool:
    """Capture each ring slot's static TensorRT and mask-decode launches when supported."""
    return _env_flag('YOLO_TTA_RESIDENT_TRT_CUDA_GRAPHS', True)


def resident_trt_native_warp_enabled() -> bool:
    """Allow the resident ring to fuse a non-identity network->native affine."""
    return _env_flag('YOLO_TTA_RESIDENT_TRT_NATIVE_WARP', True)


def _cuda_stream_priority(torch_mod: object, *, high: bool) -> int:
    """Return a supported CUDA stream priority, tolerating older torch builds.

    torch reports ``(least_priority, greatest_priority)``; CUDA uses smaller numeric
    values for higher priority.  A zero priority is universally valid.
    """
    try:
        least, greatest = torch_mod.cuda.get_stream_priority_range()
        return int(greatest if bool(high) else least)
    except Exception:
        return -1 if bool(high) else 0


class _ResidentGpuPipelineSlot:
    """One static-address input/output/event slot in the resident two-entry ring."""

    def __init__(
        self,
        torch_mod: object,
        device: object,
        out_size: int,
        input_dtype: object,
        slot_id: int,
    ) -> None:
        self.slot_id = int(slot_id)
        if input_dtype not in (torch_mod.float16, torch_mod.float32):
            raise RuntimeError(
                f'resident ring does not support TensorRT input dtype {input_dtype}; '
                'only float16/float32 normalized image bindings are supported'
            )
        self.input = torch_mod.empty(
            (1, 1, int(out_size), int(out_size)),
            dtype=input_dtype,
            device=device,
        )
        # Stable metadata address for P4 renderer launches. A one-thread setter kernel
        # updates its value on the render stream without a reusable-host-buffer race.
        self.render_meta = torch_mod.empty((2,), dtype=torch_mod.int32, device=device)
        # Distinct high-priority streams allow the two TensorRT execution contexts to
        # overlap.  Mask decode/quantize/union uses a third, ordinary-priority stream.
        high_priority = _cuda_stream_priority(torch_mod, high=True)
        low_priority = _cuda_stream_priority(torch_mod, high=False)
        self.infer_stream = torch_mod.cuda.Stream(device=device, priority=high_priority)
        self.post_stream = torch_mod.cuda.Stream(device=device, priority=low_priority)
        # Events are allocated once and re-recorded.  render_done protects input reads,
        # infer_done protects input reuse, and post_done protects output-binding reuse.
        self.render_done = torch_mod.cuda.Event(enable_timing=False, blocking=False)
        self.infer_done = torch_mod.cuda.Event(enable_timing=False, blocking=False)
        self.post_done = torch_mod.cuda.Event(enable_timing=False, blocking=False)
        self.infer_valid = False
        self.post_valid = False
        self.frame_index = -1
        self.absolute_index = -1
        self.synthetic = False
        self.context = None
        self.binding_addresses: Optional[List[int]] = None
        self.head = None
        self.proto = None
        self.compact_indices = None
        self.compact_count = None
        self.max_logit = None
        self.conf_proto = None
        self.native_union = None
        self.native_conf = None
        self.infer_graph = None
        self.post_graph = None
        self.render_graph = None
        self.render_graph_key = None
        # Prepared once per resident source/task. Graph replay compares this cached key
        # instead of rebuilding large Radial azimuth-byte geometry keys for every frame.
        self.render_expected_key = None
        # Keep zero-copy cupy array views alive for the lifetime of captured graphs.
        self._cupy_refs: Dict[str, object] = {}
        # P4 renderer views are separate from postprocess graph views: the latter mapping
        # is rebuilt by _ResidentTensorRTRingExecutor after the slots are allocated.
        self._render_cupy_refs: Dict[str, object] = {}


_RESIDENT_MASK_KERNELS: Optional[object] = None
_RESIDENT_MASK_KERNELS_FAILED = False


def _resident_mask_kernels() -> Optional[object]:
    """Compile the small device compaction/proto-union kernels once with NVRTC.

    The compaction count remains in device memory.  The following proto kernel reads
    that count directly, so there is no per-frame ``nonzero()``, ``tolist()`` or count
    readback.  CuPy is already an optional dependency of the GPU cleanup path; failure
    to import/compile it simply disables this stricter fast path.
    """
    global _RESIDENT_MASK_KERNELS, _RESIDENT_MASK_KERNELS_FAILED
    if _RESIDENT_MASK_KERNELS is not None:
        return _RESIDENT_MASK_KERNELS
    if _RESIDENT_MASK_KERNELS_FAILED:
        return None
    try:
        import cupy as cp  # type: ignore
        src = r'''
        #include <cuda_fp16.h>
        extern "C" __global__ void compact_f32(
            const float* head, int anchors, float threshold, int* indices, int* count) {
          int a = blockDim.x * blockIdx.x + threadIdx.x;
          if (a < anchors && head[4 * anchors + a] >= threshold) {
            int dst = atomicAdd(count, 1);
            indices[dst] = a;
          }
        }
        extern "C" __global__ void compact_f16(
            const half* head, int anchors, float threshold, int* indices, int* count) {
          int a = blockDim.x * blockIdx.x + threadIdx.x;
          if (a < anchors && __half2float(head[4 * anchors + a]) >= threshold) {
            int dst = atomicAdd(count, 1);
            indices[dst] = a;
          }
        }

        __device__ __forceinline__ float rd(const float* p, int i) { return p[i]; }
        __device__ __forceinline__ float rd(const half* p, int i) { return __half2float(p[i]); }

        template <typename H, typename P>
        __device__ void proto_union_body(
            const H* head, const P* proto, const int* indices, const int* count,
            int anchors, int masks, int ph, int pw, int ih, int iw,
            float* max_logit, float* conf_proto) {
          int p = blockDim.x * blockIdx.x + threadIdx.x;
          int pixels = ph * pw;
          if (p >= pixels) return;
          int y = p / pw;
          int x = p - y * pw;
          float best = -6.0f;
          float best_conf = 0.0f;
          int n = *count;
          for (int j = 0; j < n; ++j) {
            int a = indices[j];
            float cx = rd(head, 0 * anchors + a);
            float cy = rd(head, 1 * anchors + a);
            float bw = rd(head, 2 * anchors + a);
            float bh = rd(head, 3 * anchors + a);
            float x1 = (cx - 0.5f * bw) * ((float)pw / (float)iw);
            float y1 = (cy - 0.5f * bh) * ((float)ph / (float)ih);
            float x2 = (cx + 0.5f * bw) * ((float)pw / (float)iw);
            float y2 = (cy + 0.5f * bh) * ((float)ph / (float)ih);
            if ((float)x < x1 || (float)x >= x2 || (float)y < y1 || (float)y >= y2) continue;
            float logit = 0.0f;
            #pragma unroll 4
            for (int c = 0; c < masks; ++c) {
              logit += rd(head, (5 + c) * anchors + a) * rd(proto, c * pixels + p);
            }
            best = fmaxf(best, logit);
            if (conf_proto != nullptr && logit > 0.0f) {
              best_conf = fmaxf(best_conf, rd(head, 4 * anchors + a));
            }
          }
          max_logit[p] = best;
          if (conf_proto != nullptr) conf_proto[p] = best_conf;
        }

        #define DECL_UNION(NAME, HT, PT) \
        extern "C" __global__ void NAME( \
            const HT* head, const PT* proto, const int* indices, const int* count, \
            int anchors, int masks, int ph, int pw, int ih, int iw, \
            float* max_logit, float* conf_proto) { \
          proto_union_body(head, proto, indices, count, anchors, masks, ph, pw, ih, iw, \
                           max_logit, conf_proto); \
        }
        DECL_UNION(union_f32_f32, float, float)
        DECL_UNION(union_f32_f16, float, half)
        DECL_UNION(union_f16_f32, half, float)
        DECL_UNION(union_f16_f16, half, half)

        extern "C" __global__ void upsample_quantize(
            const float* max_logit, const float* conf_proto,
            int ph, int pw, int oh, int ow, unsigned char* out_union,
            unsigned char* out_conf) {
          int q = blockDim.x * blockIdx.x + threadIdx.x;
          int out_pixels = oh * ow;
          if (q >= out_pixels) return;
          int oy = q / ow;
          int ox = q - oy * ow;
          float sy = ((float)oy + 0.5f) * ((float)ph / (float)oh) - 0.5f;
          float sx = ((float)ox + 0.5f) * ((float)pw / (float)ow) - 0.5f;
          int y0r = (int)floorf(sy), x0r = (int)floorf(sx);
          float fy = sy - (float)y0r, fx = sx - (float)x0r;
          int y0 = max(0, min(ph - 1, y0r));
          int x0 = max(0, min(pw - 1, x0r));
          int y1 = max(0, min(ph - 1, y0r + 1));
          int x1 = max(0, min(pw - 1, x0r + 1));
          float v00 = max_logit[y0 * pw + x0];
          float v01 = max_logit[y0 * pw + x1];
          float v10 = max_logit[y1 * pw + x0];
          float v11 = max_logit[y1 * pw + x1];
          float v0 = v00 + fx * (v01 - v00);
          float v1 = v10 + fx * (v11 - v10);
          unsigned char fg = (v0 + fy * (v1 - v0)) > 0.0f ? 1 : 0;
          out_union[q] = fg;
          if (out_conf != nullptr) {
            int ny = min(ph - 1, (int)((long long)oy * ph / oh));
            int nx = min(pw - 1, (int)((long long)ox * pw / ow));
            float cf = fminf(1.0f, fmaxf(0.0f, conf_proto[ny * pw + nx]));
            out_conf[q] = fg ? (unsigned char)__float2uint_rn(cf * 255.0f) : 0;
          }
        }

        extern "C" __global__ void upsample_quantize_affine(
            const float* max_logit, const float* conf_proto,
            int ph, int pw, int ih, int iw, int oh, int ow,
            float m00, float m01, float m02,
            float m10, float m11, float m12,
            unsigned char* out_union, unsigned char* out_conf) {
          int q = blockDim.x * blockIdx.x + threadIdx.x;
          int out_pixels = oh * ow;
          if (q >= out_pixels) return;
          int oy = q / ow;
          int ox = q - oy * ow;

          // Pixel-center convention: integer (ox,oy) is a native pixel center.  The
          // precomputed inverse affine maps it to the network raster, matching
          // _affine_theta_for_grid_sample with align_corners=False.  Outside the
          // network pixel-center extent is constant zero padding.  Inside, compose
          // that coordinate directly with the align_corners=False proto upsample;
          // threshold only after this one bilinear sample (there is no intermediate
          // out_size binary plane and no full-resolution grid tensor).
          float ix = m00 * (float)ox + m01 * (float)oy + m02;
          float iy = m10 * (float)ox + m11 * (float)oy + m12;
          if (ix < -0.5f || ix >= (float)iw - 0.5f ||
              iy < -0.5f || iy >= (float)ih - 0.5f) {
            out_union[q] = 0;
            if (out_conf != nullptr) out_conf[q] = 0;
            return;
          }

          float sx = (ix + 0.5f) * ((float)pw / (float)iw) - 0.5f;
          float sy = (iy + 0.5f) * ((float)ph / (float)ih) - 0.5f;
          int y0r = (int)floorf(sy), x0r = (int)floorf(sx);
          float fy = sy - (float)y0r, fx = sx - (float)x0r;
          int y0 = max(0, min(ph - 1, y0r));
          int x0 = max(0, min(pw - 1, x0r));
          int y1 = max(0, min(ph - 1, y0r + 1));
          int x1 = max(0, min(pw - 1, x0r + 1));
          float v00 = max_logit[y0 * pw + x0];
          float v01 = max_logit[y0 * pw + x1];
          float v10 = max_logit[y1 * pw + x0];
          float v11 = max_logit[y1 * pw + x1];
          float v0 = v00 + fx * (v01 - v00);
          float v1 = v10 + fx * (v11 - v10);
          unsigned char fg = (v0 + fy * (v1 - v0)) > 0.0f ? 1 : 0;
          out_union[q] = fg;
          if (out_conf != nullptr) {
            // Confidence remains nearest-proto sampled, as in the generic path.
            int ny = max(0, min(ph - 1, (int)floorf(iy * ((float)ph / (float)ih))));
            int nx = max(0, min(pw - 1, (int)floorf(ix * ((float)pw / (float)iw))));
            float cf = fminf(1.0f, fmaxf(0.0f, conf_proto[ny * pw + nx]));
            out_conf[q] = fg ? (unsigned char)__float2uint_rn(cf * 255.0f) : 0;
          }
        }
        '''
        names = (
            'compact_f32', 'compact_f16',
            'union_f32_f32', 'union_f32_f16', 'union_f16_f32', 'union_f16_f16',
            'upsample_quantize', 'upsample_quantize_affine',
        )
        module = cp.RawModule(code=src, options=('--std=c++11',), name_expressions=names)
        _RESIDENT_MASK_KERNELS = argparse.Namespace(
            cp=cp,
            **{name: module.get_function(name) for name in names},
        )
        return _RESIDENT_MASK_KERNELS
    except Exception:
        _RESIDENT_MASK_KERNELS_FAILED = True
        return None


class _DirectPredictResult:
    """Minimal per-frame result for the direct loop.

    Duck-typed for _extract_result_masks_and_confs: it only carries the prebuilt
    GpuFlattenedRetinaPayload; no Ultralytics Results object, boxes, paths, or orig
    images are constructed.
    """

    __slots__ = ('_tta_gpu_flattened_payload',)

    def __init__(self, payload: GpuFlattenedRetinaPayload) -> None:
        self._tta_gpu_flattened_payload = payload


def _direct_predict_applicable(cfg: 'PredictConfig') -> bool:
    """Direct loop preconditions: proto-union consume path + a CUDA device."""
    if not direct_predict_enabled():
        return False
    if cpu_retina_masks_enabled() or not gpu_retina_proto_union_enabled():
        return False
    try:
        import torch  # type: ignore
    except Exception:
        return False
    try:
        if not str(canonical_single_device(str(cfg.device))).startswith('cuda'):
            return False
        return bool(torch.cuda.is_available())
    except Exception:
        return False


def _ensure_predictor_for_direct_predict(model: object, cfg: 'PredictConfig') -> Optional[object]:
    """Create/fetch the Ultralytics predictor + backend without running stream_inference.

    Model.predict(..., stream=True) constructs the predictor and calls setup_model
    (AutoBackend load, device/half placement) eagerly but returns an UNITERATED generator,
    so no source setup, warmup, or inference runs. The predictor's (patched) preprocess and
    its AutoBackend are then driven directly by _direct_predict_stream.
    """
    try:
        predictor = getattr(model, 'predictor', None)
        if predictor is None or getattr(predictor, 'model', None) is None:
            _ = model.predict(
                source=np.zeros((32, 32, 3), dtype=np.uint8),
                task='segment',
                imgsz=cfg.imgsz,
                conf=cfg.conf,
                iou=1.0,
                save=False,
                stream=True,
                retina_masks=True,
                batch=max(1, int(cfg.batch)),
                device=cfg.device,
                half=cfg.half,
                int8=cfg.int8,
                verbose=False,
            )
            predictor = getattr(model, 'predictor', None)
        if predictor is None or getattr(predictor, 'model', None) is None:
            return None
        ensure_yolo_ready_for_predict(model, cfg)
        return predictor
    except Exception as exc:
        print(f'Warning: direct predict setup failed ({exc}); using model.predict for this source.')
        return None


def _split_segmentation_backend_outputs(preds: object) -> Optional[Tuple[object, object]]:
    """Return (head, protos) from a raw segmentation forward.

    Mirrors SegmentationPredictor.postprocess's output handling: preds[0] is the
    (B, 4+nc+nm, A) detection head, preds[1] the (B, nm, mh, mw) prototype tensor (torch
    .pt backends nest it as the last element of a tuple). None when the structure does not
    match, so the caller can fail fast instead of mis-decoding.
    """
    try:
        if not isinstance(preds, (list, tuple)) or len(preds) < 2:
            return None
        head = preds[0]
        proto = preds[1]
        if isinstance(proto, (list, tuple)):
            proto = proto[-1]
        if getattr(head, 'ndim', 0) != 3 or getattr(proto, 'ndim', 0) != 4:
            return None
        return head, proto
    except Exception:
        return None


_DIRECT_DEVICE_COMPACTION_ANNOUNCED = False
_DIRECT_DEVICE_COMPACTION_FALLBACK_WARNED = False


def direct_device_compaction_enabled() -> bool:
    """Fuse the generic direct loop's confidence gate + proto union without host counts."""
    return _env_flag('YOLO_TTA_DIRECT_DEVICE_COMPACTION', True)


def _build_direct_device_compacted_payload(
    head_frame: object,
    proto_frame: object,
    im: object,
    confidence_threshold: float,
    min_conf_applied: bool = False,
) -> Optional[GpuFlattenedRetinaPayload]:
    """Build one flattened mask using the resident kernels on the current CUDA stream.

    Unlike the legacy direct path this never evaluates a data-dependent tensor shape on the
    host. ``compact_count`` is consumed by the proto kernel in device memory and travels with
    the payload for task-end accounting.
    """
    if not direct_device_compaction_enabled():
        return None
    try:
        import torch  # type: ignore
        import torch.nn.functional as F  # type: ignore

        kernels = _resident_mask_kernels()
        if kernels is None:
            return None
        # AutoBackend/TensorRT may reuse static output bindings on the next enqueue while this
        # payload is queued to a postprocess worker. Snapshot the compact head/proto tensors;
        # this is still orders of magnitude smaller than materializing an instance-mask stack.
        head = head_frame.contiguous().clone()
        proto = proto_frame.contiguous().clone()
        if int(head.ndim) != 2 or int(proto.ndim) != 3:
            return None
        if head.dtype not in (torch.float16, torch.float32):
            return None
        if proto.dtype not in (torch.float16, torch.float32):
            return None
        masks, ph, pw = (int(v) for v in proto.shape)
        if int(head.shape[0]) != 5 + int(masks):
            return None  # this pipeline supports one segmentation class
        anchors = int(head.shape[1])
        if anchors <= 0 or masks <= 0 or ph <= 0 or pw <= 0:
            return None
        img_h, img_w = int(im.shape[-2]), int(im.shape[-1])
        device = head.device
        indices = torch.empty((anchors,), dtype=torch.int32, device=device)
        count = torch.zeros((1,), dtype=torch.int32, device=device)
        max_logit = torch.empty((ph, pw), dtype=torch.float32, device=device)
        conf_proto = (
            torch.empty((ph, pw), dtype=torch.float32, device=device)
            if gpu_flatten_conf_tracking_enabled() else None
        )

        cp = kernels.cp
        stream = torch.cuda.current_stream(device)
        external = _cupy_external_stream(cp, stream)
        cp_head = cp.asarray(head)
        cp_proto = cp.asarray(proto)
        cp_indices = cp.asarray(indices)
        cp_count = cp.asarray(count)
        cp_max_logit = cp.asarray(max_logit)
        cp_conf_proto = cp.asarray(conf_proto) if conf_proto is not None else None
        compact = kernels.compact_f16 if head.dtype == torch.float16 else kernels.compact_f32
        compact(
            ((anchors + 255) // 256,), (256,),
            (
                cp_head, np.int32(anchors), np.float32(confidence_threshold),
                cp_indices, cp_count,
            ),
            stream=external,
        )
        htag = 'f16' if head.dtype == torch.float16 else 'f32'
        ptag = 'f16' if proto.dtype == torch.float16 else 'f32'
        union_kernel = getattr(kernels, f'union_{htag}_{ptag}')
        union_kernel(
            (((ph * pw) + 255) // 256,), (256,),
            (
                cp_head, cp_proto, cp_indices, cp_count,
                np.int32(anchors), np.int32(masks), np.int32(ph), np.int32(pw),
                np.int32(img_h), np.int32(img_w), cp_max_logit,
                cp_conf_proto if cp_conf_proto is not None else np.uintp(0),
            ),
            stream=external,
        )

        # One plane, not one plane per instance. The terminal view warp remains in the existing
        # post path; the resident-ring specialization fuses this upsample with that warp.
        union_gpu = (
            F.interpolate(
                max_logit.reshape(1, 1, ph, pw),
                size=(img_h, img_w), mode='bilinear', align_corners=False,
            ).reshape(img_h, img_w) > 0.0
        ).to(torch.float32)
        conf_gpu = None
        if conf_proto is not None:
            conf_gpu = F.interpolate(
                conf_proto.reshape(1, 1, ph, pw),
                size=(img_h, img_w), mode='nearest',
            ).reshape(img_h, img_w)

        ready_event = torch.cuda.Event()
        ready_event.record(stream)
        fastpath = single_angle_gpu_fastpath()
        fastpath_radius = 0.0 if fastpath is None else float(fastpath[1])
        payload = GpuFlattenedRetinaPayload(
            union_gpu=union_gpu,
            conf_gpu=conf_gpu,
            instance_count=-1,
            instance_count_device=count,
            min_conf_applied=bool(min_conf_applied),
            run_gpu_cleanup=bool(
                fastpath is not None and gpu_retina_cleanup_enabled() and fastpath_radius > 0.0
            ),
            gpu_min_radius=float(fastpath_radius),
            ready_event=ready_event,
            device_refs=(
                head, proto, indices, count, max_logit, conf_proto,
                cp_head, cp_proto, cp_indices, cp_count, cp_max_logit, cp_conf_proto,
            ),
        )
        return payload
    except Exception:
        return None


def _direct_predict_stream(
    predictor: object,
    source: object,
    cfg: 'PredictConfig',
    source_label: str,
) -> Iterator[_DirectPredictResult]:
    """v13.3.6 (C2): preprocess -> backend forward -> conf gate -> proto-union payload.

    Yields one payload-carrying result per frame in stream order (synthetic padded frames
    included, exactly like model.predict's per-frame Results). v13.3.12 C3 compacts the
    confidence gate and consumes its count entirely on device; the old nonzero/bincount
    readbacks remain only as an automatic capability fallback.
    Instances are decoded to the post-NMS (n, 6+nm) layout the payload builder already
    consumes: xyxy, conf, cls, mask coefficients — box-only, at network scale.
    """
    import torch  # type: ignore

    backend = getattr(predictor, 'model', None)
    if backend is None:
        raise RuntimeError('direct predict: predictor has no backend model')
    names = getattr(backend, 'names', None) or {}
    nc = max(1, len(names))
    conf_thres = float(cfg.conf)
    device_compaction_active = bool(direct_device_compaction_enabled())

    global _DIRECT_PREDICT_ANNOUNCED, _DIRECT_DEVICE_COMPACTION_ANNOUNCED, _DIRECT_DEVICE_COMPACTION_FALLBACK_WARNED
    if not _DIRECT_PREDICT_ANNOUNCED:
        _DIRECT_PREDICT_ANNOUNCED = True
        print(
            'Direct backend predict loop active (v13.3.6 C2): stream_inference, NMS and '
            'per-frame Results are bypassed; confidence-gated instances feed the '
            'proto-resolution union directly (YOLO_TTA_DIRECT_PREDICT=0 restores model.predict).'
        )

    start_fn = getattr(source, 'start', None)
    if callable(start_fn):
        try:
            start_fn()
        except Exception:
            pass

    with torch.inference_mode():
        for _paths, im0s, _info in iter(source):
            im = predictor.preprocess(im0s)
            preds = backend(im)
            split = _split_segmentation_backend_outputs(preds)
            if split is None:
                raise RuntimeError(
                    f'direct predict: unexpected backend output structure for {source_label}; '
                    'set YOLO_TTA_DIRECT_PREDICT=0 to use model.predict'
                )
            head, protos = split
            bsz = int(im.shape[0])
            no = int(head.shape[1])
            nm = int(protos.shape[1])
            if no != 4 + nc + nm or int(head.shape[0]) != bsz or int(protos.shape[0]) != bsz:
                raise RuntimeError(
                    f'direct predict: head/proto layout mismatch for {source_label} '
                    f'(head channels {no}, nc {nc}, protos {nm}); '
                    'set YOLO_TTA_DIRECT_PREDICT=0 to use model.predict'
                )
            if nc == 1 and device_compaction_active:
                _direct_fastpath = single_angle_gpu_fastpath()
                _direct_effective_threshold = max(
                    float(conf_thres),
                    float(_direct_fastpath[0]) if _direct_fastpath is not None else float(conf_thres),
                )
                compacted_payloads = [
                    _build_direct_device_compacted_payload(
                        head[int(i)], protos[int(i)], im, float(_direct_effective_threshold),
                        min_conf_applied=bool(
                            _direct_fastpath is not None and float(_direct_fastpath[0]) > 0.0
                        ),
                    )
                    for i in range(int(bsz))
                ]
                if all(payload is not None for payload in compacted_payloads):
                    if not _DIRECT_DEVICE_COMPACTION_ANNOUNCED:
                        _DIRECT_DEVICE_COMPACTION_ANNOUNCED = True
                        print(
                            'Direct device compaction active (v13.3.12 C3): confidence filtering, '
                            'proto dot/crop union, and instance counts remain on device; '
                            'YOLO_TTA_DIRECT_DEVICE_COMPACTION=0 restores the synchronized fallback.'
                        )
                    for payload in compacted_payloads:
                        yield _DirectPredictResult(payload)  # type: ignore[arg-type]
                    continue
                if not _DIRECT_DEVICE_COMPACTION_FALLBACK_WARNED:
                    _DIRECT_DEVICE_COMPACTION_FALLBACK_WARNED = True
                    print(
                        'Warning: direct device compaction unavailable; this source uses the '
                        'legacy nonzero/count fallback. The resident TensorRT ring remains independent.'
                    )
                # A deterministic dtype/CuPy/NVRTC failure or OOM should not repeat the same
                # clone/allocation/probe on every remaining batch in this source.
                device_compaction_active = False
            scores = head[:, 4:4 + nc, :]
            if nc == 1:
                conf_all = scores[:, 0, :]
                cls_all = None
            else:
                conf_all, cls_all = scores.max(dim=1)
            keep_mask = conf_all >= conf_thres  # (B, A)
            nz = keep_mask.nonzero()  # host sync #1; row-major => grouped by image
            if int(nz.shape[0]) > 0:
                counts = torch.bincount(nz[:, 0], minlength=bsz).tolist()  # host sync #2 (tiny)
            else:
                counts = [0] * bsz
            offset = 0
            for i in range(bsz):
                n_i = int(counts[i])
                if n_i <= 0:
                    pred_i = head.new_zeros((0, 6 + nm))
                else:
                    rows = nz[offset:offset + n_i, 1]
                    det = head[i].index_select(1, rows)  # (4+nc+nm, n) — copies out of binding memory
                    xy = det[0:2, :].transpose(0, 1).to(torch.float32)
                    half_wh = det[2:4, :].transpose(0, 1).to(torch.float32) * 0.5
                    conf_i = conf_all[i].index_select(0, rows).to(torch.float32).reshape(-1, 1)
                    cls_i = (
                        torch.zeros_like(conf_i)
                        if cls_all is None
                        else cls_all[i].index_select(0, rows).to(torch.float32).reshape(-1, 1)
                    )
                    coeffs = det[4 + nc:, :].transpose(0, 1).to(torch.float32)
                    pred_i = torch.cat([xy - half_wh, xy + half_wh, conf_i, cls_i, coeffs], dim=1)
                offset += n_i
                payload = _build_gpu_flattened_payload_from_proto(pred_i, im, protos[i])
                if payload is None:
                    raise RuntimeError(
                        f'direct predict: payload construction failed for {source_label}; '
                        'set YOLO_TTA_DIRECT_PREDICT=0 to use model.predict'
                    )
                yield _DirectPredictResult(payload)


def predict_source_and_accumulate(
    model,
    source: object,
    *,
    source_label: str,
    num_frames: int,
    out_size: int,
    cfg: PredictConfig,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    postprocess_workers: int = 1,
    streaming_cleanup_enabled: bool = False,
    streaming_cleanup_min_conf: float = 0.0,
    streaming_cleanup_min_radius: float = 0.0,
    slice_locks: Optional[Sequence[threading.Lock]] = None,
    device_hole_fill: bool = False,
    defer_device_union_flush: bool = False,
) -> Dict[str, object]:
    """Run YOLO predict(stream=True) on an in-memory source and accumulate native masks.

    The predictor consumes ``InMemoryYoloVolumeSource`` instances in the v12 path,
    so the GPU no longer reads augmented FFV1 videos from scratch.  CPU-side result
    handling remains bounded by ``cpu_mask_postprocess_pending_limit`` and runs
    behind the streamed GPU inference.  When the v12.2.8 single-angle cleanup
    path is enabled, slice-local filtering is appended to the same streamed
    postprocess unit so a completed prediction slice is already cleaned before
    the full view volume has finished inferencing.
    """
    # v13.2.5 (speed #7): only compute the GPU flatten's max-conf plane when a confidence
    # volume actually exists downstream.
    set_gpu_flatten_conf_tracking(view_confmap_mm is not None)
    ensure_yolo_ready_for_predict(model, cfg)
    unwrapped_source = source
    source = maybe_wrap_source_with_gpu_input_staging(source, cfg, source_label)
    # v13.2.2 bug #3: the call above may create a GpuPrefetchingYoloSource that nothing
    # else owns. If iteration is abandoned by an exception (model.predict setup, a
    # mid-stream CUDA error, a postprocess future failure), its producer thread and
    # VRAM-staged queue leaked for the life of the process. Close the wrapper created
    # here on the way out; on success this is an idempotent no-op (the sentinel path in
    # GpuPrefetchingYoloSource.__next__ already closed it).
    owned_staging_wrapper = (
        source
        if (source is not unwrapped_source and isinstance(source, GpuPrefetchingYoloSource))
        else None
    )
    try:
        if isinstance(source, (InMemoryYoloVolumeSource, StreamingYoloVolumeSource, GpuPrefetchingYoloSource, GpuRenderedYoloSource)):
            ensure_single_channel_yolo_preprocess_patch()
        use_custom_cpu_retina = False
        if cpu_retina_masks_enabled():
            use_custom_cpu_retina = bool(ensure_cpu_retina_mask_predictor_patch())
            if not use_custom_cpu_retina:
                print('Warning: CPU retina predictor patch unavailable; using Ultralytics native retina_masks=True for this source.')
        else:
            # v13.3.0 (R9): GPU retina mode — reduce unions at proto resolution inside
            # construct_result instead of materializing (n, imgsz, imgsz) retina stacks.
            ensure_gpu_retina_proto_union_predictor_patch()

        prediction_count = 0
        frames_with_predictions = 0

        # v13.3.6 (C2): drive the backend directly on the proto-union fast path; fall back
        # to Ultralytics stream_inference when the direct loop's preconditions do not hold.
        results = None
        predictor_direct = None
        if not use_custom_cpu_retina and _direct_predict_applicable(cfg):
            predictor_direct = _ensure_predictor_for_direct_predict(model, cfg)
            if predictor_direct is not None:
                results = _direct_predict_stream(predictor_direct, source, cfg, source_label)
        if results is None:
            results = model.predict(
                source=source,
                task='segment',
                imgsz=cfg.imgsz,
                conf=cfg.conf,
                iou=1.0,
                save=False,
                stream=True,
                retina_masks=not bool(use_custom_cpu_retina),
                batch=max(1, int(cfg.batch)),
                device=cfg.device,
                half=cfg.half,
                int8=cfg.int8,
                verbose=False,
            )

        worker_count = max(1, min(int(postprocess_workers), int(num_frames)))
        pending_limit = cpu_mask_postprocess_pending_limit(worker_count, int(num_frames))
        stream_cleanup = bool(streaming_cleanup_enabled)
        stream_backend = cleanup_backend() if stream_cleanup else ''
        stream_structure2 = np.ones((3, 3), dtype=bool) if stream_cleanup else None
        stream_min_conf = float(streaming_cleanup_min_conf)
        stream_min_radius = float(streaming_cleanup_min_radius)
        stream_min_conf_u8 = int(min_conf_to_u8_threshold(stream_min_conf)) if stream_min_conf > 0.0 else 0

        # v13.3.2 (R21)/v13.3.12: per-task device union accumulation. A positive min_conf is
        # allowed because the single-angle proto/ring compactor applies it before union; a
        # positive min_radius still requires component cleanup and therefore retains the
        # per-frame fallback. VRAM-gated; None keeps the pinned-D2H path.
        device_union: Optional[_DeviceUnionAccumulator] = None
        fastpath_confidence_on_device = bool(single_angle_gpu_fastpath() is not None)
        if (
            not cpu_retina_masks_enabled()
            and single_angle_gpu_fastpath() is not None
            and not (
                stream_cleanup
                and (
                    (stream_min_conf > 0.0 and not fastpath_confidence_on_device)
                    or stream_min_radius > 0.0
                )
            )
        ):
            device_union = _try_create_device_union_accumulator(
                canonical_single_device(str(cfg.device)),
                int(num_frames), int(native_h), int(native_w),
                want_conf=view_confmap_mm is not None,
            )
            if device_union is not None:
                print(
                    f'Device union accumulation active for {source_label}: '
                    f'{int(num_frames)}x{int(native_h)}x{int(native_w)} u8 on device (v13.3.2 R21).'
                )

        # Fixed batch-1, angle-0, resident-render path: run render -> TensorRT ->
        # confidence compaction/proto union -> native task union as one device pipeline.
        # It consumes no Results objects and dispatches no per-frame Futures. Capability
        # rejection happens before source consumption and leaves ``results`` untouched.
        specialized_stats: Optional[Dict[str, int]] = None
        if predictor_direct is not None:
            specialized_stats = _try_resident_trt_ring_accumulate(
                predictor_direct, source, cfg,
                source_label=source_label,
                num_frames=int(num_frames),
                out_size=int(out_size),
                M_out_to_native=M_out_to_native,
                native_h=int(native_h),
                native_w=int(native_w),
                device_union=device_union,
            )
            if specialized_stats is not None:
                prediction_count = int(specialized_stats['prediction_count'])
                frames_with_predictions = int(specialized_stats['frames_with_predictions'])

        def _process_prediction_unit(idx_i: int, masks_obj: Optional[object], confs_arr: Optional[np.ndarray]) -> Tuple[int, int]:
            slice_lock = None
            if slice_locks is not None and len(slice_locks) > 0:
                slice_lock = slice_locks[int(idx_i) % len(slice_locks)]
            if isinstance(masks_obj, GpuFlattenedRetinaPayload):
                # The payload builder only sees the process-global/native CLI radius. D6's
                # destination may be a smaller canonical grid, so override it with this
                # prediction source's already-scaled radius before GPU component cleanup.
                masks_obj.gpu_min_radius = float(stream_min_radius)
                masks_obj.run_gpu_cleanup = bool(
                    single_angle_gpu_fastpath() is not None
                    and gpu_retina_cleanup_enabled()
                    and float(stream_min_radius) > 0.0
                )
            pred_inc, frame_inc = _process_prediction_frame(
                idx=int(idx_i),
                masks_np=masks_obj,
                confs_np=confs_arr,
                out_size=out_size,
                view_union_mm=view_union_mm,
                view_confmap_mm=view_confmap_mm,
                M_out_to_native=M_out_to_native,
                native_h=native_h,
                native_w=native_w,
                slice_lock=slice_lock,
                device_union=device_union,
            )
            # v13.1.0 (#2.3): skip the per-slice CPU streaming cleanup when the GPU fast path already ran
            # --min_conf + --min_radius + hole fill on this slice (cleanup_done_on_gpu is set by the frame
            # processor only when the on-GPU connected-component cleanup actually completed).
            # v13.3.2 (R21): also skip it for device-accumulated frames — their host slice is
            # written by the task-end flush, and this cleanup was gated to scan-only work anyway.
            if (
                stream_cleanup
                and not bool(getattr(masks_obj, 'cleanup_done_on_gpu', False))
                and not bool(getattr(masks_obj, 'accumulated_on_device', False))
            ):
                cleaned_has_foreground = _cleanup_prediction_slice_inplace(
                    view_union_mm,
                    view_confmap_mm,
                    int(idx_i),
                    min_conf=stream_min_conf,
                    min_radius=stream_min_radius,
                    backend=stream_backend,
                    structure2=stream_structure2,
                    min_conf_u8=stream_min_conf_u8,
                )
                frame_inc = 1 if bool(cleaned_has_foreground) else 0
            return int(pred_inc), int(frame_inc)

        def _extract_and_process_result(idx_i: int, result_obj: object) -> Tuple[int, int]:
            masks_np, confs_np = _extract_result_masks_and_confs(result_obj)
            try:
                del result_obj
            except Exception:
                pass
            return _process_prediction_unit(int(idx_i), masks_np, confs_np)

        # v13.1.0 (#2.2): on the GPU-flatten path, eagerly reduce each (n,Hr,Wr) GPU stack to 2 small
        # planes on this (stream) thread so the full stack is released immediately, and bound the queue so
        # only a capped number of GPU-resident flattened frames stay alive (avoids device OOM).
        gpu_flatten_eager = bool(
            gpu_retina_flatten_enabled() and not cpu_retina_masks_enabled() and gpu_retina_eager_flatten_enabled()
        )
        effective_pending_limit = int(pending_limit)
        if gpu_flatten_eager:
            effective_pending_limit = max(1, min(int(pending_limit), gpu_retina_flatten_pending_limit(worker_count)))

        if specialized_stats is not None:
            # The resident ring wrote the device union and task metadata directly.
            pass
        elif worker_count <= 1:
            for idx, r in enumerate(results):
                if idx >= num_frames:
                    # Synthetic final-batch padding is required for fixed-batch inference engines;
                    # consume but discard those results so the predictor stream drains cleanly.
                    continue
                masks_np, confs_np = _extract_result_masks_and_confs(r)
                pred_inc, frame_inc = _process_prediction_unit(int(idx), masks_np, confs_np)
                prediction_count += int(pred_inc)
                frames_with_predictions += int(frame_inc)
        else:
            pending: List[Future] = []
            # v13.3.4 (T5): checkout-cached pool — one build per worker process, not per task.
            executor = _acquire_parallel_pool(worker_count)
            try:
                for idx, r in enumerate(results):
                    if idx >= num_frames:
                        # Discard synthetic repeated-slice results from the padded final batch.
                        continue

                    if gpu_flatten_eager:
                        masks_np, confs_np = _extract_result_masks_and_confs(r)
                        try:
                            del r
                        except Exception:
                            pass
                        pending.append(executor.submit(_process_prediction_unit, int(idx), masks_np, confs_np))
                    else:
                        pending.append(executor.submit(_extract_and_process_result, int(idx), r))
                    if len(pending) >= effective_pending_limit:
                        fut = pending.pop(0)
                        pred_inc, frame_inc = fut.result()
                        prediction_count += int(pred_inc)
                        frames_with_predictions += int(frame_inc)

                while pending:
                    fut = pending.pop(0)
                    pred_inc, frame_inc = fut.result()
                    prediction_count += int(pred_inc)
                    frames_with_predictions += int(frame_inc)
            finally:
                _settle_parallel_futures(pending)
                _release_parallel_pool(worker_count, executor)

        if device_union is not None and specialized_stats is None:
            compacted_predictions, compacted_frames = device_union.take_device_prediction_stats()
            prediction_count += int(compacted_predictions)
            frames_with_predictions += int(compacted_frames)

        # v13.3.3 (S2): when requested (single-angle, no min_conf/min_radius work), hole-fill the
        # accumulated device union per slice ON DEVICE before the flush; the scheduler then skips
        # the CPU per-view "2D hole fill" pass once every slice of the view reports device-filled.
        device_hole_filled_frames = 0
        if device_union is not None and bool(device_hole_fill) and gpu_device_hole_fill_enabled():
            device_hole_filled_frames = int(device_union.fill_holes_2d())

        # v13.3.6 (D1): per-slice foreground metadata from the resident union (post hole
        # fill, pre flush) — a few hundred KB that saves whole CPU read passes downstream.
        slice_meta = device_union.compute_slice_metadata() if device_union is not None else None

        # v13.3.14 (G8): a multi-GPU worker may retire this accumulator on its private
        # copy/host-merge thread while the main worker starts the next task with a second
        # accumulator. Seal all producer streams BEFORE submission; the retirement thread
        # then skips its old device-wide sync so it cannot accidentally wait on next-task
        # kernels. The worker withholds this task's result until the returned Future settles.
        device_union_flush_future: Optional[Future] = None
        if device_union is not None:
            if bool(defer_device_union_flush) and gpu_union_flush_overlap_enabled():
                device_union.synchronize_for_retirement()

                def _retire_device_union() -> None:
                    device_union.flush_into(
                        view_union_mm, view_confmap_mm, synchronize_device=False,
                    )
                    if prediction_hot_path_flush_enabled():
                        if view_confmap_mm is not None:
                            flush_array(view_confmap_mm)
                        flush_array(view_union_mm)

                device_union_flush_future = _gpu_union_flush_executor().submit(
                    _retire_device_union,
                )
            else:
                device_union.flush_into(view_union_mm, view_confmap_mm)

        if prediction_hot_path_flush_enabled() and device_union_flush_future is None:
            if view_confmap_mm is not None:
                flush_array(view_confmap_mm)
            flush_array(view_union_mm)

        return {
            'prediction_count': int(prediction_count),
            'frames_with_predictions': int(frames_with_predictions),
            'device_hole_filled_frames': int(device_hole_filled_frames),
            'slice_meta': slice_meta,
            # Private worker protocol; removed before the stats cross the process queue.
            '_device_union_flush_future': device_union_flush_future,
        }
    finally:
        if owned_staging_wrapper is not None:
            try:
                owned_staging_wrapper.close()
            except Exception:
                pass


def predict_source_and_submit_accumulation(
    model,
    source: object,
    *,
    source_label: str,
    num_frames: int,
    out_size: int,
    cfg: PredictConfig,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    postprocess_executor: ThreadPoolExecutor,
    streaming_cleanup_enabled: bool = False,
    streaming_cleanup_min_conf: float = 0.0,
    streaming_cleanup_min_radius: float = 0.0,
    slice_locks: Optional[Sequence[threading.Lock]] = None,
) -> PredictionAccumulationHandle:
    """Run YOLO streaming inference and enqueue result accumulation without draining it."""
    # v13.2.5 (speed #7): only compute the GPU flatten's max-conf plane when a confidence
    # volume actually exists downstream.
    set_gpu_flatten_conf_tracking(view_confmap_mm is not None)
    ensure_yolo_ready_for_predict(model, cfg)
    unwrapped_source = source
    source = maybe_wrap_source_with_gpu_input_staging(source, cfg, source_label)
    # v13.2.2 bug #3: the call above may create a GpuPrefetchingYoloSource that nothing
    # else owns. If iteration is abandoned by an exception (model.predict setup, a
    # mid-stream CUDA error, a postprocess future failure), its producer thread and
    # VRAM-staged queue leaked for the life of the process. Close the wrapper created
    # here on the way out; on success this is an idempotent no-op (the sentinel path in
    # GpuPrefetchingYoloSource.__next__ already closed it).
    owned_staging_wrapper = (
        source
        if (source is not unwrapped_source and isinstance(source, GpuPrefetchingYoloSource))
        else None
    )
    try:
        if isinstance(source, (InMemoryYoloVolumeSource, StreamingYoloVolumeSource, GpuPrefetchingYoloSource, GpuRenderedYoloSource)):
            ensure_single_channel_yolo_preprocess_patch()
        use_custom_cpu_retina = False
        if cpu_retina_masks_enabled():
            use_custom_cpu_retina = bool(ensure_cpu_retina_mask_predictor_patch())
            if not use_custom_cpu_retina:
                print('Warning: CPU retina predictor patch unavailable; using Ultralytics native retina_masks=True for this source.')
        else:
            # v13.3.0 (R9): GPU retina mode — reduce unions at proto resolution inside
            # construct_result instead of materializing (n, imgsz, imgsz) retina stacks.
            ensure_gpu_retina_proto_union_predictor_patch()

        # v13.3.6 (C2): same direct-loop preference as predict_source_and_accumulate.
        results = None
        if not use_custom_cpu_retina and _direct_predict_applicable(cfg):
            predictor_direct = _ensure_predictor_for_direct_predict(model, cfg)
            if predictor_direct is not None:
                results = _direct_predict_stream(predictor_direct, source, cfg, source_label)
        if results is None:
            results = model.predict(
                source=source,
                task='segment',
                imgsz=cfg.imgsz,
                conf=cfg.conf,
                iou=1.0,
                save=False,
                stream=True,
                retina_masks=not bool(use_custom_cpu_retina),
                batch=max(1, int(cfg.batch)),
                device=cfg.device,
                half=cfg.half,
                int8=cfg.int8,
                verbose=False,
            )

        stream_cleanup = bool(streaming_cleanup_enabled)
        stream_backend = cleanup_backend() if stream_cleanup else ''
        stream_structure2 = np.ones((3, 3), dtype=bool) if stream_cleanup else None
        stream_min_conf = float(streaming_cleanup_min_conf)
        stream_min_radius = float(streaming_cleanup_min_radius)
        stream_min_conf_u8 = int(min_conf_to_u8_threshold(stream_min_conf)) if stream_min_conf > 0.0 else 0

        def _process_prediction_unit(idx_i: int, masks_obj: Optional[object], confs_arr: Optional[np.ndarray]) -> Tuple[int, int]:
            slice_lock = None
            if slice_locks is not None and len(slice_locks) > 0:
                slice_lock = slice_locks[int(idx_i) % len(slice_locks)]
            if isinstance(masks_obj, GpuFlattenedRetinaPayload):
                masks_obj.gpu_min_radius = float(stream_min_radius)
                masks_obj.run_gpu_cleanup = bool(
                    single_angle_gpu_fastpath() is not None
                    and gpu_retina_cleanup_enabled()
                    and float(stream_min_radius) > 0.0
                )
            pred_inc, frame_inc = _process_prediction_frame(
                idx=int(idx_i),
                masks_np=masks_obj,
                confs_np=confs_arr,
                out_size=out_size,
                view_union_mm=view_union_mm,
                view_confmap_mm=view_confmap_mm,
                M_out_to_native=M_out_to_native,
                native_h=native_h,
                native_w=native_w,
                slice_lock=slice_lock,
            )
            # v13.1.0 (#2.3): skip the per-slice CPU streaming cleanup when the GPU fast path already ran
            # --min_conf + --min_radius + hole fill on this slice (cleanup_done_on_gpu is set by the frame
            # processor only when the on-GPU connected-component cleanup actually completed).
            if stream_cleanup and not bool(getattr(masks_obj, 'cleanup_done_on_gpu', False)):
                cleaned_has_foreground = _cleanup_prediction_slice_inplace(
                    view_union_mm,
                    view_confmap_mm,
                    int(idx_i),
                    min_conf=stream_min_conf,
                    min_radius=stream_min_radius,
                    backend=stream_backend,
                    structure2=stream_structure2,
                    min_conf_u8=stream_min_conf_u8,
                )
                frame_inc = 1 if bool(cleaned_has_foreground) else 0
            return int(pred_inc), int(frame_inc)

        def _extract_and_process_result(idx_i: int, result_obj: object) -> Tuple[int, int]:
            masks_np, confs_np = _extract_result_masks_and_confs(result_obj)
            try:
                del result_obj
            except Exception:
                pass
            return _process_prediction_unit(int(idx_i), masks_np, confs_np)

        futures: List[Future] = []
        submitted_frames = 0
        synthetic_discarded = 0
        precompleted_prediction_count = 0
        precompleted_frames_with_predictions = 0
        pending_limit = async_predict_pending_frame_limit(int(num_frames))

        # v13.1.0 (#2.2): eagerly reduce GPU stacks to 2 small planes on this thread and bound the queue
        # so GPU-resident flattened frames stay capped (see predict_source_and_accumulate).
        gpu_flatten_eager = bool(
            gpu_retina_flatten_enabled() and not cpu_retina_masks_enabled() and gpu_retina_eager_flatten_enabled()
        )
        if gpu_flatten_eager:
            gpu_cap = gpu_retina_flatten_pending_limit(max(1, int(getattr(postprocess_executor, '_max_workers', 1) or 1)))
            pending_limit = max(1, min(int(pending_limit) if int(pending_limit) > 0 else gpu_cap, gpu_cap))

        def _join_one_pending() -> None:
            nonlocal futures, precompleted_prediction_count, precompleted_frames_with_predictions
            if not futures:
                return
            done, remaining = wait(set(futures), return_when=FIRST_COMPLETED)
            futures = list(remaining)
            for fut_done in done:
                pred_inc, frame_inc = fut_done.result()
                precompleted_prediction_count += int(pred_inc)
                precompleted_frames_with_predictions += int(frame_inc)

        for idx, r in enumerate(results):
            if int(idx) >= int(num_frames):
                synthetic_discarded += 1
                continue
            submitted_frames += 1
            if gpu_flatten_eager:
                masks_np, confs_np = _extract_result_masks_and_confs(r)
                try:
                    del r
                except Exception:
                    pass
                futures.append(postprocess_executor.submit(_process_prediction_unit, int(idx), masks_np, confs_np))
            else:
                futures.append(postprocess_executor.submit(_extract_and_process_result, int(idx), r))
            while int(pending_limit) > 0 and len(futures) >= int(pending_limit):
                _join_one_pending()

        return PredictionAccumulationHandle(
            source_label=str(source_label),
            futures=futures,
            view_union_mm=view_union_mm,
            view_confmap_mm=view_confmap_mm,
            submitted_frames=int(submitted_frames),
            synthetic_discarded=int(synthetic_discarded),
            precompleted_prediction_count=int(precompleted_prediction_count),
            precompleted_frames_with_predictions=int(precompleted_frames_with_predictions),
            pending_limit=int(pending_limit),
        )
    finally:
        if owned_staging_wrapper is not None:
            try:
                owned_staging_wrapper.close()
            except Exception:
                pass


def predict_in_memory_volume_and_submit_accumulation(
    model,
    prediction_volume: PredictionVolumeRef,
    *,
    num_frames: int,
    out_size: int,
    cfg: PredictConfig,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    postprocess_executor: ThreadPoolExecutor,
    streaming_cleanup_enabled: bool = False,
    streaming_cleanup_min_conf: float = 0.0,
    streaming_cleanup_min_radius: float = 0.0,
    slice_locks: Optional[Sequence[threading.Lock]] = None,
) -> PredictionAccumulationHandle:
    source = make_prediction_ref_yolo_source(
        prediction_volume,
        batch_size=max(1, int(cfg.batch)),
        max_frames=int(num_frames),
    )
    return predict_source_and_submit_accumulation(
        model,
        source,
        source_label=prediction_volume.name,
        num_frames=int(num_frames),
        out_size=int(out_size),
        cfg=cfg,
        view_union_mm=view_union_mm,
        view_confmap_mm=view_confmap_mm,
        M_out_to_native=M_out_to_native,
        native_h=int(native_h),
        native_w=int(native_w),
        postprocess_executor=postprocess_executor,
        streaming_cleanup_enabled=bool(streaming_cleanup_enabled),
        streaming_cleanup_min_conf=float(streaming_cleanup_min_conf),
        streaming_cleanup_min_radius=float(streaming_cleanup_min_radius),
        slice_locks=slice_locks,
    )

def predict_in_memory_volume_and_accumulate(
    model,
    prediction_volume: PredictionVolumeRef,
    *,
    num_frames: int,
    out_size: int,
    cfg: PredictConfig,
    view_union_mm: np.ndarray,
    view_confmap_mm: Optional[np.ndarray],
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    postprocess_workers: int = 1,
    streaming_cleanup_enabled: bool = False,
    streaming_cleanup_min_conf: float = 0.0,
    streaming_cleanup_min_radius: float = 0.0,
    slice_locks: Optional[Sequence[threading.Lock]] = None,
) -> Dict[str, int]:
    source = make_prediction_ref_yolo_source(
        prediction_volume,
        batch_size=max(1, int(cfg.batch)),
        max_frames=int(num_frames),
    )
    return predict_source_and_accumulate(
        model,
        source,
        source_label=prediction_volume.name,
        num_frames=int(num_frames),
        out_size=int(out_size),
        cfg=cfg,
        view_union_mm=view_union_mm,
        view_confmap_mm=view_confmap_mm,
        M_out_to_native=M_out_to_native,
        native_h=int(native_h),
        native_w=int(native_w),
        postprocess_workers=int(postprocess_workers),
        streaming_cleanup_enabled=bool(streaming_cleanup_enabled),
        streaming_cleanup_min_conf=float(streaming_cleanup_min_conf),
        streaming_cleanup_min_radius=float(streaming_cleanup_min_radius),
        slice_locks=slice_locks,
    )


# --------------------------
# Per-view postprocessing
# --------------------------


def cleanup_backend() -> str:
    """Return the per-slice cleanup backend.

    OpenCV is the default because the hot operations used here release the GIL and scale better
    under Python thread pools. Set YOLO_TTA_CLEANUP_BACKEND=scipy to recover the older scipy.ndimage
    cleanup path for debugging or strict regression comparison.
    """
    backend = os.environ.get('YOLO_TTA_CLEANUP_BACKEND', 'opencv').strip().lower()
    if backend not in {'opencv', 'scipy'}:
        backend = 'opencv'
    return backend


def _cv2_connected_components(mask_u8: np.ndarray, connectivity: int = 8) -> Tuple[int, np.ndarray]:
    return cv2.connectedComponents(
        np.ascontiguousarray(mask_u8, dtype=np.uint8),
        connectivity=int(connectivity),
        ltype=cv2.CV_32S,
    )


def _fill_holes_2d_scipy(mask_bool: np.ndarray) -> np.ndarray:
    return np.asarray(ndi.binary_fill_holes(np.asarray(mask_bool, dtype=bool)), dtype=bool)


def _fill_holes_2d_opencv(mask_bool: np.ndarray) -> np.ndarray:
    """Fill 2D holes using background connected components.

    This matches scipy.ndimage.binary_fill_holes' default 2D background connectivity (4-connected)
    while avoiding the slower Python-visible scipy path for thousands of large slices.
    """
    mask_u8 = np.ascontiguousarray(np.asarray(mask_bool, dtype=np.uint8))
    if mask_u8.size == 0 or not np.any(mask_u8):
        return np.zeros(mask_u8.shape, dtype=bool)
    if bool(np.all(mask_u8)):
        return np.ones(mask_u8.shape, dtype=bool)

    bg_u8 = (mask_u8 == 0).astype(np.uint8, copy=False)
    num_labels, labels2d = _cv2_connected_components(bg_u8, connectivity=4)
    if int(num_labels) <= 1:
        return mask_u8.astype(bool, copy=False)

    touches_boundary = np.zeros((int(num_labels),), dtype=bool)
    touches_boundary[np.unique(labels2d[0, :])] = True
    touches_boundary[np.unique(labels2d[-1, :])] = True
    touches_boundary[np.unique(labels2d[:, 0])] = True
    touches_boundary[np.unique(labels2d[:, -1])] = True

    enclosed_bg = (labels2d > 0) & (~touches_boundary[labels2d])
    if np.any(enclosed_bg):
        mask_u8 = mask_u8.copy()
        mask_u8[enclosed_bg] = np.uint8(1)
    return mask_u8.astype(bool, copy=False)


def _fill_holes_2d_opencv_u8_inplace(arr_u8: np.ndarray) -> None:
    """v13.3.3 (S3): ``_fill_holes_2d_opencv`` without the bool->u8->bool->u8 churn.

    Labels the background of the (contiguous) uint8 slice directly (4-connected, matching
    scipy.ndimage.binary_fill_holes' default) and writes ONLY the enclosed-hole pixels back,
    instead of materializing bool/u8 copies and rewriting the full plane.
    """
    bg = arr_u8 == 0
    if not bg.any():
        return
    num_labels, labels2d = _cv2_connected_components(bg.view(np.uint8), connectivity=4)
    if int(num_labels) <= 1:
        return
    touches_boundary = np.zeros((int(num_labels),), dtype=bool)
    touches_boundary[np.unique(labels2d[0, :])] = True
    touches_boundary[np.unique(labels2d[-1, :])] = True
    touches_boundary[np.unique(labels2d[:, 0])] = True
    touches_boundary[np.unique(labels2d[:, -1])] = True
    enclosed_bg = (labels2d > 0) & (~touches_boundary[labels2d])
    if np.any(enclosed_bg):
        arr_u8[enclosed_bg] = np.uint8(1)


def _filter_connected_components_by_min_radius_scipy(
    mask_bool: np.ndarray,
    structure2: np.ndarray,
    min_radius: float,
) -> np.ndarray:
    labels2d, num = ndi.label(mask_bool, structure=structure2)
    if int(num) <= 0:
        return np.zeros(mask_bool.shape, dtype=bool)

    label_ids = np.arange(1, int(num) + 1, dtype=np.int32)
    dist = np.asarray(ndi.distance_transform_edt(mask_bool), dtype=np.float32)
    radii = np.asarray(ndi.maximum(dist, labels=labels2d, index=label_ids), dtype=np.float32)
    keep_ids = label_ids[radii >= float(min_radius)]
    if keep_ids.size <= 0:
        return np.zeros(mask_bool.shape, dtype=bool)
    return np.isin(labels2d, keep_ids)


def _filter_connected_components_by_min_radius_opencv(
    mask_bool: np.ndarray,
    min_radius: float,
) -> np.ndarray:
    mask_u8 = np.ascontiguousarray(np.asarray(mask_bool, dtype=np.uint8))
    if mask_u8.size == 0 or not np.any(mask_u8):
        return np.zeros(mask_u8.shape, dtype=bool)

    num_labels, labels2d = _cv2_connected_components(mask_u8, connectivity=8)
    if int(num_labels) <= 1:
        return np.zeros(mask_u8.shape, dtype=bool)

    dist = cv2.distanceTransform(mask_u8, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)
    radii = np.zeros((int(num_labels),), dtype=np.float32)
    np.maximum.at(radii, labels2d.ravel(), np.asarray(dist, dtype=np.float32).ravel())
    keep_lookup = radii >= float(min_radius)
    keep_lookup[0] = False
    return keep_lookup[labels2d]


def _filter_connected_components_by_min_conf_opencv(
    mask_bool: np.ndarray,
    conf_slice: np.ndarray,
    min_conf_u8: int,
) -> np.ndarray:
    mask_u8 = np.ascontiguousarray(np.asarray(mask_bool, dtype=np.uint8))
    if mask_u8.size == 0 or not np.any(mask_u8):
        return np.zeros(mask_u8.shape, dtype=bool)

    num_labels, labels2d = _cv2_connected_components(mask_u8, connectivity=8)
    if int(num_labels) <= 1:
        return np.zeros(mask_u8.shape, dtype=bool)

    maxima = np.zeros((int(num_labels),), dtype=np.uint8)
    np.maximum.at(maxima, labels2d.ravel(), np.asarray(conf_slice, dtype=np.uint8).ravel())
    keep_lookup = maxima >= int(min_conf_u8)
    keep_lookup[0] = False
    return keep_lookup[labels2d]


def _filter_connected_components_by_min_conf_scipy(
    mask_bool: np.ndarray,
    conf_slice: np.ndarray,
    min_conf_u8: int,
    structure2: np.ndarray,
) -> np.ndarray:
    labels2d, num = ndi.label(mask_bool, structure=structure2)
    if int(num) <= 0:
        return np.zeros(mask_bool.shape, dtype=bool)
    label_ids = np.arange(1, int(num) + 1, dtype=np.int32)
    maxima = np.asarray(ndi.maximum(conf_slice, labels=labels2d, index=label_ids), dtype=np.uint8)
    keep_ids = label_ids[maxima >= int(min_conf_u8)]
    if keep_ids.size <= 0:
        return np.zeros(mask_bool.shape, dtype=bool)
    return np.isin(labels2d, keep_ids)


def _view_native_slice_min_radius(view: ViewInfo, min_radius: float) -> float:
    """Return the --min_radius applied on this view's own native 2D slices.

    v13.1.0 (spec): --min_radius is measured on the YOLO output masks in each prediction set's
    OWN native 2D slice plane, before backprojection, independently per active view. Every
    view's native slice plane is therefore the plane --min_radius is measured in, so the full
    radius is returned for all views (Transverse, Sagittal, Coronal, Radial, Tilted, and tiles).
    The previous transverse-plane special-casing -- which returned the radius only for Transverse
    and Tilted-Transverse and deferred Sagittal/Coronal/Radial/Tilted to a transverse-plane pass --
    is retired, which also removes every deferred/post-backprojection radius stage from scheduling.
    """
    if float(min_radius) <= 0.0:
        return 0.0
    return float(min_radius)


def _cleanup_prediction_slice_inplace(
    mask_mm: np.ndarray,
    confmap_mm: Optional[np.ndarray],
    idx: int,
    *,
    min_conf: float = 0.0,
    min_radius: float = 0.0,
    backend: Optional[str] = None,
    structure2: Optional[np.ndarray] = None,
    min_conf_u8: Optional[int] = None,
) -> bool:
    """Clean one accumulated native-view prediction slice in place.

    This is the unit used by the v12.2.8 single-angle streaming path and by the
    older whole-volume cleanup pass. v13.0.0 applies the spec-ordered slice-local
    semantics: confidence gating (--min_conf) followed by view-native 2D min-radius
    filtering (--min_radius). 2D hole filling is NOT performed here; per spec items
    5-6 it runs as a final per-view volume pass after radius filtering, so it is
    handled by cleanup_view_volume_after_prediction_inplace(). v13.1.0 (spec): the full
    --min_radius is valid on every view's own native slice plane, so there is no longer
    any deferred transposed/transverse-plane radius pass for Sagittal/Coronal (or any
    post-backprojection radius pass for Radial/Tilted); this per-slice unit is the only
    radius stage.
    """
    idx_i = int(idx)
    if confmap_mm is None and float(min_conf) <= 0.0 and float(min_radius) <= 0.0:
        # v13.2.5 (speed #7): nothing to filter and no confidence map to zero — skip the full
        # slice bool-cast + unconditional write-back (a pure read+rewrite no-op at
        # --min_conf 0 --min_radius 0) and report foreground from a read-only scan.
        return bool(np.any(np.asarray(mask_mm[idx_i])))
    backend_norm = cleanup_backend() if backend is None else str(backend)
    structure = np.ones((3, 3), dtype=bool) if structure2 is None else structure2
    min_conf_u8_i = (
        int(min_conf_to_u8_threshold(float(min_conf)))
        if min_conf_u8 is None and float(min_conf) > 0.0
        else int(min_conf_u8 or 0)
    )

    mask_slice = np.asarray(mask_mm[idx_i], dtype=bool)
    conf_slice = None if confmap_mm is None else np.asarray(confmap_mm[idx_i], dtype=np.uint8)

    if np.any(mask_slice) and conf_slice is not None and float(min_conf) > 0.0:
        if backend_norm == 'opencv':
            mask_slice = _filter_connected_components_by_min_conf_opencv(
                mask_slice,
                conf_slice,
                int(min_conf_u8_i),
            )
        else:
            mask_slice = _filter_connected_components_by_min_conf_scipy(
                mask_slice,
                conf_slice,
                int(min_conf_u8_i),
                structure,
            )

    # v13.0.0 (bug fix): apply --min_radius BEFORE hole filling. Spec items 5-6 require the order
    # --min_conf -> --min_radius -> hole fill, with hole filling applied to the FINAL per-view
    # volume. Hole filling is therefore performed as a separate volume-level 2D pass in
    # cleanup_view_volume_after_prediction_inplace() after the (v13.1.0: native per-view) radius
    # filter completes, rather than here in the per-slice unit (which previously hole-filled before radius).
    if np.any(mask_slice) and float(min_radius) > 0.0:
        if backend_norm == 'opencv':
            mask_slice = _filter_connected_components_by_min_radius_opencv(
                mask_slice,
                float(min_radius),
            )
        else:
            mask_slice = _filter_connected_components_by_min_radius_scipy(
                mask_slice,
                structure,
                float(min_radius),
            )

    has_foreground = bool(np.any(mask_slice))
    mask_mm[idx_i, :, :] = mask_slice.astype(np.uint8, copy=False)
    if conf_slice is not None:
        if has_foreground:
            conf_slice[~mask_slice] = np.uint8(0)
        else:
            conf_slice.fill(np.uint8(0))
        confmap_mm[idx_i, :, :] = conf_slice.astype(np.uint8, copy=False)
    return bool(has_foreground)


_INFERENCE_BATCH_SIZE = 1

# v13.2.5 (speed #7): whether the GPU retina flatten should compute the per-frame max-confidence
# plane. Set by the predict entry points from whether a confidence volume actually exists
# (--min_conf > 0); with it disabled the flatten skips one (n,H,W) float transient per frame.
_GPU_FLATTEN_TRACK_CONF = True


def set_gpu_flatten_conf_tracking(enabled: bool) -> None:
    global _GPU_FLATTEN_TRACK_CONF
    _GPU_FLATTEN_TRACK_CONF = bool(enabled)


def gpu_flatten_conf_tracking_enabled() -> bool:
    return bool(_GPU_FLATTEN_TRACK_CONF)


def set_inference_batch_size(batch_size: int) -> None:
    global _INFERENCE_BATCH_SIZE
    _INFERENCE_BATCH_SIZE = max(1, int(batch_size))


def inference_batch_size() -> int:
    return max(1, int(_INFERENCE_BATCH_SIZE))


def fused_slice_cleanup_inplace(
    mask_mm: np.ndarray,
    confmap_mm: Optional[np.ndarray] = None,
    *,
    min_conf: float = 0.0,
    min_radius: float = 0.0,
    workers: int = 1,
    desc: str = 'Fused slice cleanup',
) -> None:
    """Slice-parallel cleanup with chunked worker fan-out.

    The old path delegated one future per slice and, when ``--min_radius`` was active, performed a
    Python loop plus one EDT per connected component. On large sparse slices that makes the stage
    look effectively single-threaded even though it nominally uses a thread pool. The updated path
    keeps the same semantics but:
      - submits chunked slice ranges so worker threads stay busy with lower dispatch overhead
      - computes connected-component radii with one EDT + one reduce per slice instead of one EDT
        per component
    """
    num_slices = int(mask_mm.shape[0])
    structure2 = np.ones((3, 3), dtype=bool)
    min_conf_u8 = int(min_conf_to_u8_threshold(float(min_conf))) if float(min_conf) > 0.0 else 0
    worker_count = choose_slice_parallel_workers(int(workers), num_slices)
    chunk_size = choose_parallel_chunk_size(num_slices, worker_count, target_chunks_per_worker=2, min_chunk_size=1)
    backend = cleanup_backend()

    def _process(i: int) -> None:
        _cleanup_prediction_slice_inplace(
            mask_mm,
            confmap_mm,
            int(i),
            min_conf=float(min_conf),
            min_radius=float(min_radius),
            backend=backend,
            structure2=structure2,
            min_conf_u8=int(min_conf_u8),
        )

    parallel_for_indices_chunked(
        num_slices,
        _process,
        max_workers=worker_count,
        desc=desc,
        chunk_size=chunk_size,
    )
    flush_array(mask_mm)
    if confmap_mm is not None:
        flush_array(confmap_mm)


def fill_view_volume_holes_2d_inplace(
    mask_mm: np.ndarray,
    *,
    workers: int = 1,
    desc: str = '2D hole fill (per-view volume)',
) -> None:
    """v13.0.0: fill 2D enclosed holes per slice across a completed per-view mask volume.

    Spec item 6 applies hole filling to each final per-view volume AFTER --min_conf and
    --min_radius. Holes appear because unioned overlapping masks can enclose a background
    region in 2D. This runs slice-parallel; each slice sets to foreground any background
    connected component fully enclosed by foreground. Empty slices are skipped.
    """
    num_slices = int(mask_mm.shape[0])
    if num_slices <= 0:
        return
    backend = cleanup_backend()
    worker_count = choose_slice_parallel_workers(int(workers), num_slices)
    chunk_size = choose_parallel_chunk_size(num_slices, worker_count, target_chunks_per_worker=2, min_chunk_size=1)

    def _process(i: int) -> None:
        idx_i = int(i)
        # v13.3.3 (S3): stay uint8 end-to-end and write back only the enclosed-hole pixels —
        # the old path cast to bool, filled into a fresh plane, and rewrote the whole slice.
        arr = np.asarray(mask_mm[idx_i])
        if not arr.any():
            return
        if backend == 'opencv':
            _fill_holes_2d_opencv_u8_inplace(arr)
        else:
            filled = _fill_holes_2d_scipy(arr > 0)
            holes = filled & (arr == 0)
            if bool(np.any(holes)):
                arr[holes] = np.uint8(1)

    parallel_for_indices_chunked(
        num_slices,
        _process,
        max_workers=worker_count,
        desc=desc,
        chunk_size=chunk_size,
    )
    flush_array(mask_mm)


def cleanup_view_volume_after_prediction_inplace(
    mask_mm: np.ndarray,
    confmap_mm: Optional[np.ndarray],
    view: ViewInfo,
    min_conf: float,
    min_radius: float,
    *,
    workers: int = 1,
    precleaned_slice_cleanup: bool = False,
    skip_hole_fill: bool = False,
) -> None:
    # v13.3.12 (D6): non-radial masks can still be on the canonical inference grid here.
    # Convert the native-view radius once and perform every component operation on that smaller
    # raster. Radial already owns a deliberately folded native raster and keeps its historical
    # threshold unchanged.
    native_min_radius = view_processing_min_radius(
        view, float(min_radius), np.asarray(mask_mm).shape[-2:],
    )

    if bool(precleaned_slice_cleanup):
        # v12.2.8 single-angle inference has already applied per-slice --min_conf and the full
        # view-native --min_radius as results streamed in (streaming_cleanup_min_radius now equals
        # the full radius for every view), so nothing radius-related remains before the final
        # hole-fill pass.
        pass
    else:
        effective_confmap_mm = confmap_mm if float(min_conf) > 0.0 else None

        fused_slice_cleanup_inplace(
            mask_mm,
            effective_confmap_mm,
            min_conf=float(min_conf),
            min_radius=float(native_min_radius),
            workers=int(workers),
            desc=f'Fused cleanup ({view.name})',
        )

    # v13.0.0 (bug fix): 2D hole filling is the FINAL per-view step (spec item 6), applied after
    # --min_conf and the view-native --min_radius filter. The previous order hole-filled before
    # --min_radius inside the per-slice unit.
    # v13.3.3 (S2): skipped when every slice of this view was already hole-filled on device by
    # the GPU workers (identical per-slice semantics; the CPU pass would be pure recompute).
    if bool(skip_hole_fill):
        print(f'2D hole fill ({view.name}): done on device during accumulation (v13.3.3 S2); CPU pass skipped.')
    else:
        fill_view_volume_holes_2d_inplace(
            mask_mm,
            workers=int(workers),
            desc=f'2D hole fill ({view.name})',
        )

    flush_array(mask_mm)
    if confmap_mm is not None:
        flush_array(confmap_mm)


# --------------------------
# v13.0.0 process-per-GPU multi-GPU inference workers
# --------------------------
# Thread-per-GPU inference does not scale in CPython: Ultralytics' per-batch Python work
# (NMS, mask/Results construction, retina-mask handling) holds the GIL, so multiple GPU
# threads serialize down to roughly single-GPU throughput. v13.0.0 therefore drives each GPU
# from its own worker PROCESS (separate interpreter, no shared GIL, independent CUDA context).
# Workers render + predict + accumulate one prediction volume at a time from a shared task
# queue and write the per-volume native-space result to a file-backed memmap; the main process
# unions those results into the per-view union and runs all postprocessing/interpolation/output.


def open_existing_gray_memmap(path: object, shape: Sequence[int], dtype: object = np.uint8, mode: str = 'r') -> np.memmap:
    return np.memmap(Path(path), dtype=np.dtype(dtype), mode=str(mode), shape=tuple(int(x) for x in shape))


def union_conf_volume_into_volume_inplace(
    dst_mask_mm: np.ndarray,
    dst_conf_mm: Optional[np.ndarray],
    src_mask_mm: np.ndarray,
    src_conf_mm: Optional[np.ndarray],
    *,
    workers: int = 1,
    desc: str = 'Union view-volume contributions',
) -> None:
    """Union one prediction-volume result into the per-view union.

    When confidence maps are present (``--min_conf`` > 0) this performs a per-pixel
    maximum-confidence union (the surviving pixel keeps the higher confidence), matching the
    in-thread accumulation semantics. Otherwise it is a plain binary OR.
    """
    num_slices = int(dst_mask_mm.shape[0]) if int(dst_mask_mm.ndim) > 0 else 0
    if num_slices <= 0:
        return
    use_conf = bool(dst_conf_mm is not None and src_conf_mm is not None)

    def _merge_slice(idx: int) -> None:
        i = int(idx)
        src_mask = np.asarray(src_mask_mm[i], dtype=np.uint8)
        if not use_conf:
            dst_mask_mm[i, :, :] |= src_mask
            return
        dst_mask = np.asarray(dst_mask_mm[i], dtype=np.uint8)
        dst_conf = np.asarray(dst_conf_mm[i], dtype=np.uint8)
        src_conf = np.asarray(src_conf_mm[i], dtype=np.uint8)
        # A source pixel wins where it is foreground and strictly more confident than the
        # current destination (ties keep the existing pixel, matching first-writer-wins).
        take = (src_mask > 0) & (src_conf > dst_conf)
        if np.any(take):
            dst_mask = np.where(take, src_mask, dst_mask)
            dst_conf = np.where(take, src_conf, dst_conf)
        # Foreground from the source that lands where the destination is empty is also unioned.
        add = (src_mask > 0) & (dst_mask == 0)
        if np.any(add):
            dst_mask = np.where(add, src_mask, dst_mask)
            dst_conf = np.where(add, src_conf, dst_conf)
        dst_mask_mm[i, :, :] = dst_mask
        dst_conf_mm[i, :, :] = dst_conf

    parallel_for_indices(
        num_slices,
        _merge_slice,
        max_workers=choose_slice_parallel_workers(int(workers), num_slices),
        desc=desc,
        show_progress=False,
    )
    flush_array(dst_mask_mm)
    if dst_conf_mm is not None:
        flush_array(dst_conf_mm)


# --------------------------
# v13.3.0 (R1/R21) GPU-resident worker rendering
# --------------------------
# Each multi-GPU inference worker owns a _GpuWorkerRenderEngine. Two modes:
#   resident — the uint8 source volume fits in VRAM (mem_get_info headroom check): every
#              full-frame view family renders ON DEVICE and batches feed TensorRT directly
#              through the existing _tta_gpu_tensor preprocess contract (no CPU render pool,
#              no host staging round trip).
#   stream   — the volume does not fit: radial full-frame tasks still render on the GPU by
#              streaming transient source t-blocks through an azimuth-chunked gather and
#              assembling the task's frames into a HOST slab that feeds the unchanged
#              StreamingYoloVolumeSource/CUDA-staging path (the ~1e12-op GIL-held CPU radial
#              extraction disappears in both modes); other views use the existing CPU path.


def gpu_worker_render_enabled() -> bool:
    """v13.3.0 (R1/R21): render full-frame views on the worker's GPU. YOLO_TTA_GPU_RENDER=0 disables."""
    return _env_flag('YOLO_TTA_GPU_RENDER', True)


def gpu_worker_render_resident_enabled() -> bool:
    """v13.3.0 (R21): allow uploading the whole source volume to the device when it fits."""
    return _env_flag('YOLO_TTA_GPU_RENDER_RESIDENT', True)


def gpu_render_reserve_bytes() -> int:
    """VRAM headroom that must remain free AFTER a resident source-volume upload."""
    return int(max(1.0, _env_float('YOLO_TTA_GPU_RENDER_RESERVE_GIB', 12.0)) * GIB)


def gpu_render_tblock_slices() -> int:
    """Transient source t-block size for streaming-mode GPU radial prerendering."""
    return max(16, _env_int('YOLO_TTA_GPU_RENDER_TBLOCK_SLICES', 256))


def gpu_cube_resize_enabled() -> bool:
    """v13.3.9 (E3): retain native t and fold cube-t scaling into GPU renderers.

    Each worker uploads the smaller NATIVE decoded volume and applies the two-tap
    center-aligned t map inside each renderer. v13.3.17 C10 constructs the host cube only
    when a CPU/tile/nonresident fallback requests its sentinel. Only T-only slab resizing
    is eligible. YOLO_TTA_GPU_CUBE_RESIZE=0 restores cube-gated enqueue/residency.
    """
    return _env_flag('YOLO_TTA_GPU_CUBE_RESIZE', True)


def fused_direct_render_enabled() -> bool:
    """Allow resident-ring renderers to write normalized pixels straight to TRT bindings."""
    return _env_flag('YOLO_TTA_FUSED_DIRECT_RENDER', True)


def fused_radial_render_enabled() -> bool:
    """P4 Radial direct-to-binding kernel; zero selects the retained Torch renderer."""
    return fused_direct_render_enabled() and _env_flag('YOLO_TTA_FUSED_RADIAL_RENDER', True)


def fused_tilted_render_enabled() -> bool:
    """P4 Tilted direct-to-binding kernel; zero selects the retained Torch renderer."""
    return fused_direct_render_enabled() and _env_flag('YOLO_TTA_FUSED_TILTED_RENDER', True)


def fused_render_cuda_graphs_enabled() -> bool:
    """Capture the stable P4 render kernel; metadata remains a dynamic device-side input."""
    return (
        fused_direct_render_enabled()
        and resident_trt_cuda_graphs_enabled()
        and _env_flag('YOLO_TTA_FUSED_RENDER_CUDA_GRAPHS', True)
    )


def fused_radial_tap_cache_bytes() -> int:
    """Maximum device bytes used by an all-azimuth separable Lanczos descriptor table."""
    return int(max(0.0, _env_float('YOLO_TTA_FUSED_RADIAL_TAPS_GIB', 2.0)) * GIB)


_FUSED_DIRECT_RENDER_KERNELS: Optional[object] = None
_FUSED_DIRECT_RENDER_KERNELS_FAILED = False
_FUSED_DIRECT_RENDER_KERNELS_ERROR: Optional[str] = None
_FUSED_DIRECT_RENDER_KERNELS_WARNED = False


def _fused_direct_render_kernels() -> Optional[object]:
    """Compile P4's allocation-free resident Radial/Tilted render kernels once.

    v13.3.15 removes the templated device writers/macros used by v13.3.14. Several
    NVRTC/CuPy combinations accepted the source object but failed when the first named
    kernel was materialized, disabling both render families. The replacement exports
    explicit fp32/fp16 kernels, eagerly compiles the module, and preserves the full
    compiler diagnostic so a future CUDA-toolchain mismatch is actionable.
    """
    global _FUSED_DIRECT_RENDER_KERNELS, _FUSED_DIRECT_RENDER_KERNELS_FAILED
    global _FUSED_DIRECT_RENDER_KERNELS_ERROR, _FUSED_DIRECT_RENDER_KERNELS_WARNED
    if _FUSED_DIRECT_RENDER_KERNELS is not None:
        return _FUSED_DIRECT_RENDER_KERNELS
    if _FUSED_DIRECT_RENDER_KERNELS_FAILED:
        return None
    src = r'''
    #include <cuda_fp16.h>

    __device__ __forceinline__ int clamp_i(int v, int lo, int hi) {
      return v < lo ? lo : (v > hi ? hi : v);
    }
    __device__ __forceinline__ float clamp_f(float v, float lo, float hi) {
      return v < lo ? lo : (v > hi ? hi : v);
    }
    // Header-free device math: run 126080 showed NVRTC 13.0 could not locate
    // the host system math.h. CUDA device math functions need no host header path.
    __device__ __forceinline__ float abs_f(float v) {
      return v < 0.0f ? -v : v;
    }
    __device__ __forceinline__ int floor_i(float v) {
      return __float2int_rd(v);
    }
    __device__ __forceinline__ float round_nearest_f(float v) {
      return (float)__float2int_rn(v);
    }
    __device__ __forceinline__ float sinc1(float x) {
      if (abs_f(x) < 1.0e-7f) return 1.0f;
      float pix = 3.14159265358979323846f * x;
      return sinf(pix) / pix;
    }
    __device__ __forceinline__ float norm_u8(float value) {
      return clamp_f(value, 0.0f, 255.0f) * (1.0f / 255.0f);
    }

    extern "C" __global__ void set_render_meta(int* render_meta, int frame_value) {
      if (blockIdx.x == 0 && threadIdx.x == 0) {
        render_meta[0] = frame_value;
        render_meta[1] = 0;
      }
    }

    extern "C" __global__ void precompute_radial_taps(
        const float* angles_deg, int n_angles, int n_u,
        int full_h, int full_w, float center_x, float center_y, float roi_radius,
        int* x_idx, int* y_idx, float* x_w, float* y_w) {
      int p = (int)(blockDim.x * blockIdx.x + threadIdx.x);
      int total = n_angles * n_u;
      if (p >= total) return;
      int aidx = p / n_u;
      int u = p - aidx * n_u;
      float coord = n_u > 1
          ? -roi_radius + (2.0f * roi_radius) * ((float)u / (float)(n_u - 1))
          : -roi_radius;
      float theta = angles_deg[aidx] * 0.01745329251994329577f;
      float sx = center_x + coord * cosf(theta);
      float sy = center_y + coord * sinf(theta);
      int bx = floor_i(sx);
      int by = floor_i(sy);
      float wx[6], wy[6];
      int ix[6], iy[6];
      float sumx = 0.0f, sumy = 0.0f;
      #pragma unroll
      for (int k = 0; k < 6; ++k) {
        int rx = bx + k - 2;
        int ry = by + k - 2;
        float dx = sx - (float)rx;
        float dy = sy - (float)ry;
        float vx = abs_f(dx) >= 3.0f ? 0.0f : sinc1(dx) * sinc1(dx / 3.0f);
        float vy = abs_f(dy) >= 3.0f ? 0.0f : sinc1(dy) * sinc1(dy / 3.0f);
        if (rx < 0 || rx >= full_w) vx = 0.0f;
        if (ry < 0 || ry >= full_h) vy = 0.0f;
        ix[k] = clamp_i(rx, 0, full_w - 1);
        iy[k] = clamp_i(ry, 0, full_h - 1);
        wx[k] = vx; wy[k] = vy;
        sumx += vx; sumy += vy;
      }
      int off = p * 6;
      #pragma unroll
      for (int k = 0; k < 6; ++k) {
        x_idx[off + k] = ix[k];
        y_idx[off + k] = iy[k];
        x_w[off + k] = abs_f(sumx) > 1.0e-6f ? wx[k] / sumx : wx[k];
        y_w[off + k] = abs_f(sumy) > 1.0e-6f ? wy[k] / sumy : wy[k];
      }
    }

    __device__ __forceinline__ float radial_native_value(
        const unsigned char* volume, int native_t, int full_h, int full_w,
        int rows, int n_u, int angle_idx, int row, int u,
        const int* x_idx, const int* y_idx, const float* x_w, const float* y_w) {
      float rf = ((float)row + 0.5f) * ((float)native_t / (float)rows) - 0.5f;
      int raw0 = floor_i(rf);
      int t0 = clamp_i(raw0, 0, native_t - 1);
      int t1 = t0 + 1 < native_t ? t0 + 1 : native_t - 1;
      float ta = clamp_f(rf - (float)t0, 0.0f, 1.0f);
      int tap = (angle_idx * n_u + u) * 6;
      long long plane_stride = (long long)full_h * (long long)full_w;
      float v0 = 0.0f, v1 = 0.0f;
      #pragma unroll
      for (int ky = 0; ky < 6; ++ky) {
        int yy = y_idx[tap + ky];
        float wy = y_w[tap + ky];
        long long row_off = (long long)yy * (long long)full_w;
        #pragma unroll
        for (int kx = 0; kx < 6; ++kx) {
          int xx = x_idx[tap + kx];
          float w = wy * x_w[tap + kx];
          long long spatial = row_off + (long long)xx;
          v0 += w * (float)volume[(long long)t0 * plane_stride + spatial];
          v1 += w * (float)volume[(long long)t1 * plane_stride + spatial];
        }
      }
      return v0 + ta * (v1 - v0);
    }

    __device__ __forceinline__ float radial_bilinear_value(
        const unsigned char* volume, int native_t, int full_h, int full_w,
        int rows, int n_u, int angle_idx, float sy, float sx,
        const int* x_idx, const int* y_idx, const float* x_w, const float* y_w) {
      int x0 = floor_i(sx), y0 = floor_i(sy);
      int x1 = x0 + 1, y1 = y0 + 1;
      float fx = sx - (float)x0, fy = sy - (float)y0;
      float v00 = (x0 >= 0 && x0 < n_u && y0 >= 0 && y0 < rows)
          ? radial_native_value(volume, native_t, full_h, full_w, rows, n_u,
                                angle_idx, y0, x0, x_idx, y_idx, x_w, y_w) : 0.0f;
      if (fx == 0.0f && fy == 0.0f) return v00;
      float v01 = (x1 >= 0 && x1 < n_u && y0 >= 0 && y0 < rows)
          ? radial_native_value(volume, native_t, full_h, full_w, rows, n_u,
                                angle_idx, y0, x1, x_idx, y_idx, x_w, y_w) : 0.0f;
      float v10 = (x0 >= 0 && x0 < n_u && y1 >= 0 && y1 < rows)
          ? radial_native_value(volume, native_t, full_h, full_w, rows, n_u,
                                angle_idx, y1, x0, x_idx, y_idx, x_w, y_w) : 0.0f;
      float v11 = (x1 >= 0 && x1 < n_u && y1 >= 0 && y1 < rows)
          ? radial_native_value(volume, native_t, full_h, full_w, rows, n_u,
                                angle_idx, y1, x1, x_idx, y_idx, x_w, y_w) : 0.0f;
      float a = v00 + fx * (v01 - v00);
      float b = v10 + fx * (v11 - v10);
      return a + fy * (b - a);
    }

    __device__ __forceinline__ float radial_direct_value(
        const unsigned char* volume, int native_t, int full_h, int full_w,
        int rows, int n_u, const int* render_meta, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12,
        const int* x_idx, const int* y_idx, const float* x_w, const float* y_w,
        int q) {
      int angle_idx = render_meta[0];
      int oy = q / ow, ox = q - oy * ow;
      float sx = __fadd_rn(__fadd_rn(__fmul_rn(m00, (float)ox), __fmul_rn(m01, (float)oy)), m02);
      float sy = __fadd_rn(__fadd_rn(__fmul_rn(m10, (float)ox), __fmul_rn(m11, (float)oy)), m12);
      return radial_bilinear_value(volume, native_t, full_h, full_w, rows, n_u,
          angle_idx, sy, sx, x_idx, y_idx, x_w, y_w);
    }

    extern "C" __global__ void radial_direct_f32(
        const unsigned char* volume, int native_t, int full_h, int full_w,
        int rows, int n_u, const int* render_meta, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12,
        const int* x_idx, const int* y_idx, const float* x_w, const float* y_w,
        float* out) {
      int q = (int)(blockDim.x * blockIdx.x + threadIdx.x);
      if (q >= oh * ow) return;
      out[q] = norm_u8(radial_direct_value(volume, native_t, full_h, full_w, rows, n_u,
          render_meta, oh, ow, m00, m01, m02, m10, m11, m12,
          x_idx, y_idx, x_w, y_w, q));
    }

    extern "C" __global__ void radial_direct_f16(
        const unsigned char* volume, int native_t, int full_h, int full_w,
        int rows, int n_u, const int* render_meta, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12,
        const int* x_idx, const int* y_idx, const float* x_w, const float* y_w,
        __half* out) {
      int q = (int)(blockDim.x * blockIdx.x + threadIdx.x);
      if (q >= oh * ow) return;
      float value = norm_u8(radial_direct_value(volume, native_t, full_h, full_w, rows, n_u,
          render_meta, oh, ow, m00, m01, m02, m10, m11, m12,
          x_idx, y_idx, x_w, y_w, q));
      out[q] = __float2half_rn(value);
    }

    __device__ __forceinline__ void logical_t_taps(
        int logical_idx, int native_t, int logical_t, int* t0, int* t1, float* alpha) {
      float pos = ((float)logical_idx + 0.5f) * ((float)native_t / (float)logical_t) - 0.5f;
      int raw0 = floor_i(pos);
      *t0 = clamp_i(raw0, 0, native_t - 1);
      *t1 = *t0 + 1 < native_t ? *t0 + 1 : native_t - 1;
      *alpha = clamp_f(pos - (float)(*t0), 0.0f, 1.0f);
    }

    __device__ __forceinline__ float rounded_t_lerp(
        const unsigned char* volume, long long plane_stride, long long spatial,
        int t0, int t1, float alpha) {
      float a = (float)volume[(long long)t0 * plane_stride + spatial];
      float b = (float)volume[(long long)t1 * plane_stride + spatial];
      return clamp_f(round_nearest_f(a + alpha * (b - a)), 0.0f, 255.0f);
    }

    __device__ __forceinline__ float tilted_direct_value(
        const unsigned char* volume, int native_t, int full_h, int full_w, int logical_t,
        int src_h, int src_w, int stack_len, int base_id, int direction_id,
        const int* render_meta, float tan_tilt, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12, int q) {
      int frame_center = render_meta[0];
      int oy = q / ow, ox = q - oy * ow;
      float sx = __fadd_rn(__fadd_rn(__fmul_rn(m00, (float)ox), __fmul_rn(m01, (float)oy)), m02);
      float sy = __fadd_rn(__fadd_rn(__fmul_rn(m10, (float)ox), __fmul_rn(m11, (float)oy)), m12);
      int x = __float2int_rn(sx);
      int y = __float2int_rn(sy);
      if (x < 0 || x >= src_w || y < 0 || y >= src_h) return 0.0f;
      float axis = direction_id == 0
          ? sy - 0.5f * (float)(src_h - 1)
          : sx - 0.5f * (float)(src_w - 1);
      float stack = __fadd_rn((float)frame_center, __fmul_rn(tan_tilt, axis));
      if (stack < 0.0f || stack > (float)(stack_len - 1)) return 0.0f;
      int s0 = clamp_i(floor_i(stack), 0, stack_len - 1);
      int s1 = s0 + 1 < stack_len ? s0 + 1 : stack_len - 1;
      float sa = stack - (float)s0;
      long long ps = (long long)full_h * (long long)full_w;
      float v0, v1;
      if (base_id == 0) {
        long long spatial = (long long)y * (long long)full_w + (long long)x;
        if (native_t == logical_t) {
          v0 = (float)volume[(long long)s0 * ps + spatial];
          v1 = (float)volume[(long long)s1 * ps + spatial];
        } else {
          int a0, a1, b0, b1; float aa, ba;
          logical_t_taps(s0, native_t, logical_t, &a0, &a1, &aa);
          logical_t_taps(s1, native_t, logical_t, &b0, &b1, &ba);
          v0 = rounded_t_lerp(volume, ps, spatial, a0, a1, aa);
          v1 = rounded_t_lerp(volume, ps, spatial, b0, b1, ba);
        }
      } else {
        int t0, t1; float ta;
        logical_t_taps(y, native_t, logical_t, &t0, &t1, &ta);
        long long spatial0, spatial1;
        if (base_id == 1) {
          spatial0 = (long long)s0 * (long long)full_w + (long long)x;
          spatial1 = (long long)s1 * (long long)full_w + (long long)x;
        } else {
          spatial0 = (long long)x * (long long)full_w + (long long)s0;
          spatial1 = (long long)x * (long long)full_w + (long long)s1;
        }
        if (native_t == logical_t) {
          v0 = (float)volume[(long long)y * ps + spatial0];
          v1 = (float)volume[(long long)y * ps + spatial1];
        } else {
          v0 = rounded_t_lerp(volume, ps, spatial0, t0, t1, ta);
          v1 = rounded_t_lerp(volume, ps, spatial1, t0, t1, ta);
        }
      }
      return v0 + sa * (v1 - v0);
    }

    extern "C" __global__ void tilted_direct_f32(
        const unsigned char* volume, int native_t, int full_h, int full_w, int logical_t,
        int src_h, int src_w, int stack_len, int base_id, int direction_id,
        const int* render_meta, float tan_tilt, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12, float* out) {
      int q = (int)(blockDim.x * blockIdx.x + threadIdx.x);
      if (q >= oh * ow) return;
      out[q] = norm_u8(tilted_direct_value(volume, native_t, full_h, full_w, logical_t,
          src_h, src_w, stack_len, base_id, direction_id, render_meta, tan_tilt,
          oh, ow, m00, m01, m02, m10, m11, m12, q));
    }

    extern "C" __global__ void tilted_direct_f16(
        const unsigned char* volume, int native_t, int full_h, int full_w, int logical_t,
        int src_h, int src_w, int stack_len, int base_id, int direction_id,
        const int* render_meta, float tan_tilt, int oh, int ow,
        float m00, float m01, float m02, float m10, float m11, float m12, __half* out) {
      int q = (int)(blockDim.x * blockIdx.x + threadIdx.x);
      if (q >= oh * ow) return;
      float value = norm_u8(tilted_direct_value(volume, native_t, full_h, full_w, logical_t,
          src_h, src_w, stack_len, base_id, direction_id, render_meta, tan_tilt,
          oh, ow, m00, m01, m02, m10, m11, m12, q));
      out[q] = __float2half_rn(value);
    }
    '''
    try:
        import cupy as cp  # type: ignore
        names = (
            'set_render_meta', 'precompute_radial_taps', 'radial_direct_f32', 'radial_direct_f16',
            'tilted_direct_f32', 'tilted_direct_f16',
        )
        module = cp.RawModule(code=src, options=('--std=c++14',))
        compile_fn = getattr(module, 'compile', None)
        if callable(compile_fn):
            compile_fn()
        functions = {name: module.get_function(name) for name in names}
        _FUSED_DIRECT_RENDER_KERNELS = argparse.Namespace(cp=cp, module=module, **functions)
        _FUSED_DIRECT_RENDER_KERNELS_ERROR = None
        return _FUSED_DIRECT_RENDER_KERNELS
    except Exception as exc:
        _FUSED_DIRECT_RENDER_KERNELS_FAILED = True
        try:
            import hashlib
            source_id = hashlib.sha256(src.encode('utf-8')).hexdigest()[:16]
        except Exception:
            source_id = 'unknown'
        details = [f'{type(exc).__name__}: {exc}', f'cuda_source_sha256={source_id}']
        try:
            import cupy as cp  # type: ignore
            details.append(f'cupy={getattr(cp, "__version__", "unknown")}')
            details.append(f'cuda_runtime={cp.cuda.runtime.runtimeGetVersion()}')
            try:
                details.append(f'nvrtc={cp.cuda.nvrtc.getVersion()}')
            except Exception:
                pass
            try:
                details.append(f'compute_capability={cp.cuda.Device().compute_capability}')
            except Exception:
                pass
        except Exception:
            pass
        _FUSED_DIRECT_RENDER_KERNELS_ERROR = '; '.join(details)
        dump_path = os.environ.get('YOLO_TTA_FUSED_RENDER_DUMP_CUDA', '').strip()
        if dump_path:
            try:
                Path(dump_path).expanduser().write_text(src)
            except Exception:
                pass
        if not _FUSED_DIRECT_RENDER_KERNELS_WARNED:
            _FUSED_DIRECT_RENDER_KERNELS_WARNED = True
            print(
                'Warning: fused Radial/Tilted NVRTC module failed to compile; '
                f'{_FUSED_DIRECT_RENDER_KERNELS_ERROR}. '
                'The reference Torch renderers remain active.'
            )
        return None
def _wait_for_cube_ready_sentinel(
    sentinel_path: str,
    *,
    request_path: Optional[str] = None,
    failed_path: Optional[str] = None,
    poll_seconds: float = 0.5,
) -> None:
    """v13.3.8 (E1): block until main signals the shared cube volume file is complete.

    Reached only on fallbacks (failed residency, tile tasks, CPU renders) while the host
    cube is still being produced. Scheduler teardown terminates workers parked here if the
    producer dies (the sentinel is only ever written after wait_for_volume_ready + flush).
    """
    sentinel = Path(str(sentinel_path))
    request = Path(str(request_path)) if request_path else None
    failed = Path(str(failed_path)) if failed_path else None
    if request is not None:
        # v13.3.17 C10: this is the first proven need for the host cube. A tiny atomic
        # marker wakes the main-process materializer; all workers share the same result.
        request.parent.mkdir(parents=True, exist_ok=True)
        request.touch(exist_ok=True)
    announced = False
    timeout_seconds = max(
        60.0,
        _env_float('YOLO_TTA_LAZY_CUBE_WAIT_TIMEOUT_SEC', 3600.0),
    )
    deadline = time.monotonic() + float(timeout_seconds)
    while True:
        # Failure wins if both records somehow exist; C10 publishes them transactionally,
        # but this also makes stale/corrupt shared state fail closed.
        if failed is not None and failed.exists():
            try:
                detail = failed.read_text().strip()
            except Exception:
                detail = 'unknown producer failure'
            raise RuntimeError(f'shared cube fallback construction failed: {detail}')
        if sentinel.exists():
            return
        if time.monotonic() >= float(deadline):
            raise TimeoutError(
                'timed out waiting for the deferred shared cube after '
                f'{float(timeout_seconds):.0f}s; ready={sentinel}, failed={failed}'
            )
        if not announced:
            announced = True
            print(
                'GPU worker: requested the deferred shared cube and is waiting for '
                'file-backed fallback rendering...'
            )
        time.sleep(max(0.05, float(poll_seconds)))


class _GpuWorkerRenderEngine:
    """Per-worker-process GPU renderer for full-frame prediction sources (v13.3.0 R1/R21)."""

    def __init__(self, device_str: str = 'cuda:0') -> None:
        import torch  # type: ignore
        import torch.nn.functional as F  # type: ignore
        self.torch = torch
        self.F = F
        self.device = torch.device(str(device_str))
        if self.device.type != 'cuda' or not torch.cuda.is_available():
            raise RuntimeError('GPU render engine requires a CUDA device')
        # A worker owns exactly one inference/render GPU. Keep CuPy/NVRTC's implicit
        # current device aligned with the explicit Torch device used below.
        torch.cuda.set_device(self.device)
        # All renders run on a dedicated LOW-priority stream; the resident batch-1 ring
        # gives TensorRT distinct high-priority streams so frame n inference can preempt/
        # overlap frame n+1 rendering. Consumers order through per-slot events.
        self._stream = torch.cuda.Stream(
            device=self.device, priority=_cuda_stream_priority(torch, high=False),
        )
        self._volume_key: Optional[Tuple[str, Tuple[int, int, int], int]] = None
        self._volume_mm: Optional[np.ndarray] = None
        self._volume_gpu: Optional[object] = None
        self._volume_flat: Optional[object] = None
        # v13.3.9 (E3): _volume_gpu keeps NATIVE t while _logical_t is the
        # approximately-cubic working t seen by ViewInfo/render coordinates.
        self._logical_t = 0
        self._native_t_map_cache: Dict[Tuple[int, int], Tuple[object, object, object]] = {}
        self._mode = 'unresolved'
        self._tilted_plans: 'OrderedDict[Tuple[str, int, int, Tuple[float, ...]], Dict[str, object]]' = OrderedDict()
        self._fold_cache: Dict[Tuple[int, int, int], Tuple[object, object, object]] = {}
        # P4 keeps one all-azimuth separable tap table per resident Radial geometry.
        # It is generated by one CUDA launch and remains device-resident across task windows.
        self._fused_radial_taps: 'OrderedDict[object, object]' = OrderedDict()
        self._fused_volume_ref: Optional[object] = None
        self._fused_disabled_families: set = set()
        self._fused_warned_families: set = set()
        self._fused_announced_families: set = set()
        self._fused_graph_announced_families: set = set()
        self._fused_graph_warned_families: set = set()
        self._fused_graph_rejected_keys: set = set()
        self._fused_validated_keys: set = set()
        self._warned_fallback = False
        self._resident_runtime_disabled = False

    # ---- volume residency ----

    def ensure_volume(
        self,
        path: str,
        shape: Sequence[int],
        dtype: str = 'uint8',
        *,
        resize_to_t: Optional[int] = None,
    ) -> str:
        """Resolve source-volume residency while retaining a native-t device buffer.

        v13.3.9 (E3): with ``resize_to_t`` set, ``path`` is the NATIVE decoded
        volume and only that smaller volume is uploaded.  Renderers compose the
        center-aligned native->working t map at use time instead of materializing a
        cube-t uint8 copy. Residency failure still returns ``stream`` with native
        state reset, because streaming/CPU fallbacks require the completed cube file.
        """
        torch = self.torch
        shape_t = tuple(int(x) for x in shape)
        if len(shape_t) != 3:
            raise ValueError(f'GPU render source must be 3D (t,Y,X), got {shape_t}')
        in_t, in_h, in_w = (int(shape_t[0]), int(shape_t[1]), int(shape_t[2]))
        out_t = int(resize_to_t) if resize_to_t else int(in_t)
        if min(in_t, in_h, in_w, out_t) <= 0:
            raise ValueError(f'GPU render source has invalid native/logical shape {shape_t} -> t={out_t}')
        resize_active = int(out_t) != int(in_t)
        key = (str(path), shape_t, int(out_t))
        if self._volume_key == key and self._mode != 'unresolved':
            return self._mode
        self._volume_key = key
        self._volume_mm = np.memmap(Path(str(path)), dtype=np.dtype(str(dtype)), mode='c', shape=shape_t)
        self._volume_gpu = None
        self._volume_flat = None
        self._logical_t = int(out_t)
        self._native_t_map_cache.clear()
        self._fold_cache.clear()
        self._tilted_plans.clear()
        self._fused_radial_taps.clear()
        self._fused_volume_ref = None
        self._fused_disabled_families.clear()
        self._fused_graph_rejected_keys.clear()
        self._fused_validated_keys.clear()
        self._mode = 'stream'
        # E3's admission test is based on the NATIVE buffer, not the inflated cube t.
        nbytes = int(in_t) * int(in_h) * int(in_w)
        if gpu_worker_render_resident_enabled() and not self._resident_runtime_disabled:
            try:
                free_bytes, total_bytes = torch.cuda.mem_get_info(self.device)
                need = nbytes + gpu_render_reserve_bytes()
                if int(free_bytes) >= int(need):
                    vol = torch.empty((int(in_t), int(in_h), int(in_w)), dtype=torch.uint8, device=self.device)
                    chunk = 256
                    for t0 in range(0, int(in_t), chunk):
                        t1 = min(int(in_t), t0 + chunk)
                        vol[t0:t1].copy_(torch.from_numpy(np.ascontiguousarray(self._volume_mm[t0:t1])))
                    self._volume_gpu = vol
                    self._volume_flat = vol.view(-1)
                    # Build/cache the integer logical-t taps now; transverse and
                    # Cartesian planes use them directly and tilted plans reuse the
                    # same center-aligned convention.
                    self._native_t_indices(int(out_t))
                    self._mode = 'resident'
                else:
                    print(
                        f'GPU render: source volume NOT resident ({nbytes / GIB:.1f} GiB needed + '
                        f'{gpu_render_reserve_bytes() / GIB:.1f} GiB reserve > {free_bytes / GIB:.1f} GiB free); '
                        'radial tasks use streamed GPU prerendering, other views use CPU rendering. '
                        'A TensorRT engine rebuilt at max batch 1 frees enough VRAM for residency.'
                    )
            except Exception as exc:
                self._volume_gpu = None
                self._volume_flat = None
                self._mode = 'stream'
                print(f'GPU render: resident upload failed ({exc}); falling back to streaming mode.')
        if resize_active and self._mode != 'resident':
            # v13.3.8 (E1): never leave a native-geometry memmap where streaming-mode
            # consumers (radial slab prerender, shape probes) expect the cube.
            self._volume_key = None
            self._volume_mm = None
            self._logical_t = 0
            self._native_t_map_cache.clear()
            self._mode = 'unresolved'
            return 'stream'
        if self._mode == 'resident':
            resize_note = (
                f' (v13.3.9 E3: native t retained; renderers map {in_t}->{out_t} on device)'
                if resize_active else ''
            )
            print(
                f'GPU render: source volume resident on {self.device} '
                f'({nbytes / GIB:.1f} GiB){resize_note}; full-frame views render on device.'
            )
        return self._mode

    def disable_resident_after_runtime_failure(self) -> None:
        """Release E3 residency and keep this worker on completed-cube fallbacks.

        Rendering is lazy, so a gather-plan error or late OOM can occur after prediction has
        started. Releasing the large resident tensor gives a clean CPU-render retry enough VRAM
        for inference and avoids repeating the same failing resident path on later tasks.
        """
        self._resident_runtime_disabled = True
        try:
            self._stream.synchronize()
        except Exception:
            pass
        self._volume_gpu = None
        self._volume_flat = None
        self._volume_mm = None
        self._volume_key = None
        self._logical_t = 0
        self._native_t_map_cache.clear()
        self._fold_cache.clear()
        self._tilted_plans.clear()
        self._fused_radial_taps.clear()
        self._fused_volume_ref = None
        self._fused_disabled_families.clear()
        self._fused_graph_rejected_keys.clear()
        self._fused_validated_keys.clear()
        self._mode = 'unresolved'
        try:
            self.torch.cuda.empty_cache()
        except Exception:
            pass

    def _native_t_indices(self, logical_t: Optional[int] = None) -> Tuple[object, object, object]:
        """Integer logical-t planes -> native two-tap indices/weights on device."""
        torch = self.torch
        native_t = int(self._volume_gpu.shape[0])
        logical = int(self._logical_t if logical_t is None else logical_t)
        key = (native_t, logical)
        cached = self._native_t_map_cache.get(key)
        if cached is not None:
            return cached
        rf = (np.arange(logical, dtype=np.float64) + 0.5) * (float(native_t) / float(logical)) - 0.5
        r0 = np.clip(np.floor(rf).astype(np.int64), 0, native_t - 1)
        r1 = np.minimum(r0 + 1, native_t - 1)
        alpha = np.clip(rf - r0, 0.0, 1.0).astype(np.float32)
        mapped = (
            torch.from_numpy(r0).to(self.device),
            torch.from_numpy(r1).to(self.device),
            torch.from_numpy(alpha).to(self.device),
        )
        self._native_t_map_cache[key] = mapped
        return mapped

    def _resample_native_t_axis(self, values: object) -> object:
        """Map a native-t-leading tensor to logical t with E1-compatible u8 rounding."""
        torch = self.torch
        native_t = int(values.shape[0])
        logical_t = int(self._logical_t)
        if native_t == logical_t:
            return values.to(torch.float32)
        r0, r1, alpha = self._native_t_indices(logical_t)
        alpha_shape = [logical_t] + [1] * max(0, int(values.ndim) - 1)
        a = alpha.view(*alpha_shape)
        f0 = values.index_select(0, r0).to(torch.float32)
        f1 = values.index_select(0, r1).to(torch.float32)
        # The old E1 resident cube stored uint8 after cv2-compatible lerp.
        return torch.lerp(f0, f1, a).round_().clamp_(0.0, 255.0)

    # ---- P4 fused resident-ring renderers ----

    def _fused_render_fallback(self, family: str, exc: object) -> None:
        """Disable one optional fused family after a synchronous capability failure."""
        family_s = str(family)
        self._fused_disabled_families.add(family_s)
        if family_s not in self._fused_warned_families:
            self._fused_warned_families.add(family_s)
            gate = (
                'YOLO_TTA_FUSED_RADIAL_RENDER=0'
                if family_s == 'radial' else 'YOLO_TTA_FUSED_TILTED_RENDER=0'
            )
            print(
                f'P4 fused {family_s} renderer unavailable ({exc}); using the reference '
                f'Torch renderer for this worker. {gate} disables the capability probe.'
            )

    def _fused_cupy_volume(self, kernels: object) -> object:
        if self._fused_volume_ref is None:
            self._fused_volume_ref = kernels.cp.asarray(self._volume_gpu)
        return self._fused_volume_ref

    @staticmethod
    def _fused_slot_output(slot: _ResidentGpuPipelineSlot, kernels: object) -> object:
        ref = slot._render_cupy_refs.get('input_plane')
        ptr = int(slot.input.data_ptr())
        if ref is None or int(slot._render_cupy_refs.get('input_ptr', -1)) != ptr:
            ref = kernels.cp.asarray(slot.input[0, 0])
            slot._render_cupy_refs['input_plane'] = ref
            slot._render_cupy_refs['input_ptr'] = ptr
        return ref

    def _fused_slot_metadata(
        self,
        slot: _ResidentGpuPipelineSlot,
        kernels: object,
        frame_value: Optional[int],
    ) -> object:
        """Update dynamic frame metadata without changing its graph-friendly device address."""
        ref = slot._render_cupy_refs.get('render_meta')
        ptr = int(slot.render_meta.data_ptr())
        if ref is None or int(slot._render_cupy_refs.get('render_meta_ptr', -1)) != ptr:
            ref = kernels.cp.asarray(slot.render_meta)
            slot._render_cupy_refs['render_meta'] = ref
            slot._render_cupy_refs['render_meta_ptr'] = ptr
        if frame_value is not None:
            kernels.set_render_meta(
                (1,), (1,), (ref, np.int32(frame_value)),
                stream=_cupy_external_stream(kernels.cp, self._stream),
            )
        return ref

    def _ensure_fused_radial_taps(self, view: ViewInfo, kernels: object) -> object:
        """Generate/cache separable 6+6 tap descriptors for every configured azimuth.

        Storing separable x/y taps costs one third of a flattened 36-tap table while the
        direct renderer still performs the identical outer-product accumulation.  The table
        is built in one launch on the render stream, not reconstructed for every frame.
        """
        if int(RADIAL_LANCZOS_A) != 3 or int(_lanczos_tap_count(RADIAL_LANCZOS_A)) != 6:
            raise RuntimeError('fused Radial renderer currently requires Lanczos-3 (six taps per axis)')
        angles_np = np.ascontiguousarray(np.asarray(view.azimuths_deg, dtype=np.float32))
        n_angles = int(angles_np.size)
        n_u = int(view.src_w) if int(view.src_w) > 0 else int(view.diameter)
        if n_angles <= 0 or n_u <= 0:
            raise RuntimeError('fused Radial descriptor geometry is empty')
        key = (
            int(view.full_h), int(view.full_w), int(n_u),
            round(float(view.center_x), 5), round(float(view.center_y), 5),
            round(float(view.roi_radius), 5), angles_np.tobytes(),
        )
        cached = self._fused_radial_taps.get(key)
        if cached is not None:
            self._fused_radial_taps.move_to_end(key)
            return cached

        # angle + four [angle,u,6] int32/float32 planes.
        descriptor_bytes = int(n_angles * 4 + n_angles * n_u * 6 * 16)
        cache_budget = int(fused_radial_tap_cache_bytes())
        if cache_budget <= 0 or descriptor_bytes > cache_budget:
            raise RuntimeError(
                f'all-azimuth tap table needs {descriptor_bytes / GIB:.2f} GiB, above '
                f'YOLO_TTA_FUSED_RADIAL_TAPS_GIB={cache_budget / GIB:.2f}'
            )
        free_bytes, _total_bytes = self.torch.cuda.mem_get_info(self.device)
        if descriptor_bytes + 512 * 1024 * 1024 > int(free_bytes):
            raise RuntimeError(
                f'all-azimuth tap table needs {descriptor_bytes / GIB:.2f} GiB plus '
                f'0.50 GiB launch headroom, only {int(free_bytes) / GIB:.2f} GiB free'
            )

        # A worker has one Radial geometry. If a caller supplies a replacement geometry,
        # release the old table rather than silently multiplying the persistent cache.
        self._fused_radial_taps.clear()
        torch = self.torch
        angles = torch.from_numpy(angles_np).to(self.device)
        shape = (n_angles, n_u, 6)
        x_idx = torch.empty(shape, dtype=torch.int32, device=self.device)
        y_idx = torch.empty(shape, dtype=torch.int32, device=self.device)
        x_w = torch.empty(shape, dtype=torch.float32, device=self.device)
        y_w = torch.empty(shape, dtype=torch.float32, device=self.device)
        cp = kernels.cp
        refs = argparse.Namespace(
            angles=angles, x_idx=x_idx, y_idx=y_idx, x_w=x_w, y_w=y_w,
            cp_angles=cp.asarray(angles), cp_x_idx=cp.asarray(x_idx),
            cp_y_idx=cp.asarray(y_idx), cp_x_w=cp.asarray(x_w), cp_y_w=cp.asarray(y_w),
            n_angles=n_angles, n_u=n_u, nbytes=descriptor_bytes,
        )
        external = _cupy_external_stream(cp, self._stream)
        total = int(n_angles) * int(n_u)
        kernels.precompute_radial_taps(
            ((total + 255) // 256,), (256,),
            (
                refs.cp_angles, np.int32(n_angles), np.int32(n_u),
                np.int32(view.full_h), np.int32(view.full_w),
                np.float32(view.center_x), np.float32(view.center_y), np.float32(view.roi_radius),
                refs.cp_x_idx, refs.cp_y_idx, refs.cp_x_w, refs.cp_y_w,
            ),
            stream=external,
        )
        self._fused_radial_taps[key] = refs
        print(
            f'P4 Radial tap cache allocated on {self.device}: {n_angles} azimuths x {n_u} samples '
            f'({descriptor_bytes / GIB:.2f} GiB, separable Lanczos-3 descriptors).'
        )
        return refs

    def _try_fused_radial_into_slot(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        aff: AffineSpec,
        frame_index: int,
        out_size: int,
        *,
        stage_metadata: bool = True,
        disable_on_failure: bool = True,
    ) -> bool:
        if not fused_radial_render_enabled() or 'radial' in self._fused_disabled_families:
            return False
        try:
            if str(view.family) != 'radial':
                return False
            if self._volume_gpu is None or not bool(self._volume_gpu.is_contiguous()):
                raise RuntimeError('resident uint8 source volume is unavailable or non-contiguous')
            if self._volume_gpu.dtype != self.torch.uint8:
                raise RuntimeError(f'expected uint8 source volume, got {self._volume_gpu.dtype}')
            if int(view.full_h) != int(self._volume_gpu.shape[1]) or int(view.full_w) != int(self._volume_gpu.shape[2]):
                raise RuntimeError('Radial view/source-volume XY geometry mismatch')
            if int(frame_index) < 0 or int(frame_index) >= len(view.azimuths_deg):
                raise RuntimeError(f'Radial frame index {frame_index} is outside its azimuth table')
            kernels = _fused_direct_render_kernels()
            if kernels is None:
                raise RuntimeError('CuPy/NVRTC direct renderer kernels are unavailable: ' + str(_FUSED_DIRECT_RENDER_KERNELS_ERROR or 'no diagnostic'))
            taps = self._ensure_fused_radial_taps(view, kernels)
            matrix = np.asarray(aff.M_out_to_src, dtype=np.float32).reshape(2, 3)
            if not bool(np.all(np.isfinite(matrix))):
                raise RuntimeError('Radial output-to-source affine is non-finite')
            cp = kernels.cp
            external = _cupy_external_stream(cp, self._stream)
            kernel = (
                kernels.radial_direct_f16
                if slot.input.dtype == self.torch.float16 else kernels.radial_direct_f32
            )
            if slot.input.dtype not in (self.torch.float16, self.torch.float32):
                raise RuntimeError(f'unsupported binding dtype {slot.input.dtype}')
            pixels = int(out_size) * int(out_size)
            kernel(
                ((pixels + 255) // 256,), (256,),
                (
                    self._fused_cupy_volume(kernels),
                    np.int32(self._volume_gpu.shape[0]), np.int32(self._volume_gpu.shape[1]),
                    np.int32(self._volume_gpu.shape[2]), np.int32(view.src_h), np.int32(taps.n_u),
                    self._fused_slot_metadata(
                        slot, kernels, int(frame_index) if bool(stage_metadata) else None,
                    ),
                    np.int32(out_size), np.int32(out_size),
                    *(np.float32(v) for v in matrix.reshape(-1)),
                    taps.cp_x_idx, taps.cp_y_idx, taps.cp_x_w, taps.cp_y_w,
                    self._fused_slot_output(slot, kernels),
                ),
                stream=external,
            )
            if 'radial' not in self._fused_announced_families:
                self._fused_announced_families.add('radial')
                print('P4 fused Radial renderer active: uint8 volume -> Lanczos/t-lerp -> TensorRT binding.')
            return True
        except Exception as exc:
            if not bool(disable_on_failure):
                raise
            self._fused_radial_taps.clear()
            self._fused_render_fallback('radial', exc)
            return False

    def _try_fused_tilted_into_slot(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        aff: AffineSpec,
        frame_index: int,
        out_size: int,
        *,
        stage_metadata: bool = True,
        disable_on_failure: bool = True,
    ) -> bool:
        if not fused_tilted_render_enabled() or 'tilted' in self._fused_disabled_families:
            return False
        try:
            if not is_tilted_view(view):
                return False
            if self._volume_gpu is None or not bool(self._volume_gpu.is_contiguous()):
                raise RuntimeError('resident uint8 source volume is unavailable or non-contiguous')
            if self._volume_gpu.dtype != self.torch.uint8:
                raise RuntimeError(f'expected uint8 source volume, got {self._volume_gpu.dtype}')
            native_t, full_h, full_w = (int(v) for v in self._volume_gpu.shape)
            if int(view.full_h) != full_h or int(view.full_w) != full_w:
                raise RuntimeError('Tilted view/source-volume XY geometry mismatch')
            base = str(tilted_base_view_name(view))
            base_ids = {'transverse': 0, 'sagittal': 1, 'coronal': 2}
            if base not in base_ids:
                raise RuntimeError(f'unsupported Tilted base {base!r}')
            direction = str(view.tilt_direction)
            if direction not in ('vertical', 'horizontal'):
                raise RuntimeError(f'unsupported Tilted direction {direction!r}')
            expected = cartesian_view_axis_spec(base, int(self._logical_t), full_h, full_w)
            if int(view.src_h) != int(expected['src_h']) or int(view.src_w) != int(expected['src_w']):
                raise RuntimeError('Tilted source raster does not match its base-view geometry')
            stack_len = int(tilted_stack_axis_length(view))
            center = int(tilted_frame_center(view, int(frame_index)))
            if stack_len <= 0 or center < 0 or center >= stack_len:
                raise RuntimeError('Tilted frame center is outside the stack geometry')
            kernels = _fused_direct_render_kernels()
            if kernels is None:
                raise RuntimeError('CuPy/NVRTC direct renderer kernels are unavailable: ' + str(_FUSED_DIRECT_RENDER_KERNELS_ERROR or 'no diagnostic'))
            matrix = np.asarray(aff.M_out_to_src, dtype=np.float32).reshape(2, 3)
            if not bool(np.all(np.isfinite(matrix))):
                raise RuntimeError('Tilted output-to-source affine is non-finite')
            cp = kernels.cp
            external = _cupy_external_stream(cp, self._stream)
            kernel = (
                kernels.tilted_direct_f16
                if slot.input.dtype == self.torch.float16 else kernels.tilted_direct_f32
            )
            if slot.input.dtype not in (self.torch.float16, self.torch.float32):
                raise RuntimeError(f'unsupported binding dtype {slot.input.dtype}')
            pixels = int(out_size) * int(out_size)
            kernel(
                ((pixels + 255) // 256,), (256,),
                (
                    self._fused_cupy_volume(kernels),
                    np.int32(native_t), np.int32(full_h), np.int32(full_w), np.int32(self._logical_t),
                    np.int32(view.src_h), np.int32(view.src_w), np.int32(stack_len),
                    np.int32(base_ids[base]), np.int32(0 if direction == 'vertical' else 1),
                    self._fused_slot_metadata(
                        slot, kernels, int(center) if bool(stage_metadata) else None,
                    ),
                    np.float32(math.tan(math.radians(float(view.tilt_angle_deg)))),
                    np.int32(out_size), np.int32(out_size),
                    *(np.float32(v) for v in matrix.reshape(-1)),
                    self._fused_slot_output(slot, kernels),
                ),
                stream=external,
            )
            if 'tilted' not in self._fused_announced_families:
                self._fused_announced_families.add('tilted')
                print('P4 fused Tilted renderer active: affine/shear/gathers/lerps -> TensorRT binding.')
            return True
        except Exception as exc:
            if not bool(disable_on_failure):
                raise
            self._fused_render_fallback('tilted', exc)
            return False

    def _try_fused_render_into_ring_slot(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        aff: AffineSpec,
        frame_index: int,
        out_size: int,
        *,
        stage_metadata: bool = True,
        allow_graph_replay: bool = True,
        disable_on_failure: bool = True,
    ) -> bool:
        """Attempt P4 only for resident-ring Radial/Tilted frames.

        Generic batches deliberately retain the reference Torch renderer: only the ring owns
        a persistent destination binding whose address and dtype have already been validated.
        """
        family = 'radial' if str(view.family) == 'radial' else ('tilted' if is_tilted_view(view) else '')
        if not family:
            return False
        if (
            bool(allow_graph_replay)
            and slot.render_graph is not None
            and slot.render_expected_key is not None
            and slot.render_graph_key == slot.render_expected_key
            and family not in self._fused_disabled_families
        ):
            kernels = _fused_direct_render_kernels()
            if kernels is None:
                return False
            if family == 'radial':
                if int(frame_index) < 0 or int(frame_index) >= len(view.azimuths_deg):
                    raise _ResidentTensorRTRingFatalError(
                        f'P4 Radial graph frame {frame_index} is outside its descriptor table'
                    )
                dynamic_value = int(frame_index)
            else:
                dynamic_value = int(tilted_frame_center(view, int(frame_index)))
                if dynamic_value < 0 or dynamic_value >= int(tilted_stack_axis_length(view)):
                    raise _ResidentTensorRTRingFatalError(
                        f'P4 Tilted graph center {dynamic_value} is outside its stack'
                    )
            try:
                self._fused_slot_metadata(slot, kernels, dynamic_value)
                slot.render_graph.replay()
            except BaseException as exc:
                # The ring has already borrowed TRT bindings when this path runs. A graph
                # replay failure cannot enter the worker's generic lazy-render retry safely.
                raise _ResidentTensorRTRingFatalError(
                    f'P4 fused {family} renderer CUDA Graph replay failed'
                ) from exc
            return True
        if family == 'radial':
            return self._try_fused_radial_into_slot(
                slot, view, aff, frame_index, out_size,
                stage_metadata=bool(stage_metadata),
                disable_on_failure=bool(disable_on_failure),
            )
        if family == 'tilted':
            return self._try_fused_tilted_into_slot(
                slot, view, aff, frame_index, out_size,
                stage_metadata=bool(stage_metadata),
                disable_on_failure=bool(disable_on_failure),
            )
        return False

    def _fused_renderer_key(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        aff: AffineSpec,
        out_size: int,
    ) -> Tuple[object, ...]:
        family = 'radial' if str(view.family) == 'radial' else ('tilted' if is_tilted_view(view) else '')
        matrix_key = tuple(
            round(float(x), 7)
            for x in np.asarray(aff.M_out_to_src, dtype=np.float32).reshape(-1).tolist()
        )
        if family == 'radial':
            family_geometry: Tuple[object, ...] = (
                int(view.src_h), int(view.src_w), int(view.full_h), int(view.full_w),
                round(float(view.center_x), 6), round(float(view.center_y), 6),
                round(float(view.roi_radius), 6),
                np.ascontiguousarray(np.asarray(view.azimuths_deg, dtype=np.float32)).tobytes(),
            )
        elif family == 'tilted':
            family_geometry = (
                str(tilted_base_view_name(view)), str(view.tilt_direction),
                round(float(view.tilt_angle_deg), 7), int(view.tilt_frame_start),
                int(view.tilt_frame_stop), int(view.src_h), int(view.src_w),
                int(view.full_t), int(view.full_h), int(view.full_w),
            )
        else:
            family_geometry = ()
        return (
            self._volume_key, str(view.name), family, int(out_size), str(slot.input.dtype),
            matrix_key, family_geometry,
        )

    def validate_fused_ring_renderer(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        job: AugJob,
        frame_index: int,
        out_size: int,
    ) -> None:
        """Synchronously prove a P4 launch before the resident source is consumed.

        NVRTC compilation and argument/configuration failures are normally synchronous, but
        descriptor or render memory faults surface only at a stream boundary.  One probe per
        volume/view/dtype/affine makes the default-on path a real capability test.  A failed
        synchronization is fatal rather than a Torch fallback because CUDA execution faults
        can poison the worker context; the parent already treats this exception as a worker-
        fatal result.  Successful keys do not add a synchronization to later task windows.
        """
        family = 'radial' if str(view.family) == 'radial' else ('tilted' if is_tilted_view(view) else '')
        if not family:
            return
        if family == 'radial' and not fused_radial_render_enabled():
            return
        if family == 'tilted' and not fused_tilted_render_enabled():
            return
        key = self._fused_renderer_key(slot, view, job.aff, int(out_size))
        if key in self._fused_validated_keys or family in self._fused_disabled_families:
            return
        with self.torch.cuda.stream(self._stream):
            launched = self._try_fused_render_into_ring_slot(
                slot, view, job.aff, int(frame_index), int(out_size),
            )
        if not launched:
            # A later launch-argument rejection can occur after descriptor generation was
            # already queued. Drain it before its Torch owners are recycled by the fallback.
            try:
                self._stream.synchronize()
            except BaseException as exc:
                raise _ResidentTensorRTRingFatalError(
                    f'P4 fused {family} renderer failed while draining a rejected probe'
                ) from exc
            return
        try:
            self._stream.synchronize()
        except BaseException as exc:
            raise _ResidentTensorRTRingFatalError(
                f'P4 fused {family} renderer failed its pre-consumption CUDA probe'
            ) from exc
        self._fused_validated_keys.add(key)

    def capture_fused_ring_renderer(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        job: AugJob,
        frame_index: int,
        out_size: int,
    ) -> None:
        """Capture and validate one slot's stable P4 render kernel opportunistically.

        The one-thread metadata setter intentionally remains outside the graph. Therefore a
        replay has fixed volume/descriptor/output addresses but reads the just-staged frame
        index or Tilted center from ``slot.render_meta``. Capture failures with a healthy
        stream retain the uncaptured fused launch; failed recovery is worker-fatal.
        """
        if not fused_render_cuda_graphs_enabled():
            return
        family = 'radial' if str(view.family) == 'radial' else ('tilted' if is_tilted_view(view) else '')
        if not family or family in self._fused_disabled_families:
            return
        key = self._fused_renderer_key(slot, view, job.aff, int(out_size))
        slot.render_expected_key = key
        # A slot can be reused after a view/affine/volume change. Never leave an older
        # executable installed when this new key is rejected or capture fails: otherwise
        # the frame path could replay stale descriptor pointers and affine constants.
        if slot.render_graph is not None and slot.render_graph_key != key:
            slot.render_graph = None
            slot.render_graph_key = None
        if key not in self._fused_validated_keys:
            return
        if key in self._fused_graph_rejected_keys:
            return
        if slot.render_graph is not None and slot.render_graph_key == key:
            return
        kernels = _fused_direct_render_kernels()
        if kernels is None:
            return
        dynamic_value = (
            int(frame_index)
            if family == 'radial'
            else int(tilted_frame_center(view, int(frame_index)))
        )
        # Create zero-copy wrappers before stream capture; their addresses remain stable.
        self._fused_slot_metadata(slot, kernels, None)
        self._fused_slot_output(slot, kernels)
        graph = None
        try:
            graph = self.torch.cuda.CUDAGraph()
            with self.torch.cuda.graph(graph, stream=self._stream):
                launched = self._try_fused_render_into_ring_slot(
                    slot, view, job.aff, int(frame_index), int(out_size),
                    stage_metadata=False, allow_graph_replay=False,
                    disable_on_failure=False,
                )
            if not launched:
                graph = None
                self._stream.synchronize()
                self._fused_graph_rejected_keys.add(key)
                return
            # Prove graph instantiation/replay before source consumption. The dynamic
            # metadata write is ordered immediately ahead of replay on the same stream.
            with self.torch.cuda.stream(self._stream):
                self._fused_slot_metadata(slot, kernels, dynamic_value)
                graph.replay()
            self._stream.synchronize()
        except Exception as exc:
            graph = None
            try:
                self._stream.synchronize()
            except BaseException as sync_exc:
                raise _ResidentTensorRTRingFatalError(
                    f'failed to recover P4 fused {family} renderer stream after graph capture'
                ) from sync_exc
            if family not in self._fused_graph_warned_families:
                self._fused_graph_warned_families.add(family)
                print(
                    f'P4 fused {family} renderer CUDA Graph capture unavailable ({exc}); '
                    'using its uncaptured direct kernel.'
                )
            self._fused_graph_rejected_keys.add(key)
            return
        slot.render_graph = graph
        slot.render_graph_key = key
        if family not in self._fused_graph_announced_families:
            self._fused_graph_announced_families.add(family)
            print(f'P4 fused {family} renderer CUDA Graph active (dynamic device metadata).')

    # ---- radial taps / fold (device) ----

    def _radial_taps_gpu(self, view: ViewInfo, angle_deg: float) -> Tuple[object, object]:
        """Device port of get_radial_sampler + _radial_sampler_flat_taps for one azimuth."""
        torch = self.torch
        dev = self.device
        full_w = int(view.full_w)
        full_h = int(view.full_h)
        n_u = int(view.src_w) if int(view.src_w) > 0 else int(view.diameter)
        a = int(RADIAL_LANCZOS_A)
        coords = torch.linspace(
            -float(view.roi_radius), float(view.roi_radius), n_u, dtype=torch.float32, device=dev,
        )
        theta = math.radians(float(angle_deg))
        xs = float(view.center_x) + coords * float(math.cos(theta))
        ys = float(view.center_y) + coords * float(math.sin(theta))
        offs = torch.arange(-(a - 1), a + 1, dtype=torch.float32, device=dev)
        x_pos = xs.floor().unsqueeze(1) + offs.unsqueeze(0)
        y_pos = ys.floor().unsqueeze(1) + offs.unsqueeze(0)
        dx = xs.unsqueeze(1) - x_pos
        dy = ys.unsqueeze(1) - y_pos
        zero = torch.zeros((), dtype=torch.float32, device=dev)
        x_w = torch.where(dx.abs() >= float(a), zero, torch.sinc(dx) * torch.sinc(dx / float(a)))
        y_w = torch.where(dy.abs() >= float(a), zero, torch.sinc(dy) * torch.sinc(dy / float(a)))
        x_w = x_w * ((x_pos >= 0) & (x_pos < float(full_w))).to(torch.float32)
        y_w = y_w * ((y_pos >= 0) & (y_pos < float(full_h))).to(torch.float32)
        # v13.2.4 (task #3): renormalize each sample's separable taps after OOB zeroing.
        x_sum = x_w.sum(dim=1, keepdim=True)
        y_sum = y_w.sum(dim=1, keepdim=True)
        x_w = torch.where(x_sum.abs() > 1e-6, x_w / x_sum, x_w)
        y_w = torch.where(y_sum.abs() > 1e-6, y_w / y_sum, y_w)
        x_idx = x_pos.clamp(0.0, float(full_w - 1)).to(torch.int64)
        y_idx = y_pos.clamp(0.0, float(full_h - 1)).to(torch.int64)
        flat_idx = (y_idx.unsqueeze(2) * int(full_w) + x_idx.unsqueeze(1)).reshape(n_u, -1)
        w2d = (y_w.unsqueeze(2) * x_w.unsqueeze(1)).reshape(n_u, -1)
        return flat_idx, w2d

    def _radial_fold_indices(
        self,
        t_dim: int,
        rows: int,
        logical_t: Optional[int] = None,
    ) -> Tuple[object, object, object]:
        torch = self.torch
        # The two center-aligned maps (rows -> logical/cube t -> native t)
        # compose to this direct native coordinate. Keep logical_t in the key so
        # cache identity still describes the renderer geometry being composed.
        logical = int(t_dim if logical_t is None else logical_t)
        key = (int(t_dim), int(logical), int(rows))
        cached = self._fold_cache.get(key)
        if cached is not None:
            return cached
        rf = (np.arange(int(rows), dtype=np.float64) + 0.5) * (float(t_dim) / float(rows)) - 0.5
        r0 = np.clip(np.floor(rf).astype(np.int64), 0, int(t_dim) - 1)
        r1 = np.minimum(r0 + 1, int(t_dim) - 1)
        alpha = np.clip(rf - r0, 0.0, 1.0).astype(np.float32)[:, None]
        out = (
            torch.from_numpy(r0).to(self.device),
            torch.from_numpy(r1).to(self.device),
            torch.from_numpy(alpha).to(self.device),
        )
        self._fold_cache[key] = out
        return out

    def _radial_project_blocks(self, view: ViewInfo, block2d: object, flat_idx: object, w2d: object) -> object:
        """(rows, H*W) u8 block -> (rows, u) float32 Lanczos projection."""
        samples = block2d[:, flat_idx]
        return (samples.to(self.torch.float32) * w2d.unsqueeze(0)).sum(dim=-1)

    def _render_radial_native_resident(self, view: ViewInfo, frame_idx: int) -> object:
        torch = self.torch
        vol = self._volume_gpu
        t_dim = int(vol.shape[0])
        rows_out = int(view.src_h)
        u_len = int(view.src_w) if int(view.src_w) > 0 else int(view.diameter)
        flat_idx, w2d = self._radial_taps_gpu(view, float(view.azimuths_deg[int(frame_idx)]))
        vol2d = vol.view(t_dim, -1)
        proj = torch.empty((t_dim, u_len), dtype=torch.float32, device=self.device)
        chunk = 512
        for t0 in range(0, t_dim, chunk):
            t1 = min(t_dim, t0 + chunk)
            proj[t0:t1] = self._radial_project_blocks(view, vol2d[t0:t1], flat_idx, w2d)
        if rows_out == t_dim:
            return proj
        r0, r1, alpha = self._radial_fold_indices(t_dim, rows_out, logical_t=int(self._logical_t))
        return proj[r0] * (1.0 - alpha) + proj[r1] * alpha

    def prerender_radial_slab(self, view: ViewInfo, slice_start: int, slice_count: int) -> np.ndarray:
        """v13.3.0 (R1, stream mode): GPU-render one radial task's frames into a host slab.

        Streams transient source t-blocks to the device and evaluates an adaptive azimuth chunk
        per block (per-azimuth fp16 t-projections stay device-resident between blocks), then
        folds/quantizes each frame and copies it into a host uint8 slab. VRAM working set is
        bounded by the t-block plus the azimuth-chunk projections; the volume is re-uploaded
        ceil(count/az_chunk) times.
        """
        torch = self.torch
        t_dim, full_h, full_w = (int(x) for x in self._volume_mm.shape)
        rows_out = int(view.src_h)
        u_len = int(view.src_w) if int(view.src_w) > 0 else int(view.diameter)
        count = int(slice_count)
        slab = np.empty((count, rows_out, u_len), dtype=np.uint8)
        tblock = int(gpu_render_tblock_slices())
        per_az_bytes = t_dim * u_len * 2 + u_len * RADIAL_LANCZOS_A * RADIAL_LANCZOS_A * 4 * 12 * 2
        with torch.cuda.stream(self._stream):
            try:
                free_bytes, _total = torch.cuda.mem_get_info(self.device)
            except Exception:
                free_bytes = 8 * GIB
            gather_temp = tblock * u_len * (RADIAL_LANCZOS_A * 2) ** 2 * 4
            budget = max(0, int(free_bytes) - tblock * full_h * full_w - gather_temp - 2 * GIB)
            az_chunk = int(np.clip(budget // max(1, per_az_bytes), 1, count))
            # Each azimuth chunk re-streams the whole source volume; a tiny chunk would multiply
            # that H2D traffic pathologically — hand the task back to the CPU render path instead.
            if az_chunk < min(8, count):
                raise RuntimeError(
                    f'insufficient free VRAM for streamed radial prerender '
                    f'(az_chunk={az_chunk}, free={free_bytes / GIB:.1f} GiB)'
                )
            fold = rows_out != t_dim
            if fold:
                r0, r1, alpha = self._radial_fold_indices(t_dim, rows_out)
            for a0 in range(0, count, az_chunk):
                a1 = min(count, a0 + az_chunk)
                proj = torch.zeros((a1 - a0, t_dim, u_len), dtype=torch.float16, device=self.device)
                taps = [
                    self._radial_taps_gpu(view, float(view.azimuths_deg[int(slice_start) + i]))
                    for i in range(a0, a1)
                ]
                for t0 in range(0, t_dim, tblock):
                    t1 = min(t_dim, t0 + tblock)
                    block = torch.from_numpy(np.ascontiguousarray(self._volume_mm[t0:t1])).to(self.device)
                    block2d = block.view(t1 - t0, -1)
                    for j, (flat_idx, w2d) in enumerate(taps):
                        proj[j, t0:t1] = self._radial_project_blocks(view, block2d, flat_idx, w2d).to(torch.float16)
                    del block, block2d
                for j in range(a1 - a0):
                    pj = proj[j].to(torch.float32)
                    folded = (pj[r0] * (1.0 - alpha) + pj[r1] * alpha) if fold else pj
                    frame_u8 = folded.round().clamp_(0.0, 255.0).to(torch.uint8)
                    slab[a0 + j] = frame_u8.cpu().numpy()
                del proj, taps
        return slab

    # ---- tilted (device) ----

    def _tilted_plan_gpu(self, view: ViewInfo, M_grid_to_src: np.ndarray, grid_h: int, grid_w: int) -> Dict[str, object]:
        torch = self.torch
        key = _tilted_plan_cache_key(view, M_grid_to_src, int(grid_h), int(grid_w))
        cached = self._tilted_plans.get(key)
        if cached is not None:
            self._tilted_plans.move_to_end(key)
            return cached
        plan = get_tilted_render_plan(view, M_grid_to_src, int(grid_h), int(grid_w))
        native_t, full_h, full_w = (int(x) for x in self._volume_gpu.shape)
        logical_t = int(self._logical_t)
        base = tilted_base_view_name(view)
        x64 = plan.x_idx.astype(np.int64)
        y64 = plan.y_idx.astype(np.int64)
        if base == 'transverse':
            # X/Y are native and working-identical on the E3 admission path; t is
            # the fractional STACK coordinate and is composed in _render_tilted_frame.
            inplane0 = y64 * full_w + x64
            inplane1 = inplane0
            t_alpha_np = np.zeros_like(plan.axis_offset, dtype=np.float32)
            stride = full_h * full_w
        elif base == 'sagittal':
            # base axes (X,t), stack Y: working-t is an IN-PLANE coordinate.
            t_pos = (y64.astype(np.float64) + 0.5) * (float(native_t) / float(logical_t)) - 0.5
            t0 = np.clip(np.floor(t_pos).astype(np.int64), 0, native_t - 1)
            t1 = np.minimum(t0 + 1, native_t - 1)
            t_alpha_np = np.clip(t_pos - t0, 0.0, 1.0).astype(np.float32)
            inplane0 = t0 * (full_h * full_w) + x64
            inplane1 = t1 * (full_h * full_w) + x64
            stride = full_w
        elif base == 'coronal':
            # base axes (Y,t), stack X: like sagittal, t needs its own two taps.
            t_pos = (y64.astype(np.float64) + 0.5) * (float(native_t) / float(logical_t)) - 0.5
            t0 = np.clip(np.floor(t_pos).astype(np.int64), 0, native_t - 1)
            t1 = np.minimum(t0 + 1, native_t - 1)
            t_alpha_np = np.clip(t_pos - t0, 0.0, 1.0).astype(np.float32)
            inplane0 = t0 * (full_h * full_w) + x64 * full_w
            inplane1 = t1 * (full_h * full_w) + x64 * full_w
            stride = 1
        else:  # pragma: no cover
            raise ValueError(f'Unsupported Tilted View base: {base}')
        tan_alpha = float(math.tan(math.radians(float(view.tilt_angle_deg))))
        info: Dict[str, object] = {
            'base': str(base),
            't_identity': bool(native_t == logical_t),
            'inplane0': torch.from_numpy(np.ascontiguousarray(inplane0)).to(self.device),
            'inplane1': torch.from_numpy(np.ascontiguousarray(inplane1)).to(self.device),
            't_alpha': torch.from_numpy(np.ascontiguousarray(t_alpha_np)).to(self.device),
            'stack_base': torch.from_numpy(
                np.ascontiguousarray(np.asarray(plan.axis_offset, dtype=np.float32) * np.float32(tan_alpha))
            ).to(self.device),
            'valid_xy': torch.from_numpy(np.ascontiguousarray(plan.valid_xy)).to(self.device),
            'stride': int(stride),
            'stack_len': int(tilted_stack_axis_length(view)),
        }
        self._tilted_plans[key] = info
        self._tilted_plans.move_to_end(key)
        while len(self._tilted_plans) > 10:
            self._tilted_plans.popitem(last=False)
        return info

    def _render_tilted_frame(self, view: ViewInfo, M_grid_to_src: np.ndarray, grid_h: int, grid_w: int, frame_idx: int) -> object:
        torch = self.torch
        info = self._tilted_plan_gpu(view, M_grid_to_src, int(grid_h), int(grid_w))
        stack_len = int(info['stack_len'])
        center = float(tilted_frame_center(view, int(frame_idx)))
        stack_src = info['stack_base'] + center
        valid = info['valid_xy'] & (stack_src >= 0.0) & (stack_src <= float(stack_len - 1))
        s0f = stack_src.floor().clamp(0.0, float(stack_len - 1))
        s1f = (s0f + 1.0).clamp(max=float(stack_len - 1))
        alpha = stack_src - s0f
        stride = int(info['stride'])
        if str(info['base']) == 'transverse':
            # Reconstruct the two working-t stack taps from native t (including
            # the former cube-u8 rounding), then apply the existing stack lerp.
            # This is exact to E1 without materializing the full cube volume.
            inplane = info['inplane0']
            if bool(info['t_identity']):
                f0 = torch.take(
                    self._volume_flat, inplane + s0f.to(torch.int64) * stride,
                ).to(torch.float32)
                f1 = torch.take(
                    self._volume_flat, inplane + s1f.to(torch.int64) * stride,
                ).to(torch.float32)
                vals = f0 + alpha * (f1 - f0)
                return torch.where(valid, vals, torch.zeros((), dtype=torch.float32, device=self.device))
            r0, r1, tmap_alpha = self._native_t_indices(int(self._logical_t))
            s0i = s0f.to(torch.int64)
            s1i = s1f.to(torch.int64)
            n00 = r0[s0i]; n01 = r1[s0i]; a0 = tmap_alpha[s0i]
            n10 = r0[s1i]; n11 = r1[s1i]; a1 = tmap_alpha[s1i]
            f00 = torch.take(self._volume_flat, inplane + n00 * stride).to(torch.float32)
            f01 = torch.take(self._volume_flat, inplane + n01 * stride).to(torch.float32)
            f10 = torch.take(self._volume_flat, inplane + n10 * stride).to(torch.float32)
            f11 = torch.take(self._volume_flat, inplane + n11 * stride).to(torch.float32)
            v0 = (f00 + a0 * (f01 - f00)).round_().clamp_(0.0, 255.0)
            v1 = (f10 + a1 * (f11 - f10)).round_().clamp_(0.0, 255.0)
            vals = v0 + alpha * (v1 - v0)
        else:
            # Sagittal/coronal bases carry working t in-plane. Interpolate native
            # t at each of the two spatial stack taps (four gathers total), round
            # each t-lerp as the former resident uint8 cube did, then stack-lerp.
            inplane0 = info['inplane0']
            inplane1 = info['inplane1']
            t_alpha = info['t_alpha']
            s0 = s0f.to(torch.int64) * stride
            s1 = s1f.to(torch.int64) * stride
            if bool(info['t_identity']):
                v0 = torch.take(self._volume_flat, inplane0 + s0).to(torch.float32)
                v1 = torch.take(self._volume_flat, inplane0 + s1).to(torch.float32)
            else:
                f00 = torch.take(self._volume_flat, inplane0 + s0).to(torch.float32)
                f01 = torch.take(self._volume_flat, inplane1 + s0).to(torch.float32)
                f10 = torch.take(self._volume_flat, inplane0 + s1).to(torch.float32)
                f11 = torch.take(self._volume_flat, inplane1 + s1).to(torch.float32)
                v0 = (f00 + t_alpha * (f01 - f00)).round_().clamp_(0.0, 255.0)
                v1 = (f10 + t_alpha * (f11 - f10)).round_().clamp_(0.0, 255.0)
            vals = v0 + alpha * (v1 - v0)
        return torch.where(valid, vals, torch.zeros((), dtype=torch.float32, device=self.device))

    # ---- cartesian / dispatch ----

    @staticmethod
    def _affine_is_identity_render(aff: AffineSpec) -> bool:
        return bool(
            int(aff.src_w) == int(aff.out_size)
            and int(aff.src_h) == int(aff.out_size)
            and int(aff.canvas_w) == int(aff.src_w)
            and int(aff.canvas_h) == int(aff.src_h)
            and float(aff.angle_deg) % 360.0 == 0.0
        )

    def _render_native_plane(self, view: ViewInfo, frame_idx: int) -> object:
        vol = self._volume_gpu
        name = str(view.name)
        if name == 'transverse':
            if int(vol.shape[0]) == int(self._logical_t):
                return vol[int(frame_idx)].to(self.torch.float32)
            r0, r1, alpha = self._native_t_indices(int(self._logical_t))
            tap0 = r0[int(frame_idx):int(frame_idx) + 1]
            tap1 = r1[int(frame_idx):int(frame_idx) + 1]
            f0 = vol.index_select(0, tap0).squeeze(0).to(self.torch.float32)
            f1 = vol.index_select(0, tap1).squeeze(0).to(self.torch.float32)
            return (f0 + alpha[int(frame_idx)] * (f1 - f0)).round_().clamp_(0.0, 255.0)
        if name == 'sagittal':
            return self._resample_native_t_axis(vol[:, int(frame_idx), :])
        if name == 'coronal':
            return self._resample_native_t_axis(vol[:, :, int(frame_idx)]).contiguous()
        if str(view.family) == 'radial':
            return self._render_radial_native_resident(view, int(frame_idx))
        raise ValueError(f'Unsupported view for GPU native plane: {name}')

    def _render_fullframe_frame(self, view: ViewInfo, aff: AffineSpec, frame_idx: int, out_size: int) -> object:
        if is_tilted_view(view):
            return self._render_tilted_frame(view, aff.M_out_to_src, int(out_size), int(out_size), int(frame_idx))
        plane = self._render_native_plane(view, int(frame_idx))
        if self._affine_is_identity_render(aff):
            return plane
        theta = _affine_theta_from_dst_to_src(
            aff.M_out_to_src, int(plane.shape[0]), int(plane.shape[1]), int(out_size), int(out_size),
        )
        grid = _get_cached_affine_grid(theta, int(out_size), int(out_size), self.device)
        return self.F.grid_sample(
            plane.reshape(1, 1, int(plane.shape[0]), int(plane.shape[1])),
            grid, mode='bilinear', padding_mode='zeros', align_corners=False,
        ).reshape(int(out_size), int(out_size))

    def render_fullframe_batch(
        self, view: ViewInfo, job: AugJob, frame_indices: Sequence[int], out_size: int, half: bool,
    ) -> Tuple[object, object]:
        """Render one normalized BCHW batch on the render stream; returns (tensor, ready event)."""
        torch = self.torch
        with torch.cuda.stream(self._stream):
            frames = [
                self._render_fullframe_frame(view, job.aff, int(fi), int(out_size))
                for fi in frame_indices
            ]
            batch = torch.stack(frames, dim=0).unsqueeze(1)
            batch = batch.clamp_(0.0, 255.0).mul_(1.0 / 255.0)
            if bool(half):
                batch = batch.to(torch.float16)
            ready_event = torch.cuda.Event()
            ready_event.record(self._stream)
        return batch, ready_event

    def render_fullframe_into_ring_slot(
        self,
        slot: _ResidentGpuPipelineSlot,
        view: ViewInfo,
        job: AugJob,
        frame_index: int,
        out_size: int,
    ) -> None:
        """Render/normalize one frame into a slot's persistent TensorRT input address."""
        torch = self.torch
        if tuple(int(x) for x in slot.input.shape) != (1, 1, int(out_size), int(out_size)):
            raise RuntimeError(
                f'resident ring input shape {tuple(slot.input.shape)} != (1,1,{int(out_size)},{int(out_size)})'
            )
        with torch.cuda.stream(self._stream):
            if bool(slot.infer_valid):
                # This slot's preceding TensorRT enqueue has consumed its input before
                # the low-priority renderer writes the next frame into the same address.
                self._stream.wait_event(slot.infer_done)
            # P4: the specialized ring admits angle-0 jobs only. Radial/Tilted kernels
            # consume the resident uint8 volume and write normalized pixels directly to
            # this static binding, avoiding proj/plane/grid/gather/cast intermediates.
            if (
                abs(float(job.angle_deg)) <= 1.0e-7
                and self._try_fused_render_into_ring_slot(
                    slot, view, job.aff, int(frame_index), int(out_size),
                )
            ):
                slot.render_done.record(self._stream)
                return
            plane = self._render_fullframe_frame(view, job.aff, int(frame_index), int(out_size))
            # Renderers return disposable float planes. Normalize in place and convert
            # directly into the preallocated fp16/fp32 binding (no stack/cast allocation).
            plane.clamp_(0.0, 255.0).mul_(1.0 / 255.0)
            slot.input[0, 0].copy_(plane, non_blocking=True)
            slot.render_done.record(self._stream)


class GpuRenderedYoloSource:
    """Ultralytics-compatible source whose batches are rendered AND normalized on the GPU.

    v13.3.0 (R21): used by multi-GPU workers in resident mode. __next__ yields
    (paths, GpuPrefetchedYoloBatch, info) exactly like GpuPrefetchingYoloSource — the batch
    carries a device-resident normalized BCHW tensor plus a render-stream event, and the
    patched BasePredictor.preprocess consumes it via the _tta_gpu_tensor contract. The
    orig-image entries are zero-strided placeholder frames (only their shape is read).
    """

    def __init__(
        self,
        engine: _GpuWorkerRenderEngine,
        view: ViewInfo,
        job: AugJob,
        *,
        slice_offset: int,
        num_frames: int,
        batch_size: int,
        out_size: int,
        half: bool,
        name: str,
    ) -> None:
        self.engine = engine
        self.view = view
        self.job = job
        self.slice_offset = int(slice_offset)
        self.name = re.sub(r'[^A-Za-z0-9_.-]+', '_', str(name)).strip('_') or 'gpu_rendered_volume'
        self.out_size = int(out_size)
        self.half = bool(half)
        self.nf = max(0, int(num_frames))
        self.bs = max(1, int(batch_size))
        self.yield_nf = int(math.ceil(float(self.nf) / float(self.bs)) * self.bs) if self.nf > 0 else 0
        self.synthetic_count = max(0, int(self.yield_nf) - int(self.nf))
        self.mode = 'image'
        self.count = 0
        self._direct_count = 0
        self._direct_ring: Optional[List[_ResidentGpuPipelineSlot]] = None
        self._fake_frame = np.broadcast_to(
            np.zeros((1, 1, 1), dtype=np.uint8), (self.out_size, self.out_size, 1),
        )
        # This source bypasses maybe_wrap_source_with_gpu_input_staging (which is where other
        # sources get registered), so register with Ultralytics' source checker here.
        ensure_ultralytics_accepts_in_memory_volume_source()
        try:
            from ultralytics.data.loaders import SourceTypes  # type: ignore
            self.source_type = SourceTypes(stream=False, screenshot=False, from_img=True, tensor=False)
        except Exception:
            self.source_type = argparse.Namespace(stream=False, screenshot=False, from_img=True, tensor=False)

    def __len__(self) -> int:
        return int(math.ceil(float(self.nf) / float(self.bs))) if self.nf > 0 else 0

    def __iter__(self) -> 'GpuRenderedYoloSource':
        self.count = 0
        self._direct_count = 0
        return self

    def start(self) -> None:
        return None

    def close(self) -> None:
        return None

    def prepare_direct_ring(self, input_dtype: Optional[object] = None) -> List[_ResidentGpuPipelineSlot]:
        """Allocate the two-entry ring in the TensorRT ENGINE input binding dtype.

        ``--half`` describes predictor policy, but stock Ultralytics FP16 TensorRT engines
        commonly retain a float32 image binding.  The capability probe therefore resolves
        that binding before calling here; using ``self.half`` is retained only for callers
        outside the specialized TensorRT path.
        """
        if self.bs != 1 or self.nf <= 0 or str(getattr(self.engine, '_mode', '')) != 'resident':
            raise RuntimeError('direct resident ring requires a nonempty batch-1 resident source')
        torch = self.engine.torch
        resolved_dtype = (
            input_dtype
            if input_dtype is not None
            else (torch.float16 if bool(self.half) else torch.float32)
        )
        if resolved_dtype not in (torch.float16, torch.float32):
            raise RuntimeError(
                f'resident ring cannot render normalized images into TensorRT dtype {resolved_dtype}'
            )
        if (
            self._direct_ring is None
            or any(slot.input.dtype != resolved_dtype for slot in self._direct_ring)
        ):
            self._direct_ring = [
                _ResidentGpuPipelineSlot(
                    torch, self.engine.device, int(self.out_size), resolved_dtype, slot_id=i,
                )
                for i in range(2)
            ]
        if abs(float(self.job.angle_deg)) <= 1.0e-7:
            family = (
                'radial' if str(self.view.family) == 'radial'
                else ('tilted' if is_tilted_view(self.view) else '')
            )
            for slot in self._direct_ring:
                expected_key = (
                    self.engine._fused_renderer_key(
                        slot, self.view, self.job.aff, int(self.out_size),
                    )
                    if family else None
                )
                slot.render_expected_key = expected_key
                if slot.render_graph is not None and slot.render_graph_key != expected_key:
                    slot.render_graph = None
                    slot.render_graph_key = None
            # P4's first async descriptor/render launch is synchronized here, before
            # _try_resident_trt_ring_accumulate consumes a frame or borrows TRT bindings.
            self.engine.validate_fused_ring_renderer(
                self._direct_ring[0], self.view, self.job,
                int(self.slice_offset), int(self.out_size),
            )
            for slot in self._direct_ring:
                self.engine.capture_fused_ring_renderer(
                    slot, self.view, self.job,
                    int(self.slice_offset), int(self.out_size),
                )
        self._direct_count = 0
        self.count = 0
        return self._direct_ring

    def reset_direct_ring(self) -> None:
        """Reset source position after a pre-consumption capability probe failed."""
        self._direct_count = 0
        self.count = 0
        # The generic fallback never uses these buffers. Drop a rejected probe's static
        # bindings/events immediately so a capability mismatch does not reserve VRAM for
        # the remainder of the worker process.
        self._direct_ring = None

    def next_direct_slot(self) -> Optional[Tuple[int, _ResidentGpuPipelineSlot]]:
        """Queue one render without constructing paths/info/source tuples.

        This entry point belongs exclusively to the specialized accumulator.  Generic
        Ultralytics/direct iterators continue to use ``__next__`` unchanged.
        """
        if self._direct_ring is None:
            raise RuntimeError('direct resident ring has not been prepared')
        if int(self._direct_count) >= int(self.nf):
            return None
        local_index = int(self._direct_count)
        absolute_index = int(self.slice_offset) + local_index
        slot = self._direct_ring[local_index & 1]
        slot.frame_index = int(local_index)
        slot.absolute_index = int(absolute_index)
        slot.synthetic = False
        self.engine.render_fullframe_into_ring_slot(
            slot, self.view, self.job, int(absolute_index), int(self.out_size),
        )
        self._direct_count += 1
        return int(local_index), slot

    def __next__(self) -> Tuple[List[str], object, List[str]]:
        if self.count >= self.yield_nf or self.nf <= 0:
            raise StopIteration
        start = int(self.count)
        stop = min(int(self.yield_nf), start + int(self.bs))
        self.count = int(stop)
        paths: List[str] = []
        info: List[str] = []
        abs_indices: List[int] = []
        last_real_idx = max(0, int(self.nf) - 1)
        for idx in range(start, stop):
            real_idx = int(idx) if int(idx) < int(self.nf) else int(last_real_idx)
            synthetic = int(idx) >= int(self.nf)
            suffix = '_synthetic' if synthetic else ''
            abs_indices.append(int(self.slice_offset) + int(real_idx))
            paths.append(f'{self.name}_{idx + 1:06d}{suffix}.png')
            if synthetic:
                info.append(f'gpu-rendered {self.name} synthetic padded slice {idx + 1}/{self.yield_nf} repeats real slice {real_idx + 1}/{self.nf}: ')
            else:
                info.append(f'gpu-rendered {self.name} slice {idx + 1}/{self.nf}: ')
        gpu_tensor, ready_event = self.engine.render_fullframe_batch(
            self.view, self.job, abs_indices, int(self.out_size), bool(self.half),
        )
        batch = GpuPrefetchedYoloBatch(
            [self._fake_frame] * len(abs_indices),
            gpu_tensor=gpu_tensor,
            ready_event=ready_event,
            source_label=self.name,
        )
        return paths, batch, info


_WORKER_GPU_RENDER_ENGINE: Optional[_GpuWorkerRenderEngine] = None


def _worker_gpu_render_engine() -> Optional[_GpuWorkerRenderEngine]:
    return _WORKER_GPU_RENDER_ENGINE


def _init_worker_gpu_render_engine(device_str: str = 'cuda:0') -> Optional[_GpuWorkerRenderEngine]:
    """Create this worker process's GPU render engine (call after the model/CUDA context exists)."""
    global _WORKER_GPU_RENDER_ENGINE
    if _WORKER_GPU_RENDER_ENGINE is not None:
        return _WORKER_GPU_RENDER_ENGINE
    if not gpu_worker_render_enabled():
        return None
    try:
        import torch  # type: ignore
        if not bool(torch.cuda.is_available()):
            return None
        _WORKER_GPU_RENDER_ENGINE = _GpuWorkerRenderEngine(str(device_str))
        print('GPU render engine initialized (v13.3.0 R1/R21); volume residency resolves on the first task.')
    except Exception as exc:
        print(f'Warning: GPU render engine unavailable ({exc}); worker uses CPU rendering.')
        _WORKER_GPU_RENDER_ENGINE = None
    return _WORKER_GPU_RENDER_ENGINE


def _slab_frame_renderer(slab: np.ndarray) -> Callable[[int], np.ndarray]:
    def _render(idx: int) -> np.ndarray:
        return slab[int(idx)]
    return _render


def _worker_render_callable(volume_rgb: np.ndarray, view: ViewInfo, job: object, kind: str, slice_offset: int = 0) -> Callable[[int], np.ndarray]:
    # local index -> absolute view slice index (sub-range tasks render a contiguous slice window).
    off = int(slice_offset)
    if str(kind) == 'tile':
        def _render_tile(idx: int) -> np.ndarray:
            return render_dense_tile_frame_for_job(
                volume_rgb=volume_rgb, view=view, tile_job=job, frame_idx=off + int(idx), view_frames=None,
            )
        return _render_tile

    def _render_full(idx: int) -> np.ndarray:
        return render_fullframe_frame_for_job(
            volume_rgb=volume_rgb, view=view, job=job, frame_idx=off + int(idx), view_frames=None,
        )
    return _render_full


@dataclass
class _DeferredGpuWorkerTaskResult:
    """Task stats whose device-union flush is retiring on the worker's copy lane."""

    stats: Dict[str, object]
    flush_future: Future
    memmaps: Tuple[object, ...]

    def finish(self) -> Dict[str, object]:
        try:
            self.flush_future.result()
            return self.stats
        finally:
            for mm in self.memmaps:
                if mm is not None:
                    try:
                        close_memmap_array(mm)
                    except Exception:
                        pass


def run_prediction_volume_in_worker(
    model: object,
    cfg: 'PredictConfig',
    task: Dict[str, object],
) -> Dict[str, object] | _DeferredGpuWorkerTaskResult:
    """Render + predict + accumulate one prediction volume in a GPU worker process.

    Writes the per-volume processing-grid mask (and confidence map, if --min_conf > 0) to the
    file-backed result memmaps named in the task, then returns small inference stats. D6 uses
    the canonical inference grid for non-radial views and the native raster for Radial.
    """
    view: ViewInfo = task['view']  # type: ignore[assignment]
    job = task['job']
    kind = str(task['kind'])
    slice_offset = int(task.get('slice_start', 0))
    slice_count = int(task.get('slice_count', int(view.num_slices)))
    num_frames = int(slice_count)
    out_size = int(task['out_size'])
    # The result memmap covers only this task's contiguous slice window [slice_start, slice_start+count).
    _full_processing_shape = view_processing_volume_shape(view, int(out_size))
    processing_h, processing_w = int(_full_processing_shape[1]), int(_full_processing_shape[2])
    result_shape = (int(slice_count), int(processing_h), int(processing_w))

    source_mm: Optional[np.memmap] = None
    result_mask: Optional[np.ndarray] = None
    result_conf: Optional[np.ndarray] = None
    result_mask_full: Optional[np.memmap] = None
    result_conf_full: Optional[np.memmap] = None
    source: Optional[object] = None
    deferred_result: Optional[_DeferredGpuWorkerTaskResult] = None

    def _open_cpu_render_source() -> Tuple[np.memmap, object]:
        if native_resize is not None:
            _wait_for_cube_ready_sentinel(
                str(native_resize['sentinel']),
                request_path=(str(native_resize['request']) if native_resize.get('request') else None),
                failed_path=(str(native_resize['failed']) if native_resize.get('failed') else None),
            )
        mm = open_existing_gray_memmap(
            task['source_volume_path'], task['source_shape'], task.get('source_dtype', 'uint8'), mode='r',
        )
        try:
            cpu_source = StreamingYoloVolumeSource(
                _worker_render_callable(mm, view, job, kind, slice_offset=slice_offset),
                num_frames=num_frames,
                name=f"worker-{kind}-{view.name}-{task['job_id']}",
                batch_size=max(1, int(cfg.batch)),
                out_size=out_size,
                render_workers=max(1, int(task.get('render_workers', 1))),
                prefetch_frames=max(1, int(task.get('prefetch_frames', 1))),
                autostart=True,
                shared_executor=None,
            )
        except BaseException:
            close_memmap_array(mm)
            raise
        return mm, cpu_source

    try:
        if str(task.get('result_mode', 'file')) == 'direct_union':
            # v13.3.1 (R4): single-angle tasks accumulate straight into the shared per-view
            # union memmap, which the scheduler created zeroed BEFORE enqueueing tasks. Slice
            # windows are disjoint per task, and same-host page-cache coherence makes the writes
            # visible to the main process without msync. 'r+' is required — 'w+' would truncate
            # the shared file under the other workers.
            union_shape = (
                int(task.get('union_num_slices', slice_count)), int(processing_h), int(processing_w),
            )
            result_mask_full = np.memmap(
                Path(str(task['result_mask_path'])), dtype=np.uint8, mode='r+', shape=union_shape,
            )
            result_mask = result_mask_full[slice_offset:slice_offset + slice_count]
            if task.get('result_conf_path'):
                result_conf_full = np.memmap(
                    Path(str(task['result_conf_path'])), dtype=np.uint8, mode='r+', shape=union_shape,
                )
                result_conf = result_conf_full[slice_offset:slice_offset + slice_count]
        else:
            # v13.2.5 (speed #6): mode 'w+' truncates and re-extends the file, so fresh result
            # memmaps are already zero-filled — the old explicit [:] = 0 dirtied ~GBs of pages
            # per chunk for nothing.
            result_mask = np.memmap(Path(str(task['result_mask_path'])), dtype=np.uint8, mode='w+', shape=result_shape)
            if task.get('result_conf_path'):
                result_conf = np.memmap(Path(str(task['result_conf_path'])), dtype=np.uint8, mode='w+', shape=result_shape)

        # v13.3.0 (R1/R21): render full-frame sources on this worker's GPU when possible —
        # resident mode feeds device tensors straight to the predictor; streaming mode still
        # GPU-prerenders radial tasks into a host slab. Any engine failure falls back to the
        # unchanged CPU render path for this task.
        gpu_engine = _worker_gpu_render_engine()
        # v13.3.8 (E1): when main enqueued before the host cube finished, the task carries
        # the native decoded volume + a cube-ready sentinel for every file-backed fallback.
        native_resize = task.get('native_resize') if isinstance(task.get('native_resize'), dict) else None
        if gpu_engine is not None and str(kind) == 'fullframe':
            try:
                if native_resize is not None:
                    # Residency straight from the (smaller, hotter) native volume with the
                    # t-resize on device — no wait on the host cube at all.
                    render_mode = gpu_engine.ensure_volume(
                        str(native_resize['path']),
                        tuple(int(x) for x in native_resize['shape']),
                        str(native_resize.get('dtype', 'uint8')),
                        resize_to_t=int(task['source_shape'][0]),
                    )
                    if render_mode != 'resident':
                        _wait_for_cube_ready_sentinel(
                            str(native_resize['sentinel']),
                            request_path=(str(native_resize['request']) if native_resize.get('request') else None),
                            failed_path=(str(native_resize['failed']) if native_resize.get('failed') else None),
                        )
                        render_mode = gpu_engine.ensure_volume(
                            str(task['source_volume_path']),
                            tuple(int(x) for x in task['source_shape']),
                            str(task.get('source_dtype', 'uint8')),
                        )
                else:
                    render_mode = gpu_engine.ensure_volume(
                        str(task['source_volume_path']),
                        tuple(int(x) for x in task['source_shape']),
                        str(task.get('source_dtype', 'uint8')),
                    )
                if render_mode == 'resident':
                    source = GpuRenderedYoloSource(
                        gpu_engine,
                        view,
                        job,
                        slice_offset=slice_offset,
                        num_frames=num_frames,
                        batch_size=max(1, int(cfg.batch)),
                        out_size=out_size,
                        half=bool(cfg.half),
                        name=f"gpu-render-{kind}-{view.name}-{task['job_id']}",
                    )
                elif str(getattr(view, 'family', '')) == 'radial':
                    slab = gpu_engine.prerender_radial_slab(view, slice_offset, num_frames)
                    source = StreamingYoloVolumeSource(
                        _slab_frame_renderer(slab),
                        num_frames=num_frames,
                        name=f"worker-radialslab-{view.name}-{task['job_id']}",
                        batch_size=max(1, int(cfg.batch)),
                        out_size=out_size,
                        render_workers=2,
                        prefetch_frames=max(1, int(task.get('prefetch_frames', 1))),
                        autostart=True,
                        shared_executor=None,
                    )
            except Exception as exc:
                print(
                    f"Warning: GPU render path failed for {view.name}/{task['job_id']} ({exc}); "
                    'using the CPU render path for this task.'
                )
                source = None

        if source is None:
            source_mm, source = _open_cpu_render_source()

        def _predict(active_source: object) -> Dict[str, object]:
            return predict_source_and_accumulate(
                model,
                active_source,
                source_label=f"{view.name}-{task['job_id']}",
                num_frames=num_frames,
                out_size=out_size,
                cfg=cfg,
                view_union_mm=result_mask,
                view_confmap_mm=result_conf,
                M_out_to_native=np.asarray(
                    task.get(
                        'M_out_to_processing',
                        output_to_view_processing_affine(
                            view, np.asarray(task['M_out_to_src'], dtype=np.float32), int(out_size),
                        ),
                    ),
                    dtype=np.float32,
                ),
                native_h=int(processing_h),
                native_w=int(processing_w),
                postprocess_workers=int(task.get('postprocess_workers', 1)),
                streaming_cleanup_enabled=bool(task.get('streaming_cleanup_enabled', False)),
                streaming_cleanup_min_conf=float(task.get('streaming_cleanup_min_conf', 0.0)),
                streaming_cleanup_min_radius=float(task.get('streaming_cleanup_min_radius', 0.0)),
                slice_locks=None,
                device_hole_fill=bool(task.get('device_hole_fill', False)),
                defer_device_union_flush=bool(gpu_union_flush_overlap_enabled()),
            )

        retry_with_cpu_render = False
        try:
            stats = _predict(source)
        except _ResidentTensorRTRingFatalError:
            # Teardown could not prove the borrowed TensorRT backend safe. Retrying with a
            # CPU renderer would still reuse that same backend/context in this worker.
            raise
        except Exception as exc:
            if not isinstance(source, GpuRenderedYoloSource):
                raise
            # GpuRenderedYoloSource renders lazily in __next__, so construction-time fallback
            # cannot catch a late gather-plan failure/OOM. This task owns a disjoint output-z
            # window; clear any partial monotonic accumulation and retry from the completed cube.
            print(
                f"Warning: lazy GPU render failed for {view.name}/{task['job_id']} ({exc}); "
                'restarting this task with the completed-cube CPU renderer.'
            )
            try:
                source.close()
            except Exception:
                pass
            source = None
            if gpu_engine is not None:
                gpu_engine.disable_resident_after_runtime_failure()
            if result_mask is not None:
                result_mask[...] = np.uint8(0)
            if result_conf is not None:
                result_conf[...] = np.uint8(0)
            retry_with_cpu_render = True

        if retry_with_cpu_render:
            # Run outside the except suite: Python clears the active exception/traceback here,
            # releasing failed-batch GPU tensors before CPU-rendered inference starts again.
            gc.collect()
            if gpu_engine is not None:
                try:
                    gpu_engine.torch.cuda.empty_cache()
                except Exception:
                    pass
            source_mm, source = _open_cpu_render_source()
            stats = _predict(source)
        # v13.2.5 (speed #6): no msync here — the main process reopens the result file on the
        # same host, where page-cache coherence makes the data visible without a blocking
        # multi-GiB writeback per task (msync was crash-durability only).
        public_stats: Dict[str, object] = {
            'prediction_count': int(stats.get('prediction_count', 0)),
            'frames_with_predictions': int(stats.get('frames_with_predictions', 0)),
            'device_hole_filled_frames': int(stats.get('device_hole_filled_frames', 0)),
            # v13.3.6 (D1): per-slice foreground metadata (or None) rides the result queue.
            'slice_meta': stats.get('slice_meta'),
        }
        flush_future = stats.get('_device_union_flush_future')
        if isinstance(flush_future, Future):
            # Keep the result mappings alive until the copy thread has finished its final
            # np.copyto. The main worker may now start the next task with a fresh device
            # accumulator; `_gpu_inference_worker_main` publishes these stats only after
            # `finish()` succeeds.
            deferred_result = _DeferredGpuWorkerTaskResult(
                stats=public_stats,
                flush_future=flush_future,
                memmaps=(result_mask, result_conf, result_mask_full, result_conf_full),
            )
            result_mask = None
            result_conf = None
            result_mask_full = None
            result_conf_full = None
            return deferred_result
        return public_stats
    finally:
        # Always release the source render threads first, then close every memmap, even when
        # predict_source_and_accumulate raised, so a persistent worker never leaks fds/mmaps.
        if source is not None:
            try:
                source.close()
            except Exception:
                pass
        for _mm in (result_mask, result_conf, result_mask_full, result_conf_full, source_mm):
            if _mm is not None:
                try:
                    close_memmap_array(_mm)
                except Exception:
                    pass


def _pin_cuda_visible_device_token(logical_index: int) -> str:
    """Resolve a torch logical CUDA index to the CUDA_VISIBLE_DEVICES token that pins it.

    torch's cuda:N indexes into the CUDA_VISIBLE_DEVICES list inherited from the
    environment (SLURM commonly exports e.g. '2,3' for an allocation). Overwriting the
    variable with the raw logical index would escape the allocation onto foreign
    physical GPUs on nodes without cgroup device isolation (v13.2.2 bug #13); index
    into the inherited list instead. Tokens pass through verbatim so GPU UUIDs and MIG
    ids keep working. Without an inherited list, logical == physical and the raw index
    is correct.
    """
    idx = int(logical_index)
    raw = os.environ.get('CUDA_VISIBLE_DEVICES')
    if raw is None:
        return str(idx)
    tokens = [tok.strip() for tok in str(raw).split(',') if tok.strip()]
    if idx < 0 or idx >= len(tokens):
        raise RuntimeError(
            f'--device cuda:{idx} is out of range for inherited CUDA_VISIBLE_DEVICES={raw!r} '
            f'({len(tokens)} visible device(s))'
        )
    return tokens[idx]


def _gpu_inference_worker_main(
    gpu_index: int,
    model_path: str,
    init_dict: Dict[str, object],
    task_queue: object,
    result_queue: object,
) -> None:
    """Persistent GPU worker process: pin to one physical GPU, load the model once, serve tasks."""
    global _GPU_WORKER_NUMA_PIN, _GPU_WORKER_NUMA_FULL
    try:
        # Pin the process to its physical GPU before any CUDA context is created, so the model and
        # all tensors live on that device and never contend with the other workers' GPUs. The
        # logical --device index is remapped through the inherited CUDA_VISIBLE_DEVICES list
        # (v13.2.2 bug #13).
        os.environ['CUDA_VISIBLE_DEVICES'] = _pin_cuda_visible_device_token(int(gpu_index))
        # v13.3.5 (N1): pin every thread of this worker to its GPU's NUMA node BEFORE any
        # CUDA/model work, so allocator arenas, pinned staging and TRT host scratch land
        # node-local. The parent computed the plan (None = stay unpinned).
        _numa_pin_cpus = init_dict.get('numa_affinity_cpus', None)
        if _numa_pin_cpus and hasattr(os, 'sched_getaffinity'):
            try:
                _GPU_WORKER_NUMA_FULL = {int(c) for c in os.sched_getaffinity(0)}
                if _sched_setaffinity_all_threads([int(c) for c in _numa_pin_cpus]):  # type: ignore[union-attr]
                    _GPU_WORKER_NUMA_PIN = {int(c) for c in _numa_pin_cpus}  # type: ignore[union-attr]
                    print(f'[numa] gpu-worker {int(gpu_index)}: pinned to {len(_GPU_WORKER_NUMA_PIN)} cpu(s)')
            except Exception as _numa_exc:
                _GPU_WORKER_NUMA_PIN = None
                print(f'Warning: [numa] gpu-worker {int(gpu_index)}: pinning failed ({_numa_exc}); running unpinned.')
        try:
            cv2.setNumThreads(max(1, int(init_dict.get('cv2_threads', 1))))
        except Exception:
            pass
        set_retina_mask_processor(str(init_dict.get('retina_processor', 'cpu')))
        # v13.1.0 (#2.3): propagate the single-angle GPU fast-path (min_conf, min_radius) into this
        # worker process (globals do not cross the spawn boundary). None disables the fast path.
        _fastpath_min_conf = init_dict.get('single_angle_gpu_fastpath_min_conf', None)
        _fastpath_min_radius = init_dict.get('single_angle_gpu_fastpath_min_radius', 0.0)
        set_single_angle_gpu_fastpath(
            None if _fastpath_min_conf is None else float(_fastpath_min_conf),
            float(_fastpath_min_radius or 0.0),
        )
        cfg = PredictConfig(
            imgsz=int(init_dict['imgsz']),
            conf=float(init_dict['conf']),
            device='cuda:0',
            half=bool(init_dict['half']),
            int8=bool(init_dict['int8']),
            batch=max(1, int(init_dict['batch'])),
        )
        model = load_ultralytics_model(str(model_path), task='segment')
        ensure_yolo_ready_for_predict(model, cfg)
        try:
            ensure_single_channel_yolo_preprocess_patch()
        except Exception:
            pass
        if cpu_retina_masks_enabled():
            try:
                ensure_cpu_retina_mask_predictor_patch()
            except Exception:
                pass
        else:
            # v13.3.0 (R9): GPU retina mode — reduce per-frame unions at proto resolution.
            try:
                ensure_gpu_retina_proto_union_predictor_patch()
            except Exception:
                pass
        # v13.3.0 (R1/R21): per-worker GPU render engine (volume residency resolves lazily on
        # the first task, once the shared source volume exists and VRAM headroom is known).
        try:
            _init_worker_gpu_render_engine('cuda:0')
        except Exception as _render_engine_exc:
            print(f'Warning: GPU render engine init failed ({_render_engine_exc}); worker uses CPU rendering.')
        result_queue.put({'type': 'ready', 'gpu_index': int(gpu_index), 'pid': int(os.getpid())})
    except Exception as exc:  # pragma: no cover - worker init failure surfaced to main
        import traceback
        try:
            result_queue.put({'type': 'fatal', 'gpu_index': int(gpu_index), 'error': repr(exc), 'traceback': traceback.format_exc()})
        except Exception:
            pass
        return

    publication_queue: 'queue.Queue[Optional[Tuple[int, _DeferredGpuWorkerTaskResult]]]' = queue.Queue(maxsize=1)
    retirement_gate = threading.Semaphore(1)
    overlap_announced = False

    def _publish_deferred(item: Tuple[int, _DeferredGpuWorkerTaskResult]) -> None:
        finished_task_id, deferred = item
        try:
            finished_stats = deferred.finish()
            result_queue.put({
                'type': 'result', 'task_id': int(finished_task_id),
                'gpu_index': int(gpu_index), 'ok': True, 'stats': finished_stats,
            })
        except Exception as exc:  # pragma: no cover - surfaced to scheduler
            import traceback
            result_queue.put({
                'type': 'result', 'task_id': int(finished_task_id),
                'gpu_index': int(gpu_index), 'ok': False,
                'error': repr(exc), 'traceback': traceback.format_exc(),
            })

    def _publisher_main() -> None:
        while True:
            item = publication_queue.get()
            try:
                if item is None:
                    return
                try:
                    _publish_deferred(item)
                except BaseException as exc:
                    # A closed/broken result transport must not kill the publisher while
                    # leaving queue.join() permanently blocked during worker teardown.
                    print(f'Warning: GPU retirement publication transport failed ({exc}).')
            finally:
                if item is not None:
                    retirement_gate.release()
                publication_queue.task_done()

    publication_thread = threading.Thread(
        target=_publisher_main,
        name=f'gpu-{int(gpu_index)}-retirement-publisher',
        daemon=True,
    )
    publication_thread.start()

    try:
      while True:
        task = task_queue.get()
        if task is None:
            break
        task_id = int(task['task_id'])
        if str(task.get('task_type', 'inference')) == 'interpolation_pass':
            # Auxiliary work is submitted only after inference drains. Defensively wait
            # for the prompt publisher before widening affinity or reusing CUDA state.
            publication_queue.join()
            # v13.3.4 (T4): after the inference queue drains, this warm worker process doubles
            # as an interpolation host — same memmap-path protocol as the dedicated
            # interpolation process pool, one pass at a time per worker.
            # v13.3.5 (N1): the pass's planner pools are sized for the whole allocation, so
            # widen every thread back to the full cpuset for the pass, then re-pin. (Inference
            # has drained by the time aux tasks arrive, so the wide window contends with
            # nothing GPU-side.)
            _numa_widened = False
            if _GPU_WORKER_NUMA_PIN is not None and _GPU_WORKER_NUMA_FULL:
                _numa_widened = _sched_setaffinity_all_threads(sorted(_GPU_WORKER_NUMA_FULL))
            try:
                aux_stats = _interpolation_process_entry(**dict(task['aux_kwargs']))  # type: ignore[arg-type]
                result_queue.put({
                    'type': 'aux_result', 'task_id': task_id, 'gpu_index': int(gpu_index),
                    'ok': True, 'stats': dict(aux_stats),
                })
            except Exception as exc:  # pragma: no cover - surfaced to the waiting submitter
                import traceback
                result_queue.put({
                    'type': 'aux_result', 'task_id': task_id, 'gpu_index': int(gpu_index), 'ok': False,
                    'error': repr(exc), 'traceback': traceback.format_exc(),
                })
            finally:
                if _numa_widened and _GPU_WORKER_NUMA_PIN is not None:
                    _sched_setaffinity_all_threads(sorted(_GPU_WORKER_NUMA_PIN))
            continue
        try:
            # The parent affinity plan can be uneven across NUMA nodes. Size this worker's
            # pools from its own whole-core allocation instead of a logical-CPU global average.
            task_local = dict(task)
            local_cpu_workers = max(1, int(init_dict.get('cpu_workers', task.get('postprocess_workers', 1))))
            task_local['render_workers'] = max(
                1, min(local_cpu_workers, int(task.get('slice_count', 1))),
            )
            task_local['postprocess_workers'] = int(local_cpu_workers)
            completed = run_prediction_volume_in_worker(model, cfg, task_local)
            if isinstance(completed, _DeferredGpuWorkerTaskResult):
                # C11: publication is tied to the D2H future itself, not to completion of
                # the next inference task. The gate admits one retiring accumulator per
                # worker; a slow retirement blocks only the handoff of the next completed
                # task and cannot grow an unbounded queue of live device/host mappings.
                retirement_gate.acquire()
                publication_queue.put((int(task_id), completed))
                if not overlap_announced:
                    overlap_announced = True
                    print(
                        'GPU union prompt retirement active (v13.3.18 C11): one retiring '
                        'device accumulator publishes immediately when its D2H future settles; '
                        'YOLO_TTA_GPU_UNION_FLUSH_OVERLAP=0 restores synchronous flushes.'
                    )
            else:
                result_queue.put({
                    'type': 'result', 'task_id': task_id, 'gpu_index': int(gpu_index),
                    'ok': True, 'stats': completed,
                })
        except _ResidentTensorRTRingFatalError as exc:  # pragma: no cover - unsafe TRT state
            # A failed post/infer-stream drain or binding-address restore means this process's
            # TensorRT contexts can no longer be reused safely.  Surface a worker-fatal result
            # and exit instead of dequeuing another view on the compromised backend.
            import traceback
            result_queue.put({
                'type': 'fatal', 'task_id': task_id, 'gpu_index': int(gpu_index),
                'error': repr(exc), 'traceback': traceback.format_exc(),
            })
            return
        except Exception as exc:  # pragma: no cover - per-task failure surfaced to main
            import traceback
            result_queue.put({
                'type': 'result', 'task_id': task_id, 'gpu_index': int(gpu_index), 'ok': False,
                'error': repr(exc), 'traceback': traceback.format_exc(),
            })
    finally:
        publication_queue.join()
        publication_queue.put(None)
        publication_thread.join()
        _shutdown_resident_trt_pipeline_cache()
        _shutdown_gpu_union_flush_executor()


# --------------------------
# 3D assembly + postprocessing
# --------------------------


if _numba is not None:
    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_union_find_batch_kernel(
        parent: np.ndarray,   # int64, mutated in place
        rank: np.ndarray,     # int32, mutated in place
        touches: np.ndarray,  # bool, mutated in place
        a_ids: np.ndarray,    # int64
        b_ids: np.ndarray,    # int64
    ) -> None:
        # Identical algorithm to _UnionFind.find/union (path halving + union by rank), applied
        # to a whole batch of pairs in one nogil call.
        for i in range(a_ids.shape[0]):
            ra = a_ids[i]
            while parent[ra] != ra:
                parent[ra] = parent[parent[ra]]
                ra = parent[ra]
            rb = b_ids[i]
            while parent[rb] != rb:
                parent[rb] = parent[parent[rb]]
                rb = parent[rb]
            if ra == rb:
                continue
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if touches[rb]:
                touches[ra] = True
            if rank[ra] == rank[rb]:
                rank[ra] += 1
else:
    _numba_union_find_batch_kernel = None


_NUMBA_UNION_FIND_KERNEL_RUNTIME_DISABLED = False


class _UnionFind:
    """Dynamic union-find for slice-streamed 3D connected-components.

    v13.3.4 (T2): numpy-array-backed (was python lists). Batched pair merges run through one
    numba nogil kernel call per batch (``union_pair_codes``; python loop fallback preserves
    the exact algorithm), and ``root_map`` resolves every id by vectorized pointer jumping
    instead of a per-id python find loop. Same union-by-rank + path-halving as before, so
    root representatives are identical for the same union order.
    """

    def __init__(self) -> None:
        cap = 1024
        self.parent = np.arange(cap, dtype=np.int64)
        self.rank = np.zeros(cap, dtype=np.int32)
        self.touches_boundary = np.zeros(cap, dtype=bool)
        self._size = 1

    def _ensure_capacity(self, need: int) -> None:
        cap = int(self.parent.shape[0])
        if int(need) <= cap:
            return
        new_cap = max(int(need), cap * 2)
        new_parent = np.arange(new_cap, dtype=np.int64)
        new_parent[:cap] = self.parent
        new_rank = np.zeros(new_cap, dtype=np.int32)
        new_rank[:cap] = self.rank
        new_touches = np.zeros(new_cap, dtype=bool)
        new_touches[:cap] = self.touches_boundary
        self.parent = new_parent
        self.rank = new_rank
        self.touches_boundary = new_touches

    def new_ids(self, count: int) -> np.ndarray:
        if count <= 0:
            return np.zeros((0,), dtype=np.uint32)
        start = int(self._size)
        stop = start + int(count)
        if stop >= 2 ** 32:
            raise RuntimeError('3D component id space exceeded uint32 capacity')
        self._ensure_capacity(stop)
        # parent[start:stop] is already arange-initialized (construction/growth), rank/touches zero.
        self._size = stop
        return np.arange(start, stop, dtype=np.uint32)

    def find(self, x: int) -> int:
        parent = self.parent
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return int(x)

    def union(self, a: int, b: int) -> int:
        ra = self.find(int(a))
        rb = self.find(int(b))
        if ra == rb:
            return ra

        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra

        self.parent[rb] = ra
        self.touches_boundary[ra] = bool(self.touches_boundary[ra] or self.touches_boundary[rb])
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        return int(ra)

    def union_pair_codes(self, codes: np.ndarray) -> None:
        """Merge a batch of uint64 pair codes ((a << 32) | b) in one call."""
        global _NUMBA_UNION_FIND_KERNEL_RUNTIME_DISABLED
        codes_arr = np.asarray(codes, dtype=np.uint64)
        if codes_arr.size <= 0:
            return
        a_ids = (codes_arr >> np.uint64(32)).astype(np.int64, copy=False)
        b_ids = (codes_arr & np.uint64(0xFFFFFFFF)).astype(np.int64, copy=False)
        if (
            _numba_union_find_batch_kernel is not None
            and compiled_interpolation_kernels_enabled()
            and not _NUMBA_UNION_FIND_KERNEL_RUNTIME_DISABLED
        ):
            try:
                _numba_union_find_batch_kernel(
                    self.parent, self.rank, self.touches_boundary,
                    np.ascontiguousarray(a_ids), np.ascontiguousarray(b_ids),
                )
                return
            except Exception as exc:
                _NUMBA_UNION_FIND_KERNEL_RUNTIME_DISABLED = True
                print(f'Warning: numba union-find batch kernel failed ({exc}); using the python loop.')
        for i in range(int(a_ids.shape[0])):
            self.union(int(a_ids[i]), int(b_ids[i]))

    def mark_boundary(self, x: int) -> None:
        self.touches_boundary[self.find(int(x))] = True

    def root_map(self) -> np.ndarray:
        # v13.3.4 (T2): vectorized pointer jumping — every id follows its parent chain in
        # O(log depth) whole-array passes (depth is tiny thanks to path halving during unions).
        n = int(self._size)
        p = self.parent[:n].copy()
        while True:
            pp = p[p]
            if np.array_equal(pp, p):
                break
            p = pp
        out = p.astype(np.uint32, copy=False)
        out[0] = np.uint32(0)
        return np.ascontiguousarray(out)


def _adjacent_xy_offsets_for_3d_connectivity(connectivity: int) -> Tuple[Tuple[int, int], ...]:
    """Return XY offsets that connect components across adjacent z-slices.

    Connectivity is interpreted in the standard cubic-neighborhood sense:
      - 6-connected: only face adjacency across z, so the same (y, x) position
      - 18-connected: face/edge adjacency, so same position plus cardinal XY offsets
      - 26-connected: face/edge/corner adjacency, so the full 3x3 XY neighborhood
    """
    connectivity_i = int(connectivity)
    if connectivity_i == 6:
        return ((0, 0),)
    if connectivity_i == 18:
        return tuple((dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1) if abs(dy) + abs(dx) <= 1)
    if connectivity_i == 26:
        return tuple((dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1))
    raise ValueError('3D connectivity must be one of 6, 18, or 26')


def _slice_connectivity_for_3d_connectivity(connectivity: int) -> int:
    connectivity_i = int(connectivity)
    if connectivity_i == 6:
        return 4
    if connectivity_i in (18, 26):
        return 8
    raise ValueError('3D connectivity must be one of 6, 18, or 26')


def _adjacent_gid_pair_codes(
    prev_gid: np.ndarray,
    curr_gid: np.ndarray,
    xy_offsets: Optional[Sequence[Tuple[int, int]]] = None,
    prev_offset: int = 0,
    curr_offset: int = 0,
) -> np.ndarray:
    """Return unique touching component-id pairs encoded as uint64 values.

    The upper 32 bits contain the previous-slice gid and the lower 32 bits contain the
    current-slice gid. ``prev_offset`` and ``curr_offset`` allow callers to pass per-slice
    local labels and encode global provisional ids without first rewriting the whole volume.
    Pair extraction is independent for each adjacent slice pair, so callers can run this
    function concurrently and then apply union-find merges serially.
    """
    h, w = prev_gid.shape
    offsets = tuple(xy_offsets) if xy_offsets is not None else _adjacent_xy_offsets_for_3d_connectivity(26)
    code_parts: List[np.ndarray] = []

    for dy, dx in offsets:
        dy_i = int(dy)
        dx_i = int(dx)
        py0 = max(0, -dy_i)
        py1 = min(h, h - dy_i)
        cy0 = max(0, dy_i)
        cy1 = min(h, h + dy_i)
        px0 = max(0, -dx_i)
        px1 = min(w, w - dx_i)
        cx0 = max(0, dx_i)
        cx1 = min(w, w + dx_i)

        if py0 >= py1 or px0 >= px1 or cy0 >= cy1 or cx0 >= cx1:
            continue

        a = prev_gid[py0:py1, px0:px1]
        b = curr_gid[cy0:cy1, cx0:cx1]
        overlap = (a > 0) & (b > 0)
        if not np.any(overlap):
            continue

        a_vals = a[overlap].astype(np.uint64, copy=False)
        b_vals = b[overlap].astype(np.uint64, copy=False)
        if int(prev_offset) != 0:
            a_vals = a_vals + np.uint64(int(prev_offset))
        if int(curr_offset) != 0:
            b_vals = b_vals + np.uint64(int(curr_offset))
        codes = (a_vals << np.uint64(32)) | b_vals
        if codes.size > 0:
            code_parts.append(np.unique(codes))

    if not code_parts:
        return np.zeros((0,), dtype=np.uint64)
    if len(code_parts) == 1:
        return np.asarray(code_parts[0], dtype=np.uint64)
    return np.unique(np.concatenate(code_parts).astype(np.uint64, copy=False))


def _iter_adjacent_gid_pairs(
    prev_gid: np.ndarray,
    curr_gid: np.ndarray,
    xy_offsets: Optional[Sequence[Tuple[int, int]]] = None,
) -> Iterator[Tuple[int, int]]:
    """Yield unique touching component-id pairs across adjacent z-slices.

    ``xy_offsets`` controls the 3D connectivity across adjacent slices. When omitted, the
    existing 26-connected behavior is used for foreground interpolation labeling.
    """
    for code in _adjacent_gid_pair_codes(prev_gid, curr_gid, xy_offsets):
        code_i = int(code)
        yield (code_i >> 32), (code_i & 0xFFFFFFFF)


def _mark_boundary_components_from_local_labels(
    uf: _UnionFind,
    local_to_gid: np.ndarray,
    labels2d: np.ndarray,
    z: int,
    z_max: int,
) -> None:
    if labels2d.size == 0 or local_to_gid.size <= 1:
        return

    if z == 0 or z == z_max:
        for gid in local_to_gid[1:]:
            uf.mark_boundary(int(gid))

    border_vals = np.unique(np.concatenate([
        labels2d[0, :],
        labels2d[-1, :],
        labels2d[:, 0],
        labels2d[:, -1],
    ]))
    border_vals = border_vals[border_vals > 0]
    for local_lbl in border_vals.tolist():
        uf.mark_boundary(int(local_to_gid[int(local_lbl)]))


def fill_3d_voids_inplace_streaming(
    mask_mm: np.ndarray,
    work_prefix: Path,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    connectivity: int = 6,
) -> None:
    """Fill enclosed 3D voids by labeling background connected components once.

    v12.2.0 allows 3D void fill only as an optional final global-union step. This
    function performs that operation by labeling the background volume, marking any
    background component connected to the volume boundary, and converting all other
    background components to foreground. The default 6-connected background matches
    the usual enclosed-void interpretation used by binary hole filling; set
    ``YOLO_TTA_VOIDFILL_CONNECTIVITY`` or pass ``connectivity`` explicitly to use 18
    or 26 connectivity.

      - prefers anonymous RAM/swap-backed arrays for the 3D background-ID workspace
      - falls back to a disk-backed memmap only when the estimated working set would be too large
      - avoids tmpfs-backed bulk scratch files that could previously SIGBUS when /dev/shm filled
    """
    env_conn = os.environ.get('YOLO_TTA_VOIDFILL_CONNECTIVITY', '').strip()
    if env_conn:
        try:
            connectivity = int(env_conn)
        except Exception:
            pass
    connectivity = int(connectivity)
    if connectivity not in (6, 18, 26):
        raise ValueError('3D void fill connectivity must be one of 6, 18, or 26')

    z_dim, h, w = mask_mm.shape
    if z_dim <= 0:
        return

    slice_connectivity = _slice_connectivity_for_3d_connectivity(connectivity)
    adjacent_offsets = _adjacent_xy_offsets_for_3d_connectivity(connectivity)

    estimated_bytes = estimate_voidfill_workspace_bytes((z_dim, h, w))
    use_in_memory = bool(prefer_memory) and should_use_in_memory_workspace(estimated_bytes, reserve_bytes=reserve_bytes)
    budget = workspace_budget_summary(estimated_bytes, reserve_bytes=reserve_bytes)
    if use_in_memory:
        print(f"3D void fill workspace: in-memory ({budget}, background connectivity={connectivity})")
        bg_gid_store: np.ndarray = np.zeros((z_dim, h, w), dtype=np.uint32)
        bg_gid_path: Optional[Path] = None
    else:
        print(f"3D void fill workspace: disk-backed ({budget}, background connectivity={connectivity}) -> {work_prefix.parent}")
        bg_gid_path = work_prefix.with_suffix('.bg_gid.u32.dat')
        bg_gid_path.parent.mkdir(parents=True, exist_ok=True)
        bg_gid_store = np.memmap(bg_gid_path, dtype=np.uint32, mode='w+', shape=(z_dim, h, w))
    numa_interleave_memory(bg_gid_store, desc='3D void fill gid store')  # v13.3.5 (N2)

    uf = _UnionFind()
    prev_gid_slice: Optional[np.ndarray] = None

    for z in tqdm(range(z_dim), desc='3D void fill: slice labeling'):
        bg = (np.asarray(mask_mm[z]) == 0).astype(np.uint8, copy=False)
        num_labels, labels2d = cv2.connectedComponents(bg, connectivity=slice_connectivity, ltype=cv2.CV_32S)
        if int(num_labels) <= 1:
            bg_gid_store[z, :, :] = 0
            prev_gid_slice = None
            continue

        local_to_gid = np.zeros((int(num_labels),), dtype=np.uint32)
        local_to_gid[1:] = uf.new_ids(int(num_labels) - 1)
        gid_slice = local_to_gid[labels2d]
        bg_gid_store[z, :, :] = gid_slice

        _mark_boundary_components_from_local_labels(uf, local_to_gid, labels2d, z=z, z_max=z_dim - 1)

        if prev_gid_slice is not None and np.any(prev_gid_slice) and np.any(gid_slice):
            uf.union_pair_codes(_adjacent_gid_pair_codes(prev_gid_slice, gid_slice, adjacent_offsets))

        prev_gid_slice = np.asarray(gid_slice)

    root_map = uf.root_map()
    touches_by_gid = np.zeros(root_map.shape, dtype=bool)
    for gid in range(1, root_map.shape[0]):
        touches_by_gid[gid] = bool(uf.touches_boundary[int(root_map[gid])])

    for z in tqdm(range(z_dim), desc='3D void fill: apply enclosed components'):
        gid_slice = np.asarray(bg_gid_store[z])
        enclosed = (gid_slice > 0) & (~touches_by_gid[gid_slice])
        if np.any(enclosed):
            mask_mm[z, enclosed] = np.uint8(1)

    flush_array(mask_mm)
    flush_array(bg_gid_store)
    del bg_gid_store
    if bg_gid_path is not None and not keep_temp:
        try:
            bg_gid_path.unlink(missing_ok=True)
        except Exception:
            pass


# v13.3.2 (R6b/R6c): no-GIL LUT-apply kernels. Both walk only each slice's recorded foreground
# bbox and read the slice's LUT window from one concatenated table (slice z's local id v maps
# through lut_flat[lut_offsets[z] + v]).
if _numba is not None:
    @_numba.njit(cache=True, nogil=True, parallel=True)  # type: ignore[misc]
    def _numba_compact_relabel_kernel(labels, lut_flat, lut_offsets, bboxes, counts):  # pragma: no cover - jit
        z_dim = labels.shape[0]
        for z in _numba.prange(z_dim):
            if counts[z] == 0:
                continue
            off = lut_offsets[z]
            y0 = bboxes[z, 0]
            y1 = bboxes[z, 1]
            x0 = bboxes[z, 2]
            x1 = bboxes[z, 3]
            for y in range(y0, y1):
                row = labels[z, y]
                for x in range(x0, x1):
                    v = row[x]
                    if v != 0:
                        row[x] = lut_flat[off + v]

    @_numba.njit(cache=True, nogil=True, parallel=True)  # type: ignore[misc]
    def _numba_keep_lut_apply_kernel(labels, keep_flat, lut_offsets, bboxes, apply_slice, mask_out):  # pragma: no cover - jit
        z_dim = labels.shape[0]
        for z in _numba.prange(z_dim):
            if apply_slice[z] == 0:
                continue
            off = lut_offsets[z]
            y0 = bboxes[z, 0]
            y1 = bboxes[z, 1]
            x0 = bboxes[z, 2]
            x1 = bboxes[z, 3]
            for y in range(y0, y1):
                lrow = labels[z, y]
                mrow = mask_out[z, y]
                for x in range(x0, x1):
                    mrow[x] = keep_flat[off + lrow[x]]

    @_numba.njit(cache=True, nogil=True, parallel=True)  # type: ignore[misc]
    def _numba_sparse_keep_lut_apply_kernel(  # pragma: no cover - jit
        labels_flat, label_offsets, keep_flat, lut_offsets, bboxes, apply_slice, mask_out,
    ):
        """C4 keep-largest apply directly from the packed per-slice label arena."""
        z_dim = apply_slice.shape[0]
        for z in _numba.prange(z_dim):
            if apply_slice[z] == 0:
                continue
            keep_off = lut_offsets[z]
            label_off = label_offsets[z]
            y0 = bboxes[z, 0]
            y1 = bboxes[z, 1]
            x0 = bboxes[z, 2]
            x1 = bboxes[z, 3]
            crop_w = x1 - x0
            for y in range(y0, y1):
                row_off = label_off + (y - y0) * crop_w
                mrow = mask_out[z, y]
                for x in range(x0, x1):
                    mrow[x] = keep_flat[keep_off + labels_flat[row_off + x - x0]]
else:
    _numba_compact_relabel_kernel = None
    _numba_keep_lut_apply_kernel = None
    _numba_sparse_keep_lut_apply_kernel = None


@dataclass(frozen=True)
class SliceLocalLabelLUTs:
    """v13.3.6 (A1): per-slice local-id -> canonical-compact-id lookup tables.

    Exported by label_foreground_volume_streaming when the compact relabel pass is
    skipped: slice z's local label v canonicalizes through
    ``lut_flat[lut_offsets[z] + v]``. Consumers (component tables, projection-candidate
    kernels) resolve ids through these tables instead of the full-volume relabel
    rewriting the full-volume compact/global-id store.
    """

    lut_flat: np.ndarray       # uint32, concatenated per-slice tables (index 0 of each = 0)
    lut_offsets: np.ndarray    # int64, one entry per slice
    component_counts: np.ndarray  # uint32, per-slice 2D component counts

    def lut_for(self, z: int) -> np.ndarray:
        lo = int(self.lut_offsets[int(z)])
        return self.lut_flat[lo:lo + int(self.component_counts[int(z)]) + 1]


def interpolation_sparse_labels_enabled() -> bool:
    """v13.3.17 (C4): retain only each slice's local-label bbox crop.

    The dense uint16 local-id raster was 22.7--37.1 GiB for the prioritized
    views even though every consumer already knew the per-slice foreground
    bbox. Sparse labels are default-on whenever compact relabel is skipped;
    YOLO_TTA_INTERPOLATION_SPARSE_LABELS=0 restores the dense store.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_SPARSE_LABELS', True)


class SparseSliceLabelStore:
    """Ragged per-slice local-label arena with dense-window compatibility.

    Stage A writes one tight crop per slice. finalize packs those crops into
    one contiguous typed arena plus offsets/bboxes, so compiled candidate search
    can address a global (z,y,x) without a dense volume. Compatibility reads
    materialize only the requested window; a full plane is produced only for a
    legacy fallback, not the normal component-table/planner path.
    """

    def __init__(self, shape: Sequence[int], dtype: np.dtype | str | type) -> None:
        self.shape = tuple(int(v) for v in shape)
        if len(self.shape) != 3:
            raise ValueError(f'SparseSliceLabelStore expects 3D shape, got {self.shape}')
        self.dtype = np.dtype(dtype)
        self.ndim = 3
        self._pending: Optional[List[Optional[Tuple[int, int, int, int, np.ndarray]]]] = [
            None
        ] * int(self.shape[0])
        self.bboxes = np.zeros((int(self.shape[0]), 4), dtype=np.int64)
        self.offsets = np.zeros((int(self.shape[0]) + 1,), dtype=np.int64)
        self.flat = np.empty((0,), dtype=self.dtype)
        self._finalized = False

    @property
    def nbytes(self) -> int:
        return int(self.flat.nbytes) if self._finalized else int(sum(
            0 if item is None else int(item[4].nbytes)
            for item in (self._pending or [])
        ))

    def write_crop(
        self,
        z: int,
        y0: int,
        y1: int,
        x0: int,
        x1: int,
        values: np.ndarray,
    ) -> None:
        if self._finalized:
            raise RuntimeError('SparseSliceLabelStore is finalized')
        z_i = int(z)
        y0_i, y1_i, x0_i, x1_i = int(y0), int(y1), int(x0), int(x1)
        h, w = int(self.shape[1]), int(self.shape[2])
        if not (0 <= z_i < int(self.shape[0])):
            raise IndexError(z_i)
        if y1_i <= y0_i or x1_i <= x0_i:
            self.clear_slice(z_i)
            return
        if not (0 <= y0_i < y1_i <= h and 0 <= x0_i < x1_i <= w):
            raise ValueError(
                f'sparse label crop {(y0_i, y1_i, x0_i, x1_i)} outside {(h, w)}'
            )
        crop = np.ascontiguousarray(values, dtype=self.dtype)
        if tuple(int(v) for v in crop.shape) != (y1_i - y0_i, x1_i - x0_i):
            raise ValueError(
                f'sparse label crop data {tuple(crop.shape)} != '
                f'{(y1_i - y0_i, x1_i - x0_i)}'
            )
        assert self._pending is not None
        self._pending[z_i] = (y0_i, y1_i, x0_i, x1_i, crop)
        self.bboxes[z_i] = np.asarray((y0_i, y1_i, x0_i, x1_i), dtype=np.int64)

    def clear_slice(self, z: int) -> None:
        if self._finalized:
            raise RuntimeError('SparseSliceLabelStore is finalized')
        z_i = int(z)
        assert self._pending is not None
        self._pending[z_i] = None
        self.bboxes[z_i] = np.int64(0)

    def finalize(self) -> None:
        if self._finalized:
            return
        pending = self._pending or []
        sizes = np.zeros((int(self.shape[0]),), dtype=np.int64)
        for z, item in enumerate(pending):
            if item is not None:
                sizes[int(z)] = np.int64(item[4].size)
        if sizes.size:
            self.offsets[1:] = np.cumsum(sizes, dtype=np.int64)
        self.flat = np.empty((int(self.offsets[-1]),), dtype=self.dtype)
        for z, item in enumerate(pending):
            if item is None:
                continue
            lo, hi = int(self.offsets[int(z)]), int(self.offsets[int(z) + 1])
            self.flat[lo:hi] = item[4].reshape(-1)
        self._pending = None
        self._finalized = True

    def crop_with_origin(self, z: int) -> Tuple[int, int, np.ndarray]:
        if not self._finalized:
            self.finalize()
        z_i = int(z)
        y0, y1, x0, x1 = (int(v) for v in self.bboxes[z_i])
        if y1 <= y0 or x1 <= x0:
            return 0, 0, np.empty((0, 0), dtype=self.dtype)
        lo, hi = int(self.offsets[z_i]), int(self.offsets[z_i + 1])
        return y0, x0, self.flat[lo:hi].reshape((y1 - y0, x1 - x0))

    def read_window(self, z: int, y0: int, y1: int, x0: int, x1: int) -> np.ndarray:
        y0_i, y1_i, x0_i, x1_i = int(y0), int(y1), int(x0), int(x1)
        out = np.zeros(
            (max(0, y1_i - y0_i), max(0, x1_i - x0_i)), dtype=self.dtype,
        )
        if out.size <= 0:
            return out
        cy0, cx0, crop = self.crop_with_origin(int(z))
        if crop.size <= 0:
            return out
        cy1, cx1 = cy0 + int(crop.shape[0]), cx0 + int(crop.shape[1])
        iy0, iy1 = max(y0_i, cy0), min(y1_i, cy1)
        ix0, ix1 = max(x0_i, cx0), min(x1_i, cx1)
        if iy0 < iy1 and ix0 < ix1:
            out[iy0 - y0_i:iy1 - y0_i, ix0 - x0_i:ix1 - x0_i] = crop[
                iy0 - cy0:iy1 - cy0, ix0 - cx0:ix1 - cx0
            ]
        return out

    def _normalize_plane_key(self, selector: object, length: int) -> Tuple[int, int]:
        if isinstance(selector, slice):
            start, stop, step = selector.indices(int(length))
            if int(step) != 1:
                raise IndexError('SparseSliceLabelStore only supports unit-stride windows')
            return int(start), int(stop)
        idx = int(selector)  # type: ignore[arg-type]
        if idx < 0:
            idx += int(length)
        if idx < 0 or idx >= int(length):
            raise IndexError(idx)
        return int(idx), int(idx) + 1

    def __getitem__(self, key: object) -> object:
        z_dim, h, w = self.shape
        if isinstance(key, tuple):
            if len(key) != 3:
                raise IndexError('SparseSliceLabelStore expects (z,y,x)')
            z_sel, y_sel, x_sel = key
            if isinstance(z_sel, (int, np.integer)):
                z_i = int(z_sel)
                if z_i < 0:
                    z_i += int(z_dim)
                y0, y1 = self._normalize_plane_key(y_sel, int(h))
                x0, x1 = self._normalize_plane_key(x_sel, int(w))
                window = self.read_window(z_i, y0, y1, x0, x1)
                if not isinstance(y_sel, slice):
                    window = window[0]
                if not isinstance(x_sel, slice):
                    window = window[..., 0]
                return window
            z0, z1 = self._normalize_plane_key(z_sel, int(z_dim))
            y0, y1 = self._normalize_plane_key(y_sel, int(h))
            x0, x1 = self._normalize_plane_key(x_sel, int(w))
            return np.stack(
                [self.read_window(z, y0, y1, x0, x1) for z in range(z0, z1)],
                axis=0,
            )
        if isinstance(key, (int, np.integer)):
            return self.read_window(int(key), 0, int(h), 0, int(w))
        z0, z1 = self._normalize_plane_key(key, int(z_dim))
        return np.stack(
            [self.read_window(z, 0, int(h), 0, int(w)) for z in range(z0, z1)],
            axis=0,
        )

    def __setitem__(self, key: object, value: object) -> None:
        # Used only by the GPU failure reset. Normal writers call write_crop.
        if isinstance(key, tuple) and len(key) == 3 and isinstance(key[0], (int, np.integer)):
            z_i = int(key[0])
            if np.isscalar(value) and int(value) == 0:
                self.clear_slice(z_i)
                return
        raise TypeError('SparseSliceLabelStore writes must use write_crop')

    def __array__(self, dtype: Optional[np.dtype] = None, copy: Optional[bool] = None) -> np.ndarray:
        dense = np.stack(
            [self.read_window(z, 0, int(self.shape[1]), 0, int(self.shape[2]))
             for z in range(int(self.shape[0]))],
            axis=0,
        )
        if dtype is not None:
            dense = dense.astype(dtype, copy=False)
        if copy:
            dense = dense.copy()
        return dense


def interpolation_skip_compact_relabel_enabled() -> bool:
    """v13.3.6 (A1): interpolation consumes per-slice local ids through LUTs by default.

    The compact relabel was a full read+write pass over the label store whose only product
    was canonical ids in the raster; component tables and
    the candidate kernels now canonicalize at read time. Set
    YOLO_TTA_INTERPOLATION_SKIP_COMPACT_RELABEL=0 to restore the relabel pass.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_SKIP_COMPACT_RELABEL', True)


def interpolation_local_label_uint16_enabled() -> bool:
    """v13.3.9 (D5): use uint16 for stores that contain only slice-local ids.

    Compact relabeling still requires uint32 because canonical/global component ids
    can exceed 65535.  Set YOLO_TTA_INTERPOLATION_LOCAL_LABEL_UINT16=0 to restore
    the previous uint32 local-label store.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_LOCAL_LABEL_UINT16', True)


def _local_label_store_dtype(compact_relabel: bool) -> np.dtype:
    if not bool(compact_relabel) and interpolation_local_label_uint16_enabled():
        return np.dtype(np.uint16)
    return np.dtype(np.uint32)


class _LocalLabelCapacityError(RuntimeError):
    """D5's deliberate pre-narrowing stop; never reinterpret it as a GPU failure."""


def _check_local_label_store_capacity(count: int, dtype: np.dtype, *, z: int) -> None:
    if np.dtype(dtype) == np.dtype(np.uint16) and int(count) > int(np.iinfo(np.uint16).max):
        raise _LocalLabelCapacityError(
            f'Interpolation slice {int(z)} has {int(count)} local components, exceeding the '
            'uint16 local-label capacity (65535). Set '
            'YOLO_TTA_INTERPOLATION_LOCAL_LABEL_UINT16=0 and rerun.'
        )


def gpu_slice_labeling_enabled() -> bool:
    """v13.3.6 (D3): run per-slice 2D component labeling on the GPU where CUDA is available."""
    return _env_flag('YOLO_TTA_GPU_SLICE_LABELING', True)


def gpu_slice_labeling_in_children_enabled() -> bool:
    """v13.3.6 (D3): allow GPU labeling inside dedicated interpolation child processes.

    Off by default: each child would have to create its own CUDA context (init latency +
    VRAM per child, times up to 6 children) just for labeling. The aux GPU-worker
    interpolation hosts (v13.3.4 T4) already own a warm context and take the GPU path
    automatically; the main process (keep_objects) does too.
    """
    return _env_flag('YOLO_TTA_GPU_SLICE_LABELING_IN_CHILDREN', False)


def gpu_slice_labeling_pairs_enabled() -> bool:
    """v13.3.14 (D6): emit adjacent-slice local-id pair codes while labels are on CUDA."""
    return _env_flag('YOLO_TTA_GPU_SLICE_LABELING_PAIRS', True)


_GPU_SLICE_LABELING_CONFIGURED_DEVICES: Optional[Tuple[int, ...]] = None


def configure_gpu_slice_labeling_devices(devices: Sequence[str]) -> None:
    """Remember the CUDA subset selected by ``--device`` for main-process D7 work.

    CUDA worker processes are pinned to one visible device before importing/initializing
    torch, so their logical device count remains authoritative.  This hint is primarily for
    the unpinned parent, where every SLURM-visible GPU may otherwise be discoverable even when
    the command selected a smaller subset.
    """
    configured: List[int] = []
    for device in devices:
        token = str(device).strip().lower()
        if not token.startswith('cuda:'):
            continue
        try:
            idx = int(token.split(':', 1)[1])
        except Exception:
            continue
        if idx >= 0 and idx not in configured:
            configured.append(idx)
    global _GPU_SLICE_LABELING_CONFIGURED_DEVICES
    _GPU_SLICE_LABELING_CONFIGURED_DEVICES = tuple(configured) if configured else None


@dataclass
class _GpuSliceLabelBlockResult:
    z0: int
    z1: int
    device_index: int
    first_plane: Optional[object]
    last_plane: Optional[object]
    internal_pair_codes: Dict[int, np.ndarray]


def _gpu_adjacent_local_pair_codes_device(
    cp: object,
    prev_local: object,
    curr_local: object,
    prev_bbox: Sequence[int],
    curr_bbox: Sequence[int],
    h: int,
    w: int,
) -> object:
    """D6 device equivalent of ``_adjacent_gid_pair_codes`` for local ids.

    The same one-pixel-expanded bbox-intersection window and the same nine XY shifts are
    used as the CPU stage-C path.  Local ids are packed into uint64 (previous in the high
    word, current in the low word); global slice offsets are deliberately applied only after
    all blocks finish and the complete component-count prefix sum is known.
    """
    py0, py1, px0, px1 = (int(v) for v in prev_bbox)
    cy0, cy1, cx0, cx1 = (int(v) for v in curr_bbox)
    ry0 = max(0, max(py0, cy0) - 1)
    ry1 = min(int(h), min(py1, cy1) + 1)
    rx0 = max(0, max(px0, cx0) - 1)
    rx1 = min(int(w), min(px1, cx1) + 1)
    if ry0 >= ry1 or rx0 >= rx1:
        return cp.empty((0,), dtype=cp.uint64)

    prev_crop = prev_local[ry0:ry1, rx0:rx1]
    curr_crop = curr_local[ry0:ry1, rx0:rx1]
    ch = int(ry1 - ry0)
    cw = int(rx1 - rx0)
    code_parts: List[object] = []
    for dy, dx in _adjacent_xy_offsets_for_3d_connectivity(26):
        dy_i = int(dy)
        dx_i = int(dx)
        py0_i = max(0, -dy_i)
        py1_i = min(ch, ch - dy_i)
        cy0_i = max(0, dy_i)
        cy1_i = min(ch, ch + dy_i)
        px0_i = max(0, -dx_i)
        px1_i = min(cw, cw - dx_i)
        cx0_i = max(0, dx_i)
        cx1_i = min(cw, cw + dx_i)
        if py0_i >= py1_i or px0_i >= px1_i:
            continue
        a = prev_crop[py0_i:py1_i, px0_i:px1_i]
        b = curr_crop[cy0_i:cy1_i, cx0_i:cx1_i]
        overlap = (a > 0) & (b > 0)
        a_vals = a[overlap].astype(cp.uint64, copy=False)
        b_vals = b[overlap].astype(cp.uint64, copy=False)
        code_parts.append((a_vals << cp.uint64(32)) | b_vals)
    if not code_parts:
        return cp.empty((0,), dtype=cp.uint64)
    # Exactly one unique reduction per adjacent slice pair.  The caller concatenates every
    # pair result in the block for one small D2H transfer rather than one transfer per z.
    return cp.unique(cp.concatenate(code_parts))


_GPU_SLICE_LABELING_ANNOUNCED = False


def _try_label_slices_stage_a_gpu(
    mask_mm: np.ndarray,
    labels_store: object,
    component_counts: np.ndarray,
    slice_bboxes: np.ndarray,
    slice_areas: Optional[List[Optional[np.ndarray]]],
    known_slice_any: Optional[np.ndarray] = None,
) -> Tuple[bool, Optional[List[Optional[np.ndarray]]]]:
    """D3/D6/D7 GPU drop-in for per-slice labeling and adjacent-pair extraction.

    One cupy ``label`` call per z-block with a z-DISCONNECTED structure (full 3x3 in-plane
    neighbourhood, nothing across z — the same trick as the S2 device hole fill) labels
    every slice of the block independently and 8-connected in one kernel pass. Component
    slice/area/bbox stats come from torch scatter reductions over the block's foreground
    coordinates, components are renumbered to per-slice-contiguous LOCAL ids (the CPU cv2
    stage's contract: ids 1..k per slice, order arbitrary), and the relabeled block is
    written back into the selected local-label store restricted to each slice's bbox.
    v13.3.9 (D5) makes that store uint16 on the default no-compact-relabel path;
    the device-to-host relabel result remains int32 and is narrowed during the
    bbox-restricted host copy.

    v13.3.14 D7 assigns independent blocks round-robin to a bounded one-lane-per-device
    thread pool. D6 extracts local-id adjacency codes before each relabeled device block is
    released, including block boundaries from retained edge planes. Stage C applies global
    prefix offsets and feeds the unchanged union-find. The second return value contains one
    optional local-code array per z pair; ``None`` means stage C must use its CPU reader.
    ANY GPU failure re-zeroes the store and returns ``(False, None)`` for the complete CPU
    fallback.
    """
    if not gpu_slice_labeling_enabled():
        return False, None
    try:
        import torch  # type: ignore
        if not bool(torch.cuda.is_available()):
            return False, None
        if (
            _INTERPOLATION_PROCESS_WORKER
            and not gpu_slice_labeling_in_children_enabled()
            and not bool(torch.cuda.is_initialized())
        ):
            # Dedicated interpolation children refuse to CREATE a CUDA context just for
            # labeling (init latency + VRAM, times up to 6 children). The aux GPU-worker
            # hosts (v13.3.4 T4) enter through the same entry point but already own a live
            # context from inference — they proceed.
            return False, None
        cp_mod = _try_import_cupy_ndimage()
        if cp_mod is None:
            return False, None
        cp, cpx_ndi = cp_mod
    except Exception:
        return False, None

    z_dim, h, w = (int(x) for x in mask_mm.shape)
    if z_dim <= 0 or h < 2 or w < 2:
        return False, None

    # Filled once D7 admission succeeds.  Keeping this outside the guarded body lets
    # every exit path release cached allocations on *all* participating devices rather
    # than whichever CUDA device happens to be current in the coordinator thread.
    device_indices: List[int] = []

    def _free_admitted_device_pools() -> None:
        if device_indices:
            for cleanup_dev_idx in device_indices:
                try:
                    with cp.cuda.Device(int(cleanup_dev_idx)):
                        cp.get_default_memory_pool().free_all_blocks()
                except Exception:
                    pass
            return
        # No D7 device was admitted, so preserve the former best-effort cleanup for
        # failures that occur before the selected-device list is finalized.
        try:
            cp.get_default_memory_pool().free_all_blocks()
        except Exception:
            pass

    try:
        visible_count = max(0, int(torch.cuda.device_count()))
        if visible_count <= 0:
            return False, None
        configured = _GPU_SLICE_LABELING_CONFIGURED_DEVICES
        candidate_indices = [
            int(idx) for idx in (configured if configured is not None else tuple(range(visible_count)))
            if 0 <= int(idx) < int(visible_count)
        ]
        if not candidate_indices:
            candidate_indices = list(range(visible_count))

        requested_device_cap = max(
            1,
            _env_int('YOLO_TTA_GPU_SLICE_LABELING_DEVICES', len(candidate_indices)),
        )
        requested_device_cap = min(int(requested_device_cap), len(candidate_indices))
        plane = int(h) * int(w)
        # Adaptive z-block: u8 mask + int32 labels + int32 relabel + label() workspace,
        # ~17 B/voxel, plus ~1 GiB headroom for the coordinate transients.
        requested_block = max(4, _env_int('YOLO_TTA_GPU_SLICE_LABELING_BLOCK', 64))
        device_free: List[Tuple[int, int]] = []
        for dev_idx in candidate_indices:
            try:
                device = torch.device(f'cuda:{int(dev_idx)}')
                free_bytes, _total = torch.cuda.mem_get_info(device)
                device_free.append((int(dev_idx), int(free_bytes)))
            except Exception:
                continue
        if not device_free:
            return False, None
        if requested_device_cap == 1:
            # Preserve D3's least-contentious single-device behavior when explicitly forced.
            selected_free = [max(device_free, key=lambda item: int(item[1]))]
        else:
            # Use the freest configured devices, then restore logical-index order so block
            # assignment is stable and visibly round-robin in logs/profilers.
            selected_free = sorted(device_free, key=lambda item: int(item[1]), reverse=True)[:requested_device_cap]
            selected_free.sort(key=lambda item: int(item[0]))

        admitted: List[Tuple[int, int]] = []
        for dev_idx, free_bytes in selected_free:
            candidate_block = int(requested_block)
            while candidate_block > 4 and int(free_bytes) < candidate_block * plane * 17 + GIB:
                candidate_block = max(4, candidate_block // 2)
            if int(free_bytes) >= candidate_block * plane * 17 + GIB:
                admitted.append((int(dev_idx), int(candidate_block)))
        if not admitted:
            return False, None
        device_indices = [int(item[0]) for item in admitted]
        # Fixed block boundaries make round-robin dispatch and the retained-plane boundary
        # contract deterministic. Use the smallest admitted block across selected devices.
        block = min(int(item[1]) for item in admitted)
        block_specs = [
            (int(z0), min(int(z_dim), int(z0) + int(block)))
            for z0 in range(0, int(z_dim), int(block))
        ]
        device_indices = device_indices[:max(1, min(len(device_indices), len(block_specs)))]
        pairs_on_device = bool(gpu_slice_labeling_pairs_enabled())

        global _GPU_SLICE_LABELING_ANNOUNCED
        if not _GPU_SLICE_LABELING_ANNOUNCED:
            _GPU_SLICE_LABELING_ANNOUNCED = True
            print(
                f'GPU per-slice labeling active on '
                f'{", ".join(f"cuda:{idx}" for idx in device_indices)} '
                f'(v13.3.14 D3/D7, block={int(block)}, device-pairs={pairs_on_device}; '
                'YOLO_TTA_GPU_SLICE_LABELING=0 disables, '
                'YOLO_TTA_GPU_SLICE_LABELING_DEVICES=1 forces one device).'
            )

        empty_codes = lambda: np.zeros((0,), dtype=np.uint64)

        def _label_block(z0: int, z1: int, dev_idx: int) -> _GpuSliceLabelBlockResult:
            device = torch.device(f'cuda:{int(dev_idx)}')
            with torch.cuda.device(device), cp.cuda.Device(int(dev_idx)):
                structure = cp.zeros((3, 3, 3), dtype=cp.bool_)
                structure[1, :, :] = True  # in-plane 8-connectivity; z disconnected
                bs = int(z1 - z0)
                if known_slice_any is not None and not bool(np.any(known_slice_any[z0:z1])):
                    component_counts[z0:z1] = np.uint32(0)
                    internal = (
                        {int(z): empty_codes() for z in range(int(z0) + 1, int(z1))}
                        if pairs_on_device else {}
                    )
                    return _GpuSliceLabelBlockResult(
                        int(z0), int(z1), int(dev_idx), None, None, internal,
                    )
                host_block = np.ascontiguousarray(np.asarray(mask_mm[z0:z1]))
                mask_t = torch.from_numpy(host_block).to(device=device, non_blocking=False)
                fg_cp = cp.asarray(mask_t) > 0
                labels_cp, num = cpx_ndi.label(fg_cp, structure=structure)
                del fg_cp, mask_t, host_block
                num_i = int(num)
                if num_i <= 0:
                    component_counts[z0:z1] = np.uint32(0)
                    internal = (
                        {int(z): empty_codes() for z in range(int(z0) + 1, int(z1))}
                        if pairs_on_device else {}
                    )
                    return _GpuSliceLabelBlockResult(
                        int(z0), int(z1), int(dev_idx), None, None, internal,
                    )
                try:
                    labels_t = torch.from_dlpack(labels_cp)
                except Exception:
                    labels_t = torch.utils.dlpack.from_dlpack(labels_cp.toDlpack())
                flat = labels_t.reshape(-1)
                nz = flat.nonzero().squeeze(1)
                vals = flat.index_select(0, nz).to(torch.int64)
                zz = torch.div(nz, plane, rounding_mode='floor')
                rem = nz - zz * plane
                yy = torch.div(rem, int(w), rounding_mode='floor')
                xx = rem - yy * int(w)
                big = torch.iinfo(torch.int64).max
                comp_area = torch.bincount(vals, minlength=num_i + 1)
                comp_z = torch.full((num_i + 1,), big, dtype=torch.int64, device=device)
                comp_z.scatter_reduce_(0, vals, zz, reduce='amin', include_self=True)
                comp_y0 = torch.full((num_i + 1,), big, dtype=torch.int64, device=device)
                comp_y0.scatter_reduce_(0, vals, yy, reduce='amin', include_self=True)
                comp_y1 = torch.full((num_i + 1,), -1, dtype=torch.int64, device=device)
                comp_y1.scatter_reduce_(0, vals, yy, reduce='amax', include_self=True)
                comp_x0 = torch.full((num_i + 1,), big, dtype=torch.int64, device=device)
                comp_x0.scatter_reduce_(0, vals, xx, reduce='amin', include_self=True)
                comp_x1 = torch.full((num_i + 1,), -1, dtype=torch.int64, device=device)
                comp_x1.scatter_reduce_(0, vals, xx, reduce='amax', include_self=True)
                del nz, vals, zz, rem, yy, xx
                # Per-slice-contiguous local ids: rank components within their slice after a
                # stable (slice, component-id) ordering.
                comp_ids = torch.arange(1, num_i + 1, device=device, dtype=torch.int64)
                order = torch.argsort(comp_z[1:] * (num_i + 2) + comp_ids)
                sorted_z = comp_z[1:].index_select(0, order)
                counts_t = torch.bincount(sorted_z, minlength=bs)
                starts = torch.zeros((bs,), dtype=torch.int64, device=device)
                if bs > 1:
                    starts[1:] = torch.cumsum(counts_t, dim=0)[:-1]
                local_rank = torch.arange(num_i, device=device, dtype=torch.int64) - starts.index_select(0, sorted_z)
                lut = torch.zeros((num_i + 1,), dtype=torch.int32, device=device)
                lut.index_copy_(0, order + 1, (local_rank + 1).to(torch.int32))
                # Relabel in cupy (int32 fancy indexing avoids a full int64 index copy).
                relabeled_cp = cp.take(cp.asarray(lut), labels_cp)
                del labels_cp, labels_t, flat, lut

                counts_np = counts_t.cpu().numpy()
                starts_np = starts.cpu().numpy()
                y0s = comp_y0[1:].index_select(0, order).cpu().numpy()
                y1s = comp_y1[1:].index_select(0, order).cpu().numpy()
                x0s = comp_x0[1:].index_select(0, order).cpu().numpy()
                x1s = comp_x1[1:].index_select(0, order).cpu().numpy()
                areas_sorted = comp_area[1:].index_select(0, order).cpu().numpy()
                del comp_area, comp_z, comp_y0, comp_y1, comp_x0, comp_x1, order, sorted_z, counts_t, starts, local_rank, comp_ids

                store_dtype = np.dtype(labels_store.dtype)
                block_bboxes = np.zeros((int(bs), 4), dtype=np.int64)
                for zi in range(bs):
                    z = int(z0 + zi)
                    k = int(counts_np[zi])
                    _check_local_label_store_capacity(k, store_dtype, z=z)
                    component_counts[z] = np.uint32(k)
                    if k <= 0:
                        continue
                    seg0 = int(starts_np[zi])
                    seg1 = seg0 + k
                    by0 = int(y0s[seg0:seg1].min())
                    by1 = int(y1s[seg0:seg1].max()) + 1
                    bx0 = int(x0s[seg0:seg1].min())
                    bx1 = int(x1s[seg0:seg1].max()) + 1
                    block_bboxes[zi, :] = (by0, by1, bx0, bx1)
                    slice_bboxes[z, 0] = by0
                    slice_bboxes[z, 1] = by1
                    slice_bboxes[z, 2] = bx0
                    slice_bboxes[z, 3] = bx1
                    if slice_areas is not None:
                        slice_areas[z] = areas_sorted[seg0:seg1].astype(np.int64, copy=True)

                internal_pair_codes: Dict[int, np.ndarray] = {}
                if pairs_on_device:
                    pair_device_arrays: List[object] = []
                    pair_zs: List[int] = []
                    for zi in range(1, int(bs)):
                        z = int(z0 + zi)
                        pair_zs.append(z)
                        if int(counts_np[zi - 1]) <= 0 or int(counts_np[zi]) <= 0:
                            pair_device_arrays.append(cp.empty((0,), dtype=cp.uint64))
                        else:
                            pair_device_arrays.append(_gpu_adjacent_local_pair_codes_device(
                                cp,
                                relabeled_cp[zi - 1],
                                relabeled_cp[zi],
                                block_bboxes[zi - 1],
                                block_bboxes[zi],
                                int(h),
                                int(w),
                            ))
                    pair_lengths = [int(arr.size) for arr in pair_device_arrays]
                    pair_total = int(sum(pair_lengths))
                    if pair_total > 0:
                        pair_flat = cp.asnumpy(cp.concatenate(pair_device_arrays))
                    else:
                        pair_flat = empty_codes()
                    cursor = 0
                    for z, length in zip(pair_zs, pair_lengths):
                        internal_pair_codes[int(z)] = np.ascontiguousarray(
                            pair_flat[cursor:cursor + int(length)], dtype=np.uint64,
                        )
                        cursor += int(length)

                # Retain only the two block-edge planes on their owning device. Internal
                # pairs have already consumed the full block; these small references let
                # the coordinator form the one cross-block pair without rereading labels.
                first_plane = (
                    relabeled_cp[0].copy()
                    if pairs_on_device and int(counts_np[0]) > 0 else None
                )
                last_plane = (
                    relabeled_cp[-1].copy()
                    if pairs_on_device and int(counts_np[-1]) > 0 else None
                )
                # Existing D3 transfer: labels must remain in the local-id store for later
                # component-table/SDF consumers. Pair codes above add only one tiny D2H block.
                # v13.3.17 C4 packs the tight device crops (already narrowed to the store
                # dtype) and transfers them once. The normal sparse path therefore never
                # creates the former dense int32 host block (~1 GiB at 64x2048^2).
                if isinstance(labels_store, SparseSliceLabelStore):
                    crop_specs: List[Tuple[int, int, int, int, int, int]] = []
                    crop_device_parts: List[object] = []
                    for zi in range(bs):
                        z = int(z0 + zi)
                        if int(counts_np[zi]) <= 0:
                            continue
                        by0, by1, bx0, bx1 = (int(v) for v in block_bboxes[zi])
                        size = int((by1 - by0) * (bx1 - bx0))
                        crop_specs.append((z, by0, by1, bx0, bx1, size))
                        crop_device_parts.append(
                            relabeled_cp[zi, by0:by1, bx0:bx1]
                            .astype(cp.dtype(store_dtype), copy=False)
                            .reshape(-1)
                        )
                    if crop_device_parts:
                        packed_device = (
                            crop_device_parts[0]
                            if len(crop_device_parts) == 1
                            else cp.concatenate(crop_device_parts)
                        )
                        packed_host = cp.asnumpy(packed_device)
                        del packed_device
                    else:
                        packed_host = np.empty((0,), dtype=store_dtype)
                    del crop_device_parts, relabeled_cp
                    cursor = 0
                    for z, by0, by1, bx0, bx1, size in crop_specs:
                        labels_store.write_crop(
                            z, by0, by1, bx0, bx1,
                            packed_host[cursor:cursor + size].reshape(
                                (by1 - by0, bx1 - bx0),
                            ),
                        )
                        cursor += int(size)
                    del packed_host, crop_specs
                else:
                    relabeled_np = cp.asnumpy(relabeled_cp)
                    del relabeled_cp
                    for zi in range(bs):
                        z = int(z0 + zi)
                        if int(counts_np[zi]) <= 0:
                            continue
                        by0, by1, bx0, bx1 = (int(v) for v in block_bboxes[zi])
                        np.copyto(
                            np.asarray(labels_store[z, by0:by1, bx0:bx1]),
                            relabeled_np[zi, by0:by1, bx0:bx1].astype(
                                store_dtype, copy=False,
                            ),
                        )
                return _GpuSliceLabelBlockResult(
                    int(z0), int(z1), int(dev_idx), first_plane, last_plane,
                    internal_pair_codes,
                )

        precomputed_pairs: Optional[List[Optional[np.ndarray]]] = (
            [None] * int(z_dim) if pairs_on_device else None
        )
        # Keep no more than one block outstanding per GPU. Block i always returns to lane
        # i%N, so independent z blocks are genuinely round-robin without concurrent calls
        # fighting over one device's allocator/default stream.
        lane_count = max(1, len(device_indices))
        previous_result: Optional[_GpuSliceLabelBlockResult] = None
        with ThreadPoolExecutor(max_workers=lane_count, thread_name_prefix='slice-label-gpu') as executor:
            pending: Dict[int, Future] = {}
            for block_idx in range(min(lane_count, len(block_specs))):
                z0, z1 = block_specs[block_idx]
                dev_idx = device_indices[block_idx % lane_count]
                pending[block_idx] = executor.submit(_label_block, z0, z1, dev_idx)

            for block_idx in range(len(block_specs)):
                result = pending.pop(block_idx).result()
                if precomputed_pairs is not None:
                    for z, codes in result.internal_pair_codes.items():
                        precomputed_pairs[int(z)] = np.ascontiguousarray(codes, dtype=np.uint64)
                    if previous_result is not None:
                        boundary_z = int(result.z0)
                        if (
                            int(component_counts[boundary_z - 1]) <= 0
                            or int(component_counts[boundary_z]) <= 0
                        ):
                            boundary_codes = empty_codes()
                        else:
                            if previous_result.last_plane is None or result.first_plane is None:
                                raise RuntimeError(
                                    f'missing retained GPU label plane for block boundary z={boundary_z}'
                                )
                            # D6 boundary pair: use the retained previous-block device edge
                            # and current device edge, never re-read either label slice from
                            # the host store. Peer-copy the one previous plane when round-robin
                            # placed the blocks on different GPUs; only non-P2P systems use a
                            # retained-plane host bounce as the correctness fallback.
                            with (
                                torch.cuda.device(torch.device(f'cuda:{int(result.device_index)}')),
                                cp.cuda.Device(int(result.device_index)),
                            ):
                                curr_cp = result.first_plane
                                prev_cp = previous_result.last_plane
                                copied_prev = None
                                if int(previous_result.device_index) != int(result.device_index):
                                    try:
                                        if not bool(cp.cuda.runtime.deviceCanAccessPeer(
                                            int(result.device_index),
                                            int(previous_result.device_index),
                                        )):
                                            raise RuntimeError('CUDA peer access unavailable')
                                        copied_prev = cp.empty(
                                            tuple(int(v) for v in prev_cp.shape), dtype=prev_cp.dtype,
                                        )
                                        cp.cuda.runtime.memcpyPeerAsync(
                                            int(copied_prev.data.ptr),
                                            int(result.device_index),
                                            int(prev_cp.data.ptr),
                                            int(previous_result.device_index),
                                            int(prev_cp.nbytes),
                                            int(cp.cuda.get_current_stream().ptr),
                                        )
                                        prev_cp = copied_prev
                                    except Exception:
                                        with cp.cuda.Device(int(previous_result.device_index)):
                                            prev_host = cp.asnumpy(previous_result.last_plane)
                                        with cp.cuda.Device(int(result.device_index)):
                                            copied_prev = cp.asarray(prev_host)
                                        prev_cp = copied_prev
                                boundary_dev = _gpu_adjacent_local_pair_codes_device(
                                    cp,
                                    prev_cp,
                                    curr_cp,
                                    slice_bboxes[boundary_z - 1],
                                    slice_bboxes[boundary_z],
                                    int(h),
                                    int(w),
                                )
                                boundary_codes = np.ascontiguousarray(
                                    cp.asnumpy(boundary_dev), dtype=np.uint64,
                                )
                                del prev_cp, curr_cp, copied_prev, boundary_dev
                        precomputed_pairs[boundary_z] = boundary_codes
                previous_result = result

                next_idx = int(block_idx + lane_count)
                if next_idx < len(block_specs):
                    z0, z1 = block_specs[next_idx]
                    dev_idx = device_indices[next_idx % lane_count]
                    pending[next_idx] = executor.submit(_label_block, z0, z1, dev_idx)

        _free_admitted_device_pools()
        return True, precomputed_pairs
    except _LocalLabelCapacityError:
        # The result is data-dependent, not a GPU backend failure. Re-raise before the
        # generic fallback's full-store zero sweep and duplicate CPU labeling pass.
        _free_admitted_device_pools()
        raise
    except Exception as exc:
        print(f'Warning: GPU per-slice labeling failed ({exc}); falling back to the CPU labeling stage.')
        _free_admitted_device_pools()
        # Zero everything the GPU pass may have written so the CPU stage starts from a
        # clean store (the CPU fallback only rewrites each nonempty slice's bbox window).
        for z in range(0, int(z_dim)):
            try:
                labels_store[int(z), :, :] = 0
            except Exception:
                break
        try:
            component_counts[:] = np.uint32(0)
        except Exception:
            pass
        try:
            slice_bboxes[:] = np.int64(0)
        except Exception:
            pass
        if slice_areas is not None:
            for z in range(len(slice_areas)):
                slice_areas[z] = None
        return False, None


def label_foreground_volume_streaming(
    mask_mm: np.ndarray,
    work_prefix: Path,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    wrap_axis: bool = False,
    workers: int = 1,
    compact_relabel: bool = True,
    component_stats_out: Optional[Dict[str, object]] = None,
    known_slice_any: Optional[np.ndarray] = None,
    known_slice_bboxes: Optional[np.ndarray] = None,
    sparse_local_labels: bool = False,
) -> Tuple[object, int, List[Path]]:
    """Label a 3D foreground volume using parallel 2D slice labeling plus serial union-find.

      - the expensive per-slice 2D connected-component labeling runs concurrently across slices
      - local slice labels are promoted to global provisional ids with a parallel pass
      - adjacent-slice pair extraction can also run concurrently; only the final union-find merges
        remain serial to preserve deterministic 26-connected object identities
      - the compact relabel pass is slice-parallel (v13.3.2 R6b: bbox-restricted, and a single
        numba prange(nogil) kernel replaces the thread pool when numba is available)
      - when wrap_axis is true, the first and last slices are treated as adjacent. This is used
        for Radial view-native interpolation over the [0°, 180°) diameter-frame domain.

    v13.3.2 (R6c): ``compact_relabel=False`` leaves the label volume in per-slice LOCAL ids and
    skips the full-volume relabel write pass entirely; ``component_stats_out`` (a dict) then
    receives component_counts / slice_offsets / slice_bboxes / root_map / unique_roots /
    root_areas / total_components so callers (keep_objects) can apply decisions through
    per-slice local->root LUTs. Per-component areas are harvested during 2D labeling
    (cv2.connectedComponentsWithStats) only when stats are requested.

    v13.3.6 (A1): ``component_stats_out`` additionally receives 'slice_local_luts' (a
    SliceLocalLabelLUTs) — the same per-slice local->canonical-compact table the relabel
    pass would have applied — so interpolation consumes local ids directly.
    v13.3.6 (D1): ``known_slice_any``/``known_slice_bboxes`` (device-union metadata) let the
    labeling stage skip empty slices without reading them and crop CC calls + store writes
    to the known bboxes. v13.3.6 (D3): where CUDA is live in this process, stage A runs as
    one z-disconnected cupy label per z-block instead of per-slice cv2 calls.
    v13.3.17 (C4): ``sparse_local_labels`` stores only tight per-slice bbox crops in one
    packed arena. It is valid only for the local-id/no-compact-relabel path and avoids the
    prioritized interpolation passes' 22.7--37.1 GiB dense uint16 host raster.
    """
    z_dim, h, w = mask_mm.shape
    # v13.3.9 (D5): when compact relabel is skipped, this raster never holds
    # canonical/global ids — only per-slice local ids 1..k.  Halve the dominant
    # workspace with uint16 while retaining uint32 for the compact/global path.
    label_dtype = _local_label_store_dtype(bool(compact_relabel))
    estimated_bytes = estimate_voidfill_workspace_bytes((z_dim, h, w), dtype=label_dtype)
    use_in_memory = bool(prefer_memory) and should_use_in_memory_workspace(estimated_bytes, reserve_bytes=reserve_bytes)

    work_prefix.parent.mkdir(parents=True, exist_ok=True)
    provisional_path = work_prefix.with_suffix(
        '.fg_labels.u16.dat' if label_dtype == np.dtype(np.uint16) else '.fg_labels.u32.dat'
    )
    label_paths: List[Path] = []

    sparse_enabled = bool(
        sparse_local_labels
        and not bool(compact_relabel)
        and interpolation_sparse_labels_enabled()
    )
    if bool(sparse_local_labels) and bool(compact_relabel):
        raise ValueError('sparse_local_labels requires compact_relabel=False')

    budget = workspace_budget_summary(estimated_bytes, reserve_bytes=reserve_bytes)
    if sparse_enabled:
        logical_gib = array_nbytes((z_dim, h, w), label_dtype) / GIB
        print(
            f'Interpolation label workspace: sparse per-slice arena '
            f'(dense logical size {logical_gib:.1f} GiB, dtype={label_dtype.name})'
        )
        labels_store: object = SparseSliceLabelStore((z_dim, h, w), label_dtype)
    elif use_in_memory:
        print(f"Interpolation label workspace: in-memory ({budget}, dtype={label_dtype.name})")
        labels_store = np.zeros((z_dim, h, w), dtype=label_dtype)
    else:
        print(
            f"Interpolation label workspace: disk-backed ({budget}, dtype={label_dtype.name}) "
            f"-> {work_prefix.parent}"
        )
        labels_store = np.memmap(provisional_path, dtype=label_dtype, mode='w+', shape=(z_dim, h, w))
        label_paths = [provisional_path]
    if not sparse_enabled:
        numa_interleave_memory(labels_store, desc='Interpolation label store')  # v13.3.5 (N2)

    if int(z_dim) <= 0:
        flush_array(labels_store)
        return labels_store, 0, label_paths

    worker_count = choose_slice_parallel_workers(int(workers), int(z_dim))
    label_workers = choose_slice_parallel_workers(
        _env_int('YOLO_TTA_INTERPOLATION_LABEL_WORKERS', worker_count),
        int(z_dim),
    )
    compact_workers = choose_slice_parallel_workers(
        _env_int('YOLO_TTA_INTERPOLATION_COMPACT_WORKERS', worker_count),
        int(z_dim),
    )
    pair_workers = choose_slice_parallel_workers(
        _env_int('YOLO_TTA_INTERPOLATION_PAIR_WORKERS', worker_count),
        max(1, int(z_dim) - 1),
    )

    component_counts = np.zeros((int(z_dim),), dtype=np.uint32)
    # v13.2.5 (speed #11): per-slice foreground bboxes (y0, y1, x0, x1; exclusive stops) captured
    # during labeling so cross-slice pair extraction only reads the overlapping bbox windows.
    slice_bboxes = np.zeros((int(z_dim), 4), dtype=np.int64)
    collect_stats = component_stats_out is not None
    slice_areas: List[Optional[np.ndarray]] = [None] * int(z_dim) if collect_stats else []

    def _label_slice_local(z: int) -> None:
        z_i = int(z)
        # v13.3.6 (D1): device-union metadata skips empty slices without touching their
        # pages and restricts the CC call (and the store write) to the known bbox window.
        if known_slice_any is not None and not bool(known_slice_any[z_i]):
            component_counts[z_i] = np.uint32(0)
            return
        ky0 = kx0 = 0
        if known_slice_bboxes is not None:
            ky0, ky1, kx0, kx1 = (int(v) for v in known_slice_bboxes[z_i])
            if ky1 <= ky0 or kx1 <= kx0:
                component_counts[z_i] = np.uint32(0)
                return
            src = np.asarray(mask_mm[z_i, ky0:ky1, kx0:kx1])
        else:
            src = np.asarray(mask_mm[z_i])
        # v13.3.6 (A4): OpenCV treats ANY nonzero pixel as foreground, so the raw uint8
        # slice labels identically to the old (mask>0) cast — the full-slice compare+copy
        # per slice is deleted (contiguity copy only for bbox crops).
        fg = np.ascontiguousarray(src)
        if fg.size == 0 or not np.any(fg):
            component_counts[z_i] = np.uint32(0)
            return

        if collect_stats:
            # v13.3.2 (R6c): per-component areas (and the slice bbox) fall out of the stats —
            # this deletes the caller's full-volume bincount pass.
            num_labels, labels2d, cc_stats, _cents = cv2.connectedComponentsWithStats(
                fg, connectivity=8, ltype=cv2.CV_32S,
            )
            if int(num_labels) <= 1:
                component_counts[z_i] = np.uint32(0)
                return
            tops = cc_stats[1:, cv2.CC_STAT_TOP]
            lefts = cc_stats[1:, cv2.CC_STAT_LEFT]
            slice_bboxes[z_i, 0] = int(tops.min()) + ky0
            slice_bboxes[z_i, 1] = int((tops + cc_stats[1:, cv2.CC_STAT_HEIGHT]).max()) + ky0
            slice_bboxes[z_i, 2] = int(lefts.min()) + kx0
            slice_bboxes[z_i, 3] = int((lefts + cc_stats[1:, cv2.CC_STAT_WIDTH]).max()) + kx0
            slice_areas[z_i] = cc_stats[1:, cv2.CC_STAT_AREA].astype(np.int64, copy=True)
        else:
            num_labels, labels2d = _cv2_connected_components(fg, connectivity=8)
            if int(num_labels) <= 1:
                component_counts[z_i] = np.uint32(0)
                return

            rows_any = np.flatnonzero(fg.any(axis=1))
            cols_any = np.flatnonzero(fg.any(axis=0))
            slice_bboxes[z_i, 0] = int(rows_any[0]) + ky0
            slice_bboxes[z_i, 1] = int(rows_any[-1]) + 1 + ky0
            slice_bboxes[z_i, 2] = int(cols_any[0]) + kx0
            slice_bboxes[z_i, 3] = int(cols_any[-1]) + 1 + kx0
        local_count = int(num_labels) - 1
        _check_local_label_store_capacity(local_count, label_dtype, z=z_i)
        if sparse_enabled:
            by0, by1, bx0, bx1 = (int(v) for v in slice_bboxes[z_i])
            labels_store.write_crop(  # type: ignore[union-attr]
                z_i, by0, by1, bx0, bx1,
                np.asarray(
                    labels2d[
                        by0 - int(ky0):by1 - int(ky0),
                        bx0 - int(kx0):bx1 - int(kx0),
                    ],
                    dtype=label_dtype,
                ),
            )
        elif known_slice_bboxes is not None:
            labels_store[z_i, ky0:ky0 + int(labels2d.shape[0]), kx0:kx0 + int(labels2d.shape[1])] = (  # type: ignore[index]
                np.asarray(labels2d, dtype=label_dtype)
            )
        else:
            labels_store[z_i, :, :] = np.asarray(labels2d, dtype=label_dtype)  # type: ignore[index]
        component_counts[z_i] = np.uint32(local_count)

    # v13.3.6 (D3): one z-disconnected cupy label pass per block on the GPU replaces the
    # per-slice cv2 stage when CUDA is available in this process; CPU threads otherwise.
    gpu_stage_a_done, gpu_stage_a_pair_codes = _try_label_slices_stage_a_gpu(
        mask_mm,
        labels_store,
        component_counts,
        slice_bboxes,
        slice_areas if collect_stats else None,
        known_slice_any=known_slice_any,
    )
    if not gpu_stage_a_done:
        parallel_for_indices_chunked(
            int(z_dim),
            _label_slice_local,
            max_workers=label_workers,
            desc='Interpolation: 2D slice labeling',
            show_progress=True,
            target_chunks_per_worker=2,
        )

    if sparse_enabled:
        labels_store.finalize()  # type: ignore[union-attr]
        payload_gib = int(labels_store.nbytes) / GIB  # type: ignore[union-attr]
        logical_bytes = max(1, array_nbytes((z_dim, h, w), label_dtype))
        pct = 100.0 * float(int(labels_store.nbytes)) / float(logical_bytes)  # type: ignore[union-attr]
        print(
            f'Interpolation sparse labels: {payload_gib:.3f} GiB packed '
            f'({pct:.2f}% of dense local-id raster)'
        )

    total_components = int(np.sum(component_counts, dtype=np.uint64))
    if total_components <= 0:
        flush_array(labels_store)
        return labels_store, 0, label_paths
    if total_components >= 2 ** 32:
        raise RuntimeError('3D component id space exceeded uint32 capacity')

    # Slice z's provisional global id range is
    # [slice_offsets[z] + 1, slice_offsets[z] + component_counts[z]].  The label volume remains
    # in local per-slice ids until compact relabel so we avoid a full-volume promotion write pass.
    cumsum = np.cumsum(component_counts.astype(np.uint64, copy=False), dtype=np.uint64)
    slice_offsets = np.zeros((int(z_dim),), dtype=np.uint32)
    if int(z_dim) > 1:
        slice_offsets[1:] = cumsum[:-1].astype(np.uint32, copy=False)

    uf = _UnionFind()
    uf.new_ids(total_components)

    def _pair_codes_for_z(z: int) -> np.ndarray:
        if gpu_stage_a_pair_codes is not None:
            local_codes = gpu_stage_a_pair_codes[int(z)]
            if local_codes is not None:
                local_codes_u64 = np.asarray(local_codes, dtype=np.uint64)
                if local_codes_u64.size <= 0:
                    return np.zeros((0,), dtype=np.uint64)
                # D6 emitted local ids before the all-slice component prefix existed.
                # Promote both packed words now; no label-store page is touched.
                prev_ids = (local_codes_u64 >> np.uint64(32)) + np.uint64(
                    int(slice_offsets[int(z) - 1])
                )
                curr_ids = (local_codes_u64 & np.uint64(0xFFFFFFFF)) + np.uint64(
                    int(slice_offsets[int(z)])
                )
                return np.ascontiguousarray(
                    (prev_ids << np.uint64(32)) | curr_ids,
                    dtype=np.uint64,
                )
        # v13.2.5 (speed #11): the per-slice component counts already say whether a slice has any
        # foreground (no full-slice np.any scans), and the pair extraction is restricted to the
        # 1-pixel-expanded intersection of the two slices' foreground bboxes — every 26-connected
        # cross-slice pair lies inside that window, and cropping both slices to the SAME window
        # preserves the shift alignment _adjacent_gid_pair_codes relies on.
        if int(component_counts[int(z) - 1]) == 0 or int(component_counts[int(z)]) == 0:
            return np.zeros((0,), dtype=np.uint64)
        py0, py1, px0, px1 = (int(v) for v in slice_bboxes[int(z) - 1])
        cy0, cy1, cx0, cx1 = (int(v) for v in slice_bboxes[int(z)])
        ry0 = max(0, max(py0, cy0) - 1)
        ry1 = min(int(h), min(py1, cy1) + 1)
        rx0 = max(0, max(px0, cx0) - 1)
        rx1 = min(int(w), min(px1, cx1) + 1)
        if ry0 >= ry1 or rx0 >= rx1:
            return np.zeros((0,), dtype=np.uint64)
        prev_local_slice = np.asarray(labels_store[int(z) - 1, ry0:ry1, rx0:rx1])
        curr_local_slice = np.asarray(labels_store[int(z), ry0:ry1, rx0:rx1])
        return _adjacent_gid_pair_codes(
            prev_local_slice,
            curr_local_slice,
            prev_offset=int(slice_offsets[int(z) - 1]),
            curr_offset=int(slice_offsets[int(z)]),
        )

    if int(z_dim) > 1:
        # D6 arrays are already compact and host-resident; a large CPU read pool would add
        # scheduling overhead without any label-store I/O left to overlap.
        if pair_workers <= 1 or gpu_stage_a_pair_codes is not None:
            pair_iter: Iterable[np.ndarray] = (_pair_codes_for_z(int(z)) for z in range(1, int(z_dim)))
        else:
            pair_iter = parallel_map_in_order(
                _pair_codes_for_z,
                range(1, int(z_dim)),
                max_workers=pair_workers,
                max_pending=max(pair_workers, pair_workers * 2),
            )
        compiled_union_batching = bool(
            _numba_union_find_batch_kernel is not None
            and compiled_interpolation_kernels_enabled()
            and not _NUMBA_UNION_FIND_KERNEL_RUNTIME_DISABLED
        )
        if not compiled_union_batching:
            # The Python fallback loops over every pair inside union_pair_codes. Joining
            # adjacent arrays would add allocation/copy cost without reducing that work.
            for codes in tqdm(
                pair_iter,
                total=max(0, int(z_dim) - 1),
                desc='Interpolation: cross-slice unions',
            ):
                uf.union_pair_codes(np.asarray(codes, dtype=np.uint64))
        else:
            # C13: retain pair order but amortize the Python/Numba boundary across adjacent
            # slice pairs. The cap bounds the temporary (default 8 MiB of uint64 codes), and
            # oversized single-pair arrays are streamed through the same compiled kernel.
            union_code_cap = max(1, _env_int(
                'YOLO_TTA_TOPOLOGY_UNION_BATCH_CODES', 1_048_576,
            ))
            pending_codes: List[np.ndarray] = []
            pending_code_count = 0

            def _flush_topology_codes() -> None:
                nonlocal pending_code_count
                if pending_code_count <= 0:
                    return
                joined = (
                    pending_codes[0]
                    if len(pending_codes) == 1
                    else np.concatenate(pending_codes).astype(np.uint64, copy=False)
                )
                uf.union_pair_codes(np.ascontiguousarray(joined, dtype=np.uint64))
                pending_codes.clear()
                pending_code_count = 0

            for codes in tqdm(
                pair_iter,
                total=max(0, int(z_dim) - 1),
                desc='Interpolation: cross-slice unions',
            ):
                codes_u64 = np.asarray(codes, dtype=np.uint64)
                if codes_u64.size <= 0:
                    continue
                if (
                    int(pending_code_count) > 0
                    and int(pending_code_count) + int(codes_u64.size) > int(union_code_cap)
                ):
                    _flush_topology_codes()
                if int(codes_u64.size) >= int(union_code_cap):
                    for code0 in range(0, int(codes_u64.size), int(union_code_cap)):
                        uf.union_pair_codes(np.ascontiguousarray(
                            codes_u64[int(code0):int(code0) + int(union_code_cap)],
                            dtype=np.uint64,
                        ))
                else:
                    pending_codes.append(codes_u64)
                    pending_code_count += int(codes_u64.size)
            _flush_topology_codes()

    if bool(wrap_axis) and int(z_dim) > 1:
        if int(component_counts[0]) > 0 and int(component_counts[int(z_dim) - 1]) > 0:
            # v13.2.2 bug #2: the radial angular domain is [0°, 180°) over full-diameter
            # frames, so the plane that continues the last frame (one Δ short of 180°) is
            # frame 0 with the u axis REVERSED (u -> D-1-u) — exactly the reverse_u
            # relation the radial backprojection uses. Comparing at identical (t, u)
            # instead unioned mirror images through the rotation axis and missed the
            # true angular continuation.
            if isinstance(labels_store, SparseSliceLabelStore):
                ly0, ly1, lx0, lx1 = (
                    int(v) for v in slice_bboxes[int(z_dim) - 1]
                )
                fy0, fy1, fx0, fx1 = (int(v) for v in slice_bboxes[0])
                mfx0, mfx1 = int(w - fx1), int(w - fx0)
                ry0 = max(0, max(ly0, fy0) - 1)
                ry1 = min(int(h), min(ly1, fy1) + 1)
                rx0 = max(0, max(lx0, mfx0) - 1)
                rx1 = min(int(w), min(lx1, mfx1) + 1)
                if ry0 < ry1 and rx0 < rx1:
                    last_gid_slice = labels_store.read_window(
                        int(z_dim) - 1, ry0, ry1, rx0, rx1,
                    )
                    first_gid_slice = labels_store.read_window(
                        0, ry0, ry1, int(w - rx1), int(w - rx0),
                    )[:, ::-1]
                else:
                    last_gid_slice = np.empty((0, 0), dtype=label_dtype)
                    first_gid_slice = np.empty((0, 0), dtype=label_dtype)
            else:
                first_gid_slice = np.asarray(labels_store[0])  # type: ignore[index]
                last_gid_slice = np.asarray(labels_store[int(z_dim) - 1])  # type: ignore[index]
                first_gid_slice = first_gid_slice[:, ::-1]
            uf.union_pair_codes(_adjacent_gid_pair_codes(
                last_gid_slice,
                first_gid_slice,
                prev_offset=int(slice_offsets[int(z_dim) - 1]),
                curr_offset=int(slice_offsets[0]),
            ))

    root_map = uf.root_map()
    if root_map.shape[0] <= 1:
        flush_array(labels_store)
        return labels_store, 0, label_paths

    unique_roots = np.unique(root_map[1:])
    unique_roots = unique_roots[unique_roots > 0]

    compact_root_ids = np.zeros(root_map.shape, dtype=np.uint32)
    compact_root_ids[unique_roots] = np.arange(1, unique_roots.size + 1, dtype=np.uint32)
    gid_to_compact = compact_root_ids[root_map]

    # v13.3.2 (R6b): per-slice local->compact LUTs live in one concatenated table (slice z's
    # local id v maps through lut_flat[lut_offsets[z] + v]), and the relabel touches only each
    # slice's recorded foreground bbox — labels outside it are guaranteed zero.
    # v13.3.6 (A1): the same table is now ALSO exported through component_stats_out
    # ('slice_local_luts') so callers can consume per-slice local ids directly and skip the
    # full-volume relabel pass entirely.
    lut_sizes = component_counts.astype(np.int64, copy=False) + 1
    lut_offsets = np.zeros((int(z_dim),), dtype=np.int64)
    if int(z_dim) > 1:
        lut_offsets[1:] = np.cumsum(lut_sizes)[:-1]
    lut_flat = np.zeros((int(lut_sizes.sum()),), dtype=np.uint32)
    for z in range(int(z_dim)):
        count = int(component_counts[int(z)])
        if count > 0:
            offset = int(slice_offsets[int(z)])
            lo = int(lut_offsets[int(z)])
            lut_flat[lo + 1:lo + count + 1] = gid_to_compact[offset + 1:offset + count + 1]

    if collect_stats:
        # v13.3.2 (R6c): per-gid areas -> per-root areas (bincount is one vectorized pass; voxel
        # counts stay far below 2^53 so the float64 accumulation is exact).
        gid_areas = np.zeros((int(total_components) + 1,), dtype=np.int64)
        for z in range(int(z_dim)):
            count = int(component_counts[int(z)])
            if count <= 0:
                continue
            offset = int(slice_offsets[int(z)])
            gid_areas[offset + 1:offset + count + 1] = slice_areas[int(z)]
        root_areas = np.bincount(
            root_map.astype(np.int64, copy=False),
            weights=gid_areas.astype(np.float64, copy=False),
            minlength=int(total_components) + 1,
        ).astype(np.int64)
        component_stats_out.update({
            'component_counts': component_counts,
            'slice_offsets': slice_offsets,
            'slice_bboxes': slice_bboxes,
            'root_map': root_map,
            'unique_roots': unique_roots,
            'root_areas': root_areas,
            'total_components': int(total_components),
            'slice_local_luts': SliceLocalLabelLUTs(
                lut_flat=lut_flat,
                lut_offsets=lut_offsets,
                component_counts=component_counts,
            ),
        })

    if not compact_relabel:
        # v13.3.2 (R6c): the caller consumes per-slice LOCAL ids through root LUTs — skip the
        # full-volume relabel write pass entirely.
        flush_array(labels_store)
        return labels_store, int(unique_roots.size), label_paths

    kernel_done = False
    if compiled_interpolation_kernels_enabled() and _numba_compact_relabel_kernel is not None:
        try:
            print('Interpolation: compact relabel via numba nogil kernel')
            _numba_compact_relabel_kernel(
                np.asarray(labels_store),
                lut_flat,
                lut_offsets,
                np.ascontiguousarray(slice_bboxes),
                component_counts,
            )
            kernel_done = True
        except Exception as exc:
            print(f'Interpolation: numba compact relabel unavailable ({exc}); using the thread pool.')

    if not kernel_done:
        compact_tasks: List[Tuple[int, int, int, int, int]] = []
        row_block = max(1, _env_int('YOLO_TTA_INTERPOLATION_COMPACT_RELABEL_ROWS', 256))
        for z in range(int(z_dim)):
            if int(component_counts[int(z)]) <= 0:
                continue
            by0, by1, bx0, bx1 = (int(v) for v in slice_bboxes[int(z)])
            for y0 in range(by0, by1, int(row_block)):
                compact_tasks.append((int(z), int(y0), int(min(by1, y0 + int(row_block))), bx0, bx1))

        def _compact_block(task_idx: int) -> int:
            z, y0, y1, x0, x1 = compact_tasks[int(task_idx)]
            lo = int(lut_offsets[int(z)])
            local_to_compact = lut_flat[lo:lo + int(component_counts[int(z)]) + 1]
            block = np.asarray(labels_store[int(z), int(y0):int(y1), int(x0):int(x1)])
            if np.any(block):
                labels_store[int(z), int(y0):int(y1), int(x0):int(x1)] = local_to_compact[block]
            # v13.2.5 (speed #11): an all-zero block is already zero in the store; the old
            # else-branch fill(0) rewrote it needlessly (dirtying pages on memmap-backed stores).
            return int(y1) - int(y0)

        if compact_tasks:
            pending = max(compact_workers, compact_workers * 8)
            if compact_workers <= 1:
                for task_idx in tqdm(range(len(compact_tasks)), desc='Interpolation: compact relabel'):
                    _compact_block(int(task_idx))
            else:
                for _rows_done in tqdm(
                    parallel_map_unordered(
                        _compact_block,
                        range(len(compact_tasks)),
                        max_workers=compact_workers,
                        max_pending=pending,
                    ),
                    total=len(compact_tasks),
                    desc='Interpolation: compact relabel',
                ):
                    pass

    flush_array(labels_store)
    return labels_store, int(unique_roots.size), label_paths


def build_slice_endpoint_seeds_from_label_volume(
    labels_real: np.ndarray,
    workers: int = 1,
    desc: str = 'Interpolation: endpoint seeds [scan]',
    wrap_axis: bool = False,
    component_cache: Optional['SliceComponentTableCache'] = None,
) -> Tuple[List[SliceEndpointSeed], int]:
    """Fast slice-graph endpoint scan for slice-direction interpolation.

    This avoids per-object 3D voxel skeletonization on large relabeled volumes, which can become
    prohibitively slow when an object's bounding box spans a large fraction of the volume. Endpoints
    are identified from connected components in each slice that do not continue into the previous or
    next slice of the same relabeled object. When wrap_axis is true, slice 0 and the
    final slice are also considered adjacent for Radial interpolation.

    When a component cache is supplied, the scan reuses cached per-slice component tables and tests
    continuation only inside each component's crop. This makes endpoint discovery and later seed
    planning share the same component records instead of relabeling slices again per seed/bridge.
    """
    z_dim = int(labels_real.shape[0])
    if z_dim <= 0:
        return [], 0

    def _scan_slice_from_cache(z: int) -> List[SliceEndpointSeed]:
        if component_cache is None:
            return []
        z_i = int(z)
        table = component_cache.get(z_i)
        if not table.components:
            return []

        prev_table: Optional[SliceComponentTable] = None
        next_table: Optional[SliceComponentTable] = None
        prev_wrapped = False
        next_wrapped = False
        if bool(wrap_axis) and z_dim > 1:
            prev_table = component_cache.get((z_i - 1) % z_dim)
            next_table = component_cache.get((z_i + 1) % z_dim)
            # v13.2.2 bug #12: continuation across the radial 0°/180° wrap happens at
            # u -> width-1-u, not at the same u (see _component_record_mirrored_u).
            prev_wrapped = z_i == 0
            next_wrapped = z_i == (z_dim - 1)
        else:
            if z_i > 0:
                prev_table = component_cache.get(z_i - 1)
            if (z_i + 1) < z_dim:
                next_table = component_cache.get(z_i + 1)

        slice_w = int(table.shape[1])
        seeds_local: List[SliceEndpointSeed] = []
        for record in table.components:
            prev_records = prev_table.by_label.get(int(record.label), []) if prev_table is not None else []
            next_records = next_table.by_label.get(int(record.label), []) if next_table is not None else []
            if prev_wrapped:
                prev_records = [_component_record_mirrored_u(other, slice_w) for other in prev_records]
            if next_wrapped:
                next_records = [_component_record_mirrored_u(other, slice_w) for other in next_records]
            has_prev = any(_component_records_directly_overlap(record, other) for other in prev_records)
            has_next = any(_component_records_directly_overlap(record, other) for other in next_records)

            if not has_prev:
                seeds_local.append(SliceEndpointSeed(
                    label=int(record.label),
                    point=(z_i, int(record.anchor[0]), int(record.anchor[1])),
                    direction_sign=-1,
                ))
            if not has_next:
                seeds_local.append(SliceEndpointSeed(
                    label=int(record.label),
                    point=(z_i, int(record.anchor[0]), int(record.anchor[1])),
                    direction_sign=1,
                ))
        return seeds_local

    def _scan_slice(z: int) -> List[SliceEndpointSeed]:
        if component_cache is not None:
            return _scan_slice_from_cache(int(z))

        curr_slice = np.asarray(labels_real[int(z)])
        if not np.any(curr_slice):
            return []

        if bool(wrap_axis) and z_dim > 1:
            # v13.2.2 bug #12: the wrap-adjacent frame continues at u -> width-1-u, so
            # mirror the neighbor slice when the adjacency crosses the 0°/180° boundary.
            prev_slice = np.asarray(labels_real[(int(z) - 1) % z_dim])
            if int(z) == 0:
                prev_slice = prev_slice[:, ::-1]
            next_slice = np.asarray(labels_real[(int(z) + 1) % z_dim])
            if int(z) == (z_dim - 1):
                next_slice = next_slice[:, ::-1]
        else:
            prev_slice = np.asarray(labels_real[int(z) - 1]) if int(z) > 0 else None
            next_slice = np.asarray(labels_real[int(z) + 1]) if (int(z) + 1) < z_dim else None

        seeds_local: List[SliceEndpointSeed] = []
        present = np.unique(curr_slice)
        present = present[present > 0]
        if present.size == 0:
            return seeds_local

        for obj_id in present.tolist():
            obj_mask = (curr_slice == int(obj_id)).astype(np.uint8, copy=False)
            num_cc, cc = cv2.connectedComponents(obj_mask, connectivity=8, ltype=cv2.CV_32S)
            if int(num_cc) <= 1:
                continue

            prev_same = (prev_slice == int(obj_id)) if prev_slice is not None else None
            next_same = (next_slice == int(obj_id)) if next_slice is not None else None

            for local_lbl in range(1, int(num_cc)):
                comp = cc == int(local_lbl)
                if not np.any(comp):
                    continue
                anchor = _component_centroid_anchor(comp)
                if anchor is None:
                    continue

                # v12.2.0 endpoint continuation is defined by direct footprint overlap in
                # the adjacent slice; do not dilate/skeletonize the component for endpoint discovery.
                has_prev = bool(prev_same is not None and np.any(comp & prev_same))
                has_next = bool(next_same is not None and np.any(comp & next_same))

                if not has_prev:
                    seeds_local.append(SliceEndpointSeed(
                        label=int(obj_id),
                        point=(int(z), int(anchor[0]), int(anchor[1])),
                        direction_sign=-1,
                    ))
                if not has_next:
                    seeds_local.append(SliceEndpointSeed(
                        label=int(obj_id),
                        point=(int(z), int(anchor[0]), int(anchor[1])),
                        direction_sign=1,
                    ))

        return seeds_local

    worker_count = choose_slice_parallel_workers(int(workers), z_dim)
    if component_cache is not None:
        component_cache.prebuild(
            workers=worker_count,
            desc=f'{desc}: component tables',
        )

    seeds: List[SliceEndpointSeed] = []

    if worker_count <= 1:
        for z in tqdm(range(z_dim), desc=desc):
            seeds.extend(_scan_slice(int(z)))
    else:
        pending = max(worker_count, worker_count * 8)
        for seeds_local in tqdm(
            parallel_map_unordered(_scan_slice, range(z_dim), max_workers=worker_count, max_pending=pending),
            total=z_dim,
            desc=desc,
        ):
            seeds.extend(seeds_local)

    seeds.sort(key=lambda s: (int(s.label), int(s.point[0]), int(s.direction_sign), int(s.point[1]), int(s.point[2])))
    return seeds, int(len(seeds))


@dataclass(frozen=True)
class RadialBackprojectionSample:
    angle_deg: float
    source_index: int
    reverse_u: bool = False


@dataclass(frozen=True)
class DenseRadialBackprojectionMap:
    valid_mask: np.ndarray
    source_idx_map: np.ndarray
    u_idx_map: np.ndarray


_DENSE_RADIAL_BACKPROJECT_MAP_CACHE: Dict[Tuple[int, int, int, Tuple[Tuple[float, int, bool], ...]], DenseRadialBackprojectionMap] = {}


def radial_full_coverage_angle_deg(diameter: int) -> float:
    """Return the v12.2.0 radial spacing that gives approximately 1x ROI edge coverage."""
    diameter_i = max(1, int(diameter))
    return float(360.0 / (math.pi * float(diameter_i)))


def _radial_view_nominal_spacing_deg(radial_view: ViewInfo) -> float:
    az = list(float(a) for a in radial_view.azimuths_deg)
    if len(az) >= 2:
        return float(abs(az[1] - az[0]))
    return 180.0


def _nearest_radial_source_for_backprojection(
    target_angle_deg: float,
    source_angles_deg: np.ndarray,
) -> Tuple[int, bool]:
    """Nearest source plane over the unoriented [0, 180) radial diameter domain.

    When the nearest match crosses the 0/180 boundary, the same diameter plane is reused with
    the radial coordinate reversed so source raster coordinates still map to the target plane.
    """
    if source_angles_deg.size <= 0:
        raise ValueError('No radial source angles are available for backprojection')

    raw = float(target_angle_deg) - source_angles_deg.astype(np.float64, copy=False)
    wrapped = ((raw + 90.0) % 180.0) - 90.0
    idx = int(np.argmin(np.abs(wrapped)))
    reverse_u = bool(abs(float(raw[idx])) > 90.0)
    return idx, reverse_u


def build_radial_backprojection_plan(radial_view: ViewInfo) -> Tuple[List[RadialBackprojectionSample], Dict[str, float]]:
    """Build the angular plan used to backproject a radial view into Cartesian space.

    If the user-requested radial spacing is coarser than the v12.2.0 full-coverage spacing,
    backprojection is densified to the full-coverage spacing and each dense angle samples the
    nearest completed radial prediction frame. This keeps Radial masks view-native through
    postprocessing/interpolation while preventing sparse spoke-like Cartesian backprojections.
    """
    source_angles = np.asarray([float(a) for a in radial_view.azimuths_deg], dtype=np.float64)
    if source_angles.size <= 0:
        return [], {
            'provided_spacing_deg': 0.0,
            'coverage_spacing_deg': radial_full_coverage_angle_deg(int(radial_view.diameter)),
            'effective_spacing_deg': 0.0,
            'source_frames': 0.0,
            'backprojection_angles': 0.0,
            'densified': 0.0,
        }

    provided_spacing = _radial_view_nominal_spacing_deg(radial_view)
    coverage_spacing = radial_full_coverage_angle_deg(int(radial_view.diameter))
    # The specification's guarantee formula is a maximum safe angular spacing.  A smaller
    # user spacing is already dense enough; a larger spacing is densified during backprojection.
    effective_spacing = min(float(provided_spacing), float(coverage_spacing))

    if float(provided_spacing) <= float(coverage_spacing) * (1.0 + 1e-9):
        samples = [
            RadialBackprojectionSample(angle_deg=float(angle), source_index=int(idx), reverse_u=False)
            for idx, angle in enumerate(source_angles.tolist())
        ]
        densified = False
    else:
        dense_angles = build_radial_azimuths(float(effective_spacing))
        samples = []
        for dense_angle in dense_angles:
            source_idx, reverse_u = _nearest_radial_source_for_backprojection(float(dense_angle), source_angles)
            samples.append(RadialBackprojectionSample(
                angle_deg=float(dense_angle),
                source_index=int(source_idx),
                reverse_u=bool(reverse_u),
            ))
        densified = True

    return samples, {
        'provided_spacing_deg': float(provided_spacing),
        'coverage_spacing_deg': float(coverage_spacing),
        'effective_spacing_deg': float(effective_spacing),
        'source_frames': float(source_angles.size),
        'backprojection_angles': float(len(samples)),
        'densified': 1.0 if bool(densified) else 0.0,
    }


def _radial_plan_signature(plan: Sequence[RadialBackprojectionSample]) -> Tuple[Tuple[float, int, bool], ...]:
    return tuple((round(float(s.angle_deg), 6), int(s.source_index), bool(s.reverse_u)) for s in plan)


def build_dense_radial_backprojection_map(
    radial_view: ViewInfo,
    plan: Sequence[RadialBackprojectionSample],
    *,
    out_shape_hw: Optional[Tuple[int, int]] = None,
) -> DenseRadialBackprojectionMap:
    """Map every Cartesian ROI pixel to its nearest dense radial source frame and radial coordinate.

    This is the dense v12.2.0 backprojection path: instead of painting only the pixels that lie on
    a set of spokes, every pixel inside the circular ROI receives a sample from the Radial video's
    own frame/raster coordinate system.  When the user-provided azimuth spacing is too coarse, the
    supplied ``plan`` is already densified to the full-coverage angular spacing; pixels then select
    the nearest dense plan angle and that angle's nearest completed source frame.

    v13.2.4 (task #1, ruling A1): ``out_shape_hw`` builds the map directly on the FINAL SOURCE
    raster instead of the working plane. Source pixel centers are mapped into the working plane
    analytically with the same center-aligned convention cv2.resize uses, so backprojecting a
    radial mask straight to source geometry stays a single resample (no intermediate
    working-geometry volume). ``None`` keeps the historical working-plane map.
    """
    work_h = int(radial_view.full_h)
    work_w = int(radial_view.full_w)
    if out_shape_hw is None:
        out_h, out_w = work_h, work_w
    else:
        out_h, out_w = (int(out_shape_hw[0]), int(out_shape_hw[1]))
    if not plan:
        return DenseRadialBackprojectionMap(
            valid_mask=np.zeros((out_h, out_w), dtype=bool),
            source_idx_map=np.zeros((out_h, out_w), dtype=np.int32),
            u_idx_map=np.zeros((out_h, out_w), dtype=np.int32),
        )

    # v13.2.5 (speed #1): the radial u raster may be imgsz-folded (view.src_w < diameter);
    # u indices map the physical signed radius onto that raster, matching the sampler's
    # linspace(-R, R, src_w) tap positions exactly.
    u_len = int(radial_view.src_w) if int(radial_view.src_w) > 0 else int(radial_view.diameter)
    key = (
        int(out_h),
        int(out_w),
        int(work_h),
        int(work_w),
        int(radial_view.diameter),
        int(u_len),
        _radial_plan_signature(plan),
    )
    cached = _DENSE_RADIAL_BACKPROJECT_MAP_CACHE.get(key)
    if cached is not None:
        return cached

    diameter = int(u_len)
    radius = float(radial_view.roi_radius)
    if radius <= 0.0:
        radius = max(1.0, float(diameter - 1) / 2.0)

    plan_angles = np.asarray([float(s.angle_deg) % 180.0 for s in plan], dtype=np.float32)
    plan_sources = np.asarray([int(s.source_index) for s in plan], dtype=np.int32)
    plan_reverses = np.asarray([bool(s.reverse_u) for s in plan], dtype=bool)
    n_plan = int(plan_angles.size)
    if n_plan <= 0:
        raise ValueError('Dense radial backprojection requires at least one angular plan sample')

    if n_plan >= 2:
        diffs = np.diff(plan_angles.astype(np.float64, copy=False))
        positive_diffs = diffs[diffs > 1e-9]
        step = float(np.median(positive_diffs)) if positive_diffs.size else 180.0 / float(n_plan)
    else:
        step = 180.0
    step = max(float(step), 1e-9)

    yy, xx = np.indices((out_h, out_w), dtype=np.float32)
    if (out_h, out_w) != (work_h, work_w):
        # Source pixel centers mapped into the working plane (cv2.resize center convention).
        xx = (xx + np.float32(0.5)) * np.float32(float(work_w) / float(out_w)) - np.float32(0.5)
        yy = (yy + np.float32(0.5)) * np.float32(float(work_h) / float(out_h)) - np.float32(0.5)
    dx = xx - float(radial_view.center_x)
    dy = yy - float(radial_view.center_y)
    rr = np.sqrt((dx * dx) + (dy * dy)).astype(np.float32, copy=False)
    valid = rr <= (float(radius) + 0.5)

    theta = np.degrees(np.arctan2(dy, dx)).astype(np.float32, copy=False)
    theta = np.mod(theta, 180.0).astype(np.float32, copy=False)
    nearest_plan_idx = np.mod(np.rint(theta / float(step)).astype(np.int32, copy=False), n_plan)

    target_angles = plan_angles[nearest_plan_idx]
    cos_t = np.cos(np.deg2rad(target_angles)).astype(np.float32, copy=False)
    sin_t = np.sin(np.deg2rad(target_angles)).astype(np.float32, copy=False)
    signed_r = (dx * cos_t) + (dy * sin_t)
    signed_r[plan_reverses[nearest_plan_idx]] *= -1.0

    u_float = ((signed_r + float(radius)) / max(1e-6, 2.0 * float(radius))) * float(diameter - 1)
    u_idx = np.clip(np.rint(u_float).astype(np.int32, copy=False), 0, diameter - 1)
    source_idx = plan_sources[nearest_plan_idx].astype(np.int32, copy=False)

    source_idx[~valid] = 0
    u_idx[~valid] = 0

    dense_map = DenseRadialBackprojectionMap(
        valid_mask=np.ascontiguousarray(valid),
        source_idx_map=np.ascontiguousarray(source_idx),
        u_idx_map=np.ascontiguousarray(u_idx),
    )
    _DENSE_RADIAL_BACKPROJECT_MAP_CACHE[key] = dense_map
    return dense_map


def _pick_gpu_compute_device(torch_mod: object) -> object:
    """v13.3.3 (S1): pick the CUDA device with the most free VRAM for main-process GPU stages.

    The radial/tilted backprojections and other main-process GPU work previously hardcoded
    cuda:0, piling every stage onto one device while the other GPUs idled.
    YOLO_TTA_GPU_BACKPROJECT_DEVICE=<index> overrides the choice.
    """
    explicit = os.environ.get('YOLO_TTA_GPU_BACKPROJECT_DEVICE', '').strip()
    if explicit:
        try:
            return torch_mod.device(f'cuda:{int(explicit)}')
        except Exception:
            pass
    try:
        count = int(torch_mod.cuda.device_count())
    except Exception:
        count = 1
    if count <= 1:
        return torch_mod.device('cuda:0')
    best_idx = 0
    best_free = -1
    for idx in range(count):
        try:
            free_bytes, _total = torch_mod.cuda.mem_get_info(torch_mod.device(f'cuda:{idx}'))
        except Exception:
            continue
        if int(free_bytes) > int(best_free):
            best_free = int(free_bytes)
            best_idx = int(idx)
    return torch_mod.device(f'cuda:{best_idx}')


def _radial_row_occupancy(radial_mask_mm: np.ndarray, desc: str) -> np.ndarray:
    """v13.3.3 (S1): per-v foreground bitmap over the azimuth-major radial stack, in ONE pass.

    The chunk loop used to re-scan ``radial_mask_mm[:, v, :]`` per covering row — a strided
    reduction touching every azimuth plane of the multi-GiB memmap per row, repeated across
    ~250 chunks. This computes the same information once, azimuth-major (contiguous reads),
    parallelized over azimuth ranges (the per-plane ``any`` reductions release the GIL).
    """
    n_az, work_t, _u_len = (int(x) for x in radial_mask_mm.shape)
    row_any = np.zeros((work_t,), dtype=bool)
    if n_az <= 0 or work_t <= 0:
        return row_any
    lock = threading.Lock()
    scan_workers = max(1, min(16, _cpu_count(), n_az))
    az_chunk = max(1, int(math.ceil(float(n_az) / float(scan_workers * 4))))

    def _scan_range(range_idx: int) -> None:
        a0 = int(range_idx) * az_chunk
        a1 = min(n_az, a0 + az_chunk)
        local = np.zeros((work_t,), dtype=bool)
        for a in range(a0, a1):
            plane = np.asarray(radial_mask_mm[a])  # (work_t, u_len) contiguous
            np.logical_or(local, plane.any(axis=1), out=local)
        with lock:
            np.logical_or(row_any, local, out=row_any)

    num_ranges = int(math.ceil(float(n_az) / float(az_chunk)))
    parallel_for_indices(
        num_ranges,
        _scan_range,
        max_workers=scan_workers,
        desc=f'{desc} [row occupancy]',
        show_progress=False,
    )
    return row_any


def gpu_backproject_enabled() -> bool:
    """v13.3.2 (R6a): stream radial backprojection through the GPU when torch + CUDA exist."""
    return _env_flag('YOLO_TTA_GPU_BACKPROJECT', True)


def _validated_radial_slice_bboxes(
    value: Optional[np.ndarray],
    n_az: int,
    work_t: int,
    u_len: int,
) -> Optional[np.ndarray]:
    """Validate interpolation-carried ``(t0,t1,u0,u1)`` bounds for radial planes."""
    if value is None:
        return None
    try:
        bboxes = np.asarray(value, dtype=np.int64)
    except Exception:
        return None
    if tuple(int(v) for v in bboxes.shape) != (int(n_az), 4):
        return None
    valid = (
        (bboxes[:, 0] >= 0) & (bboxes[:, 0] <= bboxes[:, 1]) & (bboxes[:, 1] <= int(work_t))
        & (bboxes[:, 2] >= 0) & (bboxes[:, 2] <= bboxes[:, 3]) & (bboxes[:, 3] <= int(u_len))
    )
    if not bool(np.all(valid)):
        return None
    return np.ascontiguousarray(bboxes)


def _trt_engine_from_autobackend(backend: object) -> Optional[object]:
    """Find the ICudaEngine without relying on one Ultralytics release's attribute names."""
    candidates = [
        getattr(backend, 'model', None),
        getattr(backend, 'trt_engine', None),
        getattr(backend, '_engine', None),
        getattr(getattr(backend, 'context', None), 'engine', None),
    ]
    for candidate in candidates:
        if candidate is None or isinstance(candidate, (bool, str, Path)):
            continue
        if callable(getattr(candidate, 'create_execution_context', None)):
            return candidate
    return None


def _torch_dtype_for_trt_binding(backend: object, engine: object, name: str, torch_mod: object) -> Optional[object]:
    """Resolve a binding dtype, preferring AutoBackend's already-validated torch buffers."""
    try:
        binding = getattr(backend, 'bindings', {}).get(str(name))
        data = getattr(binding, 'data', None)
        if data is not None and getattr(data, 'dtype', None) is not None:
            return data.dtype
    except Exception:
        pass
    try:
        import tensorrt as trt  # type: ignore
        dtype_obj = (
            engine.get_tensor_dtype(str(name))
            if callable(getattr(engine, 'get_tensor_dtype', None))
            else engine.get_binding_dtype(int(engine.get_binding_index(str(name))))
        )
        np_dtype = np.dtype(trt.nptype(dtype_obj))
        mapping = {
            np.dtype(np.float16): torch_mod.float16,
            np.dtype(np.float32): torch_mod.float32,
            np.dtype(np.int8): torch_mod.int8,
            np.dtype(np.int32): torch_mod.int32,
            np.dtype(np.int64): torch_mod.int64,
            np.dtype(np.bool_): torch_mod.bool,
        }
        return mapping.get(np_dtype)
    except Exception:
        return None


def _trt_binding_layout_for_backend(
    backend: object, engine: object,
) -> Tuple[List[str], str, List[str], Dict[str, int]]:
    """Resolve TensorRT I/O names without allocating a resident execution context.

    The ring input dtype must be known before its static-address slots are allocated, so
    layout discovery cannot live solely in ``_ResidentTensorRTRingExecutor.__init__``.
    """
    names: List[str] = []
    indices: Dict[str, int] = {}
    if callable(getattr(engine, 'get_tensor_name', None)):
        count = int(getattr(engine, 'num_io_tensors'))
        for i in range(count):
            name = str(engine.get_tensor_name(i))
            names.append(name)
            indices[name] = int(i)
    elif callable(getattr(engine, 'get_binding_name', None)):
        count = int(getattr(engine, 'num_bindings'))
        for i in range(count):
            name = str(engine.get_binding_name(i))
            names.append(name)
            indices[name] = int(i)
    else:
        raise RuntimeError('unknown TensorRT binding API')

    backend_outputs = [str(x) for x in (getattr(backend, 'output_names', None) or [])]
    input_name = str(getattr(backend, 'input_name', '') or '')
    if input_name not in names:
        input_candidates: List[str] = []
        for name in names:
            try:
                if callable(getattr(engine, 'binding_is_input', None)):
                    is_input = bool(engine.binding_is_input(indices[name]))
                else:
                    is_input = 'INPUT' in str(engine.get_tensor_mode(name)).upper()
                if is_input:
                    input_candidates.append(name)
            except Exception:
                pass
        if len(input_candidates) != 1:
            input_candidates = [name for name in names if name not in set(backend_outputs)]
        if len(input_candidates) != 1:
            raise RuntimeError(f'expected one TensorRT image input, found {input_candidates}')
        input_name = input_candidates[0]
    output_names = [name for name in backend_outputs if name in names]
    if not output_names:
        output_names = [name for name in names if name != input_name]
    if set(output_names) | {input_name} != set(names):
        raise RuntimeError('TensorRT engine has auxiliary bindings unsupported by the resident ring')
    return names, input_name, output_names, indices


class _ResidentTensorRTRingFatalError(RuntimeError):
    """Ring teardown could not prove the borrowed backend/buffers safe for fallback."""


class _ResidentTensorRTRingExecutor:
    """Two independent TensorRT contexts with static input/output addresses.

    This adapter intentionally uses TensorRT's public execution-context API instead of
    swapping ``AutoBackend.context`` in place.  If the engine, binding metadata, async
    API, or fixed shapes cannot be proved safe, construction fails before source
    consumption and the caller retains the ordinary direct-predict path.
    """

    def __init__(
        self,
        backend: object,
        slots: Sequence[_ResidentGpuPipelineSlot],
        *,
        out_size: int,
        native_h: int,
        native_w: int,
        M_out_to_native: np.ndarray,
        track_conf: bool,
        confidence_threshold: float,
    ) -> None:
        import torch  # type: ignore
        self.torch = torch
        self._closed = False
        self.backend = backend
        self.engine = _trt_engine_from_autobackend(backend)
        if self.engine is None:
            raise RuntimeError('AutoBackend does not expose a TensorRT ICudaEngine')
        if len(slots) != 2:
            raise RuntimeError('resident TensorRT ring requires exactly two slots')
        self.slots = list(slots)
        self.out_size = int(out_size)
        self.native_h = int(native_h)
        self.native_w = int(native_w)
        if self.out_size <= 0 or self.native_h <= 0 or self.native_w <= 0:
            raise RuntimeError(
                f'invalid resident ring geometry network={self.out_size}, '
                f'native={self.native_h}x{self.native_w}'
            )
        try:
            out_to_native = np.asarray(M_out_to_native, dtype=np.float64).reshape(2, 3)
            native_to_out3 = np.linalg.inv(_affine2x3_to_3x3(out_to_native))
        except Exception as exc:
            raise RuntimeError('resident ring native affine is singular or malformed') from exc
        if not bool(np.isfinite(native_to_out3).all()):
            raise RuntimeError('resident ring native affine contains non-finite values')
        self.identity_native_warp = bool(
            self.native_h == self.out_size
            and self.native_w == self.out_size
            and _warp_matrix_is_identity(out_to_native)
        )
        # Six scalar graph arguments, constant for the whole task.  This is the exact
        # native-pixel -> network-pixel inverse used by _affine_theta_for_grid_sample,
        # without allocating a per-frame/full-resolution grid tensor.
        self.native_to_out = tuple(
            np.float32(x) for x in native_to_out3[:2, :3].reshape(-1)
        )
        self.track_conf = bool(track_conf)
        self.confidence_threshold = float(confidence_threshold)
        self.kernels = _resident_mask_kernels()
        if self.kernels is None:
            raise RuntimeError('CUDA confidence-compaction kernel is unavailable')

        self.binding_names, self.input_name, self.output_names, self.binding_indices = self._binding_layout()
        if len(self.output_names) < 2:
            raise RuntimeError(f'TensorRT segmentation engine exposes only {len(self.output_names)} outputs')
        input_dtype = _torch_dtype_for_trt_binding(backend, self.engine, self.input_name, torch)
        if input_dtype not in (torch.float16, torch.float32):
            raise RuntimeError(
                f'resident ring kernels do not support TensorRT input dtype {input_dtype}'
            )
        if any(slot.input.dtype != input_dtype for slot in self.slots):
            raise RuntimeError(
                f'TensorRT input dtype {input_dtype} does not match resident ring slot dtypes '
                f'{[slot.input.dtype for slot in self.slots]}'
            )

        # AutoBackend already owns one context. Borrow it plus ONE new context so the
        # worker has two total (not three profile-sized context allocations).  v3 tensor
        # addresses are restored before returning control to AutoBackend.
        original_context = getattr(backend, 'context', None)
        if original_context is None:
            raise RuntimeError('AutoBackend does not expose its primary TensorRT context')
        second_context = self.engine.create_execution_context()
        if second_context is None:
            raise RuntimeError('TensorRT could not allocate a second independent execution context')
        contexts: List[object] = [original_context, second_context]
        if contexts[0] is contexts[1]:
            raise RuntimeError('TensorRT returned an aliased execution context')

        self._borrowed_context = original_context
        self._restore_tensor_addresses: Dict[str, int] = {}
        if callable(getattr(original_context, 'set_tensor_address', None)):
            for name in self.binding_names:
                binding = getattr(backend, 'bindings', {}).get(str(name))
                data = getattr(binding, 'data', None)
                if data is None or not callable(getattr(data, 'data_ptr', None)):
                    raise RuntimeError(
                        f'cannot safely restore AutoBackend TensorRT address for {name!r}'
                    )
                self._restore_tensor_addresses[name] = int(data.data_ptr())

        self.infer_graph_count = 0
        self.post_graph_count = 0
        try:
            for slot, context in zip(self.slots, contexts):
                slot.context = context
                output_tensors = self._configure_context_and_buffers(slot)
                split = _split_segmentation_backend_outputs(output_tensors)
                if split is None:
                    # Output order is not guaranteed across TensorRT exporter versions; identify
                    # the detection head/proto by rank, then preserve the direct-loop contract.
                    rank3 = [x for x in output_tensors if int(getattr(x, 'ndim', 0)) == 3]
                    rank4 = [x for x in output_tensors if int(getattr(x, 'ndim', 0)) == 4]
                    if len(rank3) != 1 or len(rank4) != 1:
                        raise RuntimeError('TensorRT outputs cannot be identified as head + proto')
                    split = (rank3[0], rank4[0])
                slot.head, slot.proto = split
                if slot.head.dtype not in (torch.float16, torch.float32):
                    raise RuntimeError(
                        f'resident ring kernels do not support TensorRT head dtype {slot.head.dtype}'
                    )
                if slot.proto.dtype not in (torch.float16, torch.float32):
                    raise RuntimeError(
                        f'resident ring kernels do not support TensorRT proto dtype {slot.proto.dtype}'
                    )
                self._allocate_post_buffers(slot)

            # Shape/layout invariants for the user's single-class segmentation engines.
            for slot in self.slots:
                head, proto = slot.head, slot.proto
                if int(head.shape[0]) != 1 or int(proto.shape[0]) != 1:
                    raise RuntimeError('resident TensorRT ring is fixed to batch 1')
                nm = int(proto.shape[1])
                if int(head.shape[1]) != 5 + nm:
                    raise RuntimeError(
                        f'resident TensorRT ring requires one class (head={tuple(head.shape)}, proto={tuple(proto.shape)})'
                    )
                if tuple(int(x) for x in head.shape) != tuple(int(x) for x in self.slots[0].head.shape):
                    raise RuntimeError('TensorRT ring contexts returned different head shapes')
                if tuple(int(x) for x in proto.shape) != tuple(int(x) for x in self.slots[0].proto.shape):
                    raise RuntimeError('TensorRT ring contexts returned different proto shapes')

            # Prove that both contexts may be in flight on distinct streams before the
            # source is consumed. Dynamic-profile restrictions and plugin stream-safety
            # failures surface at stream synchronization and cleanly reject this fast path.
            self._validate_concurrent_contexts()
            # Runtime warmups are mandatory even when CUDA graphs are explicitly disabled:
            # the post warmup is the pre-consumption proof that the compaction/union/affine
            # kernels accept this engine's actual head/proto dtypes and layouts.
            self._capture_static_graphs(
                capture_graphs=bool(resident_trt_cuda_graphs_enabled()),
            )
        except Exception:
            self.close()
            raise

    def _binding_layout(self) -> Tuple[List[str], str, List[str], Dict[str, int]]:
        return _trt_binding_layout_for_backend(self.backend, self.engine)

    def _set_input_shape(self, context: object, slot: _ResidentGpuPipelineSlot) -> None:
        shape = tuple(int(x) for x in slot.input.shape)
        if callable(getattr(context, 'set_input_shape', None)):
            ok = context.set_input_shape(self.input_name, shape)
            if ok is False:
                raise RuntimeError(f'TensorRT rejected static input shape {shape}')
        elif callable(getattr(context, 'set_binding_shape', None)):
            ok = context.set_binding_shape(self.binding_indices[self.input_name], shape)
            if ok is False:
                raise RuntimeError(f'TensorRT rejected static binding shape {shape}')

    def _context_shape(self, context: object, name: str) -> Tuple[int, ...]:
        if callable(getattr(context, 'get_tensor_shape', None)):
            shape = tuple(int(x) for x in context.get_tensor_shape(name))
        else:
            shape = tuple(int(x) for x in context.get_binding_shape(self.binding_indices[name]))
        if not shape or any(int(x) <= 0 for x in shape):
            raise RuntimeError(f'TensorRT binding {name!r} has unresolved shape {shape}')
        return shape

    def _configure_context_and_buffers(self, slot: _ResidentGpuPipelineSlot) -> List[object]:
        torch = self.torch
        context = slot.context
        self._set_input_shape(context, slot)
        outputs: Dict[str, object] = {}
        for name in self.output_names:
            dtype = _torch_dtype_for_trt_binding(self.backend, self.engine, name, torch)
            if dtype is None:
                raise RuntimeError(f'cannot resolve TensorRT dtype for {name!r}')
            outputs[name] = torch.empty(
                self._context_shape(context, name), dtype=dtype, device=slot.input.device,
            )

        if callable(getattr(context, 'set_tensor_address', None)) and callable(getattr(context, 'execute_async_v3', None)):
            for name in self.binding_names:
                tensor = slot.input if name == self.input_name else outputs[name]
                ok = context.set_tensor_address(name, int(tensor.data_ptr()))
                if ok is False:
                    raise RuntimeError(f'TensorRT rejected static address for {name!r}')
            slot.binding_addresses = None
        elif callable(getattr(context, 'execute_async_v2', None)):
            addresses = [0] * len(self.binding_names)
            for name in self.binding_names:
                tensor = slot.input if name == self.input_name else outputs[name]
                addresses[self.binding_indices[name]] = int(tensor.data_ptr())
            if any(int(x) == 0 for x in addresses):
                raise RuntimeError('TensorRT v2 binding address table is incomplete')
            slot.binding_addresses = addresses
        else:
            raise RuntimeError('TensorRT context has no asynchronous enqueue API')
        return [outputs[name] for name in self.output_names]

    def _allocate_post_buffers(self, slot: _ResidentGpuPipelineSlot) -> None:
        torch = self.torch
        head, proto = slot.head, slot.proto
        anchors = int(head.shape[2])
        ph, pw = int(proto.shape[2]), int(proto.shape[3])
        device = head.device
        slot.compact_indices = torch.empty((anchors,), dtype=torch.int32, device=device)
        slot.compact_count = torch.zeros((1,), dtype=torch.int32, device=device)
        slot.max_logit = torch.empty((ph, pw), dtype=torch.float32, device=device)
        slot.conf_proto = (
            torch.empty((ph, pw), dtype=torch.float32, device=device) if self.track_conf else None
        )
        slot.native_union = torch.empty(
            (self.native_h, self.native_w), dtype=torch.uint8, device=device,
        )
        slot.native_conf = (
            torch.empty((self.native_h, self.native_w), dtype=torch.uint8, device=device)
            if self.track_conf else None
        )
        cp = self.kernels.cp
        refs = {
            'head': cp.asarray(head[0]),
            'proto': cp.asarray(proto[0]),
            'indices': cp.asarray(slot.compact_indices),
            'count': cp.asarray(slot.compact_count),
            'max_logit': cp.asarray(slot.max_logit),
            'native_union': cp.asarray(slot.native_union),
        }
        if slot.conf_proto is not None:
            refs['conf_proto'] = cp.asarray(slot.conf_proto)
        if slot.native_conf is not None:
            refs['native_conf'] = cp.asarray(slot.native_conf)
        slot._cupy_refs = refs

    def _execute_context(self, slot: _ResidentGpuPipelineSlot) -> None:
        context = slot.context
        handle = int(slot.infer_stream.cuda_stream)
        if slot.binding_addresses is None:
            try:
                ok = context.execute_async_v3(stream_handle=handle)
            except TypeError:
                ok = context.execute_async_v3(handle)
        else:
            try:
                ok = context.execute_async_v2(bindings=slot.binding_addresses, stream_handle=handle)
            except TypeError:
                ok = context.execute_async_v2(slot.binding_addresses, handle)
        if ok is False:
            raise RuntimeError(f'TensorRT enqueue failed for ring slot {slot.slot_id}')

    def _launch_post(self, slot: _ResidentGpuPipelineSlot) -> None:
        cp = self.kernels.cp
        refs = slot._cupy_refs
        head, proto = slot.head, slot.proto
        anchors = int(head.shape[2])
        masks = int(proto.shape[1])
        ph, pw = int(proto.shape[2]), int(proto.shape[3])
        external = _cupy_external_stream(cp, slot.post_stream)
        # _launch_post is always entered under torch.cuda.stream(post_stream), so this
        # clear and the external CuPy launches share the same capture-safe CUDA stream.
        slot.compact_count.zero_()
        compact = self.kernels.compact_f16 if head.dtype == self.torch.float16 else self.kernels.compact_f32
        compact(
            ((anchors + 255) // 256,), (256,),
            (refs['head'], np.int32(anchors), np.float32(self.confidence_threshold), refs['indices'], refs['count']),
            stream=external,
        )
        htag = 'f16' if head.dtype == self.torch.float16 else 'f32'
        ptag = 'f16' if proto.dtype == self.torch.float16 else 'f32'
        union_kernel = getattr(self.kernels, f'union_{htag}_{ptag}')
        conf_proto_arg = refs.get('conf_proto', np.uintp(0))
        pixels = ph * pw
        union_kernel(
            ((pixels + 255) // 256,), (256,),
            (
                refs['head'], refs['proto'], refs['indices'], refs['count'],
                np.int32(anchors), np.int32(masks), np.int32(ph), np.int32(pw),
                np.int32(self.out_size), np.int32(self.out_size), refs['max_logit'], conf_proto_arg,
            ),
            stream=external,
        )
        out_pixels = self.native_h * self.native_w
        if self.identity_native_warp:
            # Preserve the original radial/identity specialization byte-for-byte: proto
            # bilinear upsample to out_size, threshold, and nearest confidence sampling.
            self.kernels.upsample_quantize(
                ((out_pixels + 255) // 256,), (256,),
                (
                    refs['max_logit'], conf_proto_arg, np.int32(ph), np.int32(pw),
                    np.int32(self.out_size), np.int32(self.out_size), refs['native_union'],
                    refs.get('native_conf', np.uintp(0)),
                ),
                stream=external,
            )
        else:
            self.kernels.upsample_quantize_affine(
                ((out_pixels + 255) // 256,), (256,),
                (
                    refs['max_logit'], conf_proto_arg, np.int32(ph), np.int32(pw),
                    np.int32(self.out_size), np.int32(self.out_size),
                    np.int32(self.native_h), np.int32(self.native_w),
                    *self.native_to_out,
                    refs['native_union'], refs.get('native_conf', np.uintp(0)),
                ),
                stream=external,
            )

    def _validate_concurrent_contexts(self) -> None:
        """Enqueue both contexts concurrently before admitting the specialized source."""
        torch = self.torch
        for slot in self.slots:
            with torch.cuda.stream(slot.infer_stream):
                slot.input.zero_()
                self._execute_context(slot)
        # Synchronize only after both enqueues. TensorRT reports several profile/plugin
        # incompatibilities asynchronously, so checking the enqueue return alone is not
        # sufficient evidence that the two-context schedule is valid.
        first_error: Optional[BaseException] = None
        for slot in self.slots:
            try:
                slot.infer_stream.synchronize()
            except BaseException as exc:
                if first_error is None:
                    first_error = exc
        if first_error is not None:
            raise RuntimeError('resident TensorRT concurrent-context validation failed') from first_error

    def _capture_static_graphs(self, *, capture_graphs: bool = True) -> None:
        torch = self.torch
        # Runtime warmup is a capability test; graph capture itself is opportunistic.
        # Never confuse a failed TensorRT/CuPy launch with an unsupported CUDAGraph API:
        # the former must reject the ring before the source is consumed.
        for slot in self.slots:
            try:
                with torch.cuda.stream(slot.infer_stream):
                    slot.input.zero_()
                    self._execute_context(slot)
                slot.infer_stream.synchronize()
            except BaseException as exc:
                raise RuntimeError(
                    f'resident TensorRT infer warmup failed for ring slot {slot.slot_id}'
                ) from exc
            if bool(capture_graphs):
                try:
                    graph = torch.cuda.CUDAGraph()
                    with torch.cuda.graph(graph, stream=slot.infer_stream):
                        self._execute_context(slot)
                    slot.infer_stream.synchronize()
                    slot.infer_graph = graph
                    self.infer_graph_count += 1
                except Exception:
                    slot.infer_graph = None
                    try:
                        slot.infer_stream.synchronize()
                    except BaseException as sync_exc:
                        raise _ResidentTensorRTRingFatalError(
                            f'failed to recover TensorRT infer stream after graph capture '
                            f'for ring slot {slot.slot_id}'
                        ) from sync_exc
            try:
                with torch.cuda.stream(slot.post_stream):
                    self._launch_post(slot)
                slot.post_stream.synchronize()
            except BaseException as exc:
                raise RuntimeError(
                    f'resident TensorRT post-kernel warmup failed for ring slot {slot.slot_id}'
                ) from exc
            if bool(capture_graphs):
                try:
                    graph = torch.cuda.CUDAGraph()
                    with torch.cuda.graph(graph, stream=slot.post_stream):
                        self._launch_post(slot)
                    slot.post_stream.synchronize()
                    slot.post_graph = graph
                    self.post_graph_count += 1
                except Exception:
                    slot.post_graph = None
                    try:
                        slot.post_stream.synchronize()
                    except BaseException as sync_exc:
                        raise _ResidentTensorRTRingFatalError(
                            f'failed to recover post stream after graph capture '
                            f'for ring slot {slot.slot_id}'
                        ) from sync_exc

    def enqueue_inference(self, slot: _ResidentGpuPipelineSlot) -> None:
        torch = self.torch
        with torch.cuda.stream(slot.infer_stream):
            slot.infer_stream.wait_event(slot.render_done)
            if bool(slot.post_valid):
                # The preceding frame's mask kernel still reads this context's static
                # output buffers.  Do not let the next enqueue overwrite them early.
                slot.infer_stream.wait_event(slot.post_done)
            if slot.infer_graph is not None:
                slot.infer_graph.replay()
            else:
                self._execute_context(slot)
            slot.infer_done.record(slot.infer_stream)
        slot.infer_valid = True

    def enqueue_postprocess(
        self,
        slot: _ResidentGpuPipelineSlot,
        *,
        frame_index: int,
        device_union: '_DeviceUnionAccumulator',
        frame_counts_dev: object,
    ) -> None:
        torch = self.torch
        with torch.cuda.stream(slot.post_stream):
            slot.post_stream.wait_event(slot.infer_done)
            if slot.post_graph is not None:
                slot.post_graph.replay()
            else:
                self._launch_post(slot)
            # The static slot output is copied into the task-resident destination before
            # the slot is released.  No payload/result object or per-frame Future exists.
            device_union.union_dev[int(frame_index)].copy_(slot.native_union, non_blocking=True)
            if device_union.conf_dev is not None and slot.native_conf is not None:
                device_union.conf_dev[int(frame_index)].copy_(slot.native_conf, non_blocking=True)
            frame_counts_dev[int(frame_index)].copy_(slot.compact_count[0], non_blocking=True)
            slot.post_done.record(slot.post_stream)
        device_union.written[int(frame_index)] = True
        slot.post_valid = True

    def synchronize(self) -> None:
        for slot in self.slots:
            if bool(slot.post_valid):
                slot.post_done.synchronize()

    def reset_for_task(self) -> None:
        """Drain one task and retain contexts, bindings, buffers, and captured graphs."""
        if bool(getattr(self, '_closed', False)):
            raise RuntimeError('resident TensorRT executor is already closed')
        self.synchronize()
        for slot in self.slots:
            slot.infer_valid = False
            slot.post_valid = False
            slot.frame_index = -1
            slot.absolute_index = -1
            slot.synthetic = False

    def close(self) -> None:
        """Drain ring streams, then restore borrowed AutoBackend binding addresses.

        A failed drain or partial address restore is fatal: generic fallback must never run
        while a context can still write ring buffers or the borrowed backend points at storage
        this method is about to release.
        """
        if bool(getattr(self, '_closed', False)):
            return
        self._closed = True
        drain_error: Optional[BaseException] = None
        for slot in getattr(self, 'slots', []):
            for stream in (getattr(slot, 'infer_stream', None), getattr(slot, 'post_stream', None)):
                if stream is None:
                    continue
                try:
                    stream.synchronize()
                except BaseException as exc:
                    if drain_error is None:
                        drain_error = exc
        context = getattr(self, '_borrowed_context', None)
        restore = getattr(self, '_restore_tensor_addresses', {})
        restore_error: Optional[BaseException] = None
        if context is not None and restore:
            for name, address in restore.items():
                try:
                    ok = context.set_tensor_address(str(name), int(address))
                    if ok is False:
                        raise RuntimeError(f'TensorRT rejected restored address for {name!r}')
                except BaseException as exc:
                    if restore_error is None:
                        restore_error = exc
        # Release graph/context/output references promptly; the task-level device union
        # remains live for metadata, hole fill, and its single D2H drain.
        for slot in getattr(self, 'slots', []):
            slot.infer_graph = None
            slot.post_graph = None
            slot.render_graph = None
            slot.render_graph_key = None
            slot.render_expected_key = None
            slot.context = None
            slot.binding_addresses = None
            slot.head = None
            slot.proto = None
            slot.compact_indices = None
            slot.compact_count = None
            slot.max_logit = None
            slot.conf_proto = None
            slot.native_union = None
            slot.native_conf = None
            slot._cupy_refs.clear()
            slot._render_cupy_refs.clear()
        if restore_error is not None:
            raise _ResidentTensorRTRingFatalError(
                'failed to restore every AutoBackend TensorRT binding address; fallback is unsafe'
            ) from restore_error
        if drain_error is not None:
            raise _ResidentTensorRTRingFatalError(
                'failed to drain every resident TensorRT ring stream; fallback is unsafe'
            ) from drain_error


_RESIDENT_TRT_PIPELINE_CACHE_LOCK = threading.RLock()
_RESIDENT_TRT_PIPELINE_CACHE: Dict[int, Dict[str, object]] = {}
_RESIDENT_TRT_PIPELINE_CACHE_NATIVE = True
_RESIDENT_TRT_RING_CACHE_HIT_ANNOUNCED = False


def resident_trt_pipeline_persistence_enabled() -> bool:
    return _env_flag('YOLO_TTA_PERSISTENT_TRT_RING', True)


def _resident_trt_pipeline_signature(
    backend: object,
    input_dtype: object,
    *,
    out_size: int,
    native_h: int,
    native_w: int,
    M_out_to_native: np.ndarray,
    track_conf: bool,
    confidence_threshold: float,
) -> Tuple[object, ...]:
    engine = _trt_engine_from_autobackend(backend)
    matrix = tuple(float(x) for x in np.asarray(M_out_to_native, dtype=np.float32).reshape(-1))
    return (
        id(engine), str(input_dtype), int(out_size), int(native_h), int(native_w),
        matrix, bool(track_conf), float(confidence_threshold),
    )


def _resident_trt_pipeline_invalidate(backend: object, reason: Optional[BaseException] = None) -> None:
    entry: Optional[Dict[str, object]] = None
    with _RESIDENT_TRT_PIPELINE_CACHE_LOCK:
        entry = _RESIDENT_TRT_PIPELINE_CACHE.pop(id(backend), None)
    if entry is None:
        return
    executor = entry.get('executor')
    try:
        close = getattr(executor, 'close', None)
        if callable(close):
            close()
    except _ResidentTensorRTRingFatalError:
        raise
    except Exception as exc:
        if reason is None:
            print(f'Warning: resident TensorRT pipeline teardown failed ({exc}).')


def _resident_trt_pipeline_decline(backend: Optional[object]) -> None:
    """Restore AutoBackend before any non-resident fallback uses its borrowed context."""
    if backend is not None:
        _resident_trt_pipeline_invalidate(backend)


def _resident_trt_pipeline_acquire(
    backend: object,
    source: 'GpuRenderedYoloSource',
    *,
    input_dtype: object,
    out_size: int,
    native_h: int,
    native_w: int,
    M_out_to_native: np.ndarray,
    track_conf: bool,
    confidence_threshold: float,
) -> Tuple['_ResidentTensorRTRingExecutor', bool]:
    """Acquire the actual executor, not merely its two render slots (v13.3.15 P1)."""
    persist = bool(resident_trt_pipeline_persistence_enabled())
    if not persist:
        _resident_trt_pipeline_decline(backend)
    signature = _resident_trt_pipeline_signature(
        backend, input_dtype,
        out_size=int(out_size), native_h=int(native_h), native_w=int(native_w),
        M_out_to_native=M_out_to_native, track_conf=bool(track_conf),
        confidence_threshold=float(confidence_threshold),
    )
    stale: Optional[Dict[str, object]] = None
    with _RESIDENT_TRT_PIPELINE_CACHE_LOCK:
        entry = _RESIDENT_TRT_PIPELINE_CACHE.get(id(backend))
        if persist and entry is not None and entry.get('signature') == signature:
            if bool(entry.get('in_use', False)):
                raise RuntimeError('resident TensorRT executor cache re-entered concurrently')
            executor = entry['executor']
            entry['in_use'] = True
            entry['last_used'] = time.monotonic()
        else:
            if entry is not None:
                stale = _RESIDENT_TRT_PIPELINE_CACHE.pop(id(backend), None)
            executor = None
    if stale is not None:
        close = getattr(stale.get('executor'), 'close', None)
        if callable(close):
            close()

    if executor is not None:
        try:
            executor.reset_for_task()
            source._direct_ring = executor.slots
            slots = source.prepare_direct_ring(input_dtype=input_dtype)
            if len(slots) != 2 or any(a is not b for a, b in zip(slots, executor.slots)):
                raise RuntimeError('cached TensorRT executor did not retain its static ring slots')
            return executor, True
        except Exception as exc:
            source._direct_ring = None
            _resident_trt_pipeline_invalidate(backend, exc)
            raise

    slots = source.prepare_direct_ring(input_dtype=input_dtype)
    if slots is None or len(slots) != 2:
        raise RuntimeError('resident source did not provide two static ring slots')
    executor = _ResidentTensorRTRingExecutor(
        backend, slots, out_size=int(out_size),
        native_h=int(native_h), native_w=int(native_w),
        M_out_to_native=np.asarray(M_out_to_native, dtype=np.float32),
        track_conf=bool(track_conf), confidence_threshold=float(confidence_threshold),
    )
    if persist:
        with _RESIDENT_TRT_PIPELINE_CACHE_LOCK:
            _RESIDENT_TRT_PIPELINE_CACHE[id(backend)] = {
                'backend': backend, 'signature': signature, 'executor': executor,
                'in_use': True, 'last_used': time.monotonic(),
            }
    else:
        executor._resident_trt_transient = True
    return executor, False


def _resident_trt_pipeline_release(
    backend: object,
    executor: '_ResidentTensorRTRingExecutor',
    source: Optional['GpuRenderedYoloSource'] = None,
) -> None:
    try:
        executor.reset_for_task()
    except Exception as exc:
        _resident_trt_pipeline_invalidate(backend, exc)
        raise
    with _RESIDENT_TRT_PIPELINE_CACHE_LOCK:
        entry = _RESIDENT_TRT_PIPELINE_CACHE.get(id(backend))
        if entry is None or entry.get('executor') is not executor:
            if bool(getattr(executor, '_resident_trt_transient', False)):
                if source is not None:
                    source._direct_ring = None
                executor.close()
                return
            raise RuntimeError('resident TensorRT executor disappeared before release')
        entry['in_use'] = False
        entry['last_used'] = time.monotonic()
    if source is not None:
        source._direct_ring = None


def _shutdown_resident_trt_pipeline_cache() -> None:
    with _RESIDENT_TRT_PIPELINE_CACHE_LOCK:
        entries = list(_RESIDENT_TRT_PIPELINE_CACHE.values())
        _RESIDENT_TRT_PIPELINE_CACHE.clear()
    for entry in entries:
        try:
            close = getattr(entry.get('executor'), 'close', None)
            if callable(close):
                close()
        except Exception as exc:
            print(f'Warning: resident TensorRT executor shutdown failed ({exc}).')


def _try_resident_trt_ring_accumulate(
    predictor: object,
    source: object,
    cfg: 'PredictConfig',
    *,
    source_label: str,
    num_frames: int,
    out_size: int,
    M_out_to_native: np.ndarray,
    native_h: int,
    native_w: int,
    device_union: Optional['_DeviceUnionAccumulator'],
) -> Optional[Dict[str, int]]:
    """Run the fixed batch-1 resident task through a worker-lifetime TensorRT executor."""
    global _RESIDENT_TRT_RING_ANNOUNCED, _RESIDENT_TRT_RING_FALLBACK_WARNED
    global _RESIDENT_TRT_RING_CACHE_HIT_ANNOUNCED
    backend = getattr(predictor, 'model', None)

    def _decline() -> Optional[Dict[str, int]]:
        _resident_trt_pipeline_decline(backend)
        return None

    if not resident_trt_ring_enabled() or device_union is None:
        return _decline()
    if not isinstance(source, GpuRenderedYoloSource):
        return _decline()
    try:
        union_shape = tuple(int(x) for x in device_union.union_dev.shape)
        expected_shape = (int(num_frames), int(native_h), int(native_w))
        if union_shape != expected_shape:
            return _decline()
        if device_union.conf_dev is not None and tuple(int(x) for x in device_union.conf_dev.shape) != expected_shape:
            return _decline()
        if str(device_union.union_dev.device) != str(source.engine.device):
            return _decline()
    except Exception:
        return _decline()
    fastpath = single_angle_gpu_fastpath()
    identity_native_warp = bool(
        int(native_h) == int(out_size)
        and int(native_w) == int(out_size)
        and _warp_matrix_is_identity(M_out_to_native)
    )
    if (
        int(cfg.batch) != 1 or int(getattr(source, 'bs', 0)) != 1
        or int(getattr(source, 'nf', -1)) != int(num_frames)
        or abs(float(getattr(getattr(source, 'job', None), 'angle_deg', 999.0))) > 1e-7
        or str(getattr(getattr(source, 'engine', None), '_mode', '')) != 'resident'
        or fastpath is None or float(fastpath[1]) > 0.0
        or (not identity_native_warp and not resident_trt_native_warp_enabled())
    ):
        return _decline()
    trt_engine = None if backend is None else _trt_engine_from_autobackend(backend)
    if backend is None or trt_engine is None or bool(getattr(backend, 'dynamic', False)):
        return _decline()
    prepare = getattr(source, 'prepare_direct_ring', None)
    next_slot = getattr(source, 'next_direct_slot', None)
    if not callable(prepare) or not callable(next_slot):
        return _decline()

    executor: Optional[_ResidentTensorRTRingExecutor] = None
    cache_hit = False
    try:
        import torch  # type: ignore
        _names, input_name, _outputs, _indices = _trt_binding_layout_for_backend(backend, trt_engine)
        input_dtype = _torch_dtype_for_trt_binding(backend, trt_engine, input_name, torch)
        if input_dtype not in (torch.float16, torch.float32):
            raise RuntimeError(f'resident ring cannot allocate unsupported TensorRT input dtype {input_dtype}')
        threshold = max(float(cfg.conf), float(fastpath[0]))
        executor, cache_hit = _resident_trt_pipeline_acquire(
            backend, source, input_dtype=input_dtype,
            out_size=int(out_size), native_h=int(native_h), native_w=int(native_w),
            M_out_to_native=np.asarray(M_out_to_native, dtype=np.float32),
            track_conf=device_union.conf_dev is not None,
            confidence_threshold=float(threshold),
        )
    except _ResidentTensorRTRingFatalError:
        raise
    except Exception as exc:
        try:
            source.reset_direct_ring()
        except Exception:
            pass
        _resident_trt_pipeline_decline(backend)
        if not _RESIDENT_TRT_RING_FALLBACK_WARNED:
            _RESIDENT_TRT_RING_FALLBACK_WARNED = True
            print(
                f'Resident TensorRT ring unavailable ({exc}); using the existing direct predict loop. '
                'YOLO_TTA_RESIDENT_TRT_RING=0 suppresses this capability probe.'
            )
        return None

    pending: 'deque[Tuple[int, _ResidentGpuPipelineSlot]]' = deque()
    try:
        frame_counts_dev = torch.zeros(
            (int(num_frames),), dtype=torch.int32, device=device_union.device,
        )
        for _ in range(min(2, int(num_frames))):
            item = next_slot()
            if item is None:
                break
            frame_idx, slot = item
            executor.enqueue_inference(slot)
            pending.append((int(frame_idx), slot))
        submitted = len(pending)
        while pending:
            frame_idx, slot = pending.popleft()
            executor.enqueue_postprocess(
                slot, frame_index=int(frame_idx), device_union=device_union,
                frame_counts_dev=frame_counts_dev,
            )
            if submitted < int(num_frames):
                item = next_slot()
                if item is None:
                    raise RuntimeError(
                        f'resident TensorRT ring source ended at {submitted}/{int(num_frames)} frames'
                    )
                next_idx, next_pipeline_slot = item
                executor.enqueue_inference(next_pipeline_slot)
                pending.append((int(next_idx), next_pipeline_slot))
                submitted += 1
        executor.synchronize()
        prediction_count = int(frame_counts_dev.sum(dtype=torch.int64).item())
        frames_with_predictions = int((frame_counts_dev > 0).sum(dtype=torch.int64).item())
    except Exception as exc:
        source._direct_ring = None
        _resident_trt_pipeline_invalidate(backend, exc)
        raise
    else:
        _resident_trt_pipeline_release(backend, executor, source)

    if cache_hit and not _RESIDENT_TRT_RING_CACHE_HIT_ANNOUNCED:
        _RESIDENT_TRT_RING_CACHE_HIT_ANNOUNCED = True
        print(
            'Resident TensorRT executor persistence active (v13.3.15 P1): contexts, '
            'bindings, output buffers, streams, and CUDA graphs are reused across worker tasks.'
        )
    if not _RESIDENT_TRT_RING_ANNOUNCED:
        _RESIDENT_TRT_RING_ANNOUNCED = True
        print(
            'Resident TensorRT batch-1 ring active: two independent execution contexts, '
            'two static input/output slots, low-priority render, high-priority inference, '
            f'separate mask/union streams, post-warp='
            f'{"identity" if executor.identity_native_warp else "fused-native-affine"}; '
            f'CUDA graphs captured infer={executor.infer_graph_count}/2 '
            f'post={executor.post_graph_count}/2.'
        )
    return {
        'prediction_count': int(prediction_count),
        'frames_with_predictions': int(frames_with_predictions),
    }

def _stage_radial_t_major_block(
    radial_mask_mm: np.ndarray,
    v0: int,
    v1: int,
    out_t_major: np.ndarray,
    *,
    slice_bboxes: Optional[np.ndarray] = None,
    stage_pool: Optional[ThreadPoolExecutor] = None,
    stage_workers: int = 1,
) -> np.ndarray:
    """Stage one contiguous radial row block as ``(t, azimuth, u)``.

    The legacy projection repeatedly gathered ``source[:, t, :]``, which is the slow axis of
    the azimuth-major interpolation volume.  Dense sources are transposed one block at a time;
    sparse bridge deltas use their interpolation-carried bboxes and copy only intersecting crop
    rows.  The returned view always has exactly ``v1-v0`` rows.
    """
    n_az, work_t, u_len = (int(v) for v in radial_mask_mm.shape)
    lo = int(np.clip(int(v0), 0, work_t))
    hi = int(np.clip(int(v1), lo, work_t))
    count = int(hi - lo)
    dest = np.asarray(out_t_major)[:count, :n_az, :u_len]
    if count <= 0:
        return dest
    if slice_bboxes is None:
        np.copyto(
            dest,
            np.transpose(np.asarray(radial_mask_mm[:, lo:hi, :], dtype=np.uint8), (1, 0, 2)),
        )
        return dest

    # A bridge delta is sparse by azimuth plane. Clearing one bounded t-major staging block
    # is much cheaper than reading all of the source volume's implicit zero regions.
    dest.fill(np.uint8(0))
    workers_i = max(1, min(int(stage_workers), int(n_az)))

    def _stage_az_range(worker_idx: int) -> None:
        a0 = int(worker_idx) * int(math.ceil(float(n_az) / float(workers_i)))
        a1 = min(int(n_az), a0 + int(math.ceil(float(n_az) / float(workers_i))))
        for az in range(a0, a1):
            by0, by1, bx0, bx1 = (int(v) for v in slice_bboxes[int(az)])
            sy0 = max(int(lo), int(by0))
            sy1 = min(int(hi), int(by1))
            if sy0 >= sy1 or bx0 >= bx1:
                continue
            dest[sy0 - lo:sy1 - lo, int(az), bx0:bx1] = np.asarray(
                radial_mask_mm[int(az), sy0:sy1, bx0:bx1], dtype=np.uint8,
            )

    if stage_pool is not None and workers_i > 1:
        list(stage_pool.map(_stage_az_range, range(workers_i)))
    else:
        for worker_idx in range(workers_i):
            _stage_az_range(int(worker_idx))
    return dest


def _abort_projection_block_callback(
    callback: Optional[Callable[[int, np.ndarray], None]],
    reason: BaseException,
) -> None:
    """Invalidate a stateful projection callback without changing projection semantics."""
    if callback is None:
        return
    abort = getattr(callback, 'abort', None)
    if callable(abort):
        try:
            abort(reason)
        except Exception:
            pass


def _emit_projection_block_callback(
    callback: Optional[Callable[[int, np.ndarray], None]],
    z0: int,
    block: np.ndarray,
    *,
    desc: str,
    required: bool = False,
) -> None:
    """Deliver a completed projection block.

    Dense projections retain the historical best-effort tee: if the incremental store
    rejects a block, the complete dense raster is still authoritative.  v13.3.17 C2 adds
    ``required`` for sink-only projections.  With no redundant dense raster to recover
    from, callback failure aborts the transaction and propagates immediately so the
    materializer can discard the partial store and rerun through the dense fallback.
    """
    if callback is None:
        if bool(required):
            raise RuntimeError(f'{desc}: sink-only projection requires a block consumer')
        return
    try:
        callback(int(z0), np.asarray(block))
    except Exception as exc:
        _abort_projection_block_callback(callback, exc)
        if bool(required):
            raise
        warn = getattr(callback, 'warn_failed_once', None)
        if callable(warn):
            try:
                warn(f'{desc}: incremental raw-bbox callback failed ({exc})')
            except Exception:
                pass


def _emit_projection_empty_range(
    callback: Optional[Callable[[int, np.ndarray], None]],
    z0: int,
    count: int,
    plane_shape: Tuple[int, int],
    *,
    desc: str,
    required: bool = False,
) -> None:
    """Deliver a proven-empty range without constructing dense planes when supported."""
    count_i = max(0, int(count))
    if count_i <= 0:
        return
    if callback is None:
        if bool(required):
            raise RuntimeError(f'{desc}: sink-only projection requires an empty-range consumer')
        return
    empty_consumer = getattr(callback, 'consume_empty_range', None)
    if callable(empty_consumer):
        try:
            empty_consumer(int(z0), int(count_i))
            return
        except Exception as exc:
            _abort_projection_block_callback(callback, exc)
            if bool(required):
                raise
            warn = getattr(callback, 'warn_failed_once', None)
            if callable(warn):
                try:
                    warn(f'{desc}: incremental empty-range callback failed ({exc})')
                except Exception:
                    pass
            return
    # Compatibility callbacks that predate consume_empty_range still receive a normal
    # block.  This allocation is bounded by one projection chunk, never the full raster.
    _emit_projection_block_callback(
        callback,
        int(z0),
        np.zeros((int(count_i), int(plane_shape[0]), int(plane_shape[1])), dtype=np.uint8),
        desc=desc,
        required=bool(required),
    )


@dataclass(frozen=True)
class SinkOnlyProjectionResult:
    """Successful projection whose complete representation lives in its block sink."""

    shape: Tuple[int, int, int]


_RADIAL_RESIDENT_BACKPROJECT_KERNEL: Optional[object] = None
_RADIAL_RESIDENT_BACKPROJECT_KERNEL_FAILED = False
_RADIAL_RESIDENT_BACKPROJECT_KERNEL_ERROR: Optional[str] = None


def gpu_resident_radial_backproject_enabled() -> bool:
    return _env_flag('YOLO_TTA_GPU_BACKPROJECT_RESIDENT', True)


def fused_single_angle_radial_component_layer_enabled() -> bool:
    """C12: project one post-interpolation Radial union in the single-angle fast path."""
    return _env_flag('YOLO_TTA_FUSED_SINGLE_ANGLE_RADIAL_LAYER', True)


def _radial_resident_backproject_kernel() -> Optional[object]:
    global _RADIAL_RESIDENT_BACKPROJECT_KERNEL
    global _RADIAL_RESIDENT_BACKPROJECT_KERNEL_FAILED, _RADIAL_RESIDENT_BACKPROJECT_KERNEL_ERROR
    if _RADIAL_RESIDENT_BACKPROJECT_KERNEL is not None:
        return _RADIAL_RESIDENT_BACKPROJECT_KERNEL
    if _RADIAL_RESIDENT_BACKPROJECT_KERNEL_FAILED:
        return None
    try:
        import cupy as cp  # type: ignore
        code = r'''
        extern "C" __global__ void radial_backproject_azmajor_u8(
            const unsigned char* radial, int n_az, int work_t, int u_len,
            const int* source_idx, const int* u_idx, int plane_px,
            int output_t, int output_t0, int output_count, unsigned char* output) {
          long long q0 = (long long)blockDim.x * (long long)blockIdx.x + (long long)threadIdx.x;
          long long stride = (long long)blockDim.x * (long long)gridDim.x;
          long long total = (long long)output_count * (long long)plane_px;
          for (long long q = q0; q < total; q += stride) {
            int local_t = (int)(q / (long long)plane_px);
            int p = (int)(q - (long long)local_t * (long long)plane_px);
            int az = source_idx[p];
            int u = u_idx[p];
            if (az < 0 || az >= n_az || u < 0 || u >= u_len) {
              output[q] = 0;
              continue;
            }
            int t = output_t0 + local_t;
            int v0 = (int)(((long long)t * (long long)work_t) / (long long)output_t);
            int v1 = (int)((((long long)(t + 1) * (long long)work_t) + output_t - 1) / (long long)output_t);
            if (v0 < 0) v0 = 0;
            if (v1 > work_t) v1 = work_t;
            if (v1 <= v0) v1 = v0 + 1 <= work_t ? v0 + 1 : work_t;
            unsigned char value = 0;
            long long az_base = (long long)az * (long long)work_t * (long long)u_len;
            for (int v = v0; v < v1; ++v) {
              unsigned char candidate = radial[az_base + (long long)v * (long long)u_len + (long long)u];
              value = candidate > value ? candidate : value;
            }
            output[q] = value;
          }
        }

        extern "C" __global__ void radial_backproject_tmajor_u8(
            const unsigned char* radial, int n_az, int work_t, int u_len,
            const int* source_idx, const int* u_idx, int plane_px,
            int output_t, int output_t0, int output_count, unsigned char* output) {
          long long q0 = (long long)blockDim.x * (long long)blockIdx.x + (long long)threadIdx.x;
          long long stride = (long long)blockDim.x * (long long)gridDim.x;
          long long total = (long long)output_count * (long long)plane_px;
          for (long long q = q0; q < total; q += stride) {
            int local_t = (int)(q / (long long)plane_px);
            int p = (int)(q - (long long)local_t * (long long)plane_px);
            int az = source_idx[p];
            int u = u_idx[p];
            if (az < 0 || az >= n_az || u < 0 || u >= u_len) {
              output[q] = 0;
              continue;
            }
            int t = output_t0 + local_t;
            int v0 = (int)(((long long)t * (long long)work_t) / (long long)output_t);
            int v1 = (int)((((long long)(t + 1) * (long long)work_t) + output_t - 1) / (long long)output_t);
            if (v0 < 0) v0 = 0;
            if (v1 > work_t) v1 = work_t;
            if (v1 <= v0) v1 = v0 + 1 <= work_t ? v0 + 1 : work_t;
            unsigned char value = 0;
            for (int v = v0; v < v1; ++v) {
              long long index = ((long long)v * (long long)n_az + (long long)az)
                              * (long long)u_len + (long long)u;
              unsigned char candidate = radial[index];
              value = candidate > value ? candidate : value;
            }
            output[q] = value;
          }
        }

        extern "C" __global__ void radial_azmajor_to_tmajor_u8(
            const unsigned char* source, int n_az, int work_t, int u_len,
            unsigned char* target) {
          long long q0 = (long long)blockDim.x * (long long)blockIdx.x + (long long)threadIdx.x;
          long long stride = (long long)blockDim.x * (long long)gridDim.x;
          long long total = (long long)n_az * (long long)work_t * (long long)u_len;
          for (long long q = q0; q < total; q += stride) {
            int u = (int)(q % (long long)u_len);
            long long av = q / (long long)u_len;
            int v = (int)(av % (long long)work_t);
            int az = (int)(av / (long long)work_t);
            target[((long long)v * (long long)n_az + (long long)az) * (long long)u_len + (long long)u]
                = source[q];
          }
        }
        '''
        module = cp.RawModule(code=code, options=('--std=c++14',))
        compile_fn = getattr(module, 'compile', None)
        if callable(compile_fn):
            compile_fn()
        kernel_azmajor = module.get_function('radial_backproject_azmajor_u8')
        _RADIAL_RESIDENT_BACKPROJECT_KERNEL = argparse.Namespace(
            cp=cp,
            module=module,
            kernel=kernel_azmajor,  # compatibility alias
            kernel_azmajor=kernel_azmajor,
            kernel_tmajor=module.get_function('radial_backproject_tmajor_u8'),
            transpose=module.get_function('radial_azmajor_to_tmajor_u8'),
        )
        return _RADIAL_RESIDENT_BACKPROJECT_KERNEL
    except Exception as exc:
        _RADIAL_RESIDENT_BACKPROJECT_KERNEL_FAILED = True
        _RADIAL_RESIDENT_BACKPROJECT_KERNEL_ERROR = f'{type(exc).__name__}: {exc}'
        print(
            'Warning: resident Radial backprojection kernel unavailable '
            f'({_RADIAL_RESIDENT_BACKPROJECT_KERNEL_ERROR}); using the streaming GPU path.'
        )
        return None


def _radial_backproject_gpu_resident(
    radial_mask_mm: np.ndarray,
    vol_mm: Optional[np.ndarray],
    valid_mask: np.ndarray,
    source_idx_map: np.ndarray,
    u_idx_map: np.ndarray,
    v_range_for_t: Callable[[int], Tuple[int, int]],
    t_dim: int,
    out_h: int,
    out_w: int,
    desc: str,
    known_row_occupancy: Optional[np.ndarray] = None,
    projection_block_callback: Optional[Callable[[int, np.ndarray], None]] = None,
    sink_only: bool = False,
) -> bool:
    """Project a fully resident radial source with staged upload/commit overlap.

    v13.3.16 R24 keeps R23's one-time source upload but fixes the two serial sections
    visible in run 126080: two pinned source slots overlap host reads with H2D, and two
    output slots let the next CUDA chunk run while the previous dense block is copied to
    the destination and encoded into the incremental cvol. When VRAM permits, one device
    transpose changes the source from (azimuth,t,u) to (t,azimuth,u), reducing the dominant
    per-warp azimuth stride from work_t*u bytes to u bytes. Every stage retains an automatic
    fallback to the v13.3.15 azimuth-major/single-slot behavior.
    """
    if not gpu_resident_radial_backproject_enabled():
        return False
    kernels = _radial_resident_backproject_kernel()
    if kernels is None:
        return False
    try:
        import torch  # type: ignore
        if not bool(torch.cuda.is_available()):
            return False
    except Exception:
        return False
    dev = _pick_gpu_compute_device(torch)
    n_az, work_t, u_len = (int(v) for v in radial_mask_mm.shape)
    plane_px = int(out_h) * int(out_w)
    t_chunk = max(1, _env_int('YOLO_TTA_GPU_BACKPROJECT_RESIDENT_T_CHUNK', 64))
    requested_pipeline_slots = max(1, min(3, _env_int(
        'YOLO_TTA_GPU_BACKPROJECT_RESIDENT_PIPELINE_SLOTS', 2,
    )))
    reserve = int(max(0.0, _env_float('YOLO_TTA_GPU_BACKPROJECT_RESIDENT_RESERVE_GIB', 4.0)) * GIB)
    source_bytes = int(radial_mask_mm.nbytes)
    map_bytes = int(plane_px) * 2 * np.dtype(np.int32).itemsize
    output_bytes = int(t_chunk) * int(plane_px)
    base_need = int(
        source_bytes + map_bytes + int(requested_pipeline_slots) * output_bytes
        + 256 * 1024 * 1024
    )
    try:
        free_bytes, _total = torch.cuda.mem_get_info(dev)
    except Exception:
        return False
    while t_chunk > 8 and int(free_bytes) < int(base_need) + int(reserve):
        t_chunk //= 2
        output_bytes = int(t_chunk) * int(plane_px)
        base_need = int(
            source_bytes + map_bytes + int(requested_pipeline_slots) * output_bytes
            + 256 * 1024 * 1024
        )
    if int(free_bytes) < int(base_need) + int(reserve):
        print(
            f'{desc}: full-resident GPU backprojection skipped (need≈{base_need / GIB:.1f} GiB '
            f'+ {reserve / GIB:.1f} GiB reserve, free={int(free_bytes) / GIB:.1f} GiB).'
        )
        return False

    if known_row_occupancy is not None and int(np.asarray(known_row_occupancy).shape[0]) == int(work_t):
        row_any = np.asarray(known_row_occupancy, dtype=bool)
    else:
        row_any = _radial_row_occupancy(radial_mask_mm, desc)
    source_flat = np.where(
        np.asarray(valid_mask, dtype=bool), np.asarray(source_idx_map, dtype=np.int32), np.int32(-1),
    ).reshape(-1)
    u_flat = np.where(
        np.asarray(valid_mask, dtype=bool), np.asarray(u_idx_map, dtype=np.int32), np.int32(0),
    ).reshape(-1)
    source_flat = np.ascontiguousarray(source_flat, dtype=np.int32)
    u_flat = np.ascontiguousarray(u_flat, dtype=np.int32)

    upload_target = max(64 * 1024 * 1024, _env_int(
        'YOLO_TTA_GPU_BACKPROJECT_RESIDENT_UPLOAD_MIB', 512,
    ) * 1024 * 1024)
    bytes_per_azimuth = max(1, int(work_t) * int(u_len))
    az_chunk = max(1, min(int(n_az), int(upload_target) // int(bytes_per_azimuth)))
    cp = kernels.cp
    dev_index = getattr(dev, 'index', None)
    if dev_index is None:
        try:
            dev_index = int(torch.cuda.current_device())
        except Exception:
            dev_index = 0
    compute_stream = torch.cuda.Stream(device=dev)
    copy_stream = torch.cuda.Stream(device=dev)
    phase_start = time.perf_counter()
    upload_seconds = 0.0
    transpose_seconds = 0.0
    projection_seconds = 0.0
    commit_cpu_seconds = 0.0
    radial_dev = tmajor_dev = source_dev = u_dev = None
    out_dev_slots: List[object] = []
    pin_src_slots: List[object] = []
    pin_out_slots: List[object] = []
    commit_pool: Optional[ThreadPoolExecutor] = None
    commit_futures: List[Optional[Future]] = []
    try:
        # Torch and CuPy keep independent current-device state. Pin both explicitly so
        # the late-tail scheduler may choose any visible GPU, not only cuda:0.
        with torch.cuda.device(dev), cp.cuda.Device(int(dev_index)), torch.cuda.stream(compute_stream):
            radial_dev = torch.empty((n_az, work_t, u_len), dtype=torch.uint8, device=dev)

            requested_upload_slots = max(1, min(3, _env_int(
                'YOLO_TTA_GPU_BACKPROJECT_RESIDENT_UPLOAD_SLOTS', 2,
            )))
            for _ in range(int(requested_upload_slots)):
                try:
                    pin_src_slots.append(torch.empty(
                        (az_chunk, work_t, u_len), dtype=torch.uint8, pin_memory=True,
                    ))
                except Exception:
                    break
            if not pin_src_slots:
                pin_src_slots.append(torch.empty(
                    (az_chunk, work_t, u_len), dtype=torch.uint8, pin_memory=True,
                ))
            pin_src_arrays = [slot.numpy() for slot in pin_src_slots]
            upload_events: List[Optional[object]] = [None] * len(pin_src_slots)
            upload_t0 = time.perf_counter()
            for chunk_idx, a0 in enumerate(tqdm(
                range(0, n_az, az_chunk), desc=f'{desc} [resident H2D]',
            )):
                slot_idx = int(chunk_idx) % len(pin_src_slots)
                prior = upload_events[slot_idx]
                if prior is not None:
                    prior.synchronize()
                a1 = min(n_az, a0 + az_chunk)
                count = int(a1 - a0)
                np.copyto(
                    pin_src_arrays[slot_idx][:count],
                    np.asarray(radial_mask_mm[a0:a1], dtype=np.uint8),
                )
                radial_dev[a0:a1].copy_(pin_src_slots[slot_idx][:count], non_blocking=True)
                event = torch.cuda.Event(blocking=False)
                event.record(compute_stream)
                upload_events[slot_idx] = event
            compute_stream.synchronize()
            upload_seconds = time.perf_counter() - upload_t0

            source_dev = torch.from_numpy(source_flat).to(dev, non_blocking=False)
            u_dev = torch.from_numpy(u_flat).to(dev, non_blocking=False)
            external = _cupy_external_stream(cp, compute_stream)
            cp_source = cp.asarray(source_dev)
            cp_u = cp.asarray(u_dev)

            layout = 'azimuth-major'
            compute_kernel = kernels.kernel_azmajor
            compute_tensor = radial_dev
            tmajor_peak = int(
                2 * source_bytes + map_bytes
                + int(requested_pipeline_slots) * output_bytes
                + 256 * 1024 * 1024
            )
            if (
                _env_flag('YOLO_TTA_GPU_BACKPROJECT_RESIDENT_TMAJOR', True)
                and int(free_bytes) >= int(tmajor_peak) + int(reserve)
            ):
                transpose_t0 = time.perf_counter()
                try:
                    tmajor_dev = torch.empty((work_t, n_az, u_len), dtype=torch.uint8, device=dev)
                    cp_azmajor = cp.asarray(radial_dev)
                    cp_tmajor = cp.asarray(tmajor_dev)
                    total_source = int(n_az) * int(work_t) * int(u_len)
                    transpose_blocks = max(1, min(
                        (int(total_source) + 255) // 256,
                        _env_int('YOLO_TTA_GPU_BACKPROJECT_RESIDENT_CUDA_BLOCKS', 65535),
                    ))
                    kernels.transpose(
                        (int(transpose_blocks),), (256,),
                        (
                            cp_azmajor, np.int32(n_az), np.int32(work_t), np.int32(u_len),
                            cp_tmajor,
                        ),
                        stream=external,
                    )
                    compute_stream.synchronize()
                    compute_tensor = tmajor_dev
                    compute_kernel = kernels.kernel_tmajor
                    layout = 't-major'
                except Exception as exc:
                    tmajor_dev = None
                    compute_tensor = radial_dev
                    compute_kernel = kernels.kernel_azmajor
                    print(f'{desc}: t-major resident transpose unavailable ({exc}); using azimuth-major layout.')
                transpose_seconds = time.perf_counter() - transpose_t0

            cp_radial = cp.asarray(compute_tensor)
            # C12: allocate output device and pinned-host slots as pairs. A slot is not
            # reused until its D2H event and CPU sink commit have both completed; another
            # slot can therefore run the next projection while copy/packing proceeds.
            for _ in range(int(requested_pipeline_slots)):
                try:
                    out_dev_slots.append(torch.empty(
                        (t_chunk, plane_px), dtype=torch.uint8, device=dev,
                    ))
                    pin_out_slots.append(torch.empty(
                        (t_chunk, plane_px), dtype=torch.uint8, pin_memory=True,
                    ))
                except Exception:
                    if len(out_dev_slots) > len(pin_out_slots):
                        out_dev_slots.pop()
                    break
            if not out_dev_slots:
                out_dev_slots.append(torch.empty(
                    (t_chunk, plane_px), dtype=torch.uint8, device=dev,
                ))
                pin_out_slots.append(torch.empty(
                    (t_chunk, plane_px), dtype=torch.uint8, pin_memory=True,
                ))
            cp_out_slots = [cp.asarray(slot) for slot in out_dev_slots]
            pin_out_arrays = [slot.numpy() for slot in pin_out_slots]
            commit_futures = [None] * len(pin_out_slots)
            commit_pool = _acquire_parallel_pool(len(pin_out_slots))

            def _commit_block(t0_i: int, t1_i: int, block_i: np.ndarray) -> float:
                started = time.perf_counter()
                if vol_mm is not None:
                    np.copyto(np.asarray(vol_mm[int(t0_i):int(t1_i)]), block_i)
                _emit_projection_block_callback(
                    projection_block_callback,
                    int(t0_i),
                    block_i,
                    desc=desc,
                    required=bool(sink_only),
                )
                return float(time.perf_counter() - started)

            def _settle_commit(slot_idx: int) -> None:
                nonlocal commit_cpu_seconds
                fut = commit_futures[int(slot_idx)]
                if fut is not None:
                    commit_cpu_seconds += float(fut.result())
                    commit_futures[int(slot_idx)] = None

            def _commit_after_copy(
                copy_done: object,
                t0_i: int,
                t1_i: int,
                block_i: np.ndarray,
            ) -> float:
                copy_done.synchronize()
                return _commit_block(int(t0_i), int(t1_i), block_i)

            projection_t0 = time.perf_counter()
            scheduled_idx = 0
            for _chunk_idx, t0 in enumerate(tqdm(
                range(0, int(t_dim), int(t_chunk)), desc=f'{desc} [resident gpu]',
            )):
                t1 = min(int(t_dim), int(t0) + int(t_chunk))
                v0 = v_range_for_t(int(t0))[0]
                v1 = v_range_for_t(int(t1 - 1))[1]
                if not bool(np.any(row_any[int(v0):int(v1)])):
                    _emit_projection_empty_range(
                        projection_block_callback,
                        int(t0),
                        int(t1 - t0),
                        (int(out_h), int(out_w)),
                        desc=desc,
                        required=bool(sink_only),
                    )
                    continue
                slot_idx = int(scheduled_idx) % len(pin_out_slots)
                scheduled_idx += 1
                _settle_commit(slot_idx)
                count = int(t1 - t0)
                total = int(count) * int(plane_px)
                launch_blocks = max(1, min(
                    (int(total) + 255) // 256,
                    _env_int('YOLO_TTA_GPU_BACKPROJECT_RESIDENT_CUDA_BLOCKS', 65535),
                ))
                compute_kernel(
                    (int(launch_blocks),), (256,),
                    (
                        cp_radial, np.int32(n_az), np.int32(work_t), np.int32(u_len),
                        cp_source, cp_u, np.int32(plane_px), np.int32(t_dim),
                        np.int32(t0), np.int32(count), cp_out_slots[slot_idx],
                    ),
                    stream=external,
                )
                compute_done = torch.cuda.Event(blocking=False)
                compute_done.record(compute_stream)
                copy_stream.wait_event(compute_done)
                with torch.cuda.stream(copy_stream):
                    pin_out_slots[slot_idx][:count].copy_(
                        out_dev_slots[slot_idx][:count], non_blocking=True,
                    )
                    copy_done = torch.cuda.Event(blocking=False)
                    copy_done.record(copy_stream)
                block = pin_out_arrays[slot_idx][:count].reshape((count, int(out_h), int(out_w)))
                commit_futures[slot_idx] = commit_pool.submit(
                    _commit_after_copy, copy_done, int(t0), int(t1), block,
                )
            for slot_idx in range(len(commit_futures)):
                _settle_commit(slot_idx)
            compute_stream.synchronize()
            copy_stream.synchronize()
            projection_seconds = time.perf_counter() - projection_t0

        total_seconds = time.perf_counter() - phase_start
        print(
            f'{desc}: full-resident GPU backprojection complete; source={source_bytes / GIB:.1f} GiB, '
            f'layout={layout}, upload_slots={len(pin_src_slots)}, pipeline_slots={len(pin_out_slots)}, '
            f'output={"sink-only" if bool(sink_only) else "dense+sink"}, '
            f'active_rows={int(np.count_nonzero(row_any))}/{int(work_t)}, '
            f'upload={upload_seconds:.2f}s, transpose={transpose_seconds:.2f}s, '
            f'project+commit wall={projection_seconds:.2f}s, commit CPU sum={commit_cpu_seconds:.2f}s, '
            f'total={total_seconds:.2f}s.'
        )
        return True
    finally:
        active_exception = sys.exc_info()[0] is not None
        cleanup_error: Optional[BaseException] = None
        # C12 exception safety: a callback failure can leave later D2Hs queued while their
        # commit futures have not started. Quiesce both CUDA streams before any future can
        # be cancelled and before device/pinned slot references are released.
        for owned_stream in (compute_stream, copy_stream):
            try:
                owned_stream.synchronize()
            except BaseException as exc:
                if cleanup_error is None:
                    cleanup_error = exc
        if commit_pool is not None:
            # Never cancel these event-wait futures: every submitted callback either commits
            # or reports its own failure after the associated D2H becomes quiescent.
            for fut in commit_futures:
                if fut is None:
                    continue
                try:
                    fut.result()
                except BaseException as exc:
                    if cleanup_error is None:
                        cleanup_error = exc
            try:
                _release_parallel_pool(max(1, len(pin_out_slots)), commit_pool)
            except BaseException as exc:
                if cleanup_error is None:
                    cleanup_error = exc
        try:
            del radial_dev, tmajor_dev, source_dev, u_dev
            del out_dev_slots, pin_src_slots, pin_out_slots
        except Exception:
            pass
        try:
            with torch.cuda.device(dev):
                torch.cuda.empty_cache()
        except Exception:
            pass
        if cleanup_error is not None and not bool(active_exception):
            raise cleanup_error

def _radial_backproject_gpu_streaming(
    radial_mask_mm: np.ndarray,
    vol_mm: Optional[np.ndarray],
    valid_pos: np.ndarray,
    flat_src: np.ndarray,
    v_range_for_t: Callable[[int], Tuple[int, int]],
    t_dim: int,
    out_h: int,
    out_w: int,
    desc: str,
    known_row_occupancy: Optional[np.ndarray] = None,
    known_slice_bboxes: Optional[np.ndarray] = None,
    projection_block_callback: Optional[Callable[[int, np.ndarray], None]] = None,
    sink_only: bool = False,
) -> bool:
    """v13.3.2 (R6a): radial backprojection with a <1 GiB streaming GPU working set.

    The gather maps upload once; per t-chunk only the covering NONEMPTY radial cross-sections
    are copied into pinned memory (strided host copies release the GIL), gathered/scattered on
    device, and the finished output planes come back through one pinned D2H per chunk. Chunks
    whose cross-sections are all empty are skipped entirely (the output is pre-zeroed).
    Returns False when torch/CUDA/VRAM are unavailable so the caller runs the CPU path.

    v13.3.3 (S1): row emptiness comes from one up-front threaded sequential occupancy pass
    instead of per-chunk strided rescans of the whole azimuth-major memmap; the nonempty row
    staging into pinned memory is thread-parallel; the device is picked by free VRAM instead
    of hardcoded cuda:0.
    """
    try:
        import torch  # type: ignore
    except Exception:
        return False
    try:
        if not bool(torch.cuda.is_available()):
            return False
    except Exception:
        return False
    dev = _pick_gpu_compute_device(torch)
    n_az, work_t, u_len = (int(x) for x in radial_mask_mm.shape)
    plane_px = int(out_h) * int(out_w)
    # v13.3.11: 128 output planes is the default projection quantum (256 is also supported
    # through the existing environment override). This amortizes map gathers and lets the
    # source be transposed into t-major order once per block instead of once per row.
    t_chunk = max(1, _env_int('YOLO_TTA_GPU_BACKPROJECT_T_CHUNK', 128))
    cross_bytes = int(n_az) * int(u_len)
    try:
        free_bytes, _total = torch.cuda.mem_get_info(dev)
    except Exception:
        return False

    def _projection_need(chunk_planes: int) -> Tuple[int, int]:
        rows = int(math.ceil(float(chunk_planes) * float(work_t) / float(max(1, t_dim)))) + 2
        need_bytes = (
            int(valid_pos.nbytes) + int(flat_src.nbytes)
            + rows * cross_bytes                         # t-major source rows
            + rows * int(flat_src.shape[0])              # gathered (rows, valid P)
            + int(chunk_planes) * int(flat_src.shape[0]) # vectorized per-t reduction
            + 2 * int(chunk_planes) * plane_px           # device + pinned output planes
            + 512 * 1024 * 1024
        )
        return int(rows), int(need_bytes)

    max_rows, need = _projection_need(int(t_chunk))
    while int(t_chunk) > 16 and int(free_bytes) < int(need) + 1 * GIB:
        t_chunk = max(16, int(t_chunk) // 2)
        max_rows, need = _projection_need(int(t_chunk))
    if int(free_bytes) < int(need) + 1 * GIB:
        print(
            f'{desc}: GPU backprojection skipped (needs ~{need / GIB:.1f} GiB + 1 GiB headroom, '
            f'{free_bytes / GIB:.1f} GiB free); using the CPU path.'
        )
        return False

    # v13.3.3 (S1): one sequential occupancy pass replaces ~O(chunks x rows) strided rescans.
    # v13.3.6 (D1): the device union already produced this bitmap; skip even that one pass.
    if known_row_occupancy is not None and int(np.asarray(known_row_occupancy).shape[0]) == int(work_t):
        row_any = np.asarray(known_row_occupancy, dtype=bool)
    else:
        row_any = _radial_row_occupancy(radial_mask_mm, desc)
    slice_bboxes = _validated_radial_slice_bboxes(
        known_slice_bboxes, int(n_az), int(work_t), int(u_len),
    )
    stage_workers = max(1, min(8, _cpu_count()))
    stage_pool = _acquire_parallel_pool(stage_workers)  # v13.3.4 (T5): checkout-cached

    try:
        stream = torch.cuda.Stream(device=dev)
        with torch.cuda.stream(stream):
            valid_pos_t = torch.from_numpy(np.ascontiguousarray(valid_pos)).to(dev)
            flat_src_t = torch.from_numpy(np.ascontiguousarray(flat_src)).to(dev)
            pin_rows = torch.empty((max_rows, n_az, u_len), dtype=torch.uint8, pin_memory=True)
            pin_rows_np = pin_rows.numpy()
            pin_out = torch.empty((t_chunk, plane_px), dtype=torch.uint8, pin_memory=True)
            pin_out_np = pin_out.numpy()
            out_dev = torch.empty((t_chunk, plane_px), dtype=torch.uint8, device=dev)
            reduced_dev = torch.empty(
                (t_chunk, int(valid_pos.shape[0])), dtype=torch.uint8, device=dev,
            )
            scatter_reduce_supported = True
            for t0 in tqdm(range(0, int(t_dim), t_chunk), desc=f'{desc} [gpu]'):
                t1 = min(int(t_dim), t0 + t_chunk)
                v0 = v_range_for_t(int(t0))[0]
                v1 = v_range_for_t(int(t1 - 1))[1]
                v_count = int(v1 - v0)
                if not bool(np.any(row_any[int(v0):int(v1)])):
                    _emit_projection_empty_range(
                        projection_block_callback,
                        int(t0),
                        int(t1 - t0),
                        (int(out_h), int(out_w)),
                        desc=desc,
                        required=bool(sink_only),
                    )
                    continue  # dense output (when present) is pre-zeroed
                if int(v_count) > int(pin_rows.shape[0]):  # pragma: no cover - conservative bound
                    raise RuntimeError(f'{desc}: covering rows {v_count} exceed staging bound {pin_rows.shape[0]}')

                _stage_radial_t_major_block(
                    radial_mask_mm,
                    int(v0),
                    int(v1),
                    pin_rows_np,
                    slice_bboxes=slice_bboxes,
                    stage_pool=stage_pool,
                    stage_workers=stage_workers,
                )
                rows_dev = pin_rows[:v_count].to(dev, non_blocking=True)
                gathered = rows_dev.reshape(v_count, -1)[:, flat_src_t]  # (rows, valid P) u8
                out_dev.zero_()
                t_count = int(t1 - t0)
                if int(work_t) == int(t_dim):
                    out_dev[:t_count].index_copy_(1, valid_pos_t, gathered[:t_count])
                else:
                    pair_out: List[int] = []
                    pair_row: List[int] = []
                    for t in range(int(t0), int(t1)):
                        vs, ve = v_range_for_t(int(t))
                        for v in range(int(vs), int(ve)):
                            pair_out.append(int(t - t0))
                            pair_row.append(int(v - v0))
                    if pair_row and scatter_reduce_supported:
                        try:
                            pair_row_t = torch.as_tensor(pair_row, dtype=torch.int64, device=dev)
                            pair_out_t = torch.as_tensor(pair_out, dtype=torch.int64, device=dev)
                            pair_values = gathered.index_select(0, pair_row_t)
                            reduced = reduced_dev[:t_count]
                            reduced.zero_()
                            reduced.scatter_reduce_(
                                0,
                                pair_out_t[:, None].expand(-1, int(gathered.shape[1])),
                                pair_values,
                                reduce='amax',
                                include_self=True,
                            )
                            out_dev[:t_count].index_copy_(1, valid_pos_t, reduced)
                        except (AttributeError, RuntimeError, TypeError):
                            # Compatibility fallback for older torch/CUDA combinations.
                            scatter_reduce_supported = False
                    if pair_row and not scatter_reduce_supported:
                        for local_t in range(t_count):
                            idxs = [i for i, target in enumerate(pair_out) if int(target) == int(local_t)]
                            if not idxs:
                                continue
                            row_ids = [int(pair_row[i]) for i in idxs]
                            sub = gathered[row_ids[0]] if len(row_ids) == 1 else gathered[row_ids].amax(dim=0)
                            out_dev[local_t].index_put_((valid_pos_t,), sub)
                pin_out[: t1 - t0].copy_(out_dev[: t1 - t0], non_blocking=True)
                stream.synchronize()
                if vol_mm is not None:
                    np.copyto(
                        np.asarray(vol_mm[t0:t1]).reshape(t1 - t0, -1),
                        pin_out_np[: t1 - t0],
                    )
                # Feed the just-completed pinned D2H block straight to the cvol indexer.
                # The full projected volume remains available only as a failure fallback;
                # the successful path never scans it again to create the raw-bbox store.
                _emit_projection_block_callback(
                    projection_block_callback,
                    int(t0),
                    pin_out_np[: t1 - t0].reshape((int(t1 - t0), int(out_h), int(out_w))),
                    desc=desc,
                    required=bool(sink_only),
                )
            stream.synchronize()
    finally:
        _release_parallel_pool(stage_workers, stage_pool)
    print(
        f'{desc}: GPU streaming backprojection complete ({t_dim} output slices; '
        f'output={"sink-only" if bool(sink_only) else "dense+sink"}).'
    )
    return True


def backproject_radial_volume_to_volume(
    radial_mask_mm: np.ndarray,
    radial_view: ViewInfo,
    out_path: Path,
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    out_shape_tyx: Optional[Tuple[int, int, int]] = None,
    known_row_occupancy: Optional[np.ndarray] = None,
    known_slice_bboxes: Optional[np.ndarray] = None,
    projection_block_callback: Optional[Callable[[int, np.ndarray], None]] = None,
    sink_only: bool = False,
) -> np.ndarray | SinkOnlyProjectionResult:
    """Backproject a radial view-native mask stack into orthogonal (t, Y, X).

    v13.2.4 (task #1, ruling A1): ``out_shape_tyx`` backprojects DIRECTLY into the final source
    geometry in one resample — the dense map is built on the source XY raster and each source t
    slice ORs the (working-t) radial rows it covers, mirroring the union-biased semantics of the
    former tail restore without an intermediate working-geometry volume. ``None`` keeps the
    historical working-geometry target. The cube resize only ever grows axes, so the working
    geometry is never smaller than the source geometry.

    v13.3.17 C2: ``sink_only=True`` suppresses the full ``(t,Y,X)`` allocation and makes
    ``projection_block_callback`` the authoritative transactional destination. Success returns
    :class:`SinkOnlyProjectionResult`; failures propagate so the caller can discard the partial
    store and explicitly request the retained dense fallback.
    """
    if radial_view.family != 'radial':
        raise ValueError('backproject_radial_volume_to_volume expects a radial view')

    work_t = int(radial_view.src_h)
    work_h = int(radial_view.full_h)
    work_w = int(radial_view.full_w)
    if out_shape_tyx is None:
        t_dim, out_h, out_w = work_t, work_h, work_w
    else:
        t_dim, out_h, out_w = (int(v) for v in out_shape_tyx)

    if bool(sink_only) and projection_block_callback is None:
        raise ValueError(f'{desc}: sink_only=True requires projection_block_callback')
    vol_mm: Optional[np.ndarray] = None
    if not bool(sink_only):
        vol_mm = allocate_workspace_array(
            shape=(t_dim, out_h, out_w),
            dtype=np.uint8,
            path=out_path,
            desc=f'{desc} workspace',
            prefer_memory=bool(prefer_memory),
            reserve_bytes=int(reserve_bytes),
        )
    else:
        print(
            f'{desc}: v13.3.17 C2 sink-only radial projection active; '
            f'skipping {array_nbytes((t_dim, out_h, out_w), np.uint8) / GIB:.2f} GiB dense workspace.'
        )

    plan, plan_stats = build_radial_backprojection_plan(radial_view)
    if bool(plan_stats.get('densified', 0.0)):
        print(
            f"{desc}: densifying radial backprojection for continuity "
            f"from {int(plan_stats['source_frames'])} source frame(s) at "
            f"{float(plan_stats['provided_spacing_deg']):.6g}° spacing to "
            f"{int(plan_stats['backprojection_angles'])} backprojection angle(s) at "
            f"{float(plan_stats['effective_spacing_deg']):.6g}° spacing "
            f"(full-coverage threshold {float(plan_stats['coverage_spacing_deg']):.6g}°)"
        )

    if not plan:
        _emit_projection_empty_range(
            projection_block_callback,
            0,
            int(t_dim),
            (int(out_h), int(out_w)),
            desc=desc,
            required=bool(sink_only),
        )
        if vol_mm is not None:
            flush_array(vol_mm)
            return vol_mm
        return SinkOnlyProjectionResult((int(t_dim), int(out_h), int(out_w)))

    dense_map = build_dense_radial_backprojection_map(
        radial_view, plan, out_shape_hw=None if out_shape_tyx is None else (out_h, out_w)
    )
    valid = np.asarray(dense_map.valid_mask, dtype=bool)
    source_idx_map = np.asarray(dense_map.source_idx_map, dtype=np.int32)
    u_idx_map = np.asarray(dense_map.u_idx_map, dtype=np.int32)

    worker_count = choose_slice_parallel_workers(int(workers), int(t_dim))
    same_t_axis = int(work_t) == int(t_dim)

    # v13.3.2 (R6a): flatten the dense gather once. valid_pos holds the flat output positions
    # of in-ROI pixels; flat_src holds each one's flat (source_frame, u) index into a radial
    # cross-section. Per slice this turns the 2-array fancy gather + two masked passes into one
    # take + one indexed store, and empty radial cross-sections are skipped outright (the
    # nearly-empty bridge layers become almost free).
    u_len = int(radial_mask_mm.shape[2])
    valid_pos = np.flatnonzero(valid.reshape(-1))
    flat_src = (
        source_idx_map.reshape(-1)[valid_pos].astype(np.int64) * np.int64(u_len)
        + u_idx_map.reshape(-1)[valid_pos]
    )

    def _v_range_for_t(t_idx: int) -> Tuple[int, int]:
        if same_t_axis:
            return int(t_idx), int(t_idx) + 1
        # v13.2.4 (A1): source t slice ORs every working-t radial row it covers (working t >= source t).
        v_start = int(math.floor(float(t_idx) * float(work_t) / float(t_dim)))
        v_stop = int(math.ceil(float(t_idx + 1) * float(work_t) / float(t_dim)))
        v_start = int(np.clip(v_start, 0, work_t - 1))
        v_stop = int(np.clip(max(v_start + 1, v_stop), 1, work_t))
        return v_start, v_stop

    # v13.3.6 (D1): device-union row occupancy (valid for the pre-interpolation layer only,
    # per the caller's contract) replaces both the GPU path's occupancy scan and the CPU
    # path's per-row strided np.any reads.
    row_occ = None
    if known_row_occupancy is not None:
        row_occ = np.asarray(known_row_occupancy, dtype=bool).reshape(-1)
        if int(row_occ.shape[0]) != int(work_t):
            row_occ = None
    radial_slice_bboxes = _validated_radial_slice_bboxes(
        known_slice_bboxes,
        int(radial_mask_mm.shape[0]),
        int(work_t),
        int(u_len),
    )

    gpu_done = False
    if gpu_backproject_enabled():
        try:
            gpu_done = _radial_backproject_gpu_resident(
                radial_mask_mm, vol_mm, valid, source_idx_map, u_idx_map, _v_range_for_t,
                int(t_dim), int(out_h), int(out_w), desc,
                known_row_occupancy=row_occ,
                projection_block_callback=projection_block_callback,
                sink_only=bool(sink_only),
            )
            if not gpu_done:
                gpu_done = _radial_backproject_gpu_streaming(
                    radial_mask_mm, vol_mm, valid_pos, flat_src, _v_range_for_t,
                    int(t_dim), int(out_h), int(out_w), desc,
                    known_row_occupancy=row_occ,
                    known_slice_bboxes=radial_slice_bboxes,
                    projection_block_callback=projection_block_callback,
                    sink_only=bool(sink_only),
                )
        except Exception as exc:
            # Some GPU blocks may already have been indexed. The CPU retry rewrites all
            # output blocks, so retain projection correctness but discard that partial store.
            _abort_projection_block_callback(projection_block_callback, exc)
            if bool(sink_only):
                raise
            projection_block_callback = None
            print(f'{desc}: GPU backprojection failed ({exc}); using the CPU path.')
            gpu_done = False

    if not gpu_done:
        if row_occ is None:
            row_occ = _radial_row_occupancy(radial_mask_mm, desc)
        cpu_t_chunk = max(1, _env_int('YOLO_TTA_CPU_BACKPROJECT_T_CHUNK', 128))
        n_blocks = int(math.ceil(float(t_dim) / float(cpu_t_chunk)))
        stage_workers = max(1, min(8, int(worker_count), _cpu_count()))
        stage_pool = _acquire_parallel_pool(stage_workers)

        # Bound simultaneous vector blocks by an 8 GiB temporary budget. The old per-t
        # implementation launched many strided readers concurrently; two large t-major
        # blocks generally saturate memory bandwidth without recreating that contention.
        max_block_rows = int(math.ceil(float(cpu_t_chunk) * float(work_t) / float(max(1, t_dim)))) + 2
        per_block_bytes = (
            int(max_block_rows) * int(radial_mask_mm.shape[0]) * int(u_len)
            + int(max_block_rows) * int(valid_pos.shape[0])
        )
        block_workers = max(1, min(
            int(worker_count),
            int(n_blocks),
            2,
            max(1, int((8 * GIB) // max(1, int(per_block_bytes)))),
        ))

        def _backproject_t_block(block_idx: int) -> None:
            t0 = int(block_idx) * int(cpu_t_chunk)
            t1 = min(int(t_dim), int(t0) + int(cpu_t_chunk))
            v0 = int(_v_range_for_t(int(t0))[0])
            v1 = int(_v_range_for_t(int(t1 - 1))[1])
            if not bool(np.any(row_occ[int(v0):int(v1)])):
                _emit_projection_empty_range(
                    projection_block_callback,
                    int(t0),
                    int(t1 - t0),
                    (int(out_h), int(out_w)),
                    desc=desc,
                    required=bool(sink_only),
                )
                return
            t_major = np.empty(
                (int(v1 - v0), int(radial_mask_mm.shape[0]), int(u_len)), dtype=np.uint8,
            )
            _stage_radial_t_major_block(
                radial_mask_mm,
                int(v0),
                int(v1),
                t_major,
                slice_bboxes=radial_slice_bboxes,
                stage_pool=stage_pool,
                stage_workers=stage_workers,
            )
            gathered_rows = t_major.reshape(int(v1 - v0), -1).take(flat_src, axis=1)
            block_out = (
                np.asarray(vol_mm[int(t0):int(t1)])
                if vol_mm is not None
                else np.zeros((int(t1 - t0), int(out_h), int(out_w)), dtype=np.uint8)
            )
            out_flat = block_out.reshape(int(t1 - t0), -1)
            if same_t_axis:
                out_flat[:, valid_pos] = gathered_rows[:int(t1 - t0)]
                _emit_projection_block_callback(
                    projection_block_callback,
                    int(t0),
                    block_out,
                    desc=desc,
                    required=bool(sink_only),
                )
                return
            for t in range(int(t0), int(t1)):
                vs, ve = _v_range_for_t(int(t))
                local = gathered_rows[int(vs - v0):int(ve - v0)]
                if int(local.shape[0]) == 1:
                    reduced = local[0]
                else:
                    reduced = np.bitwise_or.reduce(local, axis=0)
                out_flat[int(t - t0), valid_pos] = reduced
            _emit_projection_block_callback(
                projection_block_callback,
                int(t0),
                block_out,
                desc=desc,
                required=bool(sink_only),
            )

        try:
            parallel_for_indices(
                int(n_blocks),
                _backproject_t_block,
                max_workers=int(block_workers),
                desc=f'{desc} [t-major x{int(cpu_t_chunk)}]',
                show_progress=True,
            )
        finally:
            _release_parallel_pool(stage_workers, stage_pool)

    if vol_mm is not None:
        flush_array(vol_mm)
        return vol_mm
    return SinkOnlyProjectionResult((int(t_dim), int(out_h), int(out_w)))

def backproject_tilted_volume_to_volume(
    tilted_mask_mm: np.ndarray,
    tilted_view: ViewInfo,
    out_path: Path,
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    out_shape_tyx: Optional[Tuple[int, int, int]] = None,
) -> np.ndarray:
    """Backproject a v12 Tilted View-native mask stack into native (t, Y, X).

    The input stack remains in the generated Tilted View's own frame order and
    base-view raster coordinates through cleanup and interpolation.  Only after
    all per-view operations are complete do we map each foreground pixel by
    applying the same stacking-axis shear used during rendering:

      * Tilted Transverse: base axes (X, Y), stacking axis t
      * Tilted Sagittal:  base axes (X, t), stacking axis Y
      * Tilted Coronal:   base axes (Y, t), stacking axis X

    v13.2.4 (task #1, ruling A1): ``out_shape_tyx`` scatters DIRECTLY into the final source
    geometry in one step — working-grid coordinates are mapped to source indices with
    union-biased floor scaling (every working foreground voxel lands in the source voxel whose
    footprint contains it), so no intermediate working-geometry volume or second resample
    exists. ``None`` keeps the historical working-geometry target.

    v13.3.12 (D6): a delayed non-radial source may be ``(frames,imgsz,imgsz)``. Component
    work and interpolation stay on that raster. Both direct final output and NRRD component
    materialization shear into the same reduced orthogonal grid; only then does one terminal
    restore map it to source geometry. Sparse stores are never constructed at working size.
    """
    if not is_tilted_view(tilted_view):
        raise ValueError('backproject_tilted_volume_to_volume expects a Tilted View')

    work_t = int(tilted_view.full_t)
    work_h = int(tilted_view.full_h)
    work_w = int(tilted_view.full_w)

    src = np.asarray(tilted_mask_mm)
    if int(src.ndim) != 3 or int(src.shape[0]) != int(tilted_view.num_slices):
        raise ValueError(
            f'{desc}: tilted layer shape {tuple(src.shape)} must start with '
            f'{int(tilted_view.num_slices)} frames'
        )
    plane_h, plane_w = int(src.shape[1]), int(src.shape[2])
    native_plane = (int(tilted_view.src_h), int(tilted_view.src_w))
    reduced_processing = bool(
        delayed_native_expansion_enabled()
        and (int(plane_h), int(plane_w)) != native_plane
    )
    if reduced_processing and int(plane_h) != int(plane_w):
        raise ValueError(
            f'{desc}: delayed Tilted processing requires a square inference raster, '
            f'got {(int(plane_h), int(plane_w))}'
        )
    base_view = tilted_base_view_name(tilted_view)

    if reduced_processing and out_shape_tyx is not None:
        # Use the exact same terminal definition with and without --save_nrrd:
        # reduced-view shear -> reduced orthogonal grid -> one orthogonal restore.  Shear and
        # native-plane expansion do not commute at rounded stack boundaries, so expanding each
        # tilted frame first would make final masks depend on whether component NRRDs were saved.
        reduced_path = out_path.with_name(out_path.stem + '.d6_reduced_orthogonal.u8.dat')
        reduced_mm: Optional[np.ndarray] = None
        restored_mm: Optional[np.ndarray] = None
        restore_succeeded = False
        try:
            reduced_mm = backproject_tilted_volume_to_volume(
                tilted_mask_mm=src,
                tilted_view=tilted_view,
                out_path=reduced_path,
                desc=f'{desc} [reduced orthogonal projection]',
                prefer_memory=bool(prefer_memory),
                reserve_bytes=int(reserve_bytes),
                workers=int(workers),
                out_shape_tyx=None,
            )
            target_shape = tuple(int(v) for v in out_shape_tyx)
            restored_mm = allocate_workspace_array(
                shape=target_shape,
                dtype=np.uint8,
                path=out_path,
                desc=f'{desc} workspace',
                prefer_memory=bool(prefer_memory),
                reserve_bytes=int(reserve_bytes),
            )

            def _restore_tilted_slice(z_idx: int) -> None:
                restored_mm[int(z_idx), :, :] = _read_layer_slice_in_output_shape(
                    reduced_mm, target_shape, int(z_idx),
                )

            parallel_for_indices_chunked(
                int(target_shape[0]),
                _restore_tilted_slice,
                max_workers=choose_slice_parallel_workers(int(workers), int(target_shape[0])),
                desc=f'{desc} [terminal reduced-grid restore]',
                show_progress=True,
                target_chunks_per_worker=2,
            )
            flush_array(restored_mm)
            restore_succeeded = True
            return restored_mm
        finally:
            if reduced_mm is not None:
                close_memmap_array(reduced_mm)
            if restored_mm is not None and not bool(restore_succeeded):
                close_memmap_array(restored_mm)
            try:
                reduced_path.unlink(missing_ok=True)
            except Exception:
                pass

    if out_shape_tyx is None:
        if reduced_processing:
            if base_view == 'transverse':
                t_dim, out_h, out_w = int(work_t), int(plane_h), int(plane_w)
            elif base_view == 'sagittal':
                t_dim, out_h, out_w = int(plane_h), int(work_h), int(plane_w)
            elif base_view == 'coronal':
                t_dim, out_h, out_w = int(plane_h), int(plane_w), int(work_w)
            else:  # pragma: no cover
                raise ValueError(f'Unsupported Tilted View base: {base_view}')
        else:
            t_dim, out_h, out_w = work_t, work_h, work_w
    else:
        t_dim, out_h, out_w = (int(v) for v in out_shape_tyx)
    if t_dim <= 0 or out_h <= 0 or out_w <= 0:
        raise ValueError(
            f'Tilted view {tilted_view.name} has invalid output geometry '
            f'(t,Y,X)=({t_dim},{out_h},{out_w})'
        )

    vol_mm = allocate_workspace_array(
        shape=(t_dim, out_h, out_w),
        dtype=np.uint8,
        path=out_path,
        desc=f'{desc} workspace',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
    )

    tan_alpha = float(math.tan(math.radians(float(tilted_view.tilt_angle_deg))))
    if str(tilted_view.tilt_direction) == 'vertical':
        axis_center = float((int(tilted_view.src_h) - 1) / 2.0)
    elif str(tilted_view.tilt_direction) == 'horizontal':
        axis_center = float((int(tilted_view.src_w) - 1) / 2.0)
    else:  # pragma: no cover
        raise ValueError(f'Unsupported tilt direction: {tilted_view.tilt_direction}')

    stack_len = tilted_stack_axis_length(tilted_view)

    worker_count = choose_slice_parallel_workers(int(workers), int(tilted_view.num_slices))

    def _map_axis_to_out(idx_arr: np.ndarray, in_len: int, out_len: int) -> np.ndarray:
        # v13.2.4 (A1): union-biased floor scaling from working-grid indices to source indices
        # (in_len >= out_len; the cube resize only grows axes). Identity when the axis is unscaled.
        if int(in_len) == int(out_len):
            return idx_arr
        mapped = (idx_arr.astype(np.int64, copy=False) * int(out_len)) // int(in_len)
        return np.minimum(mapped, int(out_len) - 1).astype(np.int32, copy=False)

    # v13.3.2 (R6d): per-frame invariants hoisted; the frame's emptiness test and nonzero run on
    # the raw uint8 plane (the old dtype=bool asarray made a full-plane cast COPY per frame);
    # the three mapped coordinate arrays collapse into ONE flat scatter index (built with
    # GIL-releasing int64 ufuncs) so the GIL-held portion is a single 1-array store.
    is_vertical_dir = str(tilted_view.tilt_direction) == 'vertical'
    vol_flat_scatter = np.asarray(vol_mm).reshape(-1)
    plane_stride = np.int64(int(out_h) * int(out_w))
    reduced_out_to_native: Optional[np.ndarray] = None
    if reduced_processing and out_shape_tyx is None:
        # Frame-invariant canonical-grid -> native-view transform.  Building/inverting this
        # affine inside every one of ~3k frames per Tilted stack would serialize the otherwise
        # parallel projection on OpenCV/NumPy setup work.
        canonical = build_affine(
            view=str(tilted_view.name),
            src_w=int(tilted_view.src_w),
            src_h=int(tilted_view.src_h),
            out_size=int(plane_w),
            angle_deg=0.0,
            pad_mode=str(tilted_view.pad_mode),
        )
        reduced_out_to_native = np.asarray(canonical.M_out_to_src, dtype=np.float32)

    def _backproject_frame(frame_idx: int) -> None:
        frame_arr = np.asarray(src[int(frame_idx)])
        if not np.any(frame_arr):
            return
        vv, uu = np.nonzero(frame_arr)
        if vv.size <= 0:
            return

        frame_center = float(tilted_frame_center(tilted_view, int(frame_idx)))
        if reduced_processing and out_shape_tyx is None:
            # Convert only the coordinate used by the physical shear to native-view units;
            # the orthogonal in-plane coordinates themselves stay reduced.
            if reduced_out_to_native is None:  # pragma: no cover - guarded above
                raise RuntimeError(f'{desc}: reduced Tilted affine was not initialized')
            m = reduced_out_to_native
            native_u = m[0, 0] * uu.astype(np.float32, copy=False) + m[0, 1] * vv + m[0, 2]
            native_v = m[1, 0] * uu.astype(np.float32, copy=False) + m[1, 1] * vv + m[1, 2]
            axis_coords = native_v if is_vertical_dir else native_u
        else:
            axis_coords = vv if is_vertical_dir else uu
        stack_float = frame_center + tan_alpha * (axis_coords.astype(np.float32, copy=False) - axis_center)

        ss = np.rint(stack_float).astype(np.int32, copy=False)
        valid = (ss >= 0) & (ss < int(stack_len))
        if not np.any(valid):
            return

        ss_v = ss[valid]
        vv_v = vv[valid]
        uu_v = uu[valid]
        if reduced_processing and out_shape_tyx is None:
            # Reduced orthogonal projection.  The stacking axis keeps working-grid pitch;
            # the two axes represented by the model plane retain inference pitch.
            if base_view == 'transverse':
                ti, yi, xi = ss_v, vv_v, uu_v
            elif base_view == 'sagittal':
                ti, yi, xi = vv_v, ss_v, uu_v
            elif base_view == 'coronal':
                ti, yi, xi = vv_v, uu_v, ss_v
            else:  # pragma: no cover
                raise ValueError(f'Unsupported Tilted View base: {base_view}')
        elif base_view == 'transverse':
            # base in-plane: horizontal X=uu, vertical Y=vv; stack t=ss
            ti = _map_axis_to_out(ss_v, work_t, t_dim)
            yi = _map_axis_to_out(vv_v, work_h, out_h)
            xi = _map_axis_to_out(uu_v, work_w, out_w)
        elif base_view == 'sagittal':
            # base in-plane: horizontal X=uu, vertical t=vv; stack Y=ss
            ti = _map_axis_to_out(vv_v, work_t, t_dim)
            yi = _map_axis_to_out(ss_v, work_h, out_h)
            xi = _map_axis_to_out(uu_v, work_w, out_w)
        elif base_view == 'coronal':
            # base in-plane: horizontal Y=uu, vertical t=vv; stack X=ss
            ti = _map_axis_to_out(vv_v, work_t, t_dim)
            yi = _map_axis_to_out(uu_v, work_h, out_h)
            xi = _map_axis_to_out(ss_v, work_w, out_w)
        else:  # pragma: no cover
            raise ValueError(f'Unsupported Tilted View base: {base_view}')
        flat = ti.astype(np.int64, copy=False) * plane_stride
        flat += yi.astype(np.int64, copy=False) * np.int64(out_w)
        flat += xi.astype(np.int64, copy=False)
        vol_flat_scatter[flat] = np.uint8(1)

    parallel_for_indices_chunked(
        int(tilted_view.num_slices),
        _backproject_frame,
        max_workers=worker_count,
        desc=desc,
        show_progress=True,
        target_chunks_per_worker=4,
    )

    flush_array(vol_mm)
    return vol_mm


@dataclass(frozen=True)
class ViewBackprojectionQueueJob:
    model_name: str
    view: ViewInfo
    native_source: np.ndarray
    out_path: Path
    desc: str
    min_radius: float = 0.0
    workers: int = 1
    # v13.2.4 (task #1, ruling A1): final source geometry to backproject directly into
    # (single resample). None keeps the historical working-geometry target.
    out_shape_tyx: Optional[Tuple[int, int, int]] = None


class HybridBackprojectionQueue:
    """CPU-only radial/tilted backprojection queue (one set at a time, full worker budget).

    The historical class name is retained to avoid churn in scheduler call sites; the GPU
    slot was disabled in v12.2.11 and its dormant CuPy machinery was pruned in v13.2.5.
    """

    def __init__(self, *, cpu_workers: int = 1) -> None:
        self.cpu_workers = max(1, int(cpu_workers))

    def _run_job(self, job: ViewBackprojectionQueueJob) -> Tuple[str, str, np.ndarray]:
        view_local = job.view
        if view_local.family == 'radial':
            projected = backproject_radial_volume_to_volume(
                radial_mask_mm=job.native_source,
                radial_view=view_local,
                out_path=job.out_path,
                desc=job.desc,
                prefer_memory=True,
                workers=int(job.workers),
                out_shape_tyx=job.out_shape_tyx,
            )
        elif is_tilted_view(view_local):
            projected = backproject_tilted_volume_to_volume(
                tilted_mask_mm=job.native_source,
                tilted_view=view_local,
                out_path=job.out_path,
                desc=job.desc,
                prefer_memory=True,
                workers=int(job.workers),
                out_shape_tyx=job.out_shape_tyx,
            )
        else:  # pragma: no cover
            raise ValueError(f'Unsupported queued backprojection view family: {view_local.family}')

        # --min_radius is applied per view in each view's OWN native 2D slice plane BEFORE
        # backprojection, so it is NOT re-applied here; job.min_radius is not consumed.
        return str(job.model_name), str(view_local.name), projected

    def run(self, jobs: Sequence[ViewBackprojectionQueueJob]) -> List[Tuple[str, str, np.ndarray]]:
        results: List[Tuple[str, str, np.ndarray]] = []
        for job in jobs:
            print(f'Backprojection queue: running {job.model_name}/{job.view.name} on CPU')
            results.append(self._run_job(job))
        return results

def _union_projected_layer_ref_into_volume(
    ref: 'NrrdLayerRef',
    vol_mm: np.ndarray,
    *,
    workers: int = 1,
    desc: str = 'Layer union',
) -> None:
    """OR one orthogonal NRRD component layer into ``vol_mm``.

    v13.3.12 D6 accepts reduced orthogonal stores and restores each output slice directly
    into the destination.  No dense native intermediate is reconstructed.
    """
    vol_shape = tuple(int(v) for v in vol_mm.shape)
    z_dim, h_dim, w_dim = vol_shape
    src = _open_nrrd_layer_ref(ref)
    try:
        if tuple(int(v) for v in ref.shape) != vol_shape:
            def _or_restored_slice(z_idx: int) -> None:
                restored = _read_layer_slice_in_output_shape(
                    src, (int(z_dim), int(h_dim), int(w_dim)), int(z_idx),
                )
                if bool(np.any(restored)):
                    vol_mm[int(z_idx), :, :] |= restored

            parallel_for_indices_chunked(
                int(z_dim),
                _or_restored_slice,
                max_workers=choose_slice_parallel_workers(int(workers), int(z_dim)),
                desc=f'{desc} [reduced restore]',
                show_progress=False,
                target_chunks_per_worker=2,
            )
            return
        if isinstance(src, RawBBoxMaskStore):
            index = src.index
            scratch_tls = threading.local()

            def _or_store_slice(z_idx: int) -> None:
                rec = index[int(z_idx)]
                if int(rec['kind']) != 1:
                    return
                buf = getattr(scratch_tls, 'buf', None)
                if buf is None:
                    buf = np.zeros((int(h_dim), int(w_dim)), dtype=np.uint8)
                    scratch_tls.buf = buf
                src.fill_decoded_slice_into(int(z_idx), buf)
                y0 = int(rec['y0']); x0 = int(rec['x0']); y1 = int(rec['y1']); x1 = int(rec['x1'])
                vol_mm[int(z_idx), y0:y1, x0:x1] |= buf[y0:y1, x0:x1]

            parallel_for_indices_chunked(
                int(z_dim),
                _or_store_slice,
                max_workers=choose_slice_parallel_workers(int(workers), int(z_dim)),
                desc=desc,
                show_progress=False,
                target_chunks_per_worker=2,
            )
        else:
            def _or_raw_slice(z_idx: int) -> None:
                vol_mm[int(z_idx)] |= np.asarray(src[int(z_idx)], dtype=np.uint8)

            parallel_for_indices_chunked(
                int(z_dim),
                _or_raw_slice,
                max_workers=choose_slice_parallel_workers(int(workers), int(z_dim)),
                desc=desc,
                show_progress=False,
                target_chunks_per_worker=2,
            )
    finally:
        try:
            _close_nrrd_layer_source(src)
        finally:
            _drop_nrrd_raw_store_chunks_ram_cache(src)


def scheduler_push_drain_enabled() -> bool:
    """v13.3.8 (G1): push-drain the GPU-worker result queue instead of timeout polling.

    A transport-only daemon thread blocks on the process result queue and hands messages
    to the main thread through a local deque + wake event; completed scheduler futures set
    the same event through one-time done-callbacks. Results are processed the instant they
    arrive instead of after the 0.1 s futures-poll / 0.5 s queue-poll, and handlers still
    run ONLY on the main thread. YOLO_TTA_SCHEDULER_PUSH_DRAIN=0 restores polling.
    """
    return _env_flag('YOLO_TTA_SCHEDULER_PUSH_DRAIN', True)


def scheduler_push_drain_heartbeat_seconds() -> float:
    """v13.3.8 (G1): upper bound on one push-drain sleep (worker-liveness re-check cadence)."""
    return max(0.05, _env_float('YOLO_TTA_SCHEDULER_PUSH_DRAIN_HEARTBEAT', 1.0))


def assemble_views_concurrency() -> int:
    """v13.3.8 (G4): concurrent assemble-from-projected-layers views.

    The per-view assemblies are independent unions of already-projected layer stores
    (I/O + memcpy bound), but were run strictly one view at a time. Two concurrent views
    roughly halve that tail segment on the reference 8-tilted + 1-radial run; the
    per-view worker budget is split across active assemblies so the total thread count
    is unchanged. YOLO_TTA_ASSEMBLE_VIEWS_CONCURRENCY=1 restores serial assembly.
    """
    return max(1, _env_int('YOLO_TTA_ASSEMBLE_VIEWS_CONCURRENCY', 2))


def fused_final_view_union_enabled() -> bool:
    """v13.3.9 (G5): one output-z pass for Cartesian + projected-layer union.

    The fused path is deliberately limited by its caller to working!=output geometry;
    YOLO_TTA_FUSED_FINAL_VIEW_UNION=0 restores G4's per-view intermediates and the
    separate final-union sweeps.
    """
    return _env_flag('YOLO_TTA_FUSED_FINAL_VIEW_UNION', True)


def fused_final_restore_geometry_groups_enabled() -> bool:
    """v13.3.17 (C1): union equal-geometry projected layers before one restore.

    Reduced Tilted component layers share an orthogonal backing geometry.  Binary
    union commutes with the positive-support INTER_AREA/NEAREST restore, so G5 can
    decode/OR every layer in one geometry group on its reduced grid and resize the
    group once.  The escape hatch retains the v13.3.16 per-layer restore for direct
    regression comparisons.
    """
    return _env_flag('YOLO_TTA_FUSED_FINAL_RESTORE_GEOMETRY_GROUPS', True)


def fused_final_gpu_enabled() -> bool:
    """C13: optionally move grouped final restore/OR work onto idle inference GPUs.

    Sparse cvol decoding and stack formation are still host-side, so the CUDA path is
    intentionally opt-in until its pageable H2D traffic is profiled on the target node.
    """
    return _env_flag('YOLO_TTA_FUSED_FINAL_GPU', False)


def fused_final_gpu_batch_slices() -> int:
    return max(1, _env_int('YOLO_TTA_FUSED_FINAL_GPU_BATCH_SLICES', 8))


def _resize_union_plane_to_out_xy(plane: np.ndarray, out_h: int, out_w: int) -> np.ndarray:
    """Exact Cartesian final-union binary-plane restore used by legacy and G5 paths."""
    plane_u8 = (np.asarray(plane, dtype=np.uint8) > 0).astype(np.uint8, copy=False)
    if int(plane_u8.shape[0]) == int(out_h) and int(plane_u8.shape[1]) == int(out_w):
        return plane_u8
    interp = (
        cv2.INTER_AREA
        if (int(plane_u8.shape[0]) >= int(out_h) and int(plane_u8.shape[1]) >= int(out_w))
        else cv2.INTER_NEAREST
    )
    scaled = cv2.resize(
        np.ascontiguousarray(plane_u8 * np.uint8(255)),
        (int(out_w), int(out_h)),
        interpolation=int(interp),
    )
    return (scaled > 0).astype(np.uint8, copy=False)


def assemble_view_volume_from_projected_layers(
    layer_refs: Sequence['NrrdLayerRef'],
    out_shape_tyx: Tuple[int, int, int],
    out_path: Path,
    desc: str,
    *,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
) -> np.ndarray:
    """v13.2.4 (task #2): rebuild a radial/tilted view's final projected volume from its layers.

    The dense radial gather and the tilted shear scatter both commute exactly with union, and the
    view's final native volume is by construction the union of its component layers (cleaned
    full-frame YOLO mask, one bridge delta per interpolation pass, and any accepted-tile / tile
    bridge layers). OR-ing the ALREADY-projected --save_nrrd component layers therefore
    reproduces the projected final volume bit-for-bit without a second full backprojection.
    """
    out_shape = tuple(int(v) for v in out_shape_tyx)
    vol_mm = allocate_workspace_array(
        shape=out_shape,
        dtype=np.uint8,
        path=out_path,
        desc=f'{desc} workspace',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
    )
    for ref in layer_refs:
        _union_projected_layer_ref_into_volume(
            ref,
            vol_mm,
            workers=int(workers),
            desc=f'{desc}: OR layer {ref.key}',
        )
    flush_array(vol_mm)
    return vol_mm


def assemble_view_volumes_into_native_union(
    final_union_mm: np.ndarray,
    view_volume_mms: Dict[str, np.ndarray],
    T: int,
    H: int,
    W: int,
    disable_multiplanar: bool,
    *,
    out_shape_tyx: Optional[Tuple[int, int, int]] = None,
    workers: int = 1,
) -> None:
    """OR all per-view prediction volumes from the single active model into the final union.

    Already-backprojected Tilted/Radial volumes arrive at the union's own (out) geometry and are
    merged slice-wise. Transverse, Sagittal, and Coronal retain their native working-geometry view
    stacks; v13.2.4 (task #1, ruling A1) restores each of them working->source with ONE resample
    while merging (union-biased: a source slice ORs every working slice it covers and XY planes
    are resized with the same >0-threshold INTER_AREA/NEAREST semantics as the former tail
    restore). When ``out_shape_tyx`` is None or equals the working geometry, the historical
    zero-resample axis-permutation merges are used.
    """
    out_t, out_h, out_w = (int(T), int(H), int(W)) if out_shape_tyx is None else (
        int(out_shape_tyx[0]), int(out_shape_tyx[1]), int(out_shape_tyx[2]))
    working_equals_out = (out_t, out_h, out_w) == (int(T), int(H), int(W))

    def _resize_plane_to_out_xy(plane: np.ndarray) -> np.ndarray:
        return _resize_union_plane_to_out_xy(plane, int(out_h), int(out_w))

    def _source_plane_indices(plane_count: int, out_z: int) -> range:
        count = max(1, int(plane_count))
        if count >= int(out_t):
            start = int(math.floor(float(out_z) * float(count) / float(out_t)))
            stop = int(math.ceil(float(out_z + 1) * float(count) / float(out_t)))
            start = int(np.clip(start, 0, count - 1))
            stop = int(np.clip(max(start + 1, stop), 1, count))
            return range(start, stop)
        if int(out_t) <= 1 or count <= 1:
            return range(0, 1)
        src_idx = int(round(float(out_z) * float(count - 1) / float(out_t - 1)))
        src_idx = int(np.clip(src_idx, 0, count - 1))
        return range(src_idx, src_idx + 1)

    def _or_restore_working_planes_into_union(
        get_working_plane: Callable[[int], np.ndarray],
        view_label: str,
        plane_count: int = T,
    ) -> None:
        # One terminal resample per source plane: t-range OR + XY resize straight into union.
        def _merge_out_slice(out_z: int) -> None:
            acc: Optional[np.ndarray] = None
            for v_idx in _source_plane_indices(int(plane_count), int(out_z)):
                restored = _resize_plane_to_out_xy(get_working_plane(int(v_idx)))
                if acc is None:
                    acc = restored
                else:
                    np.bitwise_or(acc, restored, out=acc)
            if acc is not None:
                final_union_mm[int(out_z), :, :] |= acc

        parallel_for_indices(
            int(out_t),
            _merge_out_slice,
            max_workers=choose_slice_parallel_workers(int(workers), int(out_t)),
            desc=f"Assembling final union from {view_label} view volume (restored to source geometry)",
        )

    consumed: set[str] = set()

    if "transverse" in view_volume_mms:
        transverse = np.asarray(view_volume_mms["transverse"])
        if int(transverse.ndim) != 3:
            raise ValueError(f'transverse volume must be 3D, got {tuple(transverse.shape)}')
        consumed.add("transverse")

        if working_equals_out and tuple(int(v) for v in transverse.shape) == (int(T), int(H), int(W)):
            transverse_workers = choose_slice_parallel_workers(int(workers), int(T))

            def _merge_transverse(t: int) -> None:
                final_union_mm[int(t), :, :] |= transverse[int(t), :, :]

            parallel_for_indices(
                int(T),
                _merge_transverse,
                max_workers=transverse_workers,
                desc="Assembling final union from transverse view volume",
            )
        else:
            _or_restore_working_planes_into_union(
                lambda v: transverse[int(v), :, :], "transverse", int(transverse.shape[0]),
            )

    if "sagittal" in view_volume_mms:
        sagittal = np.asarray(view_volume_mms["sagittal"])
        if int(sagittal.ndim) != 3:
            raise ValueError(f'sagittal volume must be 3D, got {tuple(sagittal.shape)}')
        consumed.add("sagittal")

        if working_equals_out and tuple(int(v) for v in sagittal.shape) == (int(H), int(T), int(W)):
            # v13.3.8 (A3): the per-y merge (final_union[:, y, :] |= sagittal[y]) swept the
            # ENTIRE destination volume once per y (T rows of W bytes at stride H*W) — full
            # cache lines, but H passes of page/TLB traffic. Merge K rows per block instead:
            # for each t the destination window [t, y0:y1, :] is one contiguous K*W run, so
            # every destination page is visited once per block (H/K fewer volume sweeps).
            blk_rows = int(coronal_block_cols())
            n_blocks = (int(H) + blk_rows - 1) // blk_rows

            def _merge_sagittal_block(block_idx: int) -> None:
                y0 = int(block_idx) * blk_rows
                y1 = min(int(H), y0 + blk_rows)
                sub = np.asarray(sagittal[y0:y1])
                for t in range(int(T)):
                    final_union_mm[int(t), y0:y1, :] |= sub[:, int(t), :]

            parallel_for_indices_chunked(
                int(n_blocks),
                _merge_sagittal_block,
                max_workers=choose_slice_parallel_workers(int(workers), int(n_blocks)),
                desc="Assembling final union from sagittal view volume",
                show_progress=False,
                target_chunks_per_worker=2,
            )
        else:
            # D6 reduced stack: axis 1 is the inference-pitch t axis; axis 0 remains the
            # sagittal stack/y axis. The final resize restores both Y and X in one pass.
            _or_restore_working_planes_into_union(
                lambda v: sagittal[:, int(v), :], "sagittal", int(sagittal.shape[1]),
            )

    if "coronal" in view_volume_mms:
        coronal = np.asarray(view_volume_mms["coronal"])
        if int(coronal.ndim) != 3:
            raise ValueError(f'coronal volume must be 3D, got {tuple(coronal.shape)}')
        consumed.add("coronal")

        if working_equals_out and tuple(int(v) for v in coronal.shape) == (int(W), int(T), int(H)):
            # v13.3.8 (A3): the per-x merge (final_union[:, :, x] |= coronal[x]) wrote one
            # byte per cache line across the whole (t, Y) extent — the same ~64x write
            # amplification v13.3.2 (R14) fixed for the projection copy. Same cure: permute
            # K columns at a time through per-t (K, H) -> (H, K) tile transposes (tiles stay
            # cache-resident) and OR K contiguous bytes per destination row.
            blk_cols = int(coronal_block_cols())
            n_blocks = (int(W) + blk_cols - 1) // blk_cols

            def _merge_coronal_block(block_idx: int) -> None:
                x0 = int(block_idx) * blk_cols
                x1 = min(int(W), x0 + blk_cols)
                sub = np.asarray(coronal[x0:x1])
                for t in range(int(T)):
                    final_union_mm[int(t), :, x0:x1] |= sub[:, int(t), :].T

            parallel_for_indices_chunked(
                int(n_blocks),
                _merge_coronal_block,
                max_workers=choose_slice_parallel_workers(int(workers), int(n_blocks)),
                desc="Assembling final union from coronal view volume",
                show_progress=False,
                target_chunks_per_worker=2,
            )
        else:
            # D6 reduced stack: axis 1 is inference-pitch t; transpose stack/x and plane/y.
            _or_restore_working_planes_into_union(
                lambda v: np.ascontiguousarray(np.asarray(coronal[:, int(v), :]).T),
                "coronal",
                int(coronal.shape[1]),
            )

    for view_name in sorted(view_volume_mms.keys()):
        if view_name in consumed:
            continue
        vol = np.asarray(view_volume_mms[view_name])
        if vol.shape != (out_t, out_h, out_w):
            raise ValueError(
                f"View volume '{view_name}' has shape {tuple(vol.shape)}; expected final output volume shape "
                f"{(out_t, out_h, out_w)} or a handled transverse/sagittal/coronal working stack."
            )
        native_workers = choose_slice_parallel_workers(int(workers), int(out_t))

        def _merge_native(t: int, *, _vol: np.ndarray = vol) -> None:
            final_union_mm[int(t), :, :] |= _vol[int(t), :, :]

        parallel_for_indices(
            int(out_t),
            _merge_native,
            max_workers=native_workers,
            desc=f"Assembling final union from {view_name} view volume",
        )


def assemble_view_volumes_and_projected_layers_fused(
    final_union_mm: np.ndarray,
    view_volume_mms: Dict[str, np.ndarray],
    projected_layer_refs: Sequence['NrrdLayerRef'],
    T: int,
    H: int,
    W: int,
    *,
    out_shape_tyx: Tuple[int, int, int],
    workers: int = 1,
) -> None:
    """v13.3.9 (G5): assemble every contributor with one disjoint output-z pass.

    Cartesian stacks are restored with the legacy floor/ceil t coverage and exact
    binary XY resize. Source-geometry radial/tilted component stores are read
    directly, so their former full-volume per-view intermediates never exist. Each
    worker builds one private output plane and assigns its final slice once.

    v13.3.17 C1 groups reduced projected stores by their identical orthogonal restore
    geometry.  All source slices/layers in a group are ORed on that reduced grid and
    the group is resized once; source-native Radial stores retain the direct indexed
    crop path.  This removes 14 of the 16 per-output-slice Tilted resizes in the
    reference 8-view/2-layer run without constructing any dense volume intermediate.
    """
    out_t, out_h, out_w = (int(v) for v in out_shape_tyx)
    if (out_t, out_h, out_w) == (int(T), int(H), int(W)):
        raise ValueError('G5 fused restore is scoped to working geometry != output geometry')
    if tuple(int(v) for v in np.asarray(final_union_mm).shape) != (out_t, out_h, out_w):
        raise ValueError(
            f'G5 final union shape {tuple(np.asarray(final_union_mm).shape)} != {(out_t, out_h, out_w)}'
        )

    transverse = np.asarray(view_volume_mms['transverse']) if 'transverse' in view_volume_mms else None
    sagittal = np.asarray(view_volume_mms['sagittal']) if 'sagittal' in view_volume_mms else None
    coronal = np.asarray(view_volume_mms['coronal']) if 'coronal' in view_volume_mms else None
    for _name, _vol in (('transverse', transverse), ('sagittal', sagittal), ('coronal', coronal)):
        if _vol is not None and int(_vol.ndim) != 3:
            raise ValueError(f'G5 {_name} volume must be 3D, got {tuple(_vol.shape)}')

    native_views: List[Tuple[str, np.ndarray]] = []
    for view_name in sorted(view_volume_mms):
        if view_name in {'transverse', 'sagittal', 'coronal'}:
            continue
        vol = np.asarray(view_volume_mms[view_name])
        if tuple(int(v) for v in vol.shape) != (out_t, out_h, out_w):
            raise ValueError(
                f"G5 native view '{view_name}' shape {tuple(vol.shape)} != {(out_t, out_h, out_w)}"
            )
        native_views.append((str(view_name), vol))

    opened: List[Tuple['NrrdLayerRef', object]] = []
    try:
        for ref in projected_layer_refs:
            # Do not pin every projected chunks.bin simultaneously: G5 may open ~90
            # component stores, and the explicit NRRD RAM cache would erase the peak-RAM
            # win from deleting the per-view intermediates. The OS page cache still gives
            # reclaimable reads; a read-only mmap also avoids per-slice file open/seek churn.
            if _nrrd_layer_ref_is_raw_bbox_store(ref):
                src = RawBBoxMaskStore.open(
                    ref.path, cache_payload_in_ram=False, mmap_payload=True,
                )
                try:
                    payload_map = getattr(src, '_chunks_mmap', None)
                    advice = getattr(mmap, 'MADV_SEQUENTIAL', None)
                    if payload_map is not None and advice is not None:
                        payload_map.madvise(advice)
                except Exception:
                    pass
            else:
                src = _open_nrrd_layer_ref(ref)
                _madvise_array_mmap(src, 'MADV_SEQUENTIAL')
            opened.append((ref, src))

        # v13.3.17 C1: shape fully defines the restore transform here because every
        # projected layer is already in canonical orthogonal (t,Y,X) coordinates.
        # Grouping is intentionally limited to non-native layers. Native Radial stores
        # continue to contribute bbox crops directly to the output accumulator.
        group_restores = bool(fused_final_restore_geometry_groups_enabled())
        native_projected: List[Tuple['NrrdLayerRef', object]] = []
        restore_groups: 'OrderedDict[Tuple[int, int, int], List[Tuple[NrrdLayerRef, object]]]' = OrderedDict()
        if group_restores:
            for ref, src in opened:
                geometry = tuple(int(v) for v in _volume_shape_tuple(src))
                if geometry == (out_t, out_h, out_w):
                    native_projected.append((ref, src))
                else:
                    restore_groups.setdefault(geometry, []).append((ref, src))
            grouped_layers = sum(len(group) for group in restore_groups.values())
            group_text = ', '.join(
                f'{len(group)}x{tuple(int(v) for v in geometry)}'
                for geometry, group in restore_groups.items()
            ) or 'none'
            print(
                f'v13.3.17 (C1): G5 grouped {int(grouped_layers)} reduced projected '
                f'layer(s) into {len(restore_groups)} restore geometry group(s) '
                f'[{group_text}] ({int(grouped_layers)} -> {len(restore_groups)} '
                f'restores/output-z); {len(native_projected)} native layer(s) remain direct.'
            )

        scratch_tls = threading.local()

        def _scratch_map() -> Dict[object, np.ndarray]:
            buffers = getattr(scratch_tls, 'buffers', None)
            if buffers is None:
                buffers = {}
                scratch_tls.buffers = buffers
            return buffers

        def _or_native_source_slice(dst: np.ndarray, src: object, src_z: int) -> None:
            """OR one source-grid slice, preserving RawBBoxMaskStore crop sparsity."""
            if isinstance(src, RawBBoxMaskStore):
                rec = src.index[int(src_z)]
                if int(rec['kind']) != 1:
                    return
                decoded = src.decode_slice_crop(int(src_z), dtype=np.uint8)
                if decoded is None:  # defensive: index.kind was checked above
                    return
                y0, x0, y1, x1, crop = decoded
                dst[int(y0):int(y1), int(x0):int(x1)] |= crop
                return
            np.bitwise_or(dst, np.asarray(src[int(src_z)], dtype=np.uint8), out=dst)

        def _try_gpu_final_fusion() -> bool:
            """C13 fast path: assign disjoint output-z bands to idle CUDA devices.

            Source cvol decoding remains on the host because it is sparse/file-backed;
            positive-support restores and the final contributor OR stay on each GPU until
            one completed band is copied back. A failure may leave partial bands, but the
            caller then executes the established CPU path, which assigns every output slice.
            """
            if not bool(group_restores) or not fused_final_gpu_enabled():
                return False
            try:
                import torch  # type: ignore
                import torch.nn.functional as F  # type: ignore
                if not bool(torch.cuda.is_available()):
                    return False
            except Exception:
                return False

            configured = _GPU_SLICE_LABELING_CONFIGURED_DEVICES
            devices: List[int] = []
            raw_devices = os.environ.get('YOLO_TTA_FUSED_FINAL_GPU_DEVICES', '').strip()
            if raw_devices:
                try:
                    devices = [int(tok.strip()) for tok in raw_devices.split(',') if tok.strip()]
                except Exception as exc:
                    print(f'Warning: invalid YOLO_TTA_FUSED_FINAL_GPU_DEVICES ({exc}); using configured devices.')
                    devices = []
            if not devices and configured:
                devices = [int(v) for v in configured]
            if not devices:
                devices = list(range(int(torch.cuda.device_count())))
            max_devices = max(1, _env_int('YOLO_TTA_FUSED_FINAL_GPU_MAX_DEVICES', 4))
            devices = list(dict.fromkeys(devices))[:min(int(max_devices), int(out_t))]
            if not devices:
                return False

            reserve = int(max(0.0, _env_float(
                'YOLO_TTA_FUSED_FINAL_GPU_RESERVE_GIB', 2.0,
            )) * GIB)
            admitted: List[int] = []
            for device_idx in devices:
                try:
                    free_bytes, _total_bytes = torch.cuda.mem_get_info(int(device_idx))
                    # Float resize workspace + uint8 input/output. Groups are processed
                    # sequentially, so admission depends on the largest plane only.
                    max_plane = max(
                        [int(out_h) * int(out_w)]
                        + [int(g[1]) * int(g[2]) for g in restore_groups.keys()]
                    )
                    estimate = int(fused_final_gpu_batch_slices()) * (
                        6 * int(max_plane) + 3 * int(out_h) * int(out_w)
                    )
                    if int(free_bytes) >= int(estimate) + int(reserve):
                        admitted.append(int(device_idx))
                except Exception:
                    continue
            if not admitted:
                return False

            def _indices(count: int, out_z: int) -> range:
                count_i = max(1, int(count))
                if count_i >= int(out_t):
                    lo = int(math.floor(float(out_z) * float(count_i) / float(out_t)))
                    hi = int(math.ceil(float(out_z + 1) * float(count_i) / float(out_t)))
                    lo = int(np.clip(lo, 0, count_i - 1))
                    hi = int(np.clip(max(lo + 1, hi), 1, count_i))
                    return range(lo, hi)
                if int(out_t) <= 1 or count_i <= 1:
                    return range(0, 1)
                src_i = int(round(float(out_z) * float(count_i - 1) / float(out_t - 1)))
                src_i = int(np.clip(src_i, 0, count_i - 1))
                return range(src_i, src_i + 1)

            def _lane(device_idx: int, z0_lane: int, z1_lane: int) -> None:
                device = torch.device(f'cuda:{int(device_idx)}')
                batch_slices = int(fused_final_gpu_batch_slices())
                with torch.cuda.device(device):
                    stream = torch.cuda.Stream(device=device)
                    with torch.cuda.stream(stream):
                        for batch0 in range(int(z0_lane), int(z1_lane), int(batch_slices)):
                            batch1 = min(int(z1_lane), int(batch0) + int(batch_slices))
                            count = int(batch1 - batch0)
                            acc = torch.zeros(
                                (count, int(out_h), int(out_w)),
                                dtype=torch.uint8,
                                device=device,
                            )

                            def _or_host_stack(
                                host_stack: np.ndarray,
                                acc_dev: object = acc,
                            ) -> None:
                                host_u8 = np.ascontiguousarray(host_stack, dtype=np.uint8)
                                src_dev = torch.from_numpy(host_u8).to(device, non_blocking=False)
                                in_h = int(host_u8.shape[1])
                                in_w = int(host_u8.shape[2])
                                if (in_h, in_w) == (int(out_h), int(out_w)):
                                    restored = (src_dev > 0).to(torch.uint8)
                                else:
                                    src_f = src_dev.to(torch.float32).unsqueeze(1)
                                    if in_h >= int(out_h) and in_w >= int(out_w):
                                        scaled = F.interpolate(
                                            src_f, size=(int(out_h), int(out_w)), mode='area',
                                        )
                                        # cv2's uint8 INTER_AREA rounds 255*fraction; >= 0.5
                                        # therefore matches the legacy >0 test at 1/510.
                                        restored = (scaled.squeeze(1) >= (1.0 / 510.0)).to(torch.uint8)
                                    else:
                                        scaled = F.interpolate(
                                            src_f, size=(int(out_h), int(out_w)), mode='nearest',
                                        )
                                        restored = (scaled.squeeze(1) > 0).to(torch.uint8)
                                torch.bitwise_or(acc_dev, restored, out=acc_dev)

                            # Keep Cartesian planes in their reduced working geometry;
                            # their one terminal positive-support restore runs on-device.
                            if transverse is not None:
                                transverse_host = np.zeros(
                                    (count, int(transverse.shape[1]), int(transverse.shape[2])),
                                    dtype=np.uint8,
                                )
                                for local_z, out_z in enumerate(range(int(batch0), int(batch1))):
                                    for src_z in _indices(int(transverse.shape[0]), int(out_z)):
                                        transverse_host[local_z] |= np.asarray(
                                            transverse[int(src_z)], dtype=np.uint8,
                                        )
                                _or_host_stack(transverse_host)
                            if sagittal is not None:
                                sagittal_host = np.zeros(
                                    (count, int(sagittal.shape[0]), int(sagittal.shape[2])),
                                    dtype=np.uint8,
                                )
                                for local_z, out_z in enumerate(range(int(batch0), int(batch1))):
                                    for src_z in _indices(int(sagittal.shape[1]), int(out_z)):
                                        sagittal_host[local_z] |= np.asarray(
                                            sagittal[:, int(src_z), :], dtype=np.uint8,
                                        )
                                _or_host_stack(sagittal_host)
                            if coronal is not None:
                                coronal_host = np.zeros(
                                    (count, int(coronal.shape[2]), int(coronal.shape[0])),
                                    dtype=np.uint8,
                                )
                                for local_z, out_z in enumerate(range(int(batch0), int(batch1))):
                                    for src_z in _indices(int(coronal.shape[1]), int(out_z)):
                                        coronal_host[local_z] |= np.ascontiguousarray(
                                            coronal[:, int(src_z), :].T,
                                            dtype=np.uint8,
                                        )
                                _or_host_stack(coronal_host)

                            if native_views or native_projected:
                                native_host = np.zeros(
                                    (count, int(out_h), int(out_w)), dtype=np.uint8,
                                )
                                for local_z, out_z in enumerate(range(int(batch0), int(batch1))):
                                    for _view_name, vol in native_views:
                                        native_host[local_z] |= np.asarray(vol[int(out_z)], dtype=np.uint8)
                                    for _ref, src in native_projected:
                                        _or_native_source_slice(native_host[local_z], src, int(out_z))
                                _or_host_stack(native_host)

                            for geometry, group in restore_groups.items():
                                in_t, in_h, in_w = (int(v) for v in geometry)
                                reduced_host = np.zeros(
                                    (count, int(in_h), int(in_w)), dtype=np.uint8,
                                )
                                for local_z, out_z in enumerate(range(int(batch0), int(batch1))):
                                    source_zs = _restore_source_indices_for_output_z(
                                        int(in_t), int(out_t), int(out_z),
                                    )
                                    for _ref, src in group:
                                        for src_z in source_zs:
                                            _or_native_source_slice(
                                                reduced_host[local_z], src, int(src_z),
                                            )
                                _or_host_stack(reduced_host)

                            final_union_mm[int(batch0):int(batch1)] = acc.cpu().numpy()
                            del acc
                    stream.synchronize()

            bands = _ffv1_contiguous_segments(int(out_t), len(admitted))
            lane_pool: Optional[ThreadPoolExecutor] = None
            lane_futures: List[Future] = []
            first_error: Optional[Exception] = None
            try:
                try:
                    lane_pool = ThreadPoolExecutor(
                        max_workers=len(admitted), thread_name_prefix='g5-gpu-fusion',
                    )
                    for dev, band in zip(admitted, bands):
                        lane_futures.append(lane_pool.submit(
                            _lane, int(dev), int(band[0]), int(band[1]),
                        ))
                except Exception as exc:
                    first_error = exc
                for lane_future in lane_futures:
                    try:
                        lane_future.result()
                    except Exception as exc:
                        if first_error is None:
                            first_error = exc
            finally:
                try:
                    if lane_pool is not None:
                        lane_pool.shutdown(wait=True)
                except Exception as exc:
                    if first_error is None:
                        first_error = exc
                # Futures retain exception tracebacks (and therefore tensor locals). Drop
                # those references before releasing allocator caches for later nvCOMP/NRRD.
                lane_futures.clear()
                try:
                    del lane_future
                except UnboundLocalError:
                    pass
                gc.collect()
                for device_idx in admitted:
                    try:
                        with torch.cuda.device(int(device_idx)):
                            torch.cuda.empty_cache()
                    except Exception:
                        pass
            error_text = (
                f'{type(first_error).__name__}: {first_error}'
                if first_error is not None else ''
            )
            if error_text:
                print(
                    f'Warning: v13.3.18 C13 GPU final fusion failed ({error_text}); '
                    'rewriting the complete result with the CPU G5 path.'
                )
                return False
            print(
                f'v13.3.18 (C13): final grouped restore/OR used {len(admitted)} GPU lane(s), '
                f'{int(fused_final_gpu_batch_slices())} output slice(s) per batch.'
            )
            return True

        if _try_gpu_final_fusion():
            flush_array(final_union_mm)
            return

        def _merge_out_slice(out_z: int) -> None:
            buffers = _scratch_map()
            acc = buffers.get(-1)
            if acc is None:
                acc = np.zeros((out_h, out_w), dtype=np.uint8)
                buffers[-1] = acc
            else:
                acc.fill(np.uint8(0))

            def _indices(count: int) -> range:
                count_i = max(1, int(count))
                if count_i >= int(out_t):
                    lo = int(math.floor(float(out_z) * float(count_i) / float(out_t)))
                    hi = int(math.ceil(float(out_z + 1) * float(count_i) / float(out_t)))
                    lo = int(np.clip(lo, 0, count_i - 1))
                    hi = int(np.clip(max(lo + 1, hi), 1, count_i))
                    return range(lo, hi)
                if int(out_t) <= 1 or count_i <= 1:
                    return range(0, 1)
                src_i = int(round(float(out_z) * float(count_i - 1) / float(out_t - 1)))
                src_i = int(np.clip(src_i, 0, count_i - 1))
                return range(src_i, src_i + 1)

            if transverse is not None:
                for v_idx in _indices(int(transverse.shape[0])):
                    np.bitwise_or(
                        acc,
                        _resize_union_plane_to_out_xy(transverse[int(v_idx)], out_h, out_w),
                        out=acc,
                    )
            if sagittal is not None:
                for v_idx in _indices(int(sagittal.shape[1])):
                    np.bitwise_or(
                        acc,
                        _resize_union_plane_to_out_xy(sagittal[:, int(v_idx), :], out_h, out_w),
                        out=acc,
                    )
            if coronal is not None:
                for v_idx in _indices(int(coronal.shape[1])):
                    np.bitwise_or(
                        acc,
                        _resize_union_plane_to_out_xy(
                            np.ascontiguousarray(coronal[:, int(v_idx), :].T), out_h, out_w,
                        ),
                        out=acc,
                    )

            for _view_name, vol in native_views:
                np.bitwise_or(acc, np.asarray(vol[int(out_z)], dtype=np.uint8), out=acc)

            if group_restores:
                # Native projected layers (the two Radial refs in the reference run)
                # retain the exact C1-independent sparse direct path.
                for _ref, src in native_projected:
                    _or_native_source_slice(acc, src, int(out_z))

                # One thread-private reduced plane is reused by groups with equal XY.
                # Union all t-coverage slices and component layers before the single
                # positive-support resize. For binary masks this is exactly equivalent
                # to OR(resize(layer_i)) while eliminating repeated cv2 calls/allocations.
                for geometry, group in restore_groups.items():
                    in_t, in_h, in_w = (int(v) for v in geometry)
                    reduced_key = ('c1_restore', int(in_h), int(in_w))
                    reduced = buffers.get(reduced_key)
                    if reduced is None:
                        reduced = np.zeros((int(in_h), int(in_w)), dtype=np.uint8)
                        buffers[reduced_key] = reduced
                    else:
                        reduced.fill(np.uint8(0))
                    source_zs = _restore_source_indices_for_output_z(
                        int(in_t), int(out_t), int(out_z),
                    )
                    # Keep each store's adjacent source-z reads together. This retains
                    # G9's sequential mmap/readahead locality while changing only where
                    # the group-wide binary restore occurs.
                    for _ref, src in group:
                        for src_z in source_zs:
                            _or_native_source_slice(reduced, src, int(src_z))
                    np.bitwise_or(
                        acc,
                        _resize_union_plane_to_out_xy(reduced, int(out_h), int(out_w)),
                        out=acc,
                    )
            else:
                # Exact v13.3.16 fallback: restore every reduced component layer
                # independently. Useful for byte-equivalence/performance A/B checks.
                for _ref, src in opened:
                    ref_native = tuple(int(v) for v in _ref.shape) == (out_t, out_h, out_w)
                    if ref_native:
                        _or_native_source_slice(acc, src, int(out_z))
                    else:
                        np.bitwise_or(
                            acc,
                            _read_layer_slice_in_output_shape(
                                src, (int(out_t), int(out_h), int(out_w)), int(out_z),
                            ),
                            out=acc,
                        )

            # final_union is freshly allocated, but assignment is stronger than RMW and
            # guarantees exactly one full-plane destination write for this z.
            final_union_mm[int(out_z), :, :] = acc

        # v13.3.16 G9: submitting all z chunks to 320 workers made the first
        # frontier touch roughly z=0..1280 across every projected store simultaneously.
        # The log's 40 s cold start and second 12 s stall at z=1280 line up exactly with
        # that frontier. Process bounded sequential z bands so mmap readahead/page-table
        # locality can work, while retaining enough slice parallelism for cv2 restores.
        g5_workers = choose_slice_parallel_workers(
            max(1, _env_int('YOLO_TTA_FUSED_FINAL_VIEW_UNION_WORKERS', min(64, int(workers)))),
            out_t,
        )
        g5_band = max(
            int(g5_workers),
            _env_int('YOLO_TTA_FUSED_FINAL_VIEW_UNION_BAND_SLICES', 256),
        )
        print(
            f'v13.3.16 (G9): G5 locality scheduler uses {int(g5_workers)} worker(s) '
            f'and sequential {int(g5_band)}-slice z bands.'
        )
        with tqdm(total=int(out_t), desc='v13.3.16 G9 fused final view/layer union') as pbar:
            for band0 in range(0, int(out_t), int(g5_band)):
                band1 = min(int(out_t), int(band0) + int(g5_band))
                band_count = int(band1 - band0)

                def _merge_band_slice(local_z: int, _band0: int = int(band0)) -> None:
                    _merge_out_slice(int(_band0) + int(local_z))

                parallel_for_indices_chunked(
                    band_count,
                    _merge_band_slice,
                    max_workers=min(int(g5_workers), int(band_count)),
                    desc='v13.3.16 G9 fused final view/layer union band',
                    show_progress=False,
                    target_chunks_per_worker=4,
                )
                pbar.update(int(band_count))
        flush_array(final_union_mm)
    finally:
        for _ref, src in opened:
            try:
                _close_nrrd_layer_source(src)
            finally:
                _drop_nrrd_raw_store_chunks_ram_cache(src)


def assemble_current_view_union_volume(
    view_volumes_by_model: Dict[str, Dict[str, np.ndarray]],
    T: int,
    H: int,
    W: int,
    disable_multiplanar: bool,
    out_path: Path,
    *,
    out_shape_tyx: Optional[Tuple[int, int, int]] = None,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    projected_layer_refs: Optional[Sequence['NrrdLayerRef']] = None,
) -> np.ndarray:
    """Build the single-model final view union.

    The mapping is kept keyed by model name because earlier pipeline stages store temporary
    workspaces under the model stem. v12.2.0 rejects multiple model entries and never
    combines outputs from more than one model. v13.2.4 (task #1, ruling A1): the union is
    allocated in the FINAL SOURCE geometry (``out_shape_tyx``) so all downstream global
    postprocessing runs in source voxels; None keeps the working geometry.
    """
    if len(view_volumes_by_model) != 1:
        raise ValueError('v12.2.0_SLURM supports exactly one --model; multiple-model inference has been removed')

    union_shape = (int(T), int(H), int(W)) if out_shape_tyx is None else tuple(int(v) for v in out_shape_tyx)
    model_name = next(iter(view_volumes_by_model.keys()))
    final_union_mm = allocate_workspace_array(
        shape=union_shape,
        dtype=np.uint8,
        path=out_path,
        desc='Final single-model view-union volume',
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
    )

    print(f"\n=== Assembling final view union for model: {model_name} ===")
    direct_refs = list(projected_layer_refs or [])
    working_equals_out = tuple(int(v) for v in union_shape) == (int(T), int(H), int(W))
    if direct_refs and fused_final_view_union_enabled() and not working_equals_out:
        print(
            f'v13.3.9 (G5): fusing Cartesian restore, native fallback views, and '
            f'{len(direct_refs)} projected component layer(s) into one output-z pass '
            '(YOLO_TTA_FUSED_FINAL_VIEW_UNION=0 restores per-view assembly).'
        )
        assemble_view_volumes_and_projected_layers_fused(
            final_union_mm,
            view_volumes_by_model[model_name],
            direct_refs,
            int(T), int(H), int(W),
            out_shape_tyx=tuple(int(v) for v in union_shape),
            workers=int(workers),
        )
    else:
        assemble_view_volumes_into_native_union(
            final_union_mm=final_union_mm,
            view_volume_mms=view_volumes_by_model[model_name],
            T=T,
            H=H,
            W=W,
            disable_multiplanar=disable_multiplanar,
            out_shape_tyx=out_shape_tyx,
            workers=int(workers),
        )
        # Defensive mixed-mode support. The normal tail only supplies direct refs when
        # G5 is eligible; if a caller supplies them under equal geometry, preserve the
        # A3 Cartesian path and merge refs without omitting any contribution.
        for ref in direct_refs:
            _union_projected_layer_ref_into_volume(
                ref, final_union_mm, workers=int(workers), desc=f'Fallback final union: OR {ref.key}',
            )
    flush_array(final_union_mm)
    return final_union_mm


def union_volume_into_volume(
    dst_mm: np.ndarray,
    src_mm: np.ndarray,
    *,
    workers: int = 1,
    desc: str = 'Union volumes',
) -> None:
    num_slices = int(dst_mm.shape[0]) if int(dst_mm.ndim) > 0 else 0

    def _merge_slice(idx: int) -> None:
        dst_mm[int(idx), :, :] |= np.asarray(src_mm[int(idx)], dtype=np.uint8)

    parallel_for_indices(
        num_slices,
        _merge_slice,
        max_workers=choose_slice_parallel_workers(int(workers), num_slices),
        desc=desc,
        show_progress=False,
    )
    flush_array(dst_mm)


def apply_keep_largest_objects_inplace(
    mask_mm: np.ndarray,
    keep_objects: int,
    temp_dir: Path,
    *,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
) -> Dict[str, int]:
    """Keep only the largest N connected foreground components in the final 3D volume."""
    keep_n = int(keep_objects)
    if keep_n <= 0:
        return {'enabled': 0, 'num_objects': 0, 'kept_objects': 0, 'removed_objects': 0, 'removed_voxels': 0}

    work_dir = temp_dir / 'keep_objects'
    work_dir.mkdir(parents=True, exist_ok=True)
    # v13.3.2 (R6c): label with LOCAL per-slice ids only (no compact relabel write pass) and
    # harvest per-component areas during 2D labeling — the old flow ran a full-volume compact
    # relabel, then a full-volume GIL-held bincount, then rewrote every slice. The keep decision
    # is applied through per-slice local->keep LUTs restricted to each slice's foreground bbox,
    # and slices whose components are all kept are never touched.
    comp_stats: Dict[str, object] = {}
    labels_mm, num_objects, label_paths = label_foreground_volume_streaming(
        mask_mm,
        work_dir / 'final_keep_objects',
        keep_temp=True,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        workers=int(workers),
        compact_relabel=False,
        component_stats_out=comp_stats,
        # C4 also covers the prioritized --keep_objects 1 tail: the same local-label
        # arena and direct packed-LUT apply avoid rebuilding a second dense host cube.
        sparse_local_labels=True,
    )

    if int(num_objects) <= keep_n:
        close_memmap_array(labels_mm)
        if not bool(keep_temp):
            for lp in label_paths:
                try:
                    lp.unlink(missing_ok=True)
                except Exception:
                    pass
        return {
            'enabled': 1,
            'num_objects': int(num_objects),
            'kept_objects': int(num_objects),
            'removed_objects': 0,
            'removed_voxels': 0,
        }

    z_dim = int(mask_mm.shape[0])
    component_counts = np.asarray(comp_stats['component_counts'])
    slice_offsets = np.asarray(comp_stats['slice_offsets'])
    slice_bboxes = np.asarray(comp_stats['slice_bboxes'])
    root_map = np.asarray(comp_stats['root_map'])
    unique_roots = np.asarray(comp_stats['unique_roots'])
    root_areas = np.asarray(comp_stats['root_areas'])
    total_components = int(comp_stats['total_components'])

    order = np.argsort(root_areas[unique_roots])[::-1]
    keep_roots = unique_roots[order[:keep_n]]
    keep_root_flag = np.zeros((int(total_components) + 1,), dtype=bool)
    keep_root_flag[keep_roots] = True
    gid_keep = keep_root_flag[root_map]
    gid_keep[0] = False
    # removed_voxels falls out of the root area table — no per-slice count pass.
    removed_voxels = int(root_areas[unique_roots].sum() - root_areas[keep_roots].sum())

    # Per-slice local->keep LUTs in one concatenated uint8 table; only slices that actually
    # contain a dropped component are rewritten (the mask is 0/1 everywhere in this pipeline,
    # so untouched slices are already in their final state).
    lut_sizes = component_counts.astype(np.int64, copy=False) + 1
    lut_offsets = np.zeros((z_dim,), dtype=np.int64)
    if z_dim > 1:
        lut_offsets[1:] = np.cumsum(lut_sizes)[:-1]
    keep_flat = np.zeros((int(lut_sizes.sum()),), dtype=np.uint8)
    apply_slice = np.zeros((z_dim,), dtype=np.uint8)
    for z in range(z_dim):
        count = int(component_counts[int(z)])
        if count <= 0:
            continue
        offset = int(slice_offsets[int(z)])
        lo = int(lut_offsets[int(z)])
        lut = gid_keep[offset + 1:offset + count + 1]
        keep_flat[lo + 1:lo + count + 1] = lut
        if not bool(lut.all()):
            apply_slice[int(z)] = np.uint8(1)

    kernel_done = False
    if (
        isinstance(labels_mm, SparseSliceLabelStore)
        and compiled_interpolation_kernels_enabled()
        and _numba_sparse_keep_lut_apply_kernel is not None
    ):
        try:
            print(f'keep_objects: applying keep-largest-{keep_n} from sparse labels via numba nogil kernel')
            _numba_sparse_keep_lut_apply_kernel(
                labels_mm.flat,
                labels_mm.offsets,
                keep_flat,
                lut_offsets,
                np.ascontiguousarray(slice_bboxes),
                apply_slice,
                np.asarray(mask_mm),
            )
            kernel_done = True
        except Exception as exc:
            print(f'keep_objects: sparse numba apply unavailable ({exc}); using the thread pool.')
    elif compiled_interpolation_kernels_enabled() and _numba_keep_lut_apply_kernel is not None:
        try:
            print(f'keep_objects: applying keep-largest-{keep_n} via numba nogil kernel')
            _numba_keep_lut_apply_kernel(
                np.asarray(labels_mm),
                keep_flat,
                lut_offsets,
                np.ascontiguousarray(slice_bboxes),
                apply_slice,
                np.asarray(mask_mm),
            )
            kernel_done = True
        except Exception as exc:
            print(f'keep_objects: numba apply unavailable ({exc}); using the thread pool.')

    if not kernel_done:
        apply_zs = np.flatnonzero(apply_slice)

        def _apply_slice_fn(i: int) -> None:
            z = int(apply_zs[int(i)])
            y0, y1, x0, x1 = (int(v) for v in slice_bboxes[z])
            lo = int(lut_offsets[z])
            lut_u8 = keep_flat[lo:lo + int(component_counts[z]) + 1]
            labels_window = np.asarray(labels_mm[z, y0:y1, x0:x1])
            mask_mm[z, y0:y1, x0:x1] = lut_u8[labels_window]

        parallel_for_indices(
            int(apply_zs.size),
            _apply_slice_fn,
            max_workers=choose_slice_parallel_workers(int(workers), max(1, int(apply_zs.size))),
            desc=f'keep_objects: keep largest {keep_n}',
            show_progress=True,
        )
    flush_array(mask_mm)

    close_memmap_array(labels_mm)
    if not bool(keep_temp):
        for lp in label_paths:
            try:
                lp.unlink(missing_ok=True)
            except Exception:
                pass

    return {
        'enabled': 1,
        'num_objects': int(num_objects),
        'kept_objects': int(min(keep_n, int(num_objects))),
        'removed_objects': int(max(0, int(num_objects) - keep_n)),
        'removed_voxels': int(removed_voxels),
    }


def assemble_final_union_after_view_union(
    view_volumes_by_model: Dict[str, Dict[str, np.ndarray]],
    T: int,
    H: int,
    W: int,
    disable_multiplanar: bool,
    out_path: Path,
    temp_dir: Path,
    *,
    out_shape_tyx: Optional[Tuple[int, int, int]] = None,
    enable_3d_void_fill: bool = False,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    projected_layer_refs: Optional[Sequence['NrrdLayerRef']] = None,
) -> np.ndarray:
    """Build the final single-model view union and optionally apply one 3D void fill."""
    final_union_mm = assemble_current_view_union_volume(
        view_volumes_by_model=view_volumes_by_model,
        T=T,
        H=H,
        W=W,
        disable_multiplanar=disable_multiplanar,
        out_path=out_path,
        out_shape_tyx=out_shape_tyx,
        prefer_memory=bool(prefer_memory),
        reserve_bytes=int(reserve_bytes),
        workers=int(workers),
        projected_layer_refs=projected_layer_refs,
    )

    if bool(enable_3d_void_fill):
        print('\n=== Optional 3D void fill after final global union ===')
        final_void_dir = temp_dir / 'final_global_void_fill'
        final_void_dir.mkdir(parents=True, exist_ok=True)
        fill_3d_voids_inplace_streaming(
            final_union_mm,
            final_void_dir / 'final_union',
            keep_temp=bool(keep_temp),
            prefer_memory=bool(prefer_memory),
            reserve_bytes=int(reserve_bytes),
        )
    else:
        print('\n=== Optional 3D void fill disabled (--enable_3d_void_fill not set) ===')
    return final_union_mm


# --------------------------
# v14 centerline-guided final-union filtering
# --------------------------


@dataclass(frozen=True)
class V14CenterlineSamples:
    """Centerline samples in source ``(t,Y,X)`` voxel coordinates.

    ``branch_ids`` identify VMTK polyline-cell occurrences.  VMTK may repeat a
    common trunk in several root-to-target cells; that is intentional here because
    each occurrence carries an unambiguous local tangent for the strict 2D plane.
    """

    points_tyx: np.ndarray
    tangents_tyx: np.ndarray
    radii: np.ndarray
    branch_ids: np.ndarray
    arc_indices: np.ndarray
    backend: str
    endpoint_count: int
    automatic_removal_allowed: bool
    details: Dict[str, object] = field(default_factory=dict, compare=False)


@dataclass(frozen=True)
class V14SectionEvidence:
    sample_index: int
    branch_id: int
    arc_index: int
    center_tyx: Tuple[float, float, float]
    radius: float
    voxel_tyx: np.ndarray = field(compare=False, repr=False)
    used_curved_path: bool = False
    event_id: int = -1


@dataclass(frozen=True)
class V14CenterlineEvent:
    event_id: int
    branch_id: int
    first_arc_index: int
    last_arc_index: int
    evidence_indices: Tuple[int, ...]
    clean_left: bool
    clean_right: bool
    min_t: int
    max_t: int

    @property
    def clean_flanks(self) -> bool:
        return bool(self.clean_left and self.clean_right)


def _v14_vmtk_modules_available() -> bool:
    """Cheap preflight that does not import VTK into the long-lived parent."""
    try:
        import importlib.util
        vtk_ok = importlib.util.find_spec('vtk') is not None
        vmtk_ok = (
            importlib.util.find_spec('vmtk') is not None
            or (
                importlib.util.find_spec('vtkvmtkComputationalGeometryPython') is not None
                and importlib.util.find_spec('vtkvmtkMiscPython') is not None
            )
        )
        return bool(vtk_ok and vmtk_ok)
    except Exception:
        return False


def _v14_import_vmtk_modules() -> Tuple[object, object]:
    """Load either the PyPI/conda VMTK layout or Slicer's split-module layout."""
    import vtk  # type: ignore
    try:
        from vmtk import vtkvmtk  # type: ignore
        return vtk, vtkvmtk
    except (ImportError, OSError):
        import vtkvmtkComputationalGeometryPython as computational  # type: ignore
        import vtkvmtkMiscPython as misc  # type: ignore

        class _V14VmtkNamespace:
            pass

        combined = _V14VmtkNamespace()
        for module in (computational, misc):
            for name in dir(module):
                if str(name).startswith('vtkvmtk'):
                    setattr(combined, name, getattr(module, name))
        return vtk, combined


def _v14_open_surface_one_triangle(vtk: object, surface: object, position_xyz: Sequence[float]) -> None:
    locator = vtk.vtkPointLocator()
    locator.SetDataSet(surface)
    locator.BuildLocator()
    point_id = int(locator.FindClosestPoint(tuple(float(v) for v in position_xyz)))
    if point_id < 0:
        raise RuntimeError('VMTK endpoint network cannot open an empty surface')
    surface.BuildLinks()
    cell_ids = vtk.vtkIdList()
    surface.GetPointCells(int(point_id), cell_ids)
    if int(cell_ids.GetNumberOfIds()) <= 0:
        raise RuntimeError('VMTK endpoint network surface point has no incident triangle')
    # This matches SlicerVMTK ExtractCenterline: the network extractor needs one
    # opening, and deleting one incident cell makes the smallest useful hole.
    surface.DeleteCell(int(cell_ids.GetId(0)))
    surface.RemoveDeletedCells()


def _v14_vmtk_surface_from_coarse_mask(
    mask_tyx: np.ndarray,
    *,
    spacing_tyx: Sequence[float],
    origin_tyx: Sequence[float],
    target_points: int,
) -> Tuple[object, object, object, int]:
    vtk, vtkvmtk = _v14_import_vmtk_modules()
    from vtk.util.numpy_support import numpy_to_vtk  # type: ignore

    binary = np.ascontiguousarray(np.asarray(mask_tyx) != 0, dtype=np.uint8)
    t_dim, h_dim, w_dim = (int(binary.shape[0]), int(binary.shape[1]), int(binary.shape[2]))
    image = vtk.vtkImageData()
    image.SetDimensions(int(w_dim), int(h_dim), int(t_dim))
    image.SetSpacing(
        float(spacing_tyx[2]), float(spacing_tyx[1]), float(spacing_tyx[0]),
    )
    image.SetOrigin(
        float(origin_tyx[2]), float(origin_tyx[1]), float(origin_tyx[0]),
    )
    scalars = numpy_to_vtk(
        binary.reshape(-1), deep=True, array_type=vtk.VTK_UNSIGNED_CHAR,
    )
    image.GetPointData().SetScalars(scalars)

    contour_cls = getattr(vtk, 'vtkFlyingEdges3D', None) or vtk.vtkMarchingCubes
    contour = contour_cls()
    contour.SetInputData(image)
    contour.SetValue(0, 0.5)
    if hasattr(contour, 'ComputeNormalsOff'):
        contour.ComputeNormalsOff()
    if hasattr(contour, 'ComputeGradientsOff'):
        contour.ComputeGradientsOff()
    contour.Update()

    cleaner = vtk.vtkCleanPolyData()
    cleaner.SetInputConnection(contour.GetOutputPort())
    triangles = vtk.vtkTriangleFilter()
    triangles.SetInputConnection(cleaner.GetOutputPort())
    triangles.PassLinesOff()
    triangles.PassVertsOff()
    triangles.Update()

    region_counter = vtk.vtkPolyDataConnectivityFilter()
    region_counter.SetInputConnection(triangles.GetOutputPort())
    region_counter.SetExtractionModeToAllRegions()
    region_counter.ColorRegionsOn()
    region_counter.Update()
    surface_component_count = int(region_counter.GetNumberOfExtractedRegions())

    # Exact VMTK Delaunay processing is not reliable on disconnected surfaces.
    # Analyze the largest connected foreground object, but report the full surface
    # component count so automatic removal can be disabled when centerline coverage
    # is necessarily incomplete.
    connectivity = vtk.vtkPolyDataConnectivityFilter()
    connectivity.SetInputConnection(triangles.GetOutputPort())
    connectivity.SetExtractionModeToLargestRegion()
    connectivity.Update()
    connected = connectivity.GetOutput()
    if int(connected.GetNumberOfPoints()) < 4 or int(connected.GetNumberOfCells()) < 4:
        raise RuntimeError('foreground surface is too small for VMTK centerlines')

    surface_input = connected
    target = max(1000, int(target_points))
    if int(connected.GetNumberOfPoints()) > int(target * 1.20):
        decimator = vtk.vtkDecimatePro()
        decimator.SetInputData(connected)
        decimator.SetTargetReduction(
            min(0.995, max(0.0, 1.0 - float(target) / float(connected.GetNumberOfPoints())))
        )
        decimator.PreserveTopologyOn()
        decimator.BoundaryVertexDeletionOff()
        if hasattr(decimator, 'SplittingOff'):
            decimator.SplittingOff()
        decimator.Update()
        surface_input = decimator.GetOutput()

    final_clean = vtk.vtkCleanPolyData()
    final_clean.SetInputData(surface_input)
    final_triangles = vtk.vtkTriangleFilter()
    final_triangles.SetInputConnection(final_clean.GetOutputPort())
    normals = vtk.vtkPolyDataNormals()
    normals.SetInputConnection(final_triangles.GetOutputPort())
    normals.AutoOrientNormalsOn()
    normals.ConsistencyOn()
    normals.SplittingOff()
    normals.Update()
    surface = vtk.vtkPolyData()
    surface.DeepCopy(normals.GetOutput())
    if int(surface.GetNumberOfPoints()) < 4:
        raise RuntimeError('VMTK preprocessing produced an empty surface')
    return vtk, vtkvmtk, surface, int(surface_component_count)


def _v14_vmtk_auto_endpoint_positions(vtk: object, vtkvmtk: object, surface: object) -> List[Tuple[float, float, float]]:
    network_surface = vtk.vtkPolyData()
    network_surface.DeepCopy(surface)
    bounds = network_surface.GetBounds()
    _v14_open_surface_one_triangle(
        vtk, network_surface, (float(bounds[0]), float(bounds[2]), float(bounds[4])),
    )
    network_filter = vtkvmtk.vtkvmtkPolyDataNetworkExtraction()
    network_filter.SetInputData(network_surface)
    network_filter.SetAdvancementRatio(1.05)
    network_filter.SetRadiusArrayName('Radius')
    network_filter.SetTopologyArrayName('Topology')
    network_filter.SetMarksArrayName('Marks')
    network_filter.Update()

    cleaner = vtk.vtkCleanPolyData()
    cleaner.SetInputConnection(network_filter.GetOutputPort())
    cleaner.Update()
    network = cleaner.GetOutput()
    if int(network.GetNumberOfPoints()) <= 0:
        raise RuntimeError('VMTK network endpoint detection returned no points')
    radius_array = network.GetPointData().GetArray('Radius')
    if radius_array is None:
        raise RuntimeError('VMTK endpoint network has no Radius array')
    network.BuildCells()
    network.BuildLinks(0)
    endpoint_ids = vtk.vtkIdList()
    for cell_index in range(int(network.GetNumberOfCells())):
        cell = network.GetCell(int(cell_index))
        count = int(cell.GetNumberOfPoints())
        if count < 2:
            continue
        for local_index in (0, count - 1):
            point_id = int(cell.GetPointId(int(local_index)))
            incident = vtk.vtkIdList()
            network.GetPointCells(int(point_id), incident)
            if int(incident.GetNumberOfIds()) == 1:
                endpoint_ids.InsertUniqueId(int(point_id))
    ids = [int(endpoint_ids.GetId(i)) for i in range(int(endpoint_ids.GetNumberOfIds()))]
    if len(ids) < 2:
        raise RuntimeError(f'VMTK endpoint network found only {len(ids)} endpoint(s)')
    root_id = max(ids, key=lambda idx: float(radius_array.GetTuple1(int(idx))))
    ordered = [int(root_id)] + [idx for idx in ids if int(idx) != int(root_id)]
    return [tuple(float(v) for v in network.GetPoint(int(idx))) for idx in ordered]


def _v14_vmtk_exact_centerline_arrays(
    vtk: object,
    vtkvmtk: object,
    surface: object,
    endpoint_positions: Sequence[Sequence[float]],
) -> Dict[str, np.ndarray]:
    capper = vtkvmtk.vtkvmtkCapPolyData()
    capper.SetInputData(surface)
    capper.SetDisplacement(0.0)
    capper.SetInPlaneDisplacement(0.0)
    capper.Update()
    capped = capper.GetOutput()

    locator = vtk.vtkPointLocator()
    locator.SetDataSet(capped)
    locator.BuildLocator()
    seed_ids: List[int] = []
    for position in endpoint_positions:
        point_id = int(locator.FindClosestPoint(tuple(float(v) for v in position)))
        if point_id >= 0 and point_id not in seed_ids:
            seed_ids.append(int(point_id))
    if len(seed_ids) < 2:
        raise RuntimeError('VMTK auto endpoints collapsed to fewer than two exact surface seeds')

    source_ids = vtk.vtkIdList()
    source_ids.InsertNextId(int(seed_ids[0]))
    target_ids = vtk.vtkIdList()
    for point_id in seed_ids[1:]:
        target_ids.InsertNextId(int(point_id))

    centerline_filter = vtkvmtk.vtkvmtkPolyDataCenterlines()
    centerline_filter.SetInputData(capped)
    centerline_filter.SetSourceSeedIds(source_ids)
    centerline_filter.SetTargetSeedIds(target_ids)
    centerline_filter.SetRadiusArrayName('MaximumInscribedSphereRadius')
    centerline_filter.SetCostFunction('1/R')
    centerline_filter.SetFlipNormals(False)
    centerline_filter.SetAppendEndPointsToCenterlines(0)
    # VTK9-compatible SlicerVMTK setting; Voronoi simplification has known
    # connectivity failures in that combination.
    centerline_filter.SetSimplifyVoronoi(0)
    centerline_filter.SetCenterlineResampling(0)
    centerline_filter.SetResamplingStepLength(1.0)
    centerline_filter.Update()
    centerline = centerline_filter.GetOutput()
    if centerline is None or int(centerline.GetNumberOfPoints()) <= 0:
        raise RuntimeError('accurate VMTK centerline extraction returned no points')
    radius_array = centerline.GetPointData().GetArray('MaximumInscribedSphereRadius')
    if radius_array is None:
        raise RuntimeError('accurate VMTK centerline has no maximum-inscribed-sphere radius')

    points: List[np.ndarray] = []
    tangents: List[np.ndarray] = []
    radii: List[float] = []
    branches: List[int] = []
    arcs: List[int] = []
    for cell_index in range(int(centerline.GetNumberOfCells())):
        cell = centerline.GetCell(int(cell_index))
        count = int(cell.GetNumberOfPoints())
        if count < 2:
            continue
        ids = [int(cell.GetPointId(i)) for i in range(count)]
        for local_index, point_id in enumerate(ids):
            left = np.asarray(centerline.GetPoint(ids[max(0, local_index - 1)]), dtype=np.float64)
            right = np.asarray(centerline.GetPoint(ids[min(count - 1, local_index + 1)]), dtype=np.float64)
            tangent_xyz = right - left
            norm = float(np.linalg.norm(tangent_xyz))
            if not np.isfinite(norm) or norm <= 1.0e-8:
                continue
            point_xyz = np.asarray(centerline.GetPoint(int(point_id)), dtype=np.float64)
            radius = float(radius_array.GetTuple1(int(point_id)))
            if not np.all(np.isfinite(point_xyz)) or not np.isfinite(radius) or radius <= 0.0:
                continue
            points.append(point_xyz[[2, 1, 0]])
            tangents.append((tangent_xyz / norm)[[2, 1, 0]])
            radii.append(float(radius))
            branches.append(int(cell_index))
            arcs.append(int(local_index))
    if not points:
        raise RuntimeError('accurate VMTK centerline contained no finite tangent/radius samples')
    return {
        'points_tyx': np.asarray(points, dtype=np.float64),
        'tangents_tyx': np.asarray(tangents, dtype=np.float64),
        'radii': np.asarray(radii, dtype=np.float64),
        'branch_ids': np.asarray(branches, dtype=np.int32),
        'arc_indices': np.asarray(arcs, dtype=np.int32),
        'endpoint_count': np.asarray([len(seed_ids)], dtype=np.int32),
    }


def _v14_vmtk_worker(
    coarse_npy: str,
    spacing_tyx: Tuple[float, float, float],
    origin_tyx: Tuple[float, float, float],
    target_points: int,
    result_npz: str,
    status_json: str,
) -> None:
    """Isolated native VMTK worker; a segfault cannot kill the inference parent."""
    try:
        coarse = np.load(str(coarse_npy), mmap_mode='r')
        vtk, vtkvmtk, surface, surface_component_count = _v14_vmtk_surface_from_coarse_mask(
            coarse,
            spacing_tyx=spacing_tyx,
            origin_tyx=origin_tyx,
            target_points=int(target_points),
        )
        endpoints = _v14_vmtk_auto_endpoint_positions(vtk, vtkvmtk, surface)
        arrays = _v14_vmtk_exact_centerline_arrays(vtk, vtkvmtk, surface, endpoints)
        arrays['surface_component_count'] = np.asarray(
            [int(surface_component_count)], dtype=np.int32,
        )
        np.savez_compressed(str(result_npz), **arrays)
        Path(status_json).write_text(json.dumps({
            'ok': True,
            'surface_points': int(surface.GetNumberOfPoints()),
            'surface_cells': int(surface.GetNumberOfCells()),
            'surface_component_count': int(surface_component_count),
            'endpoint_count': int(arrays['endpoint_count'][0]),
            'sample_count': int(arrays['points_tyx'].shape[0]),
        }, indent=2) + '\n')
    except BaseException as exc:
        import traceback as _traceback
        Path(status_json).write_text(json.dumps({
            'ok': False,
            'error': f'{type(exc).__name__}: {exc}',
            'traceback': _traceback.format_exc(),
        }, indent=2) + '\n')
        raise


def _v14_build_coarse_centerline_raster(
    mask_mm: np.ndarray,
    *,
    temp_dir: Path,
    pass_index: int,
    max_dim: int,
    workers: int,
) -> Tuple[Optional[Path], Dict[str, object]]:
    extent = compute_segment_extent_zyx(mask_mm, workers=int(workers))
    x0, x1, y0, y1, t0, t1 = (int(v) for v in extent)
    if x1 < x0 or y1 < y0 or t1 < t0:
        return None, {'empty': True, 'extent_xyt': [int(v) for v in extent]}
    crop_shape = (int(t1 - t0 + 1), int(y1 - y0 + 1), int(x1 - x0 + 1))
    max_axis = max(int(v) for v in crop_shape)
    max_dim_i = max(64, int(max_dim))
    factor_by_dim = int(math.ceil(float(max_axis) / float(max_dim_i)))
    crop_voxels = int(crop_shape[0]) * int(crop_shape[1]) * int(crop_shape[2])
    factor_by_voxels = int(math.ceil(max(1.0, (float(crop_voxels) / 64_000_000.0) ** (1.0 / 3.0))))
    factor = max(1, int(factor_by_dim), int(factor_by_voxels))
    out_shape = tuple(int(math.ceil(float(dim) / float(factor))) for dim in crop_shape)
    padded_shape = (int(out_shape[0]) + 2, int(out_shape[1]) + 2, int(out_shape[2]) + 2)
    work_dir = temp_dir / 'centerline_filter' / f'pass{int(pass_index):02d}'
    work_dir.mkdir(parents=True, exist_ok=True)
    coarse_path = work_dir / 'vmtk_blockmax.npy'
    coarse = np.lib.format.open_memmap(
        coarse_path, mode='w+', dtype=np.uint8, shape=padded_shape,
    )
    coarse[:] = np.uint8(0)
    y_starts = np.arange(0, int(crop_shape[1]), int(factor), dtype=np.int64)
    x_starts = np.arange(0, int(crop_shape[2]), int(factor), dtype=np.int64)
    print(
        f'v14 centerline pass {int(pass_index)}: block-max foreground crop '
        f'{crop_shape} -> {out_shape} (factor={int(factor)}, padded={padded_shape}).'
    )
    # Sequential T blocks keep reads ordered through the source memmap. NumPy's
    # reduceat performs the Y/X block maxima in compiled loops; no thin foreground
    # is lost as it would be by simple striding.
    for out_t in range(int(out_shape[0])):
        src_t0 = int(t0) + int(out_t) * int(factor)
        src_t1 = min(int(t1) + 1, int(src_t0) + int(factor))
        acc = np.zeros((int(crop_shape[1]), int(crop_shape[2])), dtype=np.uint8)
        for src_t in range(int(src_t0), int(src_t1)):
            np.maximum(
                acc,
                np.asarray(mask_mm[int(src_t), int(y0):int(y1) + 1, int(x0):int(x1) + 1], dtype=np.uint8),
                out=acc,
            )
        pooled_y = np.maximum.reduceat(acc, y_starts, axis=0)
        pooled = np.maximum.reduceat(pooled_y, x_starts, axis=1)
        coarse[int(out_t) + 1, 1:int(out_shape[1]) + 1, 1:int(out_shape[2]) + 1] = pooled
    coarse.flush()
    del coarse
    center_offset = (float(factor) - 1.0) * 0.5
    origin_tyx = (
        float(t0) + center_offset - float(factor),
        float(y0) + center_offset - float(factor),
        float(x0) + center_offset - float(factor),
    )
    return coarse_path, {
        'empty': False,
        'extent_xyt': [int(v) for v in extent],
        'crop_shape_tyx': [int(v) for v in crop_shape],
        'coarse_shape_tyx': [int(v) for v in padded_shape],
        'blockmax_factor': int(factor),
        'spacing_tyx': [float(factor), float(factor), float(factor)],
        'origin_tyx': [float(v) for v in origin_tyx],
    }


def _v14_fallback_centerline_samples(
    mask_mm: np.ndarray,
    *,
    extent_xyt: Sequence[int],
    max_samples: int = 512,
) -> V14CenterlineSamples:
    """Marker-only geometric ridge used when optional VMTK is unavailable.

    This is deliberately not authorized to remove voxels. It finds the deepest
    point in the largest 2D component on ordered source slices, forming a bounded
    approximate ridge so audit markers can still be generated and synthetic tests
    can exercise the full plane/component machinery.
    """
    x0, x1, y0, y1, t0, t1 = (int(v) for v in extent_xyt)
    if x1 < x0 or y1 < y0 or t1 < t0:
        return V14CenterlineSamples(
            np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64),
            np.empty((0,), dtype=np.float64), np.empty((0,), dtype=np.int32),
            np.empty((0,), dtype=np.int32), 'geometric_marker_only', 0, False,
            {'reason': 'empty_union'},
        )
    span = int(t1 - t0 + 1)
    stride = max(1, int(math.ceil(float(span) / float(max(2, int(max_samples))))))
    slice_ids = list(range(int(t0), int(t1) + 1, int(stride)))
    if slice_ids and int(slice_ids[-1]) != int(t1):
        slice_ids.append(int(t1))
    points: List[Tuple[float, float, float]] = []
    radii: List[float] = []
    for t_idx in slice_ids:
        crop = np.ascontiguousarray(
            np.asarray(mask_mm[int(t_idx), int(y0):int(y1) + 1, int(x0):int(x1) + 1]) != 0,
            dtype=np.uint8,
        )
        local_x0, local_y0, local_w, local_h = (int(v) for v in cv2.boundingRect(crop))
        if local_w <= 0 or local_h <= 0:
            continue
        crop = np.ascontiguousarray(
            crop[
                int(local_y0):int(local_y0) + int(local_h),
                int(local_x0):int(local_x0) + int(local_w),
            ],
            dtype=np.uint8,
        )
        count, labels, stats, _centroids = cv2.connectedComponentsWithStats(
            crop, connectivity=8, ltype=cv2.CV_32S,
        )
        if int(count) <= 1:
            continue
        largest = 1 + int(np.argmax(stats[1:, cv2.CC_STAT_AREA]))
        component = np.ascontiguousarray(labels == int(largest), dtype=np.uint8)
        dist = cv2.distanceTransform(component, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)
        _min_val, max_val, _min_loc, max_loc = cv2.minMaxLoc(dist)
        if float(max_val) <= 0.0:
            continue
        points.append((
            float(t_idx),
            float(y0 + int(local_y0) + int(max_loc[1])),
            float(x0 + int(local_x0) + int(max_loc[0])),
        ))
        radii.append(float(max_val))
    if len(points) < 2:
        return V14CenterlineSamples(
            np.asarray(points, dtype=np.float64).reshape((-1, 3)),
            np.zeros((len(points), 3), dtype=np.float64), np.asarray(radii, dtype=np.float64),
            np.zeros((len(points),), dtype=np.int32), np.arange(len(points), dtype=np.int32),
            'geometric_marker_only', 0, False,
            {'reason': 'fewer_than_two_ridge_samples', 'stride': int(stride)},
        )
    point_array = np.asarray(points, dtype=np.float64)
    tangents = np.zeros_like(point_array)
    for idx in range(int(point_array.shape[0])):
        left = point_array[max(0, idx - 1)]
        right = point_array[min(int(point_array.shape[0]) - 1, idx + 1)]
        delta = right - left
        norm = float(np.linalg.norm(delta))
        if norm > 0.0:
            tangents[idx] = delta / norm
    return V14CenterlineSamples(
        point_array, tangents, np.asarray(radii, dtype=np.float64),
        np.zeros((len(points),), dtype=np.int32), np.arange(len(points), dtype=np.int32),
        'geometric_marker_only', 0, False,
        {'stride': int(stride), 'sample_count': int(len(points))},
    )


def _v14_run_isolated_process(
    process: mp.Process,
    *,
    timeout_seconds: float,
) -> Tuple[Optional[int], str]:
    """Run a native-code child without allowing it to strand interpreter exit."""
    try:
        process.start()
    except BaseException as exc:
        try:
            process.close()
        except Exception:
            pass
        return None, f'could not start isolated VMTK process: {type(exc).__name__}: {exc}'
    error = ''
    try:
        process.join(timeout=max(1.0, float(timeout_seconds)))
        if process.is_alive():
            error = f'timed out after {float(timeout_seconds):g}s'
            process.terminate()
            process.join(timeout=30.0)
        if process.is_alive():
            if hasattr(process, 'kill'):
                process.kill()
            else:  # pragma: no cover - Python versions without Process.kill
                process.terminate()
            process.join(timeout=10.0)
        if process.is_alive():
            return None, f'{error}; isolated VMTK process could not be stopped'
        return int(process.exitcode) if process.exitcode is not None else None, str(error)
    finally:
        if not process.is_alive():
            try:
                process.close()
            except Exception:
                pass


def _v14_extract_centerline_samples(
    mask_mm: np.ndarray,
    *,
    temp_dir: Path,
    pass_index: int,
    backend: str,
    surface_max_dim: int,
    surface_points: int,
    timeout_seconds: float,
    workers: int,
    keep_temp: bool,
) -> V14CenterlineSamples:
    requested = str(backend).strip().lower()
    modules_available = _v14_vmtk_modules_available()
    # Do not build/read a second full block-max raster when auto mode already
    # knows that optional VMTK is absent. The fallback needs only one exact extent
    # scan plus its bounded set of source slices.
    if requested in {'auto', 'vmtk'} and not bool(modules_available):
        extent = compute_segment_extent_zyx(mask_mm, workers=int(workers))
        missing_error = 'VTK/VMTK Python modules are not installed'
        if requested == 'vmtk':
            print(
                f'Warning: v14 accurate VMTK extraction unavailable ({missing_error}); '
                'preserving the union and emitting empty/pass-through audit stages.'
            )
            return V14CenterlineSamples(
                np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64),
                np.empty((0,), dtype=np.float64), np.empty((0,), dtype=np.int32),
                np.empty((0,), dtype=np.int32), 'vmtk_unavailable_pass_through', 0, False,
                {'extent_xyt': [int(v) for v in extent], 'error': missing_error},
            )
        print(
            f'Warning: v14 accurate VMTK extraction unavailable ({missing_error}); '
            'using the geometric marker-only fallback. Automatic removal remains disabled.'
        )
        fallback = _v14_fallback_centerline_samples(mask_mm, extent_xyt=extent)
        return dataclasses_replace(
            fallback,
            details={**dict(fallback.details), 'extent_xyt': [int(v) for v in extent], 'vmtk_error': missing_error},
        )

    coarse_path, raster_info = _v14_build_coarse_centerline_raster(
        mask_mm,
        temp_dir=temp_dir,
        pass_index=int(pass_index),
        max_dim=int(surface_max_dim),
        workers=int(workers),
    )
    if coarse_path is None:
        return _v14_fallback_centerline_samples(
            mask_mm, extent_xyt=raster_info.get('extent_xyt', _nrrd_empty_segment_extent()),
        )

    vmtk_error = ''
    if requested in {'auto', 'vmtk'} and bool(modules_available):
        work_dir = Path(coarse_path).parent
        result_path = work_dir / 'vmtk_centerlines.npz'
        status_path = work_dir / 'vmtk_status.json'
        context = mp.get_context('spawn')
        process = context.Process(
            target=_v14_vmtk_worker,
            args=(
                str(coarse_path),
                tuple(float(v) for v in raster_info['spacing_tyx']),
                tuple(float(v) for v in raster_info['origin_tyx']),
                int(surface_points),
                str(result_path),
                str(status_path),
            ),
            daemon=False,
        )
        process_exitcode, process_error = _v14_run_isolated_process(
            process, timeout_seconds=float(timeout_seconds),
        )
        if process_error:
            vmtk_error = str(process_error)
        elif int(process_exitcode or 0) != 0:
            vmtk_error = f'isolated process exit code {process_exitcode}'
        elif not result_path.exists():
            vmtk_error = 'isolated process produced no result file'
        else:
            try:
                with np.load(result_path, allow_pickle=False) as data:
                    samples = V14CenterlineSamples(
                        np.asarray(data['points_tyx'], dtype=np.float64).copy(),
                        np.asarray(data['tangents_tyx'], dtype=np.float64).copy(),
                        np.asarray(data['radii'], dtype=np.float64).copy(),
                        np.asarray(data['branch_ids'], dtype=np.int32).copy(),
                        np.asarray(data['arc_indices'], dtype=np.int32).copy(),
                        'vmtk_centerlines',
                        int(np.asarray(data['endpoint_count']).reshape(-1)[0]),
                        bool(int(np.asarray(
                            data['surface_component_count']
                            if 'surface_component_count' in data.files
                            else np.asarray([1], dtype=np.int32)
                        ).reshape(-1)[0]) == 1),
                        dict(raster_info),
                    )
            except Exception as exc:
                vmtk_error = f'invalid isolated VMTK result: {type(exc).__name__}: {exc}'
            else:
                if status_path.exists():
                    try:
                        samples.details.update(json.loads(status_path.read_text()))
                    except Exception:
                        pass
                if not bool(keep_temp):
                    for path in (result_path, status_path, coarse_path):
                        try:
                            Path(path).unlink(missing_ok=True)
                        except Exception:
                            pass
                print(
                    f'v14 centerline pass {int(pass_index)}: accurate VMTK centerlines, '
                    f'samples={int(samples.points_tyx.shape[0])}, endpoints={int(samples.endpoint_count)}.'
                )
                return samples
        if status_path.exists():
            try:
                status = json.loads(status_path.read_text())
                vmtk_error = str(status.get('error', vmtk_error))
            except Exception:
                pass
    elif requested in {'auto', 'vmtk'}:
        vmtk_error = 'VTK/VMTK Python modules are not installed'

    if not bool(keep_temp):
        for path in (
            Path(coarse_path),
            Path(coarse_path).parent / 'vmtk_centerlines.npz',
            Path(coarse_path).parent / 'vmtk_status.json',
        ):
            try:
                Path(path).unlink(missing_ok=True)
            except Exception:
                pass

    if requested == 'vmtk':
        print(
            f'Warning: v14 accurate VMTK extraction unavailable ({vmtk_error}); '
            'preserving pass 0 and skipping the current filter pass.'
        )
        return V14CenterlineSamples(
            np.empty((0, 3), dtype=np.float64), np.empty((0, 3), dtype=np.float64),
            np.empty((0,), dtype=np.float64), np.empty((0,), dtype=np.int32),
            np.empty((0,), dtype=np.int32), 'vmtk_unavailable_pass_through', 0, False,
            {**dict(raster_info), 'error': str(vmtk_error)},
        )

    print(
        f'Warning: v14 accurate VMTK extraction unavailable ({vmtk_error}); '
        'using the geometric marker-only fallback. Automatic removal remains disabled.'
    )
    fallback = _v14_fallback_centerline_samples(
        mask_mm, extent_xyt=raster_info.get('extent_xyt', _nrrd_empty_segment_extent()),
    )
    return dataclasses_replace(
        fallback,
        details={**dict(raster_info), **dict(fallback.details), 'vmtk_error': str(vmtk_error)},
    )


def _v14_subsample_centerline_samples(samples: V14CenterlineSamples) -> V14CenterlineSamples:
    """Densify ordered cells so anomaly spans cover every crossed source slice.

    The historical name is retained to avoid disturbing callers.  Radius-adaptive
    spacing still bounds in-plane work, but the t increment is never greater than
    0.75 source voxels.  Thus a 100-slice web is inspected on all crossed source
    slices instead of only at sparse VMTK vertices.  If the global safety cap is
    reached, deletion is disabled and the retained samples remain marker-only.
    """
    input_count = int(samples.points_tyx.shape[0])
    if input_count <= 1:
        return samples
    max_samples = max(1000, _env_int('YOLO_TTA_CENTERLINE_MAX_DENSE_SAMPLES', 50000))
    points_out: List[np.ndarray] = []
    tangents_out: List[np.ndarray] = []
    radii_out: List[float] = []
    branches_out: List[int] = []
    arcs_out: List[int] = []
    truncated = False
    for branch_id in np.unique(samples.branch_ids):
        branch_idx = np.flatnonzero(samples.branch_ids == int(branch_id))
        if int(branch_idx.size) <= 0:
            continue
        order = branch_idx[np.argsort(samples.arc_indices[branch_idx], kind='stable')]
        branch_arc = 0
        if int(order.size) == 1:
            only = int(order[0])
            points_out.append(np.asarray(samples.points_tyx[only], dtype=np.float64))
            tangents_out.append(np.asarray(samples.tangents_tyx[only], dtype=np.float64))
            radii_out.append(float(samples.radii[only]))
            branches_out.append(int(branch_id))
            arcs_out.append(0)
            if len(points_out) >= int(max_samples):
                truncated = True
                break
            continue
        for local_pos in range(max(1, int(order.size) - 1)):
            idx0 = int(order[min(local_pos, int(order.size) - 1)])
            idx1 = int(order[min(local_pos + 1, int(order.size) - 1)])
            point0 = np.asarray(samples.points_tyx[idx0], dtype=np.float64)
            point1 = np.asarray(samples.points_tyx[idx1], dtype=np.float64)
            delta = point1 - point0
            distance = float(np.linalg.norm(delta))
            desired = max(1.0, min(4.0, 0.5 * max(
                float(samples.radii[idx0]), float(samples.radii[idx1]), 0.5,
            )))
            steps = max(
                1,
                int(math.ceil(abs(float(delta[0])) / 0.75)),
                int(math.ceil(float(distance) / float(desired))),
            )
            first_step = 0 if local_pos == 0 else 1
            for step in range(int(first_step), int(steps) + 1):
                alpha = float(step) / float(max(1, steps))
                point = point0 + alpha * delta
                tangent = (
                    (1.0 - alpha) * np.asarray(samples.tangents_tyx[idx0], dtype=np.float64)
                    + alpha * np.asarray(samples.tangents_tyx[idx1], dtype=np.float64)
                )
                tangent_norm = float(np.linalg.norm(tangent))
                if tangent_norm <= 1.0e-8 and distance > 1.0e-8:
                    tangent = delta / distance
                elif tangent_norm > 1.0e-8:
                    tangent = tangent / tangent_norm
                points_out.append(point)
                tangents_out.append(tangent)
                radii_out.append(float(
                    (1.0 - alpha) * float(samples.radii[idx0])
                    + alpha * float(samples.radii[idx1])
                ))
                branches_out.append(int(branch_id))
                arcs_out.append(int(branch_arc))
                branch_arc += 1
                if len(points_out) >= int(max_samples):
                    truncated = True
                    break
            if truncated:
                break
        if truncated:
            break
    if not points_out:
        return samples
    return V14CenterlineSamples(
        np.asarray(points_out, dtype=np.float64),
        np.asarray(tangents_out, dtype=np.float64),
        np.asarray(radii_out, dtype=np.float64),
        np.asarray(branches_out, dtype=np.int32),
        np.asarray(arcs_out, dtype=np.int32),
        str(samples.backend), int(samples.endpoint_count),
        bool(samples.automatic_removal_allowed and not truncated),
        {
            **dict(samples.details),
            'pre_dense_sample_count': int(input_count),
            'sample_count': int(len(points_out)),
            'dense_sample_cap': int(max_samples),
            'dense_sample_cap_reached': bool(truncated),
        },
    )


def _v14_round_and_sample_mask(
    mask_mm: np.ndarray,
    coords_tyx: np.ndarray,
) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    coords = np.asarray(coords_tyx, dtype=np.float64).reshape((-1, 3))
    rounded = np.rint(coords).astype(np.int64, copy=False)
    shape = tuple(int(v) for v in mask_mm.shape)
    valid = (
        (rounded[:, 0] >= 0) & (rounded[:, 0] < int(shape[0]))
        & (rounded[:, 1] >= 0) & (rounded[:, 1] < int(shape[1]))
        & (rounded[:, 2] >= 0) & (rounded[:, 2] < int(shape[2]))
    )
    values = np.zeros((int(rounded.shape[0]),), dtype=bool)
    if np.any(valid):
        active = rounded[valid]
        values[valid] = np.asarray(
            mask_mm[active[:, 0], active[:, 1], active[:, 2]], dtype=np.uint8,
        ) != 0
    return rounded, valid, values


def _v14_snap_center_to_foreground(
    mask_mm: np.ndarray,
    point_tyx: np.ndarray,
    radius: float,
) -> Optional[np.ndarray]:
    point = np.asarray(point_tyx, dtype=np.float64).reshape(3)
    rounded, valid, values = _v14_round_and_sample_mask(mask_mm, point.reshape(1, 3))
    if bool(valid[0]) and bool(values[0]):
        return np.asarray(rounded[0], dtype=np.float64)
    reach = max(1, min(3, int(math.ceil(max(0.5, float(radius)) * 0.5))))
    base = np.rint(point).astype(np.int64)
    t0 = max(0, int(base[0]) - reach)
    t1 = min(int(mask_mm.shape[0]), int(base[0]) + reach + 1)
    y0 = max(0, int(base[1]) - reach)
    y1 = min(int(mask_mm.shape[1]), int(base[1]) + reach + 1)
    x0 = max(0, int(base[2]) - reach)
    x1 = min(int(mask_mm.shape[2]), int(base[2]) + reach + 1)
    local = np.argwhere(np.asarray(mask_mm[t0:t1, y0:y1, x0:x1]) != 0)
    if int(local.shape[0]) <= 0:
        return None
    global_coords = local.astype(np.float64)
    global_coords[:, 0] += float(t0)
    global_coords[:, 1] += float(y0)
    global_coords[:, 2] += float(x0)
    distances = np.sum((global_coords - point.reshape(1, 3)) ** 2, axis=1)
    return global_coords[int(np.argmin(distances))]


def _v14_plane_basis(tangent_tyx: np.ndarray) -> Optional[Tuple[np.ndarray, np.ndarray, np.ndarray]]:
    normal = np.asarray(tangent_tyx, dtype=np.float64).reshape(3)
    norm = float(np.linalg.norm(normal))
    if not np.isfinite(norm) or norm <= 1.0e-8:
        return None
    normal = normal / norm
    axis = np.eye(3, dtype=np.float64)[int(np.argmin(np.abs(normal)))]
    first = np.cross(normal, axis)
    first_norm = float(np.linalg.norm(first))
    if first_norm <= 1.0e-8:
        return None
    first /= first_norm
    second = np.cross(normal, first)
    second_norm = float(np.linalg.norm(second))
    if second_norm <= 1.0e-8:
        return None
    second /= second_norm
    return normal, first, second


def _v14_unique_foreground_voxels(mask_mm: np.ndarray, coords_tyx: np.ndarray) -> np.ndarray:
    rounded, valid, values = _v14_round_and_sample_mask(mask_mm, coords_tyx)
    keep = valid & values
    if not np.any(keep):
        return np.empty((0, 3), dtype=np.int32)
    return np.unique(np.asarray(rounded[keep], dtype=np.int32), axis=0)


def _v14_sample_one_normal_section(
    mask_mm: np.ndarray,
    samples: V14CenterlineSamples,
    sample_index: int,
    radius_factor: float,
    plane_half_cap: int,
) -> Tuple[str, Optional[V14SectionEvidence]]:
    """Return ``(state, evidence)`` where state is anomaly, clean, or unknown.

    Unknown is deliberately distinct from a tested clean section: an invalid
    tangent, clipped plane, failed center snap, or safety cap may never serve as
    a clean longitudinal flank that authorizes deletion.
    """
    idx = int(sample_index)
    radius = float(samples.radii[idx])
    if not np.isfinite(radius) or radius < 0.5:
        return 'unknown', None
    basis = _v14_plane_basis(samples.tangents_tyx[idx])
    if basis is None:
        return 'unknown', None
    _normal, first, second = basis
    center = _v14_snap_center_to_foreground(mask_mm, samples.points_tyx[idx], radius)
    if center is None:
        return 'unknown', None
    expanded_radius = float(radius_factor) * float(radius)
    if not np.isfinite(expanded_radius) or expanded_radius <= radius:
        return 'unknown', None

    ring_count = max(32, min(2048, int(math.ceil(2.0 * math.pi * expanded_radius))))
    angles = np.linspace(0.0, 2.0 * math.pi, int(ring_count), endpoint=False, dtype=np.float64)
    ring_coords = (
        center.reshape(1, 3)
        + expanded_radius
        * (
            np.cos(angles).reshape(-1, 1) * first.reshape(1, 3)
            + np.sin(angles).reshape(-1, 1) * second.reshape(1, 3)
        )
    )
    ring_rounded, ring_valid, ring_values = _v14_round_and_sample_mask(mask_mm, ring_coords)
    hit_indices = np.flatnonzero(ring_valid & ring_values)
    ring_complete = bool(np.all(ring_valid))
    if int(hit_indices.size) <= 0:
        return ('clean', None) if ring_complete else ('unknown', None)

    # Fast path: check a bounded, angularly distributed set of straight paths in
    # this exact plane. This is the user's proposed line test and avoids the plane
    # raster/connected-component allocation for the common case.
    if int(hit_indices.size) > 24:
        choose = np.linspace(0, int(hit_indices.size) - 1, 24, dtype=np.int64)
        path_hit_indices = hit_indices[choose]
    else:
        path_hit_indices = hit_indices
    evidence_coords: List[np.ndarray] = []
    path_step = 0.75
    path_count = max(2, int(math.ceil(expanded_radius / path_step)) + 1)
    alpha = np.linspace(0.0, 1.0, int(path_count), dtype=np.float64)
    outer_threshold = max(float(radius) + 0.75, 1.10 * float(radius))
    for hit_idx in path_hit_indices:
        endpoint = ring_coords[int(hit_idx)]
        line = center.reshape(1, 3) + alpha.reshape(-1, 1) * (endpoint - center).reshape(1, 3)
        _rounded, valid, values = _v14_round_and_sample_mask(mask_mm, line)
        if bool(np.all(valid & values)):
            distances = alpha * expanded_radius
            outer = line[distances >= outer_threshold]
            if int(outer.shape[0]) > 0:
                evidence_coords.append(outer)
    if evidence_coords:
        voxels = _v14_unique_foreground_voxels(mask_mm, np.concatenate(evidence_coords, axis=0))
        if int(voxels.shape[0]) > 0:
            return 'anomaly', V14SectionEvidence(
                idx, int(samples.branch_ids[idx]), int(samples.arc_indices[idx]),
                tuple(float(v) for v in center), float(radius), voxels, False,
            )

    # Curved-path fallback: rasterize only the tangent-normal plane, label it in
    # 2D, and require the center's foreground component to reach the expanded
    # circle. No equivalent-radius sphere is sampled anywhere in this test.
    half = int(math.ceil(expanded_radius + 1.5))
    if half > int(plane_half_cap):
        return 'unknown', None
    offsets = np.arange(-int(half), int(half) + 1, dtype=np.float64)
    vv, uu = np.meshgrid(offsets, offsets, indexing='ij')
    plane_coords = (
        center.reshape(1, 1, 3)
        + uu[..., None] * first.reshape(1, 1, 3)
        + vv[..., None] * second.reshape(1, 1, 3)
    )
    _plane_rounded, plane_valid, plane_values = _v14_round_and_sample_mask(
        mask_mm, plane_coords.reshape((-1, 3)),
    )
    plane_complete = bool(np.all(plane_valid))
    plane_fg = (plane_valid & plane_values).reshape(plane_coords.shape[:2]).astype(np.uint8)
    center_rc = (int(half), int(half))
    if int(plane_fg[center_rc]) == 0:
        local_fg = np.argwhere(plane_fg != 0)
        if int(local_fg.shape[0]) <= 0:
            return 'unknown', None
        center_dist2 = np.sum((local_fg - np.asarray(center_rc).reshape(1, 2)) ** 2, axis=1)
        nearest_i = int(np.argmin(center_dist2))
        if float(center_dist2[nearest_i]) > 9.0:
            return 'unknown', None
        center_rc = (int(local_fg[nearest_i, 0]), int(local_fg[nearest_i, 1]))
    label_count, labels = cv2.connectedComponents(plane_fg, connectivity=8, ltype=cv2.CV_32S)
    center_label = int(labels[center_rc])
    if int(label_count) <= 1 or center_label <= 0:
        return ('clean', None) if plane_complete else ('unknown', None)
    radial = np.sqrt(uu * uu + vv * vv)
    annulus = np.abs(radial - expanded_radius) <= 1.25
    center_component = labels == int(center_label)
    if not np.any(center_component & annulus):
        return ('clean', None) if plane_complete else ('unknown', None)
    evidence_grid = center_component & (radial >= outer_threshold)
    evidence_plane_coords = plane_coords[evidence_grid]
    if int(evidence_plane_coords.shape[0]) > 16384:
        select = np.linspace(
            0, int(evidence_plane_coords.shape[0]) - 1, 16384, dtype=np.int64,
        )
        evidence_plane_coords = evidence_plane_coords[select]
    voxels = _v14_unique_foreground_voxels(mask_mm, evidence_plane_coords)
    if int(voxels.shape[0]) <= 0:
        return 'unknown', None
    return 'anomaly', V14SectionEvidence(
        idx, int(samples.branch_ids[idx]), int(samples.arc_indices[idx]),
        tuple(float(v) for v in center), float(radius), voxels, True,
    )


def _v14_detect_normal_plane_evidence(
    mask_mm: np.ndarray,
    samples: V14CenterlineSamples,
    *,
    radius_factor: float,
    workers: int,
) -> List[V14SectionEvidence]:
    count = int(samples.points_tyx.shape[0])
    if count <= 0:
        return []
    plane_cap = max(32, _env_int('YOLO_TTA_CENTERLINE_PLANE_HALF_CAP', 256))
    worker_count = max(1, min(8, choose_slice_parallel_workers(int(workers), int(count))))

    def _sample(idx: int) -> Tuple[str, Optional[V14SectionEvidence]]:
        return _v14_sample_one_normal_section(
            mask_mm, samples, int(idx), float(radius_factor), int(plane_cap),
        )

    print(
        f'v14 centerline: testing {int(count)} tangent-normal 2D section(s) '
        f'with {int(worker_count)} worker(s), radius factor X={float(radius_factor):g}.'
    )
    if int(worker_count) <= 1:
        results = [_sample(i) for i in range(int(count))]
    else:
        pool = _acquire_parallel_pool(int(worker_count))
        try:
            results = list(pool.map(_sample, range(int(count))))
        finally:
            _release_parallel_pool(int(worker_count), pool)
    tested_indices = [
        int(idx) for idx, (state, _item) in enumerate(results)
        if str(state) in {'clean', 'anomaly'}
    ]
    unknown_indices = [
        int(idx) for idx, (state, _item) in enumerate(results)
        if str(state) == 'unknown'
    ]
    # ``details`` is intentionally a mutable audit dictionary even though the
    # sample arrays are held in a frozen dataclass.
    samples.details['tested_section_sample_indices'] = tested_indices
    samples.details['unknown_section_sample_indices'] = unknown_indices
    return [item for state, item in results if str(state) == 'anomaly' and item is not None]


def _v14_cluster_centerline_events(
    samples: V14CenterlineSamples,
    evidence: Sequence[V14SectionEvidence],
    *,
    minimum_samples: int = 3,
    close_gap: int = 2,
    clean_flank_samples: int = 3,
) -> Tuple[List[V14CenterlineEvent], List[V14SectionEvidence]]:
    evidence_by_sample: Dict[int, V14SectionEvidence] = {
        int(item.sample_index): item for item in evidence
    }
    tested_raw = samples.details.get('tested_section_sample_indices')
    if tested_raw is None:
        # Conservative behavior for callers that did not run the tri-state
        # detector: evidence is tested-positive; all other samples are unknown.
        tested_samples = set(int(v) for v in evidence_by_sample)
    else:
        tested_samples = set(int(v) for v in tested_raw)
    events: List[V14CenterlineEvent] = []
    selected: List[V14SectionEvidence] = []
    next_event_id = 0
    for branch_id in np.unique(samples.branch_ids):
        branch_idx = np.flatnonzero(samples.branch_ids == int(branch_id))
        if int(branch_idx.size) <= 0:
            continue
        order = branch_idx[np.argsort(samples.arc_indices[branch_idx], kind='stable')]
        anomaly = np.asarray(
            [int(idx) in evidence_by_sample for idx in order], dtype=bool,
        )
        tested_clean = np.asarray(
            [int(idx) in tested_samples and int(idx) not in evidence_by_sample for idx in order],
            dtype=bool,
        )
        # Close only tiny longitudinal gaps; there is intentionally no maximum
        # anomaly/event duration, so a webbed run spanning hundreds of slices remains one event.
        closed = anomaly.copy()
        pos = 0
        while pos < int(closed.size):
            if bool(closed[pos]):
                pos += 1
                continue
            start = int(pos)
            while pos < int(closed.size) and not bool(closed[pos]):
                pos += 1
            stop = int(pos)
            if (
                start > 0 and stop < int(closed.size)
                and int(stop - start) <= int(close_gap)
                and bool(closed[start - 1]) and bool(closed[stop])
                and bool(np.all(tested_clean[int(start):int(stop)]))
            ):
                closed[start:stop] = True
        pos = 0
        while pos < int(closed.size):
            if not bool(closed[pos]):
                pos += 1
                continue
            run_start = int(pos)
            while pos < int(closed.size) and bool(closed[pos]):
                pos += 1
            run_stop = int(pos)
            actual = [
                evidence_by_sample[int(order[k])]
                for k in range(int(run_start), int(run_stop))
                if int(order[k]) in evidence_by_sample
            ]
            if len(actual) < int(minimum_samples):
                continue
            clean_left = bool(
                int(run_start) >= int(clean_flank_samples)
                and np.all(tested_clean[int(run_start) - int(clean_flank_samples):int(run_start)])
            )
            clean_right = bool(
                int(run_stop) + int(clean_flank_samples) <= int(anomaly.size)
                and np.all(tested_clean[int(run_stop):int(run_stop) + int(clean_flank_samples)])
            )
            voxel_blocks = [item.voxel_tyx for item in actual if int(item.voxel_tyx.shape[0]) > 0]
            if not voxel_blocks:
                continue
            all_voxels = np.concatenate(voxel_blocks, axis=0)
            event_selected_indices: List[int] = []
            for item in actual:
                event_selected_indices.append(len(selected))
                selected.append(dataclasses_replace(item, event_id=int(next_event_id)))
            events.append(V14CenterlineEvent(
                int(next_event_id), int(branch_id),
                int(samples.arc_indices[int(order[run_start])]),
                int(samples.arc_indices[int(order[run_stop - 1])]),
                tuple(int(v) for v in event_selected_indices),
                bool(clean_left), bool(clean_right),
                int(np.min(all_voxels[:, 0])), int(np.max(all_voxels[:, 0])),
            ))
            next_event_id += 1
    return events, selected


def _v14_dense_centerline_seeds_by_slice(
    mask_mm: np.ndarray,
    samples: V14CenterlineSamples,
) -> Dict[int, List[Tuple[int, int, float]]]:
    seeds: Dict[int, Dict[Tuple[int, int], float]] = {}

    def _add_protection_seeds(point_tyx: np.ndarray, radius: float) -> None:
        """Rasterize a bounded swept tube used only as a do-not-delete guard.

        Anomaly evidence is still obtained exclusively from the tangent-normal
        2D circle/path test. This small 3D neighborhood is deliberately allowed
        only to make protection more conservative for oblique centerlines whose
        central voxel falls on a neighboring source slice.
        """
        point = np.asarray(point_tyx, dtype=np.float64).reshape(3)
        protect_radius = max(1.0, float(radius))
        t_reach = min(8, int(math.ceil(protect_radius)))
        center_t = int(round(float(point[0])))
        for t_idx in range(int(center_t) - int(t_reach), int(center_t) + int(t_reach) + 1):
            if t_idx < 0 or t_idx >= int(mask_mm.shape[0]):
                continue
            dt = abs(float(t_idx) - float(point[0]))
            inplane = math.sqrt(max(0.0, protect_radius * protect_radius - dt * dt))
            if inplane < 0.5:
                continue
            center_y = int(round(float(point[1])))
            center_x = int(round(float(point[2])))
            selected: Optional[Tuple[int, int]] = None
            if (
                0 <= center_y < int(mask_mm.shape[1])
                and 0 <= center_x < int(mask_mm.shape[2])
                and int(mask_mm[int(t_idx), int(center_y), int(center_x)]) != 0
            ):
                selected = (int(center_y), int(center_x))
            else:
                reach = min(12, max(1, int(math.ceil(inplane))))
                y0 = max(0, int(center_y) - int(reach))
                y1 = min(int(mask_mm.shape[1]), int(center_y) + int(reach) + 1)
                x0 = max(0, int(center_x) - int(reach))
                x1 = min(int(mask_mm.shape[2]), int(center_x) + int(reach) + 1)
                local = np.argwhere(np.asarray(mask_mm[int(t_idx), y0:y1, x0:x1]) != 0)
                if int(local.shape[0]) > 0:
                    global_y = local[:, 0].astype(np.float64) + float(y0)
                    global_x = local[:, 1].astype(np.float64) + float(x0)
                    dist2 = (global_y - float(point[1])) ** 2 + (global_x - float(point[2])) ** 2
                    best = int(np.argmin(dist2))
                    if float(dist2[best]) <= float(inplane * inplane):
                        selected = (int(round(global_y[best])), int(round(global_x[best])))
            if selected is not None:
                per_slice = seeds.setdefault(int(t_idx), {})
                per_slice[selected] = max(
                    float(radius), float(per_slice.get(selected, 0.0)),
                )

    for branch_id in np.unique(samples.branch_ids):
        branch_idx = np.flatnonzero(samples.branch_ids == int(branch_id))
        if int(branch_idx.size) <= 0:
            continue
        order = branch_idx[np.argsort(samples.arc_indices[branch_idx], kind='stable')]
        for local_pos in range(int(order.size)):
            idx0 = int(order[local_pos])
            idx1 = int(order[min(int(order.size) - 1, local_pos + 1)])
            point0 = np.asarray(samples.points_tyx[idx0], dtype=np.float64)
            point1 = np.asarray(samples.points_tyx[idx1], dtype=np.float64)
            radius0 = float(samples.radii[idx0])
            radius1 = float(samples.radii[idx1])
            delta = point1 - point0
            distance = float(np.linalg.norm(delta))
            if distance > max(32.0, 10.0 * max(radius0, radius1, 1.0)):
                steps = 1
            else:
                steps = max(1, int(math.ceil(distance / 0.5)))
            for step in range(int(steps) + 1):
                alpha = float(step) / float(max(1, steps))
                point = point0 + alpha * delta
                radius = (1.0 - alpha) * radius0 + alpha * radius1
                snapped = _v14_snap_center_to_foreground(mask_mm, point, radius)
                if snapped is None:
                    continue
                _add_protection_seeds(snapped, float(radius))
    return {
        int(t_idx): [(int(y), int(x), float(radius)) for (y, x), radius in sorted(per_slice.items())]
        for t_idx, per_slice in seeds.items()
    }


def _v14_watershed_candidate_basin(
    component_u8: np.ndarray,
    good_seeds_yxr: Sequence[Tuple[int, int, float]],
    bad_seeds_yx: Sequence[Tuple[int, int]],
) -> np.ndarray:
    component = np.ascontiguousarray(np.asarray(component_u8) != 0, dtype=np.uint8)
    if not np.any(component):
        return np.zeros_like(component, dtype=np.uint8)
    good = np.zeros_like(component, dtype=np.uint8)
    for y, x, radius in good_seeds_yxr:
        if 0 <= int(y) < int(component.shape[0]) and 0 <= int(x) < int(component.shape[1]):
            seed_radius = max(1, min(8, int(round(0.25 * max(1.0, float(radius))))))
            cv2.circle(good, (int(x), int(y)), int(seed_radius), 1, thickness=-1)
    good &= component
    bad = np.zeros_like(component, dtype=np.uint8)
    for y, x in bad_seeds_yx:
        if 0 <= int(y) < int(component.shape[0]) and 0 <= int(x) < int(component.shape[1]):
            bad[int(y), int(x)] = np.uint8(1)
    if np.any(bad):
        bad = cv2.dilate(bad, np.ones((3, 3), dtype=np.uint8), iterations=1)
    bad &= component
    bad[good != 0] = np.uint8(0)
    fallback = np.ascontiguousarray(bad != 0, dtype=np.uint8)
    if not np.any(bad):
        return fallback
    if not np.any(good):
        # With no trusted centerline seed there is no defensible watershed
        # partition. Mark the complete suspect 2D component so audit-first output
        # is actionable instead of emitting a few seed dots.
        return np.ascontiguousarray(component != 0, dtype=np.uint8)
    dist = cv2.distanceTransform(component, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)
    max_dist = float(np.max(dist))
    if max_dist <= 0.0:
        return fallback
    topography = np.uint8(np.clip(255.0 - 254.0 * dist / max_dist, 0.0, 255.0))
    topography[component == 0] = np.uint8(255)
    markers = np.zeros(component.shape, dtype=np.int32)
    markers[good != 0] = np.int32(1)
    markers[bad != 0] = np.int32(2)
    # watershed_ift has no mask argument. Pre-seeding all background as a third
    # region prevents good/bad fronts from taking a shortcut outside the component.
    markers[component == 0] = np.int32(3)
    try:
        watershed = ndi.watershed_ift(
            topography, markers, structure=np.ones((3, 3), dtype=np.uint8),
        )
        artifact = np.ascontiguousarray((watershed == 2) & (component != 0), dtype=np.uint8)
        if np.any(artifact[good != 0]):
            return fallback
        if np.any(artifact):
            return artifact
    except Exception:
        pass
    return fallback


def _v14_submit_sparse_audit_layer(
    *,
    store_dir: Path,
    store_stats: Dict[str, object],
    shape_tyx: Tuple[int, int, int],
    model_name: str,
    mask_kind: str,
    pass_index: int,
    description: str,
) -> 'NrrdLayerRef':
    key = _nrrd_layer_key(
        view_name='global', source='centerline_filter', mask_kind=str(mask_kind),
        pass_index=int(pass_index), stage='',
    )
    extent = _coerce_segment_extent(store_stats.get('segment_extent_ijk')) or _nrrd_empty_segment_extent()
    is_removed_delta = str(mask_kind) == 'removed_components'
    ref = NrrdLayerRef(
        key=str(key),
        name=_nrrd_layer_name(
            view=None, source='centerline_filter', mask_kind=str(mask_kind),
            pass_index=int(pass_index), stage='',
        ),
        path=Path(store_dir),
        shape=tuple(int(v) for v in shape_tyx),
        dtype='uint8', storage_format=CVOL_FORMAT,
        model_name=str(model_name), view_name='global', view_family='global',
        source='centerline_filter', mask_kind=str(mask_kind),
        pass_index=int(pass_index), stage='', description=str(description),
        layer_role='subtractive_delta' if is_removed_delta else 'marker_only',
        recomposition_op='subtract_from_previous_checkpoint' if is_removed_delta else 'none',
        # Max-pool downbinning does not commute with subtraction.  Sparse audit
        # masks therefore stay full-quality only; downbinned result checkpoints
        # remain the valid low-quality representation of each pass.
        low_quality_recomposition_op='diagnostic_only' if is_removed_delta else 'none',
        force_tight_crop=True,
        mirror_low_quality=False,
        segment_extent_ijk=extent,
        segment_extent_shape_tyx=tuple(int(v) for v in shape_tyx),
        segment_extent_source='incremental_centerline_audit_cvol_index',
    )
    sink = nrrd_layer_sink()
    if sink is None:
        raise RuntimeError('v14 centerline audit layer requested without an NRRD sink')
    sink.submit_layer(
        ref,
        nrrd_layer_output_suffix(
            view_token='Global', source='centerline_filter', mask_kind=str(mask_kind),
            pass_index=int(pass_index), stage='',
        ),
    )
    return ref


def _v14_component_flank_is_clear(
    mask_mm: np.ndarray,
    component_crop: np.ndarray,
    bbox_yxyx: Tuple[int, int, int, int],
    event: V14CenterlineEvent,
    temporal_context: int,
) -> bool:
    y0, y1, x0, x1 = (int(v) for v in bbox_yxyx)
    context = max(1, int(temporal_context))
    left_start = int(event.min_t) - int(context)
    left_stop = int(event.min_t)
    right_start = int(event.max_t) + 1
    right_stop = int(event.max_t) + int(context) + 1
    if left_start < 0 or right_stop > int(mask_mm.shape[0]):
        return False
    component = np.asarray(component_crop) != 0
    area = max(1, int(np.count_nonzero(component)))
    # Permit modest source-slice motion while testing continuity.  Dilating the
    # candidate support makes the guard conservative: nearby anatomy in *any* of
    # the requested clean slices prevents deletion.
    default_motion = max(2, min(8, int(math.ceil(math.sqrt(float(context))))))
    motion = max(0, _env_int('YOLO_TTA_CENTERLINE_FLANK_MOTION_PX', default_motion))
    expanded_y0 = max(0, int(y0) - int(motion))
    expanded_y1 = min(int(mask_mm.shape[1]), int(y1) + int(motion))
    expanded_x0 = max(0, int(x0) - int(motion))
    expanded_x1 = min(int(mask_mm.shape[2]), int(x1) + int(motion))
    support = np.zeros(
        (int(expanded_y1 - expanded_y0), int(expanded_x1 - expanded_x0)), dtype=np.uint8,
    )
    support[
        int(y0 - expanded_y0):int(y1 - expanded_y0),
        int(x0 - expanded_x0):int(x1 - expanded_x0),
    ] = np.asarray(component, dtype=np.uint8)
    if int(motion) > 0:
        size = 2 * int(motion) + 1
        kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (int(size), int(size)))
        support = cv2.dilate(support, kernel, iterations=1)
    for flank_t in list(range(int(left_start), int(left_stop))) + list(range(int(right_start), int(right_stop))):
        flank = np.ascontiguousarray(
            np.asarray(mask_mm[
                int(flank_t), int(expanded_y0):int(expanded_y1), int(expanded_x0):int(expanded_x1)
            ]) != 0,
            dtype=np.uint8,
        )
        overlap = int(np.count_nonzero((support != 0) & (flank != 0)))
        if float(overlap) / float(area) > 0.01:
            return False
    return True


def _v14_apply_component_removal_plan(
    mask_mm: np.ndarray,
    anchors_by_t: Dict[int, List[Tuple[int, int]]],
    *,
    workers: int,
) -> int:
    if not anchors_by_t:
        return 0
    slice_ids = np.asarray(sorted(int(v) for v in anchors_by_t), dtype=np.int64)
    removed_counts = np.zeros((int(slice_ids.size),), dtype=np.int64)

    def _apply(local_index: int) -> None:
        t_idx = int(slice_ids[int(local_index)])
        plane = np.asarray(mask_mm[int(t_idx)], dtype=np.uint8)
        x0, y0, width, height = (int(v) for v in cv2.boundingRect(plane))
        if width <= 0 or height <= 0:
            return
        crop = np.ascontiguousarray(
            plane[int(y0):int(y0) + int(height), int(x0):int(x0) + int(width)] != 0,
            dtype=np.uint8,
        )
        _count, labels = cv2.connectedComponents(crop, connectivity=8, ltype=cv2.CV_32S)
        label_ids: set[int] = set()
        for anchor_y, anchor_x in anchors_by_t[int(t_idx)]:
            local_y = int(anchor_y) - int(y0)
            local_x = int(anchor_x) - int(x0)
            if 0 <= local_y < int(labels.shape[0]) and 0 <= local_x < int(labels.shape[1]):
                label_id = int(labels[local_y, local_x])
                if label_id > 0:
                    label_ids.add(int(label_id))
        if not label_ids:
            return
        remove_mask = np.zeros(labels.shape, dtype=bool)
        for label_id in sorted(label_ids):
            remove_mask |= labels == int(label_id)
        removed_counts[int(local_index)] = np.int64(np.count_nonzero(remove_mask))
        dst_crop = plane[int(y0):int(y0) + int(height), int(x0):int(x0) + int(width)]
        dst_crop[remove_mask] = np.uint8(0)

    parallel_for_indices(
        int(slice_ids.size), _apply,
        max_workers=choose_slice_parallel_workers(int(workers), int(slice_ids.size)),
        desc='v14 centerline: applying safe 2D component removals',
        show_progress=True,
    )
    flush_array(mask_mm)
    return int(np.sum(removed_counts, dtype=np.int64))


def _v14_plan_components_and_write_sparse_audits(
    mask_mm: np.ndarray,
    samples: V14CenterlineSamples,
    events: Sequence[V14CenterlineEvent],
    evidence: Sequence[V14SectionEvidence],
    center_seeds_by_t: Dict[int, List[Tuple[int, int, float]]],
    *,
    temp_dir: Path,
    model_name: str,
    pass_index: int,
    temporal_context: int,
    automatic_removal_enabled: bool,
    workers: int,
    nrrd_layer_refs: List['NrrdLayerRef'],
) -> Dict[str, object]:
    shape = tuple(int(v) for v in mask_mm.shape)
    pass_dir = temp_dir / 'centerline_filter' / f'pass{int(pass_index):02d}'
    removed_store_dir = pass_dir / 'removed_components.cvol'
    watershed_store_dir = pass_dir / 'watershed_candidates.cvol'
    removed_writer = IncrementalRawBBoxMaskStoreWriter(
        shape=shape, store_dir=removed_store_dir, format_name=CVOL_FORMAT,
        desc=f'v14 pass {int(pass_index)} removed 2D components',
        extra_meta={'source': 'centerline_filter', 'pass_index': int(pass_index)},
    )
    watershed_writer = IncrementalRawBBoxMaskStoreWriter(
        shape=shape, store_dir=watershed_store_dir, format_name=CVOL_FORMAT,
        desc=f'v14 pass {int(pass_index)} watershed candidates',
        extra_meta={'source': 'centerline_filter', 'pass_index': int(pass_index)},
    )
    event_by_id = {int(event.event_id): event for event in events}
    evidence_by_t: Dict[int, List[Tuple[V14SectionEvidence, int, int]]] = {}
    for item in evidence:
        for voxel in np.asarray(item.voxel_tyx, dtype=np.int32):
            t_idx, y_idx, x_idx = (int(v) for v in voxel)
            if 0 <= t_idx < int(shape[0]):
                evidence_by_t.setdefault(int(t_idx), []).append((item, int(y_idx), int(x_idx)))
    candidate_slices = sorted(int(v) for v in evidence_by_t)
    anchors_by_t: Dict[int, List[Tuple[int, int]]] = {}
    candidate_components = 0
    protected_components = 0
    deletion_plans = 0
    marker_only_components = 0
    min_component_area = max(1, _env_int('YOLO_TTA_CENTERLINE_MIN_COMPONENT_AREA', 32))
    min_evidence_coverage = min(
        1.0, max(0.0, _env_float('YOLO_TTA_CENTERLINE_MIN_EVIDENCE_COVERAGE', 0.25)),
    )
    cursor = 0
    try:
        for t_idx in candidate_slices:
            if int(t_idx) > int(cursor):
                removed_writer.consume_empty_range(int(cursor), int(t_idx) - int(cursor))
                watershed_writer.consume_empty_range(int(cursor), int(t_idx) - int(cursor))
            removed_plane = np.zeros((int(shape[1]), int(shape[2])), dtype=np.uint8)
            watershed_plane = np.zeros_like(removed_plane)
            plane = np.asarray(mask_mm[int(t_idx)], dtype=np.uint8)
            x0, y0, width, height = (int(v) for v in cv2.boundingRect(plane))
            if width > 0 and height > 0:
                crop = np.ascontiguousarray(
                    plane[int(y0):int(y0) + int(height), int(x0):int(x0) + int(width)] != 0,
                    dtype=np.uint8,
                )
                count, labels, cc_stats, _centroids = cv2.connectedComponentsWithStats(
                    crop, connectivity=8, ltype=cv2.CV_32S,
                )
                bad_by_label: Dict[int, List[Tuple[V14SectionEvidence, int, int]]] = {}
                for item, global_y, global_x in evidence_by_t[int(t_idx)]:
                    local_y = int(global_y) - int(y0)
                    local_x = int(global_x) - int(x0)
                    if 0 <= local_y < int(labels.shape[0]) and 0 <= local_x < int(labels.shape[1]):
                        label_id = int(labels[local_y, local_x])
                        if label_id > 0:
                            bad_by_label.setdefault(int(label_id), []).append(
                                (item, int(local_y), int(local_x)),
                            )
                good_by_label: Dict[int, List[Tuple[int, int, float]]] = {}
                for global_y, global_x, radius in center_seeds_by_t.get(int(t_idx), []):
                    local_y = int(global_y) - int(y0)
                    local_x = int(global_x) - int(x0)
                    if 0 <= local_y < int(labels.shape[0]) and 0 <= local_x < int(labels.shape[1]):
                        label_id = int(labels[local_y, local_x])
                        if label_id > 0:
                            good_by_label.setdefault(int(label_id), []).append(
                                (int(local_y), int(local_x), float(radius)),
                            )

                for label_id, bad_items in sorted(bad_by_label.items()):
                    if int(label_id) <= 0 or int(label_id) >= int(count):
                        continue
                    candidate_components += 1
                    component = labels == int(label_id)
                    area = int(cc_stats[int(label_id), cv2.CC_STAT_AREA])
                    bad_yx = sorted(set((int(y), int(x)) for _item, y, x in bad_items))
                    good_yxr = good_by_label.get(int(label_id), [])
                    relevant_events = [
                        event_by_id[int(event_id)]
                        for event_id in sorted(set(int(item.event_id) for item, _y, _x in bad_items))
                        if int(event_id) in event_by_id
                    ]
                    protected = bool(good_yxr)
                    if protected:
                        protected_components += 1

                    bad_seed_mask = np.zeros(component.shape, dtype=np.uint8)
                    for bad_y, bad_x in bad_yx:
                        bad_seed_mask[int(bad_y), int(bad_x)] = np.uint8(1)
                    bad_coverage_mask = cv2.dilate(
                        bad_seed_mask, np.ones((5, 5), dtype=np.uint8), iterations=1,
                    )
                    evidence_coverage = float(np.count_nonzero((bad_coverage_mask != 0) & component)) / float(max(1, area))

                    can_remove = bool(
                        automatic_removal_enabled
                        and
                        samples.automatic_removal_allowed
                        and not protected
                        and int(area) >= int(min_component_area)
                        and float(evidence_coverage) >= float(min_evidence_coverage)
                        and bool(relevant_events)
                        and all(bool(event.clean_flanks) for event in relevant_events)
                    )
                    if can_remove:
                        bbox = (
                            int(y0), int(y0) + int(height),
                            int(x0), int(x0) + int(width),
                        )
                        can_remove = all(
                            _v14_component_flank_is_clear(
                                mask_mm, component, bbox, event, int(temporal_context),
                            )
                            for event in relevant_events
                        )

                    if can_remove:
                        removed_crop = removed_plane[
                            int(y0):int(y0) + int(height), int(x0):int(x0) + int(width)
                        ]
                        removed_crop[component] = np.uint8(1)
                        first_y, first_x = bad_yx[0]
                        anchors_by_t.setdefault(int(t_idx), []).append(
                            (int(y0) + int(first_y), int(x0) + int(first_x)),
                        )
                        deletion_plans += 1
                    else:
                        basin = _v14_watershed_candidate_basin(
                            np.ascontiguousarray(component, dtype=np.uint8),
                            good_yxr, bad_yx,
                        )
                        marker_crop = watershed_plane[
                            int(y0):int(y0) + int(height), int(x0):int(x0) + int(width)
                        ]
                        marker_crop[basin != 0] = np.uint8(1)
                        marker_only_components += 1

            removed_writer.consume(int(t_idx), removed_plane.reshape((1, int(shape[1]), int(shape[2]))))
            watershed_writer.consume(int(t_idx), watershed_plane.reshape((1, int(shape[1]), int(shape[2]))))
            cursor = int(t_idx) + 1
        if int(cursor) < int(shape[0]):
            removed_writer.consume_empty_range(int(cursor), int(shape[0]) - int(cursor))
            watershed_writer.consume_empty_range(int(cursor), int(shape[0]) - int(cursor))
        removed_stats = removed_writer.finalize()
        watershed_stats = watershed_writer.finalize()
    except BaseException:
        removed_writer.discard()
        watershed_writer.discard()
        raise

    removed_ref = _v14_submit_sparse_audit_layer(
        store_dir=removed_store_dir, store_stats=removed_stats, shape_tyx=shape,
        model_name=str(model_name), mask_kind='removed_components',
        pass_index=int(pass_index),
        description=(
            'Whole 2D source-slice components approved for removal by exact centerline, '
            'clean-flank, evidence-coverage, and centerline-protection guards.'
        ),
    )
    watershed_ref = _v14_submit_sparse_audit_layer(
        store_dir=watershed_store_dir, store_stats=watershed_stats, shape_tyx=shape,
        model_name=str(model_name), mask_kind='watershed_candidates',
        pass_index=int(pass_index),
        description=(
            'Marker-only artifact basins for suspect components that contain protected '
            'centerline anatomy or do not satisfy every automatic-removal guard.'
        ),
    )
    nrrd_layer_refs.extend([removed_ref, watershed_ref])
    applied_removed_voxels = _v14_apply_component_removal_plan(
        mask_mm, anchors_by_t, workers=int(workers),
    )
    planned_removed_voxels = int(removed_stats.get('foreground_voxels', 0))
    if int(applied_removed_voxels) != int(planned_removed_voxels):
        raise RuntimeError(
            f'v14 centerline removal audit mismatch: planned={planned_removed_voxels}, '
            f'applied={applied_removed_voxels}'
        )
    return {
        'candidate_slices': int(len(candidate_slices)),
        'candidate_components': int(candidate_components),
        'protected_components': int(protected_components),
        'removed_components': int(deletion_plans),
        'removed_voxels': int(applied_removed_voxels),
        'watershed_components': int(marker_only_components),
        'watershed_voxels': int(watershed_stats.get('foreground_voxels', 0)),
        'minimum_component_area': int(min_component_area),
        'minimum_evidence_coverage': float(min_evidence_coverage),
    }


def apply_v14_centerline_filter_inplace(
    final_union_mm: np.ndarray,
    *,
    model_name: str,
    temp_dir: Path,
    passes: int,
    backend: str,
    radius_factor: float,
    temporal_context: int,
    automatic_removal_enabled: bool,
    surface_max_dim: int,
    surface_points: int,
    timeout_seconds: float,
    workers: int,
    keep_temp: bool,
    nrrd_layer_refs: List['NrrdLayerRef'],
) -> Dict[str, object]:
    """Iteratively filter the post-union volume and preserve every audit stage."""
    requested_passes = max(0, int(passes))
    stats: Dict[str, object] = {
        'enabled': bool(requested_passes > 0 and str(backend).lower() != 'off'),
        'requested_passes': int(requested_passes),
        'requested_backend': str(backend),
        'radius_factor': float(radius_factor),
        'temporal_context': int(temporal_context),
        'automatic_removal_enabled': bool(automatic_removal_enabled),
        'passes': [],
        'stop_reason': 'disabled',
    }
    if not bool(stats['enabled']):
        return stats

    print('\n=== v14 centerline filter: immutable pass-0 checkpoint ===')
    pass0_ref = materialize_nrrd_global_layer(
        final_union_mm,
        model_name=str(model_name), source='centerline_filter', mask_kind='pass00_input',
        pass_index=0, stage='',
        description=(
            'Untouched final source-geometry union before v14 centerline filtering. '
            'This is the exact pass-0 recovery checkpoint.'
        ),
        temp_dir=temp_dir, workers=int(workers), known_has_foreground=True,
        volume_is_immutable=False, keep_temp=bool(keep_temp),
        layer_role='checkpoint', recomposition_op='select',
        low_quality_recomposition_op='select', force_tight_crop=True,
    )
    if pass0_ref is not None:
        nrrd_layer_refs.append(pass0_ref)

    if str(backend).strip().lower() == 'vmtk' and not _v14_vmtk_modules_available():
        stats['passes_completed'] = 0
        stats['stop_reason'] = 'backend_unavailable_pass_through'
        stats['total_removed_components'] = 0
        stats['total_removed_voxels'] = 0
        stats['total_watershed_voxels'] = 0
        print(
            'v14 centerline filter: VTK/VMTK is unavailable; pass 0 is preserved '
            'and no duplicate pass/result volumes will be generated.'
        )
        return stats

    pass_records: List[Dict[str, object]] = []
    stop_reason = 'pass_limit_exhausted'
    for pass_index in range(1, int(requested_passes) + 1):
        print(f'\n=== v14 centerline filter pass {int(pass_index)}/{int(requested_passes)} ===')
        pass_started = time.monotonic()
        samples = _v14_extract_centerline_samples(
            final_union_mm,
            temp_dir=temp_dir, pass_index=int(pass_index), backend=str(backend),
            surface_max_dim=int(surface_max_dim), surface_points=int(surface_points),
            timeout_seconds=float(timeout_seconds), workers=int(workers),
            keep_temp=bool(keep_temp),
        )
        samples = _v14_subsample_centerline_samples(samples)
        if int(samples.points_tyx.shape[0]) <= 0:
            pass_record = {
                'pass_index': int(pass_index),
                'backend': str(samples.backend),
                'endpoint_count': int(samples.endpoint_count),
                'centerline_samples': 0,
                'section_evidence_samples': 0,
                'longitudinal_events': 0,
                'clean_flank_events': 0,
                'candidate_slices': 0,
                'candidate_components': 0,
                'protected_components': 0,
                'removed_components': 0,
                'removed_voxels': 0,
                'watershed_components': 0,
                'watershed_voxels': 0,
                'seconds': round(float(time.monotonic() - pass_started), 3),
            }
            if samples.details.get('error'):
                pass_record['backend_error'] = str(samples.details.get('error'))
            elif samples.details.get('vmtk_error'):
                pass_record['backend_error'] = str(samples.details.get('vmtk_error'))
            pass_records.append(pass_record)
            stop_reason = 'backend_unavailable_pass_through'
            print(
                f'v14 centerline pass {int(pass_index)}: backend={samples.backend}; '
                'no centerline samples, preserving pass 0 without writing a duplicate result checkpoint.'
            )
            break
        evidence = _v14_detect_normal_plane_evidence(
            final_union_mm, samples,
            radius_factor=float(radius_factor), workers=int(workers),
        )
        events, selected_evidence = _v14_cluster_centerline_events(
            samples, evidence, minimum_samples=3, close_gap=2, clean_flank_samples=3,
        )
        center_seeds = _v14_dense_centerline_seeds_by_slice(final_union_mm, samples)
        component_stats = _v14_plan_components_and_write_sparse_audits(
            final_union_mm, samples, events, selected_evidence, center_seeds,
            temp_dir=temp_dir, model_name=str(model_name), pass_index=int(pass_index),
            temporal_context=int(temporal_context),
            automatic_removal_enabled=bool(automatic_removal_enabled), workers=int(workers),
            nrrd_layer_refs=nrrd_layer_refs,
        )
        result_ref = materialize_nrrd_global_layer(
            final_union_mm,
            model_name=str(model_name), source='centerline_filter', mask_kind='result',
            pass_index=int(pass_index), stage='',
            description=(
                f'Post-union result after v14 centerline filter pass {int(pass_index)}; '
                'watershed-candidate voxels remain present unless their complete 2D component '
                'separately satisfied every automatic-removal guard.'
            ),
            temp_dir=temp_dir, workers=int(workers), known_has_foreground=True,
            volume_is_immutable=False, keep_temp=bool(keep_temp),
            layer_role='checkpoint', recomposition_op='select',
            low_quality_recomposition_op='select', force_tight_crop=True,
        )
        if result_ref is not None:
            nrrd_layer_refs.append(result_ref)
        pass_record: Dict[str, object] = {
            'pass_index': int(pass_index),
            'backend': str(samples.backend),
            'endpoint_count': int(samples.endpoint_count),
            'centerline_samples': int(samples.points_tyx.shape[0]),
            'section_evidence_samples': int(len(evidence)),
            'longitudinal_events': int(len(events)),
            'clean_flank_events': int(sum(1 for event in events if event.clean_flanks)),
            **component_stats,
            'seconds': round(float(time.monotonic() - pass_started), 3),
        }
        if samples.details.get('error'):
            pass_record['backend_error'] = str(samples.details.get('error'))
        elif samples.details.get('vmtk_error'):
            pass_record['backend_error'] = str(samples.details.get('vmtk_error'))
        pass_records.append(pass_record)
        print(
            f'v14 centerline pass {int(pass_index)}: backend={samples.backend}, '
            f'events={len(events)}, removed_components={int(component_stats["removed_components"])}, '
            f'removed_voxels={int(component_stats["removed_voxels"])}, '
            f'watershed_voxels={int(component_stats["watershed_voxels"])}.'
        )
        if int(component_stats['removed_voxels']) <= 0:
            stop_reason = (
                'backend_unavailable_pass_through'
                if int(samples.points_tyx.shape[0]) <= 0
                else 'no_safe_removals'
            )
            break
    stats['passes'] = pass_records
    stats['passes_completed'] = int(len(pass_records))
    stats['stop_reason'] = str(stop_reason)
    stats['total_removed_components'] = int(sum(int(item['removed_components']) for item in pass_records))
    stats['total_removed_voxels'] = int(sum(int(item['removed_voxels']) for item in pass_records))
    stats['total_watershed_voxels'] = int(sum(int(item['watershed_voxels']) for item in pass_records))
    return stats


# --------------------------
# Scan-based interpolation helpers (v13.0.0 removed optional skeletonization)
# --------------------------


def _keep_center_component_2d(mask2d: np.ndarray) -> np.ndarray:
    # v13.2.5 (speed #9): cv2 connectedComponents + the cv2 hole fill replace scipy.ndimage,
    # whose label/fill_holes hold the GIL and serialize the interpolation planner/render
    # thread pools. Semantics are unchanged (8-connected components, 4-connected hole fill).
    mask2d = np.asarray(mask2d, dtype=bool)
    if not mask2d.any():
        return mask2d

    if _planning_kernels_active():
        try:
            # v13.3.4 (T3): fused keep-center + hole fill in one nogil kernel (two flood
            # fills on the small canvas) instead of cv2 label + per-edge uniques + fill.
            return _numba_keep_center_fill_kernel(np.ascontiguousarray(mask2d))
        except Exception as exc:
            _disable_planning_kernels(exc)

    mask_u8 = np.ascontiguousarray(mask2d.astype(np.uint8, copy=False))
    num_labels, labels2d = _cv2_connected_components(mask_u8, connectivity=8)
    if int(num_labels) <= 2:  # background label 0 + at most one component
        return _fill_holes_2d_opencv(mask2d)

    cy = mask2d.shape[0] // 2
    cx = mask2d.shape[1] // 2
    keep = int(labels2d[cy, cx])
    if keep == 0:
        pts = np.argwhere(labels2d > 0)
        if pts.size == 0:
            return np.zeros_like(mask2d, dtype=bool)
        d2 = (pts[:, 0] - cy) ** 2 + (pts[:, 1] - cx) ** 2
        py, px = pts[int(np.argmin(d2))]
        keep = int(labels2d[py, px])

    kept = (labels2d == keep)
    return _fill_holes_2d_opencv(kept)


def _signed_distance_2d(mask2d: np.ndarray) -> np.ndarray:
    # v13.2.5 (speed #9): cv2.distanceTransform with DIST_MASK_PRECISE is the exact euclidean
    # transform (Felzenszwalb), matching scipy.ndimage.distance_transform_edt while releasing
    # the GIL so SDF construction parallelizes across planner threads.
    mask_u8 = np.ascontiguousarray(np.asarray(mask2d, dtype=np.uint8))
    inside = cv2.distanceTransform(mask_u8, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)
    outside = cv2.distanceTransform(np.uint8(1) - mask_u8, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)
    return np.asarray(inside - outside, dtype=np.float32)


INTERPOLATION_LOCAL_SDF_PAD = 2


@dataclass(frozen=True)
class SliceComponentRecord:
    z: int
    label: int
    component_index: int
    bbox: Tuple[int, int, int, int]  # y0, x0, y1, x1 in full-slice coordinates
    anchor: Tuple[int, int]          # centroid-nearest component pixel in full-slice coordinates
    area: int
    mask_crop: np.ndarray            # bool crop in bbox coordinates


@dataclass(frozen=True)
class CroppedProjectionSDF:
    origin_y: int
    origin_x: int
    sdf: np.ndarray


@dataclass
class SliceComponentTable:
    z: int
    shape: Tuple[int, int]
    components: List[SliceComponentRecord]
    by_label: Dict[int, List[SliceComponentRecord]]

    def find_record_for_point(
        self,
        label: int,
        point_yx: Tuple[int, int],
    ) -> Tuple[Optional[SliceComponentRecord], Optional[Tuple[int, int]]]:
        records = self.by_label.get(int(label), [])
        if not records:
            return None, None

        h, w = int(self.shape[0]), int(self.shape[1])
        py = int(np.clip(int(point_yx[0]), 0, max(0, h - 1)))
        px = int(np.clip(int(point_yx[1]), 0, max(0, w - 1)))

        for record in records:
            y0, x0, y1, x1 = record.bbox
            if y0 <= py < y1 and x0 <= px < x1 and bool(record.mask_crop[py - y0, px - x0]):
                return record, (int(py), int(px))

        best_record: Optional[SliceComponentRecord] = None
        best_point: Optional[Tuple[int, int]] = None
        best_d2: Optional[int] = None
        for record in records:
            nearest = _nearest_point_in_component_record(record, (py, px))
            if nearest is None:
                continue
            d2 = int((int(nearest[0]) - py) ** 2 + (int(nearest[1]) - px) ** 2)
            if best_d2 is None or d2 < best_d2:
                best_d2 = int(d2)
                best_record = record
                best_point = nearest
        return best_record, best_point

    def find_branch_continuation(
        self,
        label: int,
        prev_record: SliceComponentRecord,
        prev_anchor: Tuple[int, int],
    ) -> Tuple[Optional[SliceComponentRecord], Optional[Tuple[int, int]]]:
        records = self.by_label.get(int(label), [])
        if not records:
            return None, None
        if len(records) == 1:
            record = records[0]
            return record, _nearest_point_in_component_record(record, prev_anchor)

        best_record: Optional[SliceComponentRecord] = None
        best_anchor: Optional[Tuple[int, int]] = None
        best_score: Optional[Tuple[int, int, int]] = None
        for record in records:
            anchor = _nearest_point_in_component_record(record, prev_anchor)
            if anchor is None:
                continue
            overlap = _component_record_dilated_overlap_count(prev_record, record)
            d2 = int((int(anchor[0]) - int(prev_anchor[0])) ** 2 + (int(anchor[1]) - int(prev_anchor[1])) ** 2)
            score = (int(overlap), -int(d2), int(record.area))
            if best_score is None or score > best_score:
                best_score = score
                best_record = record
                best_anchor = anchor
        return best_record, best_anchor


class SliceComponentTableCache:
    """Lazy per-slice component table and local projection-SDF cache for interpolation.

    Tables are keyed by slice and store cropped masks/bboxes for each 2D component of
    each 3D object label.  Projection candidate search then operates only on the source
    component's bbox expanded by the maximum possible search-angle growth, avoiding
    full-slice SDFs and full-slice boolean projection scans per seed.
    """

    def __init__(self, labels_real: object, slice_luts: Optional['SliceLocalLabelLUTs'] = None) -> None:
        self.labels_real = labels_real
        # v13.3.6 (A1): when the label volume holds per-slice LOCAL ids (compact relabel
        # skipped), tables canonicalize each component's id through the per-slice LUT at
        # build time, so every record.label / by_label key is a canonical 3D object id
        # exactly as if the full-volume relabel had run.
        self.slice_luts = slice_luts
        self.z_dim = int(labels_real.shape[0])
        self.shape_yx = (int(labels_real.shape[1]), int(labels_real.shape[2]))
        self._tables: Dict[int, SliceComponentTable] = {}
        self._projection_sdfs: Dict[Tuple[int, int, int, int, float, int], CroppedProjectionSDF] = {}
        self._table_locks = [threading.Lock() for _ in range(max(1, self.z_dim))]
        self._sdf_lock = threading.Lock()

    def get(self, z: int) -> SliceComponentTable:
        z_i = int(z)
        if z_i < 0 or z_i >= self.z_dim:
            raise IndexError(z_i)
        cached = self._tables.get(z_i)
        if cached is not None:
            return cached
        with self._table_locks[z_i]:
            cached = self._tables.get(z_i)
            if cached is None:
                if isinstance(self.labels_real, SparseSliceLabelStore):
                    origin_y, origin_x, labels2d = self.labels_real.crop_with_origin(z_i)
                else:
                    origin_y, origin_x = 0, 0
                    labels2d = np.asarray(self.labels_real[z_i])  # type: ignore[index]
                cached = _build_slice_component_table(
                    labels2d,
                    z_i,
                    local_to_canonical=(
                        self.slice_luts.lut_for(z_i) if self.slice_luts is not None else None
                    ),
                    origin_yx=(int(origin_y), int(origin_x)),
                    full_shape_yx=self.shape_yx,
                )
                self._tables[z_i] = cached
            return cached

    def prebuild(self, *, workers: int = 1, desc: str = 'Interpolation: per-slice component tables') -> None:
        total = int(self.z_dim)
        if total <= 0:
            return
        worker_count = choose_slice_parallel_workers(int(workers), total)

        def _build(z: int) -> int:
            return int(len(self.get(int(z)).components))

        if worker_count <= 1:
            for z in tqdm(range(total), desc=desc):
                _build(int(z))
            return

        pending = max(worker_count, worker_count * 8)
        for _component_count in tqdm(
            parallel_map_unordered(_build, range(total), max_workers=worker_count, max_pending=pending),
            total=total,
            desc=desc,
        ):
            pass

    def find_record_for_point(
        self,
        z: int,
        label: int,
        point_yx: Tuple[int, int],
    ) -> Tuple[Optional[SliceComponentRecord], Optional[Tuple[int, int]]]:
        return self.get(int(z)).find_record_for_point(int(label), point_yx)

    def get_projection_sdf(
        self,
        record: SliceComponentRecord,
        max_slice_distance: int,
        search_angle_deg: float,
    ) -> CroppedProjectionSDF:
        slope = math.tan(math.radians(float(search_angle_deg)))
        growth = max(0.0, float(slope)) * float(max(0, int(max_slice_distance)))
        pad = max(int(INTERPOLATION_LOCAL_SDF_PAD), int(math.ceil(growth)) + int(INTERPOLATION_LOCAL_SDF_PAD))
        key = (
            int(record.z),
            int(record.label),
            int(record.component_index),
            int(max_slice_distance),
            round(float(search_angle_deg), 6),
            int(pad),
        )
        # v13.3.4 (T3): lock-free read fast path — CPython dict reads are atomic, and 160
        # planner threads were serializing on this lock for cache HITS; only inserts lock.
        cached = self._projection_sdfs.get(key)
        if cached is not None:
            return cached

        h, w = self.shape_yx
        y0, x0, y1, x1 = record.bbox
        crop_y0 = max(0, int(y0) - int(pad))
        crop_x0 = max(0, int(x0) - int(pad))
        crop_y1 = min(int(h), int(y1) + int(pad))
        crop_x1 = min(int(w), int(x1) + int(pad))
        source_crop = np.zeros((int(crop_y1 - crop_y0), int(crop_x1 - crop_x0)), dtype=bool)
        dy0 = int(y0) - int(crop_y0)
        dx0 = int(x0) - int(crop_x0)
        source_crop[dy0:dy0 + int(record.mask_crop.shape[0]), dx0:dx0 + int(record.mask_crop.shape[1])] = record.mask_crop
        cropped = CroppedProjectionSDF(
            origin_y=int(crop_y0),
            origin_x=int(crop_x0),
            sdf=np.ascontiguousarray(_signed_distance_2d(source_crop)),
        )
        with self._sdf_lock:
            existing = self._projection_sdfs.setdefault(key, cropped)
        return existing


def _nearest_point_in_component_record(record: SliceComponentRecord, ref_yx: Tuple[int, int]) -> Optional[Tuple[int, int]]:
    y0, x0, _y1, _x1 = record.bbox
    if _planning_kernels_active():
        try:
            by, bx, found = _numba_nearest_true_pixel_kernel(
                record.mask_crop, int(ref_yx[0]) - int(y0), int(ref_yx[1]) - int(x0),
            )
            if int(found) == 0:
                return None
            return int(by) + int(y0), int(bx) + int(x0)
        except Exception as exc:
            _disable_planning_kernels(exc)
    ys, xs = np.nonzero(record.mask_crop)
    if ys.size == 0:
        return None
    gy = ys.astype(np.int64, copy=False) + int(y0)
    gx = xs.astype(np.int64, copy=False) + int(x0)
    d2 = (gy - int(ref_yx[0])) ** 2 + (gx - int(ref_yx[1])) ** 2
    idx = int(np.argmin(d2))
    return int(gy[idx]), int(gx[idx])


def _component_record_dilated_overlap_count(prev_record: SliceComponentRecord, candidate_record: SliceComponentRecord) -> int:
    py0, px0, py1, px1 = prev_record.bbox
    cy0, cx0, cy1, cx1 = candidate_record.bbox
    # The previous component is dilated by one pixel for branch following, so its
    # effective bbox expands by one pixel in every direction.
    iy0 = max(int(py0) - 1, int(cy0))
    ix0 = max(int(px0) - 1, int(cx0))
    iy1 = min(int(py1) + 1, int(cy1))
    ix1 = min(int(px1) + 1, int(cx1))
    if iy0 >= iy1 or ix0 >= ix1:
        return 0

    if _planning_kernels_active():
        try:
            # v13.3.4 (T3): direct 3x3 neighborhood test — no pad, no cv2.dilate materialization.
            return int(_numba_dilated_overlap_count_kernel(
                prev_record.mask_crop, int(py0), int(px0),
                candidate_record.mask_crop, int(cy0), int(cx0),
                int(iy0), int(ix0), int(iy1), int(ix1),
            ))
        except Exception as exc:
            _disable_planning_kernels(exc)

    padded_prev = np.pad(np.asarray(prev_record.mask_crop, dtype=np.uint8), 1, mode='constant', constant_values=0)
    dilated_prev = cv2.dilate(padded_prev, np.ones((3, 3), dtype=np.uint8), iterations=1).astype(bool, copy=False)
    prev_origin_y = int(py0) - 1
    prev_origin_x = int(px0) - 1
    prev_block = dilated_prev[iy0 - prev_origin_y:iy1 - prev_origin_y, ix0 - prev_origin_x:ix1 - prev_origin_x]
    cand_block = candidate_record.mask_crop[iy0 - int(cy0):iy1 - int(cy0), ix0 - int(cx0):ix1 - int(cx0)]
    return int(np.count_nonzero(prev_block & cand_block))


def _component_records_directly_overlap(a: SliceComponentRecord, b: SliceComponentRecord) -> bool:
    ay0, ax0, ay1, ax1 = a.bbox
    by0, bx0, by1, bx1 = b.bbox
    iy0 = max(int(ay0), int(by0))
    ix0 = max(int(ax0), int(bx0))
    iy1 = min(int(ay1), int(by1))
    ix1 = min(int(ax1), int(bx1))
    if iy0 >= iy1 or ix0 >= ix1:
        return False
    if _planning_kernels_active():
        try:
            # v13.3.4 (T3): early-exit scan — no temporary AND plane per test.
            return bool(_numba_blocks_overlap_any_kernel(
                a.mask_crop, int(ay0), int(ax0),
                b.mask_crop, int(by0), int(bx0),
                int(iy0), int(ix0), int(iy1), int(ix1),
            ))
        except Exception as exc:
            _disable_planning_kernels(exc)
    a_block = a.mask_crop[iy0 - int(ay0):iy1 - int(ay0), ix0 - int(ax0):ix1 - int(ax0)]
    b_block = b.mask_crop[iy0 - int(by0):iy1 - int(by0), ix0 - int(bx0):ix1 - int(bx0)]
    return bool(np.any(a_block & b_block))


def _component_record_mirrored_u(record: SliceComponentRecord, width: int) -> SliceComponentRecord:
    """Mirror a component record along the u (x) axis of its full slice.

    v13.2.2 bug #2/#12: the radial angular domain is [0°, 180°) over full-diameter
    frames, so the frame that continues across the 0°/180° wrap is the neighbor frame
    with u REVERSED (u -> width-1-u). Wrap-crossing comparisons mirror one side through
    this helper so overlap/continuation tests run in a common coordinate frame.
    """
    w = int(width)
    y0, x0, y1, x1 = record.bbox
    return SliceComponentRecord(
        z=int(record.z),
        label=int(record.label),
        component_index=int(record.component_index),
        bbox=(int(y0), int(w - int(x1)), int(y1), int(w - int(x0))),
        anchor=(int(record.anchor[0]), int(w - 1 - int(record.anchor[1]))),
        area=int(record.area),
        mask_crop=record.mask_crop[:, ::-1],
    )


def _build_slice_component_table(
    labels2d: np.ndarray,
    z: int,
    local_to_canonical: Optional[np.ndarray] = None,
    origin_yx: Tuple[int, int] = (0, 0),
    full_shape_yx: Optional[Tuple[int, int]] = None,
) -> SliceComponentTable:
    """Build the per-slice component records for interpolation planning.

    v13.3.4 (T1): ONE cv2.connectedComponentsWithStats call over the slice's foreground bbox
    replaces the old per-3D-label scheme (full-slice foreground argsort + one CC call per label
    on its own bbox crop). In-plane labeling is always 8-connected
    (label_foreground_volume_streaming), so two different 3D labels can never be 8-adjacent
    within a slice — every whole-slice 8-connected component therefore lies wholly inside one
    3D label, and the per-label grouping is recovered by reading the label at any pixel of the
    component. Records carry identical bboxes/areas/anchors; only the LIST order (whole-slice
    scan order instead of ascending-label order) and the arbitrary component_index values
    differ, neither of which affects planning decisions beyond exact ties.
    """
    labels_arr = np.asarray(labels2d)
    h, w = (int(labels_arr.shape[0]), int(labels_arr.shape[1]))
    origin_y, origin_x = (int(origin_yx[0]), int(origin_yx[1]))
    table_shape = (
        (int(full_shape_yx[0]), int(full_shape_yx[1]))
        if full_shape_yx is not None else (h, w)
    )
    components: List[SliceComponentRecord] = []
    by_label: Dict[int, List[SliceComponentRecord]] = {}

    rows_any = labels_arr.any(axis=1)
    if not rows_any.any():
        return SliceComponentTable(
            z=int(z), shape=table_shape, components=components, by_label=by_label,
        )
    cols_any = labels_arr.any(axis=0)
    row_idx = np.flatnonzero(rows_any)
    col_idx = np.flatnonzero(cols_any)
    by0 = int(row_idx[0])
    by1 = int(row_idx[-1]) + 1
    bx0 = int(col_idx[0])
    bx1 = int(col_idx[-1]) + 1

    crop_labels = labels_arr[by0:by1, bx0:bx1]
    fg_u8 = (crop_labels > 0).astype(np.uint8, copy=False)
    num_cc, cc, stats, centroids = cv2.connectedComponentsWithStats(
        np.ascontiguousarray(fg_u8), connectivity=8, ltype=cv2.CV_32S,
    )
    for local_lbl in range(1, int(num_cc)):
        area = int(stats[int(local_lbl), cv2.CC_STAT_AREA])
        if area <= 0:
            continue
        x = int(stats[int(local_lbl), cv2.CC_STAT_LEFT])
        y = int(stats[int(local_lbl), cv2.CC_STAT_TOP])
        width = int(stats[int(local_lbl), cv2.CC_STAT_WIDTH])
        height = int(stats[int(local_lbl), cv2.CC_STAT_HEIGHT])
        if width <= 0 or height <= 0:
            continue
        comp_crop = np.ascontiguousarray(cc[y:y + height, x:x + width] == int(local_lbl))
        ys, xs = np.nonzero(comp_crop)
        if ys.size <= 0:
            continue
        # Whole component belongs to one 3D label (see docstring): read it at any member pixel.
        label_i = int(crop_labels[y + int(ys[0]), x + int(xs[0])])
        if label_i <= 0:
            continue
        if local_to_canonical is not None:
            # v13.3.6 (A1): per-slice LOCAL id -> canonical 3D object id (no relabel pass).
            label_i = int(local_to_canonical[label_i])
            if label_i <= 0:
                continue
        centroid_x = float(centroids[int(local_lbl), 0]) - float(x)
        centroid_y = float(centroids[int(local_lbl), 1]) - float(y)
        d2 = (ys.astype(np.float32, copy=False) - centroid_y) ** 2 + (xs.astype(np.float32, copy=False) - centroid_x) ** 2
        anchor_idx = int(np.argmin(d2))
        record = SliceComponentRecord(
            z=int(z),
            label=int(label_i),
            component_index=int(len(components) + 1),
            bbox=(
                int(origin_y + by0 + y), int(origin_x + bx0 + x),
                int(origin_y + by0 + y + height), int(origin_x + bx0 + x + width),
            ),
            anchor=(
                int(origin_y + by0 + y + int(ys[anchor_idx])),
                int(origin_x + bx0 + x + int(xs[anchor_idx])),
            ),
            area=int(area),
            mask_crop=comp_crop,
        )
        components.append(record)
        by_label.setdefault(int(label_i), []).append(record)
    return SliceComponentTable(
        z=int(z), shape=table_shape, components=components, by_label=by_label,
    )


def _component_record_to_local_canvas(record: SliceComponentRecord, anchor_yx: Tuple[int, int], half_width: int) -> np.ndarray:
    size = int(2 * int(half_width) + 1)
    local = np.zeros((size, size), dtype=bool)
    y0, x0, _y1, _x1 = record.bbox
    y_off = int(y0) - int(anchor_yx[0]) + int(half_width)
    x_off = int(x0) - int(anchor_yx[1]) + int(half_width)
    if _planning_kernels_active():
        try:
            _numba_scatter_true_kernel(record.mask_crop, int(y_off), int(x_off), local)
            return local
        except Exception as exc:
            _disable_planning_kernels(exc)
    ys, xs = np.nonzero(record.mask_crop)
    if ys.size == 0:
        return local
    yy = ys.astype(np.int64, copy=False) + int(y_off)
    xx = xs.astype(np.int64, copy=False) + int(x_off)
    valid = (yy >= 0) & (yy < size) & (xx >= 0) & (xx < size)
    local[yy[valid], xx[valid]] = True
    return local


def _local_half_width_for_component_records(
    source_record: SliceComponentRecord,
    source_anchor: Tuple[int, int],
    target_record: SliceComponentRecord,
    target_anchor: Tuple[int, int],
) -> int:
    max_extent = 0.0
    for record, anchor in ((source_record, source_anchor), (target_record, target_anchor)):
        y0, x0, _y1, _x1 = record.bbox
        if _planning_kernels_active():
            try:
                ext = int(_numba_max_abs_extent_kernel(
                    record.mask_crop, int(anchor[0]) - int(y0), int(anchor[1]) - int(x0),
                ))
                if ext >= 0:
                    max_extent = max(max_extent, float(ext))
                continue
            except Exception as exc:
                _disable_planning_kernels(exc)
        ys, xs = np.nonzero(record.mask_crop)
        if ys.size == 0:
            continue
        gy = ys.astype(np.int64, copy=False) + int(y0)
        gx = xs.astype(np.int64, copy=False) + int(x0)
        max_extent = max(
            max_extent,
            float(np.max(np.abs(gy - int(anchor[0])))),
            float(np.max(np.abs(gx - int(anchor[1])))),
        )

    max_extent = max(
        max_extent,
        float(abs(int(target_anchor[0]) - int(source_anchor[0]))),
        float(abs(int(target_anchor[1]) - int(source_anchor[1]))),
    )
    return max(4, int(math.ceil(max_extent)) + 4)


@dataclass(frozen=True)
class SliceEndpointSeed:
    label: int
    point: Tuple[int, int, int]  # (slice, row, col)
    direction_sign: int          # -1 or +1 along the slice axis


@dataclass(frozen=True)
class SliceProjectionCandidate:
    source_label: int
    target_label: int
    source_point: Tuple[int, int, int]
    target_point: Tuple[int, int, int]
    slice_distance: int


def _nearest_point_in_mask(mask2d: np.ndarray, ref_yx: Tuple[int, int]) -> Optional[Tuple[int, int]]:
    if _planning_kernels_active():
        try:
            by, bx, found = _numba_nearest_true_pixel_kernel(
                np.asarray(mask2d, dtype=bool), int(ref_yx[0]), int(ref_yx[1]),
            )
            if int(found) == 0:
                return None
            return int(by), int(bx)
        except Exception as exc:
            _disable_planning_kernels(exc)
    ys, xs = np.nonzero(mask2d)
    if ys.size == 0:
        return None
    d2 = (ys.astype(np.int64) - int(ref_yx[0])) ** 2 + (xs.astype(np.int64) - int(ref_yx[1])) ** 2
    idx = int(np.argmin(d2))
    return int(ys[idx]), int(xs[idx])


def _component_mask_and_anchor(mask2d: np.ndarray, point_yx: Tuple[int, int]) -> Tuple[np.ndarray, Optional[Tuple[int, int]]]:
    mask2d = np.asarray(mask2d, dtype=bool)
    if not mask2d.any():
        return np.zeros(mask2d.shape, dtype=bool), None

    labels2d, num = ndi.label(mask2d, structure=np.ones((3, 3), dtype=bool))
    if num <= 0:
        return np.zeros(mask2d.shape, dtype=bool), None

    py = int(np.clip(int(point_yx[0]), 0, mask2d.shape[0] - 1))
    px = int(np.clip(int(point_yx[1]), 0, mask2d.shape[1] - 1))
    lbl = int(labels2d[py, px])
    if lbl <= 0:
        nearest = _nearest_point_in_mask(mask2d, (py, px))
        if nearest is None:
            return np.zeros(mask2d.shape, dtype=bool), None
        lbl = int(labels2d[nearest[0], nearest[1]])
        py, px = nearest

    comp = labels2d == lbl
    anchor = _nearest_point_in_mask(comp, (py, px))
    return comp.astype(bool), anchor


def _component_centroid_anchor(mask2d: np.ndarray) -> Optional[Tuple[int, int]]:
    ys, xs = np.nonzero(mask2d)
    if ys.size == 0:
        return None
    cy = float(np.mean(ys))
    cx = float(np.mean(xs))
    d2 = (ys.astype(np.float32) - cy) ** 2 + (xs.astype(np.float32) - cx) ** 2
    idx = int(np.argmin(d2))
    return int(ys[idx]), int(xs[idx])


def _component_max_radius(mask2d: np.ndarray) -> float:
    # v13.2.5 (speed #9): exact cv2 distance transform (GIL-releasing) replaces scipy EDT.
    mask_u8 = np.ascontiguousarray(np.asarray(mask2d, dtype=np.uint8))
    if not np.any(mask_u8):
        return 0.0
    if bool(np.all(mask_u8)):
        # No background pixel: the inscribed radius is unbounded within the crop; return an
        # upper bound so the caller never rejects on this degenerate case.
        return float(max(mask_u8.shape[0], mask_u8.shape[1]))
    return float(np.max(cv2.distanceTransform(mask_u8, cv2.DIST_L2, cv2.DIST_MASK_PRECISE)))


def _follow_branch_component(
    slice_mask: np.ndarray,
    prev_component_mask: np.ndarray,
    prev_anchor: Tuple[int, int],
) -> Tuple[np.ndarray, Optional[Tuple[int, int]]]:
    slice_mask = np.asarray(slice_mask, dtype=bool)
    if not slice_mask.any():
        return np.zeros(slice_mask.shape, dtype=bool), None

    labels2d, num = ndi.label(slice_mask, structure=np.ones((3, 3), dtype=bool))
    if num <= 0:
        return np.zeros(slice_mask.shape, dtype=bool), None

    if num == 1:
        comp = labels2d == 1
        return comp.astype(bool), _nearest_point_in_mask(comp, prev_anchor)

    dil_prev = ndi.binary_dilation(np.asarray(prev_component_mask, dtype=bool), structure=np.ones((3, 3), dtype=bool))

    best_lbl = 0
    best_score: Optional[Tuple[int, int, int]] = None
    for lbl in range(1, int(num) + 1):
        comp = labels2d == lbl
        overlap = int(np.count_nonzero(comp & dil_prev))
        anchor = _nearest_point_in_mask(comp, prev_anchor)
        if anchor is None:
            continue
        d2 = int((anchor[0] - int(prev_anchor[0])) ** 2 + (anchor[1] - int(prev_anchor[1])) ** 2)
        area = int(np.count_nonzero(comp))
        score = (overlap, -d2, area)
        if best_score is None or score > best_score:
            best_score = score
            best_lbl = int(lbl)

    if best_lbl <= 0:
        return np.zeros(slice_mask.shape, dtype=bool), None

    comp = labels2d == best_lbl
    return comp.astype(bool), _nearest_point_in_mask(comp, prev_anchor)


def _component_to_local_canvas(mask2d: np.ndarray, anchor_yx: Tuple[int, int], half_width: int) -> np.ndarray:
    size = int(2 * half_width + 1)
    local = np.zeros((size, size), dtype=bool)
    y_off = -int(anchor_yx[0]) + int(half_width)
    x_off = -int(anchor_yx[1]) + int(half_width)
    if _planning_kernels_active():
        try:
            _numba_scatter_true_kernel(np.asarray(mask2d, dtype=bool), int(y_off), int(x_off), local)
            return local
        except Exception as exc:
            _disable_planning_kernels(exc)
    ys, xs = np.nonzero(mask2d)
    if ys.size == 0:
        return local

    yy = ys.astype(np.int64) + int(y_off)
    xx = xs.astype(np.int64) + int(x_off)
    valid = (yy >= 0) & (yy < size) & (xx >= 0) & (xx < size)
    local[yy[valid], xx[valid]] = True
    return local


def _paste_local_mask_onto_slice(
    dest_slice: np.ndarray,
    local_mask: np.ndarray,
    center_yx: Tuple[float, float],
    *,
    dst_bbox_union: Optional[List[int]] = None,
) -> int:
    """OR a centered local mask into a slice and optionally accumulate its clipped dst bbox.

    ``dst_bbox_union`` is a mutable ``[y0, x0, y1, x1]`` initialized by the caller to
    ``[H, W, 0, 0]``. v13.3.10 T7 uses it while rendering so the later bridge merge and
    optional delta capture touch only the union of regions that a paste could have changed.
    The return value and paste arithmetic remain unchanged.
    """
    if not np.any(local_mask):
        return 0

    size_y, size_x = local_mask.shape
    hh_y = size_y // 2
    hh_x = size_x // 2
    cy = int(round(float(center_yx[0])))
    cx = int(round(float(center_yx[1])))

    y0 = cy - hh_y
    x0 = cx - hh_x
    y1 = y0 + size_y
    x1 = x0 + size_x

    dy0 = max(0, -y0)
    dx0 = max(0, -x0)
    dy1 = max(0, y1 - dest_slice.shape[0])
    dx1 = max(0, x1 - dest_slice.shape[1])

    src_y0 = dy0
    src_y1 = size_y - dy1
    src_x0 = dx0
    src_x1 = size_x - dx1

    dst_y0 = y0 + dy0
    dst_y1 = y1 - dy1
    dst_x0 = x0 + dx0
    dst_x1 = x1 - dx1

    if src_y0 >= src_y1 or src_x0 >= src_x1:
        return 0

    if dst_bbox_union is not None:
        dst_bbox_union[0] = min(int(dst_bbox_union[0]), int(dst_y0))
        dst_bbox_union[1] = min(int(dst_bbox_union[1]), int(dst_x0))
        dst_bbox_union[2] = max(int(dst_bbox_union[2]), int(dst_y1))
        dst_bbox_union[3] = max(int(dst_bbox_union[3]), int(dst_x1))

    if _planning_kernels_active():
        try:
            # v13.3.4 (T3): one nogil pass counts+writes only newly-set pixels (bridge slices
            # hold 0/1) instead of two bool temporaries + a count + an OR store per paste.
            return int(_numba_paste_masked_or_kernel(
                np.asarray(dest_slice), np.asarray(local_mask, dtype=bool),
                int(dst_y0), int(dst_x0),
                int(src_y0), int(src_y1), int(src_x0), int(src_x1),
            ))
        except Exception as exc:
            _disable_planning_kernels(exc)

    patch = np.asarray(local_mask[src_y0:src_y1, src_x0:src_x1], dtype=bool)
    current = np.asarray(dest_slice[dst_y0:dst_y1, dst_x0:dst_x1], dtype=bool)
    added = int(np.count_nonzero(patch & (~current)))
    dest_slice[dst_y0:dst_y1, dst_x0:dst_x1] |= patch
    return added


def _local_half_width_for_components(
    source_component: np.ndarray,
    source_anchor: Tuple[int, int],
    target_component: np.ndarray,
    target_anchor: Tuple[int, int],
) -> int:
    max_extent = 0.0
    for comp, anchor in ((source_component, source_anchor), (target_component, target_anchor)):
        ys, xs = np.nonzero(comp)
        if ys.size == 0:
            continue
        max_extent = max(
            max_extent,
            float(np.max(np.abs(ys.astype(np.int64) - int(anchor[0])))),
            float(np.max(np.abs(xs.astype(np.int64) - int(anchor[1])))),
        )

    max_extent = max(
        max_extent,
        float(abs(int(target_anchor[0]) - int(source_anchor[0]))),
        float(abs(int(target_anchor[1]) - int(source_anchor[1]))),
    )
    return max(4, int(math.ceil(max_extent)) + 4)


_NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED = False
_NUMBA_PLANNING_KERNELS_RUNTIME_DISABLED = False


def compiled_interpolation_kernels_enabled() -> bool:
    return bool(_numba is not None and _env_flag('YOLO_TTA_INTERPOLATION_COMPILED_KERNELS', True))


# --------------------------
# v13.3.4 (T3): numba nogil kernels for the seed-planning inner loop
# --------------------------
# Seed planning ran at ~20-100 seeds/s with 160 planner threads: the per-seed work is dozens of
# tiny numpy/python steps (nonzero + argmin nearest-point searches, local-canvas scatters,
# extent reductions, cv2 dilate/label calls on small crops) whose python glue serializes on the
# GIL. Each helper below compresses one of those steps into a single nogil call; the python
# implementations remain as automatic fallbacks (first failure disables all planning kernels
# for the process, mirroring the projection-kernel guard).

if _numba is not None:
    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_nearest_true_pixel_kernel(mask: np.ndarray, ref_y: int, ref_x: int) -> Tuple[int, int, int]:
        best_y = -1
        best_x = -1
        best_d2 = np.int64(0)
        found = 0
        for y in range(mask.shape[0]):
            for x in range(mask.shape[1]):
                if not mask[y, x]:
                    continue
                dy = np.int64(y - ref_y)
                dx = np.int64(x - ref_x)
                d2 = dy * dy + dx * dx
                if found == 0 or d2 < best_d2:
                    best_d2 = d2
                    best_y = y
                    best_x = x
                    found = 1
        return best_y, best_x, found

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_scatter_true_kernel(mask: np.ndarray, y_off: int, x_off: int, out: np.ndarray) -> None:
        size_y = out.shape[0]
        size_x = out.shape[1]
        for y in range(mask.shape[0]):
            yy = y + y_off
            if yy < 0 or yy >= size_y:
                continue
            for x in range(mask.shape[1]):
                if mask[y, x]:
                    xx = x + x_off
                    if 0 <= xx < size_x:
                        out[yy, xx] = True

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_max_abs_extent_kernel(mask: np.ndarray, ref_y: int, ref_x: int) -> int:
        best = -1
        for y in range(mask.shape[0]):
            for x in range(mask.shape[1]):
                if not mask[y, x]:
                    continue
                dy = y - ref_y
                if dy < 0:
                    dy = -dy
                dx = x - ref_x
                if dx < 0:
                    dx = -dx
                ext = dy if dy > dx else dx
                if ext > best:
                    best = ext
        return best

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_dilated_overlap_count_kernel(
        prev_mask: np.ndarray, prev_oy: int, prev_ox: int,
        cand_mask: np.ndarray, cand_oy: int, cand_ox: int,
        iy0: int, ix0: int, iy1: int, ix1: int,
    ) -> int:
        # Count candidate pixels with any prev pixel in their 3x3 neighborhood — the
        # dilate(prev, 3x3) & cand overlap without materializing the dilation.
        ph = prev_mask.shape[0]
        pw = prev_mask.shape[1]
        count = 0
        for gy in range(iy0, iy1):
            cy = gy - cand_oy
            for gx in range(ix0, ix1):
                if not cand_mask[cy, gx - cand_ox]:
                    continue
                hit = False
                for dy in range(-1, 2):
                    py = gy + dy - prev_oy
                    if py < 0 or py >= ph:
                        continue
                    for dx in range(-1, 2):
                        px = gx + dx - prev_ox
                        if 0 <= px < pw and prev_mask[py, px]:
                            hit = True
                            break
                    if hit:
                        break
                if hit:
                    count += 1
        return count

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_blocks_overlap_any_kernel(
        a_mask: np.ndarray, a_oy: int, a_ox: int,
        b_mask: np.ndarray, b_oy: int, b_ox: int,
        iy0: int, ix0: int, iy1: int, ix1: int,
    ) -> int:
        for gy in range(iy0, iy1):
            ay = gy - a_oy
            by = gy - b_oy
            for gx in range(ix0, ix1):
                if a_mask[ay, gx - a_ox] and b_mask[by, gx - b_ox]:
                    return 1
        return 0

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_keep_center_fill_kernel(mask: np.ndarray) -> np.ndarray:
        # keep-center-component (8-connected) + enclosed-hole fill (4-connected background),
        # fused: result = NOT(border-4-connected component of NOT kept). Matches
        # _keep_center_component_2d + _fill_holes_2d_opencv semantics exactly.
        h = mask.shape[0]
        w = mask.shape[1]
        out = np.zeros((h, w), dtype=np.bool_)
        if h <= 0 or w <= 0:
            return out

        cy = h // 2
        cx = w // 2
        seed_y = -1
        seed_x = -1
        if mask[cy, cx]:
            seed_y = cy
            seed_x = cx
        else:
            best_d2 = np.int64(-1)
            for y in range(h):
                for x in range(w):
                    if not mask[y, x]:
                        continue
                    dy = np.int64(y - cy)
                    dx = np.int64(x - cx)
                    d2 = dy * dy + dx * dx
                    if best_d2 < 0 or d2 < best_d2:
                        best_d2 = d2
                        seed_y = y
                        seed_x = x
        if seed_y < 0:
            return out

        # state: 0 unknown, 1 kept (center component), 2 outside background
        state = np.zeros((h, w), dtype=np.uint8)
        stack = np.empty((h * w, 2), dtype=np.int32)
        sp = 0
        state[seed_y, seed_x] = 1
        stack[sp, 0] = seed_y
        stack[sp, 1] = seed_x
        sp += 1
        while sp > 0:
            sp -= 1
            y = int(stack[sp, 0])
            x = int(stack[sp, 1])
            for dy in range(-1, 2):
                ny = y + dy
                if ny < 0 or ny >= h:
                    continue
                for dx in range(-1, 2):
                    if dy == 0 and dx == 0:
                        continue
                    nx = x + dx
                    if nx < 0 or nx >= w:
                        continue
                    if state[ny, nx] == 0 and mask[ny, nx]:
                        state[ny, nx] = 1
                        stack[sp, 0] = ny
                        stack[sp, 1] = nx
                        sp += 1

        # 4-connected flood of NOT-kept from every border pixel -> outside background.
        sp = 0
        for x in range(w):
            if state[0, x] == 0:
                state[0, x] = 2
                stack[sp, 0] = 0
                stack[sp, 1] = x
                sp += 1
            if state[h - 1, x] == 0:
                state[h - 1, x] = 2
                stack[sp, 0] = h - 1
                stack[sp, 1] = x
                sp += 1
        for y in range(h):
            if state[y, 0] == 0:
                state[y, 0] = 2
                stack[sp, 0] = y
                stack[sp, 1] = 0
                sp += 1
            if state[y, w - 1] == 0:
                state[y, w - 1] = 2
                stack[sp, 0] = y
                stack[sp, 1] = w - 1
                sp += 1
        while sp > 0:
            sp -= 1
            y = int(stack[sp, 0])
            x = int(stack[sp, 1])
            if y > 0 and state[y - 1, x] == 0:
                state[y - 1, x] = 2
                stack[sp, 0] = y - 1
                stack[sp, 1] = x
                sp += 1
            if y + 1 < h and state[y + 1, x] == 0:
                state[y + 1, x] = 2
                stack[sp, 0] = y + 1
                stack[sp, 1] = x
                sp += 1
            if x > 0 and state[y, x - 1] == 0:
                state[y, x - 1] = 2
                stack[sp, 0] = y
                stack[sp, 1] = x - 1
                sp += 1
            if x + 1 < w and state[y, x + 1] == 0:
                state[y, x + 1] = 2
                stack[sp, 0] = y
                stack[sp, 1] = x + 1
                sp += 1

        for y in range(h):
            for x in range(w):
                out[y, x] = state[y, x] != 2
        return out

    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_paste_masked_or_kernel(
        dest: np.ndarray, local_mask: np.ndarray,
        dst_y0: int, dst_x0: int,
        src_y0: int, src_y1: int, src_x0: int, src_x1: int,
    ) -> int:
        added = 0
        for sy in range(src_y0, src_y1):
            dy = dst_y0 + (sy - src_y0)
            for sx in range(src_x0, src_x1):
                if not local_mask[sy, sx]:
                    continue
                dx = dst_x0 + (sx - src_x0)
                if dest[dy, dx] == 0:
                    dest[dy, dx] = 1
                    added += 1
        return added
else:
    _numba_nearest_true_pixel_kernel = None
    _numba_scatter_true_kernel = None
    _numba_max_abs_extent_kernel = None
    _numba_dilated_overlap_count_kernel = None
    _numba_blocks_overlap_any_kernel = None
    _numba_keep_center_fill_kernel = None
    _numba_paste_masked_or_kernel = None


def _planning_kernels_active() -> bool:
    return bool(
        _numba_nearest_true_pixel_kernel is not None
        and compiled_interpolation_kernels_enabled()
        and not _NUMBA_PLANNING_KERNELS_RUNTIME_DISABLED
    )


def _disable_planning_kernels(exc: BaseException) -> None:
    global _NUMBA_PLANNING_KERNELS_RUNTIME_DISABLED
    if not _NUMBA_PLANNING_KERNELS_RUNTIME_DISABLED:
        _NUMBA_PLANNING_KERNELS_RUNTIME_DISABLED = True
        print(f'Warning: numba planning kernels failed ({exc}); using python planning helpers for remaining calls in this process.')


def interpolation_projection_numba_max_tracked() -> int:
    return max(8, _env_int('YOLO_TTA_INTERPOLATION_NUMBA_MAX_TRACKED_CANDIDATES', 64))


def interpolation_compiled_kernels_status() -> str:
    if _numba is None:
        return f'unavailable ({_NUMBA_IMPORT_ERROR})'
    if not _env_flag('YOLO_TTA_INTERPOLATION_COMPILED_KERNELS', True):
        return 'disabled by YOLO_TTA_INTERPOLATION_COMPILED_KERNELS=0'
    if _NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED:
        return 'disabled after runtime compilation/execution failure'
    return 'enabled: numba no-GIL projection-candidate kernel'


def interpolation_planning_backend_name() -> str:
    base = 'cached_per_slice_component_tables_local_sdf_unordered'
    if compiled_interpolation_kernels_enabled() and not _NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED:
        base += '+numba_nogil_projection_candidates'
    else:
        base += '+python_projection_candidates'
    if _INTERPOLATION_PROCESS_WORKER:
        base += '+process_isolated_pass'
    return base


if _numba is not None:
    @_numba.njit(cache=True, nogil=True)  # type: ignore[misc]
    def _numba_find_projection_candidates_kernel(
        labels_real: np.ndarray,
        sparse_flat: np.ndarray,
        sparse_offsets: np.ndarray,
        sparse_bboxes: np.ndarray,
        sparse_mode: bool,
        num_slices_arg: int,
        full_w_arg: int,
        lut_flat: np.ndarray,
        lut_offsets: np.ndarray,
        sdf: np.ndarray,
        crop_y0: int,
        crop_x0: int,
        s0: int,
        source_anchor_y: int,
        source_anchor_x: int,
        seed_label: int,
        direction_sign: int,
        max_steps: int,
        slope: float,
        max_candidates: int,
        wrap_axis: bool,
        search_angle_negative: bool,
        max_tracked: int,
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, int, int]:
        out_labels = np.zeros((max_tracked,), dtype=np.int64)
        out_slices = np.zeros((max_tracked,), dtype=np.int64)
        out_ys = np.zeros((max_tracked,), dtype=np.int64)
        out_xs = np.zeros((max_tracked,), dtype=np.int64)
        out_steps = np.zeros((max_tracked,), dtype=np.int64)
        out_d2 = np.zeros((max_tracked,), dtype=np.int64)

        step_labels = np.zeros((max_tracked,), dtype=np.int64)
        step_ys = np.zeros((max_tracked,), dtype=np.int64)
        step_xs = np.zeros((max_tracked,), dtype=np.int64)
        step_d2 = np.zeros((max_tracked,), dtype=np.int64)

        found_count = 0
        num_slices = num_slices_arg
        full_w = full_w_arg
        sdf_h = sdf.shape[0]
        sdf_w = sdf.shape[1]
        overflow = 0
        # v13.3.6 (A1): when the label volume holds per-slice LOCAL ids (compact relabel
        # skipped), lut_offsets has one entry per slice and reads canonicalize through the
        # concatenated local->canonical table; a shorter array means canonical ids in-raster.
        use_lut = lut_offsets.shape[0] == num_slices

        for step in range(1, max_steps + 1):
            s = s0 + direction_sign * step
            # v13.2.2 bug #2: a projection step that crosses the radial 0°/180° wrap lands
            # in a frame whose u axis is REVERSED relative to the projection cone, so read
            # (and report) the mirrored column there. max_steps <= num_slices-1 caps the
            # walk at a single crossing.
            mirrored = False
            if wrap_axis:
                if s < 0 or s >= num_slices:
                    mirrored = True
                s = s % num_slices
            else:
                if s < 0 or s >= num_slices:
                    break

            threshold = -slope * float(step)
            any_projection = False
            step_count = 0

            for yy in range(sdf_h):
                gy = crop_y0 + yy
                for xx in range(sdf_w):
                    if sdf[yy, xx] < threshold:
                        continue
                    any_projection = True
                    gx = crop_x0 + xx
                    if mirrored:
                        gx_read = full_w - 1 - gx
                    else:
                        gx_read = gx
                    if sparse_mode:
                        sy0 = int(sparse_bboxes[s, 0])
                        sy1 = int(sparse_bboxes[s, 1])
                        sx0 = int(sparse_bboxes[s, 2])
                        sx1 = int(sparse_bboxes[s, 3])
                        if gy < sy0 or gy >= sy1 or gx_read < sx0 or gx_read >= sx1:
                            raw_label = 0
                        else:
                            sparse_index = int(sparse_offsets[s]) + (
                                (gy - sy0) * (sx1 - sx0) + (gx_read - sx0)
                            )
                            raw_label = int(sparse_flat[sparse_index])
                    else:
                        raw_label = int(labels_real[s, gy, gx_read])
                    if raw_label <= 0:
                        continue
                    if use_lut:
                        target_label = int(lut_flat[lut_offsets[s] + raw_label])
                    else:
                        target_label = raw_label
                    if target_label <= 0 or target_label == seed_label:
                        continue

                    already_found = False
                    for prev_idx in range(found_count):
                        if out_labels[prev_idx] == target_label:
                            already_found = True
                            break
                    if already_found:
                        continue

                    step_idx = -1
                    for local_idx in range(step_count):
                        if step_labels[local_idx] == target_label:
                            step_idx = local_idx
                            break

                    dy = gy - source_anchor_y
                    dx = gx - source_anchor_x
                    d2 = dy * dy + dx * dx
                    if step_idx < 0:
                        if step_count >= max_tracked:
                            overflow = 1
                            return out_labels, out_slices, out_ys, out_xs, out_steps, out_d2, found_count, overflow
                        step_labels[step_count] = target_label
                        step_ys[step_count] = gy
                        # Candidate points are reported in the target slice's own (actual)
                        # coordinates; d2 stays in unrolled projection coordinates.
                        step_xs[step_count] = gx_read
                        step_d2[step_count] = d2
                        step_count += 1
                    else:
                        if d2 < step_d2[step_idx]:
                            step_ys[step_idx] = gy
                            step_xs[step_idx] = gx_read
                            step_d2[step_idx] = d2

            if not any_projection:
                if search_angle_negative:
                    break
                continue

            for local_idx in range(step_count):
                if found_count >= max_tracked:
                    overflow = 1
                    return out_labels, out_slices, out_ys, out_xs, out_steps, out_d2, found_count, overflow
                out_labels[found_count] = step_labels[local_idx]
                out_slices[found_count] = s
                out_ys[found_count] = step_ys[local_idx]
                out_xs[found_count] = step_xs[local_idx]
                out_steps[found_count] = step
                out_d2[found_count] = step_d2[local_idx]
                found_count += 1

            if found_count >= max_candidates:
                break

        return out_labels, out_slices, out_ys, out_xs, out_steps, out_d2, found_count, overflow
else:
    _numba_find_projection_candidates_kernel = None


def _find_slice_projection_candidates_numba(
    labels_real: object,
    seed: SliceEndpointSeed,
    max_slice_distance: int,
    search_angle_deg: float,
    max_candidates: int,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
    slice_luts: Optional['SliceLocalLabelLUTs'] = None,
) -> Optional[List[SliceProjectionCandidate]]:
    global _NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED
    if (
        _numba_find_projection_candidates_kernel is None
        or not compiled_interpolation_kernels_enabled()
        or _NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED
    ):
        return None
    if int(max_slice_distance) <= 0 or int(max_candidates) <= 0:
        return []

    s0, y0, x0 = seed.point
    num_slices = int(labels_real.shape[0])
    if num_slices <= 0:
        return []

    local_cache = (
        component_cache
        if component_cache is not None
        else SliceComponentTableCache(labels_real, slice_luts=slice_luts)
    )
    source_record, source_anchor = local_cache.find_record_for_point(int(s0), int(seed.label), (int(y0), int(x0)))
    if source_record is None or source_anchor is None or int(source_record.area) <= 0:
        return []

    max_steps = min(int(max_slice_distance), max(0, int(num_slices) - 1)) if bool(wrap_axis) else int(max_slice_distance)
    if int(max_steps) <= 0:
        return []

    cropped_sdf = local_cache.get_projection_sdf(
        source_record,
        max_slice_distance=int(max_steps),
        search_angle_deg=float(search_angle_deg),
    )
    sdf = np.ascontiguousarray(cropped_sdf.sdf, dtype=np.float32)
    crop_y0 = int(cropped_sdf.origin_y)
    crop_x0 = int(cropped_sdf.origin_x)
    slope = math.tan(math.radians(float(search_angle_deg)))
    max_tracked = max(int(max_candidates), int(interpolation_projection_numba_max_tracked()))

    # v13.3.6 (A1): pass the per-slice local->canonical LUTs when the label volume holds
    # local ids; a 1-entry offsets sentinel tells the kernel the raster is already canonical.
    if slice_luts is not None:
        lut_flat_arg = slice_luts.lut_flat
        lut_offsets_arg = slice_luts.lut_offsets
    else:
        # 0-length offsets can never equal num_slices (>0 here), so use_lut stays False.
        lut_flat_arg = np.zeros((1,), dtype=np.uint32)
        lut_offsets_arg = np.zeros((0,), dtype=np.int64)
    if isinstance(labels_real, SparseSliceLabelStore):
        # Numba cannot accept the Python store object, so pass its native packed arena and
        # metadata plus a tiny unused dense sentinel. Candidate reads stay wholly compiled.
        dense_arg = np.empty((0, 0, 0), dtype=labels_real.dtype)
        sparse_flat_arg = labels_real.flat
        sparse_offsets_arg = labels_real.offsets
        sparse_bboxes_arg = labels_real.bboxes
        sparse_mode_arg = True
    else:
        dense_arg = labels_real
        sparse_flat_arg = np.empty((0,), dtype=np.uint16)
        sparse_offsets_arg = np.empty((0,), dtype=np.int64)
        sparse_bboxes_arg = np.empty((0, 4), dtype=np.int64)
        sparse_mode_arg = False
    try:
        labels_out, slices_out, ys_out, xs_out, steps_out, d2_out, count, overflow = _numba_find_projection_candidates_kernel(
            dense_arg,
            sparse_flat_arg,
            sparse_offsets_arg,
            sparse_bboxes_arg,
            bool(sparse_mode_arg),
            int(num_slices),
            int(labels_real.shape[2]),
            lut_flat_arg,
            lut_offsets_arg,
            sdf,
            int(crop_y0),
            int(crop_x0),
            int(s0),
            int(source_anchor[0]),
            int(source_anchor[1]),
            int(seed.label),
            int(seed.direction_sign),
            int(max_steps),
            float(slope),
            int(max_candidates),
            bool(wrap_axis),
            bool(float(search_angle_deg) < 0.0),
            int(max_tracked),
        )
    except Exception as exc:
        _NUMBA_PROJECTION_KERNEL_RUNTIME_DISABLED = True
        print(f'Warning: Numba interpolation projection kernel failed ({exc}); using Python candidate search for remaining calls in this process.')
        return None

    if int(overflow) != 0:
        # Preserve exact semantics by falling back to the Python implementation when a single
        # projection step contains more distinct labels than the fixed-size compiled workspace.
        return None
    if int(count) <= 0:
        return []

    rows: List[Tuple[int, int, int, int, int, int]] = []
    for idx in range(int(count)):
        rows.append((
            int(steps_out[int(idx)]),
            int(d2_out[int(idx)]),
            int(labels_out[int(idx)]),
            int(slices_out[int(idx)]),
            int(ys_out[int(idx)]),
            int(xs_out[int(idx)]),
        ))
    rows.sort(key=lambda item: (int(item[0]), int(item[1]), int(item[2])))
    out: List[SliceProjectionCandidate] = []
    for step, _d2, target_label, target_slice, target_y, target_x in rows[: int(max_candidates)]:
        out.append(SliceProjectionCandidate(
            source_label=int(seed.label),
            target_label=int(target_label),
            source_point=(int(s0), int(y0), int(x0)),
            target_point=(int(target_slice), int(target_y), int(target_x)),
            slice_distance=int(step),
        ))
    return out


def _find_slice_projection_candidates_python(
    labels_real: object,
    seed: SliceEndpointSeed,
    max_slice_distance: int,
    search_angle_deg: float,
    max_candidates: int,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
    slice_luts: Optional['SliceLocalLabelLUTs'] = None,
) -> List[SliceProjectionCandidate]:
    if int(max_slice_distance) <= 0 or int(max_candidates) <= 0:
        return []

    s0, y0, x0 = seed.point
    num_slices = int(labels_real.shape[0])
    if num_slices <= 0:
        return []

    local_cache = (
        component_cache
        if component_cache is not None
        else SliceComponentTableCache(labels_real, slice_luts=slice_luts)
    )
    source_record, source_anchor = local_cache.find_record_for_point(int(s0), int(seed.label), (int(y0), int(x0)))
    if source_record is None or source_anchor is None or int(source_record.area) <= 0:
        return []

    max_steps = min(int(max_slice_distance), max(0, int(num_slices) - 1)) if bool(wrap_axis) else int(max_slice_distance)
    if int(max_steps) <= 0:
        return []

    cropped_sdf = local_cache.get_projection_sdf(
        source_record,
        max_slice_distance=int(max_steps),
        search_angle_deg=float(search_angle_deg),
    )
    sdf = np.asarray(cropped_sdf.sdf, dtype=np.float32)
    crop_y0 = int(cropped_sdf.origin_y)
    crop_x0 = int(cropped_sdf.origin_x)
    crop_y1 = int(crop_y0 + int(sdf.shape[0]))
    crop_x1 = int(crop_x0 + int(sdf.shape[1]))

    slope = math.tan(math.radians(float(search_angle_deg)))
    full_w = int(labels_real.shape[2])
    # target_label -> (step, unrolled d2, candidate); d2 is kept separately because the
    # candidate's target_point is in the target slice's own (actual) coordinates, which
    # differ from unrolled projection coordinates for wrap-crossing steps.
    found: Dict[int, Tuple[int, int, SliceProjectionCandidate]] = {}

    for step in range(1, int(max_steps) + 1):
        s_raw = int(s0 + int(seed.direction_sign) * step)
        mirrored = False
        if bool(wrap_axis):
            s = int(s_raw % int(num_slices))
            # v13.2.2 bug #2: a step across the radial 0°/180° wrap lands in a frame whose
            # u axis is REVERSED relative to the projection cone. max_steps <= num_slices-1
            # caps the walk at a single crossing.
            mirrored = bool(s_raw < 0 or s_raw >= int(num_slices))
        elif s_raw < 0 or s_raw >= num_slices:
            break
        else:
            s = s_raw

        threshold = -float(slope) * float(step)
        projection = sdf >= threshold
        if not np.any(projection):
            if float(search_angle_deg) < 0.0:
                break
            continue

        if isinstance(labels_real, SparseSliceLabelStore):
            # C4: materialize only the SDF window. A wrap-crossing projection requests
            # the corresponding actual-u window and reverses that small crop back into
            # unrolled projection coordinates.
            if mirrored:
                actual_x0 = int(full_w - crop_x1)
                actual_x1 = int(full_w - crop_x0)
                labels_crop = labels_real.read_window(
                    int(s), crop_y0, crop_y1, actual_x0, actual_x1,
                )[:, ::-1]
            else:
                labels_crop = labels_real.read_window(
                    int(s), crop_y0, crop_y1, crop_x0, crop_x1,
                )
        else:
            slice_view = np.asarray(labels_real[int(s)])
            if mirrored:
                slice_view = slice_view[:, ::-1]
            labels_crop = slice_view[crop_y0:crop_y1, crop_x0:crop_x1]
        if slice_luts is not None:
            # v13.3.6 (A1): local-id raster — canonicalize just the SDF crop (small gather)
            # instead of relying on a full-volume compact relabel pass.
            labels_crop = slice_luts.lut_for(int(s))[labels_crop]
        overlap = projection & (labels_crop > 0) & (labels_crop != int(seed.label))
        if not np.any(overlap):
            continue

        ys_local, xs_local = np.nonzero(overlap)
        lbls = labels_crop[ys_local, xs_local].astype(np.int64, copy=False)
        for target_label in np.unique(lbls):
            target_label_i = int(target_label)
            if target_label_i <= 0 or target_label_i == int(seed.label) or target_label_i in found:
                continue
            use = lbls == target_label_i
            ys_t = ys_local[use]
            xs_t = xs_local[use]
            if ys_t.size == 0:
                continue
            ys_global = ys_t.astype(np.int64, copy=False) + int(crop_y0)
            xs_global = xs_t.astype(np.int64, copy=False) + int(crop_x0)
            d2 = (ys_global - int(source_anchor[0])) ** 2 + (xs_global - int(source_anchor[1])) ** 2
            idx = int(np.argmin(d2))
            x_actual = int(full_w - 1 - int(xs_global[idx])) if mirrored else int(xs_global[idx])
            found[target_label_i] = (int(step), int(d2[idx]), SliceProjectionCandidate(
                source_label=int(seed.label),
                target_label=target_label_i,
                source_point=(int(s0), int(y0), int(x0)),
                target_point=(int(s), int(ys_global[idx]), x_actual),
                slice_distance=int(step),
            ))

        if len(found) >= int(max_candidates):
            break

    ordered = sorted(
        found.items(),
        key=lambda item: (int(item[1][0]), int(item[1][1]), int(item[0])),
    )
    return [candidate for _label, (_step, _d2, candidate) in ordered[: int(max_candidates)]]


def _find_slice_projection_candidates(
    labels_real: np.ndarray,
    seed: SliceEndpointSeed,
    max_slice_distance: int,
    search_angle_deg: float,
    max_candidates: int,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
    slice_luts: Optional['SliceLocalLabelLUTs'] = None,
) -> List[SliceProjectionCandidate]:
    fast_candidates = _find_slice_projection_candidates_numba(
        labels_real=labels_real,
        seed=seed,
        max_slice_distance=int(max_slice_distance),
        search_angle_deg=float(search_angle_deg),
        max_candidates=int(max_candidates),
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
        slice_luts=slice_luts,
    )
    if fast_candidates is not None:
        return fast_candidates
    return _find_slice_projection_candidates_python(
        labels_real=labels_real,
        seed=seed,
        max_slice_distance=int(max_slice_distance),
        search_angle_deg=float(search_angle_deg),
        max_candidates=int(max_candidates),
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
        slice_luts=slice_luts,
    )

def _collect_walkback_source_points(
    labels_real: np.ndarray,
    label: int,
    start_point: Tuple[int, int, int],
    direction_sign: int,
    walk_back: int,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
) -> List[Tuple[int, int, int]]:
    if int(walk_back) <= 0:
        return []

    s0, y0, x0 = start_point
    num_slices = int(labels_real.shape[0])

    if component_cache is not None:
        current_record, current_anchor = component_cache.find_record_for_point(int(s0), int(label), (int(y0), int(x0)))
        if current_record is None or current_anchor is None:
            return []
        out: List[Tuple[int, int, int]] = []
        current_slice = int(s0)
        slice_w = int(labels_real.shape[2])
        max_walk = min(int(walk_back), max(0, int(num_slices) - 1)) if bool(wrap_axis) else int(walk_back)
        visited_slices = {int(current_slice)}
        for _ in range(int(max_walk)):
            next_slice_raw = int(current_slice - int(direction_sign))
            wrap_crossed = False
            if bool(wrap_axis):
                next_slice = int(next_slice_raw % int(num_slices))
                wrap_crossed = bool(next_slice_raw < 0 or next_slice_raw >= int(num_slices))
                if next_slice in visited_slices:
                    break
            elif next_slice_raw < 0 or next_slice_raw >= num_slices:
                break
            else:
                next_slice = next_slice_raw

            cmp_record = current_record
            cmp_anchor = current_anchor
            if wrap_crossed:
                # v13.2.2 bug #2: continuation across the radial 0°/180° wrap matches at
                # u -> width-1-u; mirror the near side into the far frame's coordinates.
                cmp_record = _component_record_mirrored_u(current_record, slice_w)
                cmp_anchor = (int(current_anchor[0]), int(slice_w - 1 - int(current_anchor[1])))
            next_record, next_anchor = component_cache.get(next_slice).find_branch_continuation(
                int(label),
                cmp_record,
                cmp_anchor,
            )
            if next_record is None or next_anchor is None:
                break
            out.append((int(next_slice), int(next_anchor[0]), int(next_anchor[1])))
            visited_slices.add(int(next_slice))
            current_slice = int(next_slice)
            current_record = next_record
            current_anchor = next_anchor
        return out

    current_component, current_anchor = _component_mask_and_anchor(labels_real[s0] == int(label), (y0, x0))
    if current_anchor is None or not np.any(current_component):
        return []

    out: List[Tuple[int, int, int]] = []
    current_slice = int(s0)
    slice_w = int(labels_real.shape[2])

    max_walk = min(int(walk_back), max(0, int(num_slices) - 1)) if bool(wrap_axis) else int(walk_back)
    visited_slices = {int(current_slice)}
    for _ in range(int(max_walk)):
        next_slice_raw = int(current_slice - int(direction_sign))
        wrap_crossed = False
        if bool(wrap_axis):
            next_slice = int(next_slice_raw % int(num_slices))
            wrap_crossed = bool(next_slice_raw < 0 or next_slice_raw >= int(num_slices))
            if next_slice in visited_slices:
                break
        elif next_slice_raw < 0 or next_slice_raw >= num_slices:
            break
        else:
            next_slice = next_slice_raw

        next_slice_mask = labels_real[next_slice] == int(label)
        if not np.any(next_slice_mask):
            break

        cmp_component = current_component
        cmp_anchor = current_anchor
        if wrap_crossed:
            # v13.2.2 bug #2: match across the radial 0°/180° wrap at u -> width-1-u.
            cmp_component = current_component[:, ::-1]
            cmp_anchor = (int(current_anchor[0]), int(slice_w - 1 - int(current_anchor[1])))
        next_component, next_anchor = _follow_branch_component(next_slice_mask, cmp_component, cmp_anchor)
        if next_anchor is None or not np.any(next_component):
            break

        out.append((int(next_slice), int(next_anchor[0]), int(next_anchor[1])))
        visited_slices.add(int(next_slice))
        current_slice = int(next_slice)
        current_component = next_component
        current_anchor = next_anchor

    return out


def interpolation_cache_bridge_sections_enabled() -> bool:
    """Reuse accepted min-radius scan sections during painting (v13.3.10 T6).

    ``YOLO_TTA_INTERPOLATION_CACHE_BRIDGE_SECTIONS=0`` restores recomputation.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_CACHE_BRIDGE_SECTIONS', True)


def interpolation_fused_bridge_merge_enabled() -> bool:
    """Restrict bridge merge/delta capture to rendered paste bboxes (v13.3.10 T7).

    ``YOLO_TTA_INTERPOLATION_FUSED_BRIDGE_MERGE=0`` restores full-slice sweeps.
    """
    return _env_flag('YOLO_TTA_INTERPOLATION_FUSED_BRIDGE_MERGE', True)


@dataclass(frozen=True)
class SliceBridgeRenderPlan:
    source_label: int
    target_label: int
    source_point: Tuple[int, int, int]
    target_point: Tuple[int, int, int]
    source_anchor: Tuple[int, int]
    # v13.2.2 bug #2: for a bridge crossing the radial 0°/180° wrap, target_anchor and
    # sdf1 are stored in source-side "unrolled" coordinates (u mirrored relative to the
    # target slice's own frame); the painter maps wrapped intermediate slices back.
    target_anchor: Tuple[int, int]
    steps: int
    sign: int
    num_slices: int
    sdf0: np.ndarray
    sdf1: np.ndarray
    # v13.3.10 (T6): the min-radius acceptance scan already constructs every
    # intermediate bool section. Accepted plans retain those exact post-component-filter
    # arrays by step index so painting does not repeat SDF lerp/threshold/component work.
    cached_sections: List[Optional[np.ndarray]] = field(default_factory=list, compare=False, repr=False)


@dataclass
class SliceSeedBridgePlanResult:
    candidate_connections: int = 0
    accepted_connections: int = 0
    default_bridges: int = 0
    walk_back_bridges: int = 0
    skipped_by_min_radius: int = 0
    plans: List[SliceBridgeRenderPlan] = field(default_factory=list)


def _build_slice_endpoint_seeds(
    labels_real: np.ndarray,
    extension_slices: int,
    workers: int = 1,
    wrap_axis: bool = False,
    component_cache: Optional['SliceComponentTableCache'] = None,
) -> Tuple[List[SliceEndpointSeed], int]:
    """Build interpolation endpoint seeds with the v12.2.0 per-slice component scan.

    Interpolation no longer uses skeletonization. Each labeled 3D object is scanned slice by
    slice; every 2D connected component is evaluated independently for overlap continuation
    into the previous and next slice. Components without continuation become endpoint seeds in
    the corresponding direction. Radial interpolation can wrap the slice/frame axis so frame 0
    and the final radial frame are considered adjacent.
    """
    del extension_slices  # retained for call-site compatibility; scan endpoints do not need it.
    return build_slice_endpoint_seeds_from_label_volume(
        labels_real,
        workers=int(workers),
        desc='Interpolation: endpoint seeds [scan]',
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
    )


def _build_linear_slice_bridge_plan(
    labels_real: np.ndarray,
    source_label: int,
    target_label: int,
    source_point: Tuple[int, int, int],
    target_point: Tuple[int, int, int],
    direction_sign: Optional[int] = None,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
) -> Optional[SliceBridgeRenderPlan]:
    s0, y0, x0 = source_point
    s1, y1, x1 = target_point
    if int(s0) == int(s1):
        return None

    num_slices = int(labels_real.shape[0])
    if bool(wrap_axis):
        sign = 1 if int(direction_sign or 1) >= 0 else -1
        if sign > 0:
            steps = int((int(s1) - int(s0)) % num_slices)
        else:
            steps = int((int(s0) - int(s1)) % num_slices)
    else:
        steps = int(abs(int(s1) - int(s0)))
        sign = 1 if int(s1) > int(s0) else -1
    if steps <= 0:
        return None

    # v13.2.2 bug #2: does the raw source->target walk cross the 0°/180° wrap? If so, the
    # target slice's u axis is REVERSED relative to the source side; build the morph in
    # source-side "unrolled" coordinates by mirroring the target component and anchor.
    raw_end = int(s0) + int(sign) * int(steps)
    wrap_crossed = bool(wrap_axis) and not (0 <= raw_end < num_slices)
    slice_w = int(labels_real.shape[2])

    if component_cache is not None:
        source_record, source_anchor = component_cache.find_record_for_point(int(s0), int(source_label), (int(y0), int(x0)))
        target_record, target_anchor = component_cache.find_record_for_point(int(s1), int(target_label), (int(y1), int(x1)))
        if source_record is None or target_record is None or source_anchor is None or target_anchor is None:
            return None
        if int(source_record.area) <= 0 or int(target_record.area) <= 0:
            return None
        if wrap_crossed:
            target_record = _component_record_mirrored_u(target_record, slice_w)
            target_anchor = (int(target_anchor[0]), int(slice_w - 1 - int(target_anchor[1])))

        half_width = _local_half_width_for_component_records(source_record, source_anchor, target_record, target_anchor)
        source_local = _component_record_to_local_canvas(source_record, source_anchor, half_width)
        target_local = _component_record_to_local_canvas(target_record, target_anchor, half_width)
    else:
        source_component, source_anchor = _component_mask_and_anchor(labels_real[s0] == int(source_label), (y0, x0))
        target_component, target_anchor = _component_mask_and_anchor(labels_real[s1] == int(target_label), (y1, x1))
        if source_anchor is None or target_anchor is None:
            return None
        if not np.any(source_component) or not np.any(target_component):
            return None
        if wrap_crossed:
            target_component = target_component[:, ::-1]
            target_anchor = (int(target_anchor[0]), int(slice_w - 1 - int(target_anchor[1])))

        half_width = _local_half_width_for_components(source_component, source_anchor, target_component, target_anchor)
        source_local = _component_to_local_canvas(source_component, source_anchor, half_width)
        target_local = _component_to_local_canvas(target_component, target_anchor, half_width)

    if not np.any(source_local) or not np.any(target_local):
        return None

    return SliceBridgeRenderPlan(
        source_label=int(source_label),
        target_label=int(target_label),
        source_point=(int(s0), int(y0), int(x0)),
        target_point=(int(s1), int(y1), int(x1)),
        source_anchor=(int(source_anchor[0]), int(source_anchor[1])),
        target_anchor=(int(target_anchor[0]), int(target_anchor[1])),
        steps=int(steps),
        sign=int(sign),
        num_slices=int(num_slices),
        sdf0=np.ascontiguousarray(_signed_distance_2d(source_local)),
        sdf1=np.ascontiguousarray(_signed_distance_2d(target_local)),
    )


def _estimate_linear_slice_bridge_min_radius_from_plan(
    plan: SliceBridgeRenderPlan,
    *,
    reject_at_or_below: float = 0.0,
    cache_sections: bool = False,
) -> float:
    """Thinnest inscribed radius along the bridge (endpoints + every intermediate section).

    v13.2.5 (speed #9): the endpoint radii come directly from the plan's own signed distance
    fields (max(sdf) IS the max inscribed radius — no extra distance transforms), and when
    ``reject_at_or_below`` is set the per-step scan returns as soon as the running minimum can
    no longer exceed the rejection threshold (the caller rejects on <=, so no later section
    can change the outcome). v13.3.10 T6 optionally retains each post-filter intermediate
    section on the plan; every accepted plan necessarily completes this scan.
    """
    source_local = np.asarray(plan.sdf0 >= 0.0, dtype=bool)
    target_local = np.asarray(plan.sdf1 >= 0.0, dtype=bool)
    if not np.any(source_local) or not np.any(target_local):
        return 0.0

    min_radius = float(min(float(np.max(plan.sdf0)), float(np.max(plan.sdf1))))
    threshold = float(reject_at_or_below)
    if threshold > 0.0 and min_radius <= threshold:
        return float(min_radius)
    section_cache = plan.cached_sections
    if bool(cache_sections):
        section_cache[:] = [None] * (int(plan.steps) + 1)
    for idx in range(1, int(plan.steps)):
        alpha = float(idx) / float(plan.steps)
        section = ((1.0 - alpha) * plan.sdf0 + alpha * plan.sdf1) >= 0.0
        if not np.any(section):
            return 0.0
        section = _keep_center_component_2d(section)
        if bool(cache_sections):
            # The painter only reads this array (wrap handling creates a reversed view),
            # so retaining the exact estimator result is bit-for-bit equivalent.
            section_cache[int(idx)] = section
        min_radius = min(min_radius, _component_max_radius(section))
        if threshold > 0.0 and min_radius <= threshold:
            return float(min_radius)
    return float(min_radius)


def _paint_linear_slice_bridge_plan_onto_slice(
    dest_slice: np.ndarray,
    plan: SliceBridgeRenderPlan,
    step_idx: int,
    *,
    dst_bbox_union: Optional[List[int]] = None,
) -> int:
    if int(step_idx) <= 0 or int(step_idx) >= int(plan.steps):
        return 0

    alpha = float(step_idx) / float(plan.steps)
    section: Optional[np.ndarray] = None
    if int(step_idx) < len(plan.cached_sections):
        section = plan.cached_sections[int(step_idx)]
    if section is None:
        section = ((1.0 - alpha) * plan.sdf0 + alpha * plan.sdf1) >= 0.0
        if not np.any(section):
            return 0
        section = _keep_center_component_2d(section)
    center_y = (1.0 - alpha) * float(plan.source_anchor[0]) + alpha * float(plan.target_anchor[0])
    center_x = (1.0 - alpha) * float(plan.source_anchor[1]) + alpha * float(plan.target_anchor[1])
    # v13.2.2 bug #2: the morph runs in source-side "unrolled" coordinates. Intermediate
    # slices beyond the radial 0°/180° boundary store the u-mirrored frame, so flip the
    # section (the local canvas is centered, so a column flip mirrors it about its
    # center) and mirror the center's u there. Non-wrap plans never leave [0, num_slices).
    s_raw = int(plan.source_point[0]) + int(plan.sign) * int(step_idx)
    if int(plan.num_slices) > 0 and (s_raw < 0 or s_raw >= int(plan.num_slices)):
        section = section[:, ::-1]
        center_x = float(int(dest_slice.shape[1]) - 1) - center_x
    return _paste_local_mask_onto_slice(
        dest_slice,
        section,
        (center_y, center_x),
        dst_bbox_union=dst_bbox_union,
    )


def _plan_slice_seed_bridges(
    labels_real: np.ndarray,
    seed: SliceEndpointSeed,
    max_slice_distance: int,
    search_angle_deg: float,
    interpolation_walk_back: int,
    interpolation_candidates: int,
    interpolate_min_radius: float,
    wrap_axis: bool = False,
    component_cache: Optional[SliceComponentTableCache] = None,
    slice_luts: Optional['SliceLocalLabelLUTs'] = None,
) -> SliceSeedBridgePlanResult:
    result = SliceSeedBridgePlanResult()

    candidates = _find_slice_projection_candidates(
        labels_real=labels_real,
        seed=seed,
        max_slice_distance=int(max_slice_distance),
        search_angle_deg=float(search_angle_deg),
        max_candidates=int(interpolation_candidates),
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
        slice_luts=slice_luts,
    )
    if not candidates:
        return result

    result.candidate_connections = int(len(candidates))
    source_points = [seed.point] + _collect_walkback_source_points(
        labels_real=labels_real,
        label=int(seed.label),
        start_point=seed.point,
        direction_sign=int(seed.direction_sign),
        walk_back=int(interpolation_walk_back),
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
    )

    for candidate in candidates:
        accepted_this_candidate = False
        for walk_idx, src_point in enumerate(source_points):
            plan = _build_linear_slice_bridge_plan(
                labels_real=labels_real,
                source_label=int(candidate.source_label),
                target_label=int(candidate.target_label),
                source_point=src_point,
                target_point=candidate.target_point,
                direction_sign=int(seed.direction_sign),
                wrap_axis=bool(wrap_axis),
                component_cache=component_cache,
            )
            if plan is None:
                continue

            if float(interpolate_min_radius) > 0.0:
                bridge_radius = _estimate_linear_slice_bridge_min_radius_from_plan(
                    plan,
                    reject_at_or_below=float(interpolate_min_radius),
                    cache_sections=bool(interpolation_cache_bridge_sections_enabled()),
                )
                if bridge_radius <= float(interpolate_min_radius):
                    result.skipped_by_min_radius += 1
                    continue

            if walk_idx == 0:
                result.default_bridges += 1
            else:
                result.walk_back_bridges += 1

            if not accepted_this_candidate:
                result.accepted_connections += 1
                accepted_this_candidate = True

            result.plans.append(plan)

    return result


def _build_slice_bridge_render_schedule(
    plans: Sequence[SliceBridgeRenderPlan],
    num_slices: int,
    wrap_axis: bool = False,
) -> List[List[Tuple[int, int]]]:
    schedule: List[List[Tuple[int, int]]] = [[] for _ in range(int(num_slices))]
    for plan_idx, plan in enumerate(plans):
        start_slice = int(plan.source_point[0])
        for step_idx in range(1, int(plan.steps)):
            s = int(start_slice + int(plan.sign) * step_idx)
            if bool(wrap_axis):
                s = int(s % int(num_slices))
                schedule[s].append((int(plan_idx), int(step_idx)))
            elif 0 <= s < int(num_slices):
                schedule[s].append((int(plan_idx), int(step_idx)))
    return schedule

def interpolate_view_volume_pass_inplace(
    mask_mm: np.ndarray,
    work_dir: Path,
    pass_tag: str,
    max_slice_distance: int,
    search_angle_deg: float,
    interpolation_walk_back: int,
    interpolation_candidates: int,
    interpolate_min_radius: float,
    keep_temp: bool = False,
    prefer_memory: bool = True,
    reserve_bytes: int = 16 * GIB,
    workers: int = 1,
    wrap_axis: bool = False,
    bridge_delta_path: Optional[Path] = None,
    known_slice_any: Optional[np.ndarray] = None,
    known_slice_bboxes: Optional[np.ndarray] = None,
) -> Dict[str, object]:
    """Apply one interpolation pass directly to a view-volume stack.

    The pass keeps bridge creation simultaneous by searching against a frozen label snapshot and
    merging all newly created bridge voxels only after planning is complete. Endpoint discovery,
    candidate search, bridge planning and slice rendering are parallelized across independent
    objects / seeds / slices to reduce the long single-threaded stretch after compact relabel.
    For Radial views, wrap_axis lets endpoint search and bridge rendering wrap between the
    final and first azimuth frames.

    v13.2.5 (speed #3): ``bridge_delta_path`` writes the pass's exact added-voxel volume
    (bridge AND NOT pre-merge mask) to a disk memmap during the merge step, replacing the old
    full-volume before-copy + subtract the --save_nrrd bridge layers used to require. The stat
    key 'bridge_delta_path' is set when the file was produced; the CALLER owns its cleanup.

    v13.3.10 T6 reuses accepted min-radius scan sections during painting. T7 records the
    union of clipped paste bboxes for each rendered slice and restricts the simultaneous
    bridge merge plus optional delta capture to that region. Both optimizations are default-on
    behind their ``YOLO_TTA_INTERPOLATION_*`` gates and retain the legacy path as fallback.
    """
    if int(max_slice_distance) <= 0:
        return {
            'num_objects': 0,
            'num_endpoints': 0,
            'candidate_connections': 0,
            'accepted_connections': 0,
            'default_bridges': 0,
            'walk_back_bridges': 0,
            'skipped_by_min_radius': 0,
            'added_voxels': 0,
            'skipped': True,
            'wrap_axis': bool(wrap_axis),
            'endpoint_method': 'slice_component_scan',
            'planning_backend': interpolation_planning_backend_name(),
        }

    work_dir.mkdir(parents=True, exist_ok=True)
    # v13.3.6 (A1): keep per-slice LOCAL ids in the label store and consume them through
    # the exported LUTs. v13.3.9 (D5): size the admission estimate with the actual local
    # label dtype so a uint16-capable pass is not needlessly forced to disk.
    skip_relabel = interpolation_skip_compact_relabel_enabled()
    estimated_label_dtype = _local_label_store_dtype(compact_relabel=not skip_relabel)
    estimated_bytes = estimate_interpolation_workspace_bytes(
        tuple(int(x) for x in mask_mm.shape), label_dtype=estimated_label_dtype,
    )
    use_in_memory = bool(prefer_memory) and should_use_in_memory_workspace(estimated_bytes, reserve_bytes=reserve_bytes)
    if use_in_memory:
        print(f"Interpolation workspace ({pass_tag}): in-memory ({estimated_bytes / GIB:.1f} GiB estimated)")
    else:
        print(f"Interpolation workspace ({pass_tag}): disk-backed ({estimated_bytes / GIB:.1f} GiB estimated) -> {work_dir}")

    # Component tables + candidate kernels canonicalize at read time, deleting the
    # full-volume compact-relabel read+write pass over the label store.
    label_stats: Dict[str, object] = {}
    labels_mm, num_objects, label_paths = label_foreground_volume_streaming(
        mask_mm,
        work_dir / f'{pass_tag}_labels',
        keep_temp=True,
        prefer_memory=use_in_memory,
        reserve_bytes=reserve_bytes,
        wrap_axis=bool(wrap_axis),
        workers=int(workers),
        compact_relabel=not skip_relabel,
        component_stats_out=label_stats if skip_relabel else None,
        known_slice_any=known_slice_any,
        known_slice_bboxes=known_slice_bboxes,
        sparse_local_labels=bool(skip_relabel),
    )
    slice_luts: Optional[SliceLocalLabelLUTs] = (
        label_stats.get('slice_local_luts') if skip_relabel else None  # type: ignore[assignment]
    )

    if int(num_objects) <= 1:
        del labels_mm
        if not keep_temp:
            for p in label_paths:
                try:
                    p.unlink(missing_ok=True)
                except Exception:
                    pass
        return {
            'num_objects': int(num_objects),
            'num_endpoints': 0,
            'candidate_connections': 0,
            'accepted_connections': 0,
            'default_bridges': 0,
            'walk_back_bridges': 0,
            'skipped_by_min_radius': 0,
            'added_voxels': 0,
            'skipped': int(num_objects) <= 1,
            'wrap_axis': bool(wrap_axis),
            'endpoint_method': 'slice_component_scan',
            'planning_backend': interpolation_planning_backend_name(),
        }

    if skip_relabel and slice_luts is None:
        # Defensive: a local-id raster without LUTs would be misread downstream. This can
        # only happen through an unexpected labeler edit; fail loudly rather than corrupt.
        raise RuntimeError(f'interpolation pass {pass_tag}: local-id label store without slice LUTs')

    component_cache = SliceComponentTableCache(labels_mm, slice_luts=slice_luts)
    worker_count = choose_slice_parallel_workers(int(workers), int(labels_mm.shape[0]))
    seeds, num_endpoints = _build_slice_endpoint_seeds(
        labels_mm,
        extension_slices=int(max_slice_distance),
        workers=worker_count,
        wrap_axis=bool(wrap_axis),
        component_cache=component_cache,
    )
    if not seeds:
        del labels_mm
        if not keep_temp:
            for p in label_paths:
                try:
                    p.unlink(missing_ok=True)
                except Exception:
                    pass
        return {
            'num_objects': int(num_objects),
            'num_endpoints': int(num_endpoints),
            'candidate_connections': 0,
            'accepted_connections': 0,
            'default_bridges': 0,
            'walk_back_bridges': 0,
            'skipped_by_min_radius': 0,
            'added_voxels': 0,
            'skipped': False,
            'wrap_axis': bool(wrap_axis),
            'endpoint_method': 'slice_component_scan',
            'planning_backend': interpolation_planning_backend_name(),
        }

    bridge_path: Optional[Path] = None
    if use_in_memory:
        bridge_mm: np.ndarray = np.zeros(mask_mm.shape, dtype=np.uint8)
    else:
        bridge_path = work_dir / f'{pass_tag}_bridges.u8.dat'
        bridge_mm = np.memmap(bridge_path, dtype=np.uint8, mode='w+', shape=mask_mm.shape)
    numa_interleave_memory(bridge_mm, desc='Interpolation bridge canvas')  # v13.3.5 (N2)

    candidate_connections = 0
    accepted_connections = 0
    default_bridges = 0
    walk_back_bridges = 0
    skipped_by_min_radius = 0
    added_voxels = 0
    bridge_delta_written = False
    # v13.3.11: interpolation already visits every bridge-delta crop while it is hot.
    # Preserve the exact per-azimuth bounds and per-t row occupancy here so radial
    # backprojection does not rediscover them by strided scans over the dense delta file.
    bridge_delta_slice_bboxes: Optional[np.ndarray] = None
    bridge_delta_rows_by_slice: Optional[np.ndarray] = None
    plans: List[SliceBridgeRenderPlan] = []

    try:
        plan_workers = choose_slice_parallel_workers(int(workers), len(seeds))

        def _plan_seed(idx: int) -> SliceSeedBridgePlanResult:
            return _plan_slice_seed_bridges(
                labels_real=labels_mm,
                seed=seeds[int(idx)],
                max_slice_distance=int(max_slice_distance),
                search_angle_deg=float(search_angle_deg),
                interpolation_walk_back=int(interpolation_walk_back),
                interpolation_candidates=int(interpolation_candidates),
                interpolate_min_radius=float(interpolate_min_radius),
                wrap_axis=bool(wrap_axis),
                component_cache=component_cache,
                slice_luts=slice_luts,
            )

        pending = max(plan_workers, plan_workers * 2)
        if plan_workers <= 1:
            iterable = (_plan_seed(int(idx)) for idx in range(len(seeds)))
        else:
            iterable = parallel_map_unordered(
                _plan_seed,
                range(len(seeds)),
                max_workers=plan_workers,
                max_pending=pending,
            )

        for seed_result in tqdm(iterable, total=len(seeds), desc='Interpolation: seed planning'):
            candidate_connections += int(seed_result.candidate_connections)
            accepted_connections += int(seed_result.accepted_connections)
            default_bridges += int(seed_result.default_bridges)
            walk_back_bridges += int(seed_result.walk_back_bridges)
            skipped_by_min_radius += int(seed_result.skipped_by_min_radius)
            if seed_result.plans:
                plans.extend(seed_result.plans)
        # The loop variable otherwise retains the final seed result (and its T6 section
        # caches) independently of the flattened plan list.
        del seed_result

        if plans:
            schedule = _build_slice_bridge_render_schedule(plans, int(mask_mm.shape[0]), wrap_axis=bool(wrap_axis))
            added_counts = np.zeros((int(mask_mm.shape[0]),), dtype=np.int64)
            render_workers = choose_slice_parallel_workers(int(workers), int(mask_mm.shape[0]))
            fused_bridge_merge = bool(interpolation_fused_bridge_merge_enabled())
            rendered_paste_bboxes = (
                np.zeros((int(mask_mm.shape[0]), 4), dtype=np.int64)
                if fused_bridge_merge else None
            )

            def _render_slice(z: int) -> None:
                contribs = schedule[int(z)]
                if not contribs:
                    return
                bridge_slice = bridge_mm[int(z)]
                local_added = 0
                bbox_union = (
                    [int(bridge_slice.shape[0]), int(bridge_slice.shape[1]), 0, 0]
                    if rendered_paste_bboxes is not None else None
                )
                for plan_idx, step_idx in contribs:
                    local_added += _paint_linear_slice_bridge_plan_onto_slice(
                        bridge_slice,
                        plans[int(plan_idx)],
                        int(step_idx),
                        dst_bbox_union=bbox_union,
                    )
                added_counts[int(z)] = np.int64(local_added)
                if rendered_paste_bboxes is not None and bbox_union is not None:
                    rendered_paste_bboxes[int(z)] = np.asarray(bbox_union, dtype=np.int64)

            parallel_for_indices(
                int(mask_mm.shape[0]),
                _render_slice,
                max_workers=render_workers,
                desc='Interpolation: render bridges',
            )
            added_voxels = int(np.sum(added_counts, dtype=np.int64))
            # v13.3.1 (R19): bridge voxels can only exist on slices the render schedule touched;
            # merge (and delta-capture) only those instead of np.any-scanning every slice of the
            # full bridge volume (a mostly-empty ~volume-sized read per pass per view).
            scheduled_slices = [int(z) for z in range(int(mask_mm.shape[0])) if schedule[int(z)]]
            del schedule
            del added_counts
            # Painting is the sole cache consumer. Drop plans (SDFs + T6 bool sections)
            # before allocating the optional volume-sized delta workspace.
            plans.clear()

            delta_mm: Optional[np.ndarray] = None
            if bridge_delta_path is not None:
                # v13.2.5 (speed #3): the delta is exactly bridge AND NOT pre-merge mask,
                # captured in the same read the merge already performs (no before-copy,
                # no post-pass subtract). 'w+' memmaps start zero-filled.
                Path(bridge_delta_path).parent.mkdir(parents=True, exist_ok=True)
                delta_mm = np.memmap(Path(bridge_delta_path), dtype=np.uint8, mode='w+', shape=mask_mm.shape)
                numa_interleave_memory(delta_mm, desc='Interpolation bridge delta')  # v13.3.5 (N2)
                bridge_delta_slice_bboxes = np.zeros((int(mask_mm.shape[0]), 4), dtype=np.int64)
                bridge_delta_rows_by_slice = np.zeros(
                    (int(mask_mm.shape[0]), int(mask_mm.shape[1])), dtype=bool,
                )

            def _record_bridge_delta_metadata(
                z: int,
                delta_region: np.ndarray,
                base_y: int,
                base_x: int,
            ) -> None:
                if bridge_delta_slice_bboxes is None or bridge_delta_rows_by_slice is None:
                    return
                rows = np.any(delta_region, axis=1)
                if not bool(np.any(rows)):
                    return
                cols = np.any(delta_region, axis=0)
                row_ids = np.flatnonzero(rows)
                col_ids = np.flatnonzero(cols)
                bridge_delta_slice_bboxes[int(z)] = np.asarray((
                    int(base_y) + int(row_ids[0]),
                    int(base_y) + int(row_ids[-1]) + 1,
                    int(base_x) + int(col_ids[0]),
                    int(base_x) + int(col_ids[-1]) + 1,
                ), dtype=np.int64)
                bridge_delta_rows_by_slice[int(z), int(base_y):int(base_y) + int(rows.size)] = rows

            def _merge_slice(list_idx: int) -> None:
                z = int(scheduled_slices[int(list_idx)])
                bridge_slice = np.asarray(bridge_mm[z])
                if rendered_paste_bboxes is not None:
                    y0, x0, y1, x1 = (int(v) for v in rendered_paste_bboxes[z])
                    if y0 >= y1 or x0 >= x1:
                        return
                    bridge_region = bridge_slice[y0:y1, x0:x1]
                    if not np.any(bridge_region):
                        return
                    mask_region = np.asarray(mask_mm[z, y0:y1, x0:x1])
                    if delta_mm is not None:
                        # The new w+ delta starts zero; only its possible-bridge region
                        # needs an explicit write. mask_mm remains frozen until this merge.
                        delta_region = np.where(
                            mask_region == 0, bridge_region, np.uint8(0)
                        )
                        delta_mm[z, y0:y1, x0:x1] = delta_region
                        _record_bridge_delta_metadata(int(z), delta_region, int(y0), int(x0))
                    mask_region |= bridge_region
                elif np.any(bridge_slice):
                    # YOLO_TTA_INTERPOLATION_FUSED_BRIDGE_MERGE=0: exact legacy sweep.
                    if delta_mm is not None:
                        mask_slice = np.asarray(mask_mm[z])
                        delta_region = np.where(mask_slice == 0, bridge_slice, np.uint8(0))
                        delta_mm[z, :, :] = delta_region
                        _record_bridge_delta_metadata(int(z), delta_region, 0, 0)
                    mask_mm[z, :, :] |= bridge_slice

            parallel_for_indices(
                len(scheduled_slices),
                _merge_slice,
                max_workers=choose_slice_parallel_workers(int(render_workers), max(1, len(scheduled_slices))),
                desc='Interpolation: merge bridges',
            )
            flush_array(mask_mm)
            if delta_mm is not None:
                flush_array(delta_mm)
                close_memmap_array(delta_mm)
                bridge_delta_written = True
    finally:
        if isinstance(bridge_mm, np.memmap):
            flush_array(bridge_mm)
        del bridge_mm
        try:
            del component_cache
        except Exception:
            pass
        if isinstance(labels_mm, np.memmap):
            flush_array(labels_mm)
        del labels_mm
        if not keep_temp:
            for p in label_paths:
                try:
                    p.unlink(missing_ok=True)
                except Exception:
                    pass
            if bridge_path is not None:
                try:
                    bridge_path.unlink(missing_ok=True)
                except Exception:
                    pass

    result_stats: Dict[str, object] = {
        'num_objects': int(num_objects),
        'num_endpoints': int(num_endpoints),
        'candidate_connections': int(candidate_connections),
        'accepted_connections': int(accepted_connections),
        'default_bridges': int(default_bridges),
        'walk_back_bridges': int(walk_back_bridges),
        'skipped_by_min_radius': int(skipped_by_min_radius),
        'added_voxels': int(added_voxels),
        'skipped': False,
        'wrap_axis': bool(wrap_axis),
        'endpoint_method': 'slice_component_scan',
        'planning_backend': interpolation_planning_backend_name(),
        'compact_relabel_skipped': bool(skip_relabel),  # v13.3.6 (A1)
    }
    if bool(bridge_delta_written) and bridge_delta_path is not None:
        result_stats['bridge_delta_path'] = str(bridge_delta_path)
        if bridge_delta_slice_bboxes is not None:
            result_stats['bridge_delta_slice_bboxes'] = np.ascontiguousarray(bridge_delta_slice_bboxes)
        if bridge_delta_rows_by_slice is not None:
            result_stats['bridge_delta_row_occupancy'] = np.ascontiguousarray(
                np.any(bridge_delta_rows_by_slice, axis=0)
            )
    return result_stats


